        private static bool IsAdministrator()
        {
            try
            {
                WindowsIdentity identity = WindowsIdentity.GetCurrent();
                WindowsPrincipal principal = new WindowsPrincipal(identity);
                return principal.IsInRole(WindowsBuiltInRole.Administrator);
            }
            catch
            {
                return false;
            }
        }

        // Güncellemeden kalan eski exe kopyalarını (ör. *_old.exe, *_old2.exe, *.exe.old4) otomatik siler.
        private static void CleanupLeftoverExecutables()
        {
            Thread t = new Thread(delegate()
            {
                try
                {
                    string appDir = AppDomain.CurrentDomain.BaseDirectory;
                    string selfPath = Path.GetFullPath(Application.ExecutablePath);
                    System.Text.RegularExpressions.Regex rx = new System.Text.RegularExpressions.Regex(
                        @"^GoodbyeDPI.*(_old\d*\.exe|\.exe\.old\d*|\.old\d*|\.bak)$",
                        System.Text.RegularExpressions.RegexOptions.IgnoreCase);

                    for (int attempt = 0; attempt < 30; attempt++)
                    {
                        List<string> pending = new List<string>();
                        foreach (string f in Directory.GetFiles(appDir))
                        {
                            if (string.Equals(Path.GetFullPath(f), selfPath, StringComparison.OrdinalIgnoreCase)) continue;
                            if (!rx.IsMatch(Path.GetFileName(f))) continue;
                            try
                            {
                                File.SetAttributes(f, FileAttributes.Normal);
                                File.Delete(f);
                                AppLogger.Log("UPDATE", "Eski sürüm dosyası silindi: " + Path.GetFileName(f));
                            }
                            catch { pending.Add(f); }
                        }
                        if (pending.Count == 0) return;
                        Thread.Sleep(500);
                    }
                }
                catch {}
            });
            t.IsBackground = true;
            t.Priority = ThreadPriority.BelowNormal;
            t.Start();
        }

        // Sihirbaz ihtiyacı tespiti — AppLogger.Init'ten ÖNCE çağrılır (log dosyası sinyali kullanılmaz).
        // Kural: "FirstRunCompleted" işareti yoksa kurulum sihirbazı bir kez otomatik açılır.
        // Böylece v0.4.4'e GÜNCELLEYEN mevcut kullanıcılar da (otomatik güncelleme, "--updated"
        // ile yeniden başlatma veya elle zip ile gelmiş olsun) sihirbazı ilk açılışta bir kez görür.
        // Sihirbaz hangi yolla kapanırsa kapansın işaret yazılır (WriteFirstRunMarker) ve
        // bir daha otomatik açılmaz.
        private static bool DetectWizardNeeded()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(@"Software\GoodbyeDPI_Pro_MAX", false))
                {
                    if (key != null)
                    {
                        object val = key.GetValue("FirstRunCompleted");
                        if (val != null && Convert.ToInt32(val) == 1) return false;
                    }
                }
                return true;
            }
            catch
            {
                return false;
            }
        }

        // UI iş parçacığı beklenmeyen hata fırlattığında kullanıcı en fazla 2 dakikada bir
        // nazikçe bilgilendirilir (hata fırtınasında toast spam'i olmaz).
        private static DateTime _lastCrashToastUtc = DateTime.MinValue;

        [STAThread]
        static void Main(string[] args)
        {
            // WinDivert paket filtreleme sürücüsü mutlaka Yönetici hakları gerektirir.
            // Standart kullanıcı olarak çalıştırıldıysa UAC ile kendini otomatik yükseltir.
            if (!IsAdministrator())
            {
                try
                {
                    ProcessStartInfo elevatePsi = new ProcessStartInfo();
                    elevatePsi.FileName = Application.ExecutablePath;
                    if (args != null && args.Length > 0)
                    {
                        elevatePsi.Arguments = string.Join(" ", args);
                    }
                    elevatePsi.Verb = "runas";
                    elevatePsi.UseShellExecute = true;
                    elevatePsi.WorkingDirectory = Environment.CurrentDirectory;
                    using (Process elevatedProcess = Process.Start(elevatePsi)) { }
                    return;
                }
                catch (System.ComponentModel.Win32Exception)
                {
                    // Kullanıcı UAC istemine "Hayır" dedi
                    MessageBox.Show(
                        "Programın çalışabilmesi için Yönetici izni gerekiyor.\n\nLütfen sağ tıklayıp 'Yönetici olarak çalıştır' seçeneğiyle açın.",
                        "Yönetici İzni Gerekli",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Warning);
                    return;
                }
                catch (Exception ex)
                {
                    try { AppLogger.Log("ELEVATION", "Yönetici başlatma hatası: " + ex.Message); } catch {}
                }
            }

            bool wizardPending = DetectWizardNeeded();

            AppLogger.Init();
            try
            {
                ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)12288; // TLS 1.2/1.3 (eski TLS 1.0/1.1 güvenlik gereği kaldırıldı)
            }
            catch {}
            Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
            Application.ThreadException += delegate(object sender, ThreadExceptionEventArgs e)
            {
                try
                {
                    if (e.Exception != null) AppLogger.Log("UI_CRASH", e.Exception.ToString(), LogLevel.Error);
                    if ((DateTime.UtcNow - _lastCrashToastUtc).TotalSeconds > 120)
                    {
                        _lastCrashToastUtc = DateTime.UtcNow;
                        ToastNotification.Show("Bir Sorun Olu\u015ftu", "Ayr\u0131nt\u0131lar g\u00fcnl\u00fc\u011fe kaydedildi.", ToastType.Warning, 4500);
                    }
                }
                catch {}
            };
            AppDomain.CurrentDomain.UnhandledException += delegate(object sender, UnhandledExceptionEventArgs e)
            {
                try
                {
                    Exception ex = e.ExceptionObject as Exception;
                    if (ex != null) AppLogger.Log("CRASH", ex.ToString(), LogLevel.Fatal);
                    AppLogger.Flush();
                }
                catch {}
            };

            // 1. Mutex protection
            bool createdNew = false;
            Mutex mutex = null;
            try
            {
                mutex = new Mutex(true, "Global\\GoodbyeDPI_Pro_MAX_GUI_Mutex", out createdNew);
            }
            catch (UnauthorizedAccessException)
            {
                createdNew = false;
            }
            catch
            {
                createdNew = true;
            }

            if (!createdNew)
            {
                try
                {
                    using (EventWaitHandle showEvt = EventWaitHandle.OpenExisting("Local\\GoodbyeDPI_Pro_MAX_Show_Event"))
                    {
                        showEvt.Set();
                    }
                }
                catch {}
                if (mutex != null) { try { mutex.Dispose(); } catch {} }
                return;
            }

            CleanupLeftoverExecutables();
            AppDomain.CurrentDomain.ProcessExit += delegate
            {
                try
                {
                    // Yalnızca bu uygulamanın/GoodbyeDPI klasörlerinin motor süreçleri kapatılır;
                    // başka araçlara ait aynı adlı süreçlere dokunulmaz.
                    ModernMainForm.KillStrayDpiProcesses();
                    ModernMainForm.FlushDnsFast();
                }
                catch {}
                try { AppLogger.Shutdown(); } catch {}
            };

            bool isJustUpdated = false;
            bool isUpdateFailed = false;
            bool startMinimized = false;
            if (args != null)
            {
                for (int i = 0; i < args.Length; i++)
                {
                    string arg = args[i] != null ? args[i].Trim().ToLowerInvariant() : "";
                    if (arg == "--updated" || arg == "-updated") isJustUpdated = true;
                    else if (arg == "--update-failed" || arg == "-update-failed") isUpdateFailed = true;
                    else if (arg == "--minimized" || arg == "-minimized" || arg == "/minimized" ||
                             arg == "--autostart" || arg == "-autostart" || arg == "/autostart" ||
                             arg == "--silent" || arg == "-silent" || arg == "/silent" ||
                             arg == "--tray" || arg == "-tray" || arg == "/tray" ||
                             arg.Contains("minimized") || arg.Contains("autostart"))
                    {
                        startMinimized = true;
                    }
                }
            }

            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new ModernMainForm(isJustUpdated, wizardPending, isUpdateFailed, startMinimized));

            if (mutex != null)
            {
                try { mutex.ReleaseMutex(); } catch {}
                try { mutex.Dispose(); } catch {}
            }
        }
    }

    public class IspProfile
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Tag { get; set; }
        public string Description { get; set; }
        public Color AccentColor { get; set; }
        public string DpiArgs { get; set; }
        public string PeeringTarget { get; set; }
        public long PingMs { get; set; }
        public int PacketLossPct { get; set; }
        public long TlsHandshakeMs { get; set; }
        public DateTime PingMeasuredUtc { get; set; }
        public bool IsBestForLine { get; set; }

        public IspProfile(int id, string name, string tag, string desc, Color accent, string dpiArgs, string peeringTarget = null)
        {
            Id = id;
            Name = name;
            Tag = tag;
            Description = desc;
            AccentColor = accent;
            DpiArgs = dpiArgs;
            PeeringTarget = peeringTarget;
            PingMs = -1;
            PacketLossPct = 0;
            TlsHandshakeMs = -1;
            PingMeasuredUtc = DateTime.MinValue;
            IsBestForLine = false;
        }
    }

    public static class AppPaths
    {
        private const ushort ImageFileMachineUnknown = 0x0000;
        private const ushort ImageFileMachineI386 = 0x014c;
        private const ushort ImageFileMachineAmd64 = 0x8664;
        private const ushort ImageFileMachineArm64 = 0xAA64;

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool IsWow64Process2(IntPtr process, out ushort processMachine, out ushort nativeMachine);

        [DllImport("kernel32.dll")]
        private static extern IntPtr GetCurrentProcess();

        public static string AppDir
        {
            get { return AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\', '/'); }
        }

        public static string CoreDir
        {
            get
            {
                string core = Path.Combine(AppDir, "core");
                if (Directory.Exists(core)) return core;
                return AppDir;
            }
        }

        public static string LogsDir
        {
            get
            {
                string logs = Path.Combine(AppDir, "logs");
                if (!Directory.Exists(logs))
                {
                    try { Directory.CreateDirectory(logs); } catch {}
                }
                return logs;
            }
        }

        public static string Resolve(string relativePath)
        {
            string inCore = Path.Combine(AppDir, "core", relativePath);
            if (File.Exists(inCore) || Directory.Exists(inCore)) return inCore;
            return Path.Combine(AppDir, relativePath);
        }

        public static bool TryGetEngineArchitecture(out string archDir, out string driverFileName, out string nativeArchitecture, out string error)
        {
            archDir = null;
            driverFileName = null;
            nativeArchitecture = "Bilinmiyor";
            error = null;

            try
            {
                ushort processMachine;
                ushort nativeMachine;
                if (!IsWow64Process2(GetCurrentProcess(), out processMachine, out nativeMachine))
                {
                    int win32Error = Marshal.GetLastWin32Error();
                    error = "Bilgisayarın işlemci yapısı algılanamadı (Hata: " + win32Error + ").";
                    return false;
                }

                string nativeName = GetMachineArchitectureName(nativeMachine);
                string processName = processMachine == ImageFileMachineUnknown ? null : GetMachineArchitectureName(processMachine);
                nativeArchitecture = nativeName + (string.IsNullOrEmpty(processName) ? "" : " / süreç " + processName + " (emülasyon)");

                if (nativeMachine == ImageFileMachineAmd64)
                {
                    archDir = "x86_64";
                    driverFileName = "WinDivert64.sys";
                    return true;
                }
                if (nativeMachine == ImageFileMachineI386)
                {
                    archDir = "x86";
                    driverFileName = "WinDivert32.sys";
                    return true;
                }
                if (nativeMachine == ImageFileMachineArm64)
                {
                    error = "ARM64 işlemcili bilgisayarlar şu anda desteklenmiyor.";
                    return false;
                }

                error = "Bu bilgisayarın işlemci yapısı desteklenmiyor: " + nativeArchitecture + ".";
                return false;
            }
            catch (EntryPointNotFoundException)
            {
                Version osVersion = Environment.OSVersion.Version;
                if (osVersion.Major < 10 || (osVersion.Major == 10 && osVersion.Build < 16299))
                {
                    bool is64Bit = Environment.Is64BitOperatingSystem;
                    archDir = is64Bit ? "x86_64" : "x86";
                    driverFileName = is64Bit ? "WinDivert64.sys" : "WinDivert32.sys";
                    nativeArchitecture = is64Bit ? "x64 (eski Windows algılaması)" : "x86";
                    return true;
                }

                error = "Bilgisayarın işlemci yapısı doğrulanamadığı için koruma başlatılamadı.";
                return false;
            }
            catch (Exception ex)
            {
                error = "İşlemci yapısı kontrol edilemedi: " + ex.Message;
                return false;
            }
        }

        private static string GetMachineArchitectureName(ushort machine)
        {
            if (machine == ImageFileMachineI386) return "x86";
            if (machine == ImageFileMachineAmd64) return "x64";
            if (machine == ImageFileMachineArm64) return "ARM64";
            return "Bilinmeyen (0x" + machine.ToString("X4") + ")";
        }

        public static bool IsBundledWinDivertDriverPath(string imagePath)
        {
            string normalizedImagePath = NormalizeDriverImagePath(imagePath);
            if (string.IsNullOrEmpty(normalizedImagePath)) return false;

            string[] relativePaths = new string[]
            {
                Path.Combine("core", "x86_64", "WinDivert64.sys"),
                Path.Combine("core", "x86", "WinDivert64.sys"),
                Path.Combine("core", "x86", "WinDivert32.sys"),
                Path.Combine("x86_64", "WinDivert64.sys"),
                Path.Combine("x86", "WinDivert64.sys"),
                Path.Combine("x86", "WinDivert32.sys")
            };

            for (int i = 0; i < relativePaths.Length; i++)
            {
                string expectedPath = NormalizeDriverImagePath(Path.Combine(AppDir, relativePaths[i]));
                if (string.Equals(normalizedImagePath, expectedPath, StringComparison.OrdinalIgnoreCase)) return true;
            }
            return false;
        }

        private static string NormalizeDriverImagePath(string imagePath)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(imagePath)) return null;
                string path = Environment.ExpandEnvironmentVariables(imagePath.Trim().Trim('"'));
                if (path.StartsWith("\\??\\", StringComparison.OrdinalIgnoreCase) || path.StartsWith("\\\\?\\", StringComparison.OrdinalIgnoreCase))
                {
                    path = path.Substring(4);
                }
                return Path.GetFullPath(path);
            }
            catch { return null; }
        }

        public static void EnsureCoreNormal()
        {
        }
    }

