    public class ModernMainForm : Form
    {
        [DllImport("user32.dll")]
        private static extern IntPtr GetForegroundWindow();

        [DllImport("user32.dll")]
        private static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint processId);

        [DllImport("dwmapi.dll")]
        private static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int attrValue, int attrSize);

        internal static bool TryApplyWin11RoundedCorners(IntPtr hwnd)
        {
            try
            {
                if (hwnd == IntPtr.Zero) return false;
                OperatingSystem os = Environment.OSVersion;
                if (os.Platform != PlatformID.Win32NT || os.Version.Major < 10 || os.Version.Build < 22000) return false;
                int cornerPref = 2; // DWMWCP_ROUND (DWMWA_WINDOW_CORNER_PREFERENCE = 33)
                int hr = DwmSetWindowAttribute(hwnd, 33, ref cornerPref, sizeof(int));
                return hr == 0;
            }
            catch
            {
                return false;
            }
        }

        [DllImport("uxtheme.dll", ExactSpelling = true, CharSet = CharSet.Unicode)]
        public static extern int SetWindowTheme(IntPtr hWnd, string pszSubAppName, string pszSubIdList);

        [DllImport("dnsapi.dll", EntryPoint = "DnsFlushResolverCache")]
        private static extern int DnsFlushResolverCache();

        [DllImport("psapi.dll")]
        private static extern int EmptyWorkingSet(IntPtr hwProc);

        [StructLayout(LayoutKind.Sequential)]
        private struct PROCESS_POWER_THROTTLING_STATE
        {
            public uint Version;
            public uint ControlMask;
            public uint StateMask;
        }

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern bool SetProcessInformation(
            IntPtr hProcess,
            int ProcessInformationClass,
            ref PROCESS_POWER_THROTTLING_STATE ProcessInformation,
            uint ProcessInformationSize);

        private const int ProcessPowerThrottling = 4;
        private const uint PROCESS_POWER_THROTTLING_CURRENT_VERSION = 1;
        private const uint PROCESS_POWER_THROTTLING_EXECUTION_SPEED = 0x1;

        internal static void DisableProcessEcoQoS(IntPtr hProcess)
        {
            try
            {
                if (hProcess == IntPtr.Zero) return;
                // Windows 10 Build 16299+ ve Windows 11 kontrolü (Windows 7/8.1'de EntryPointNotFoundException önlenir)
                if (Environment.OSVersion.Platform != PlatformID.Win32NT || 
                    Environment.OSVersion.Version.Major < 10 || 
                    Environment.OSVersion.Version.Build < 16299)
                {
                    return;
                }
                PROCESS_POWER_THROTTLING_STATE state = new PROCESS_POWER_THROTTLING_STATE();
                state.Version = PROCESS_POWER_THROTTLING_CURRENT_VERSION;
                state.ControlMask = PROCESS_POWER_THROTTLING_EXECUTION_SPEED;
                state.StateMask = 0; // 0 = EcoQoS/Efficiency modunu kapat, P-Core ve yüksek zamanlayıcı çözünürlüğü sağla
                SetProcessInformation(hProcess, ProcessPowerThrottling, ref state, (uint)Marshal.SizeOf(typeof(PROCESS_POWER_THROTTLING_STATE)));
            }
            catch {}
        }

        // Hibrit (P-Core / E-Core) ve çok çekirdekli işlemcilerde 1 Gbps (Gigabit) paket akışı için
        // performans çekirdeklerini (P-Core) hedefleyen güvenli çekirdek yakınlığı (Affinity) maskesi hesaplar.
        internal static IntPtr CalculatePerformanceCoreAffinityMask(bool gamePassthroughActive)
        {
            try
            {
                int logicalCores = Math.Max(1, Math.Min(64, Environment.ProcessorCount));
                long targetMask;

                if (logicalCores <= 2)
                {
                    targetMask = (logicalCores >= 64) ? -1L : ((1L << logicalCores) - 1L);
                }
                else if (gamePassthroughActive && logicalCores >= 6)
                {
                    // Rekabetçi oyun açıkken (CS2 / Valorant / FaceIT): oyunun ana render iş parçacığının
                    // kullandığı Core 0/1'i tamamen oyuna bırakıp diğer P-Core çekirdeklerini (Core 2..N) kullan.
                    int upperCoreLimit = Math.Min(8, logicalCores);
                    targetMask = (upperCoreLimit >= 64) ? (~3L) : (((1L << upperCoreLimit) - 1L) & ~3L);
                }
                else
                {
                    // 1 Gbps Gigabit modunda: Windows topolojisinde ilk yarıdaki mantıksal çekirdekler P-Core kümesidir.
                    int pCoreCount = (logicalCores >= 8) ? Math.Min(8, Math.Max(4, logicalCores / 2)) : logicalCores;
                    targetMask = (pCoreCount >= 64) ? -1L : ((1L << pCoreCount) - 1L);
                }

                if (targetMask == 0) return IntPtr.Zero;
                if (IntPtr.Size == 4)
                {
                    return new IntPtr((int)targetMask);
                }
                return new IntPtr(targetMask);
            }
            catch
            {
                return IntPtr.Zero;
            }
        }

        // 1 Gbps Gigabit paket işleme önceliği (AboveNormal + P-Core Affinity + PriorityBoost)
        // ve rekabetçi oyun açıkken Anti-Cheat / Sıfır Gecikme Passthrough izolasyonu uygular.
        internal static void ConfigureGigabitEngineProcess(Process dpiProcess, out bool gamePassthroughActive, out string activeGameName)
        {
            gamePassthroughActive = false;
            activeGameName = null;
            if (dpiProcess == null) return;

            try
            {
                gamePassthroughActive = GameNotificationDeferral.IsCompetitiveGameActive(out activeGameName);
            }
            catch {}

            try
            {
                dpiProcess.PriorityBoostEnabled = true;
            }
            catch {}

            try
            {
                // Oyun açıkken anti-cheat çakışmasını ve CPU kuantum rekabetini önlemek için Normal öncelik;
                // normal kullanımda ve 1 Gbps indirmelerde sıfır paket düşmesi için AboveNormal öncelik.
                dpiProcess.PriorityClass = gamePassthroughActive
                    ? ProcessPriorityClass.Normal
                    : ProcessPriorityClass.AboveNormal;
            }
            catch {}

            try
            {
                DisableProcessEcoQoS(dpiProcess.Handle);
            }
            catch {}

            try
            {
                IntPtr affinityMask = CalculatePerformanceCoreAffinityMask(gamePassthroughActive);
                if (affinityMask != IntPtr.Zero)
                {
                    dpiProcess.ProcessorAffinity = affinityMask;
                }
            }
            catch {}
        }

        public static void TrimProcessMemory()
        {
            try
            {
                GC.Collect(1, GCCollectionMode.Optimized);
                // Win32 pseudo-handle (IntPtr)(-1) kullanımı managed Process nesnesi tahsisini ortadan kaldırır
                EmptyWorkingSet((IntPtr)(-1));
            }
            catch {}
        }

