        public static string GetCurrentActiveIspName()
        {
            try
            {
                if (_instance != null && _instance._profiles != null &&
                    _instance._selectedProfileIndex >= 0 && _instance._selectedProfileIndex < _instance._profiles.Count &&
                    _instance._profiles[_instance._selectedProfileIndex] != null)
                {
                    return _instance._profiles[_instance._selectedProfileIndex].Name;
                }

                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false))
                {
                    if (key != null)
                    {
                        object val = key.GetValue(ProfileRegistryValue);
                        int pIdx = (val is int) ? (int)val : -1;
                        if (pIdx < 0 && val != null) int.TryParse(val.ToString(), out pIdx);
                        string[] names = new string[] {
                            "Türk Telekom (TTNet)", "Turkcell Superonline", "Vodafone Türkiye",
                            "Türksat Kablonet", "TurkNet", "Millenicom", "Netspeed", "GıbırNet", "Diğer Sağlayıcılar"
                        };
                        if (pIdx >= 0 && pIdx < names.Length) return names[pIdx];
                    }
                }
            }
            catch {}
            return "Bilinmiyor";
        }

