        private static Image _cachedLogoImage = null;
        public static Image GetLogoImage()
        {
            if (_cachedLogoImage == null)
            {
                try
                {
                    string iconPath = AppPaths.Resolve("app.ico");
                    if (File.Exists(iconPath))
                    {
                        try
                        {
                            using (Icon ico = new Icon(iconPath, 64, 64))
                            {
                                _cachedLogoImage = ico.ToBitmap();
                            }
                        }
                        catch
                        {
                            using (Icon ico = new Icon(iconPath))
                            {
                                _cachedLogoImage = ico.ToBitmap();
                            }
                        }
                    }
                }
                catch {}

                if (_cachedLogoImage == null)
                {
                    try
                    {
                        using (Icon appIco = Icon.ExtractAssociatedIcon(Application.ExecutablePath))
                        {
                            if (appIco != null) _cachedLogoImage = appIco.ToBitmap();
                        }
                    }
                    catch {}
                }

                if (_cachedLogoImage == null)
                {
                    try
                    {
                        Bitmap bmp = new Bitmap(64, 64, PixelFormat.Format32bppArgb);
                        using (Graphics g = Graphics.FromImage(bmp))
                        {
                            g.SmoothingMode = SmoothingMode.AntiAlias;
                            g.Clear(Color.Transparent);
                            using (GraphicsPath path = new GraphicsPath())
                            {
                                path.AddEllipse(4, 4, 56, 56);
                                using (LinearGradientBrush lgb = new LinearGradientBrush(
                                    new Rectangle(4, 4, 56, 56),
                                    Color.FromArgb(56, 189, 248),
                                    Color.FromArgb(99, 102, 241),
                                    45f))
                                {
                                    g.FillPath(lgb, path);
                                }
                            }
                        }
                        _cachedLogoImage = bmp;
                    }
                    catch {}
                }
            }
            return _cachedLogoImage;
        }

        public ModernMainForm(bool isJustUpdated = false, bool wizardPending = false, bool isUpdateFailed = false, bool startMinimized = false)
        {
            _instance = this;
            try { ThreadPool.SetMinThreads(32, 32); } catch {}
            _isJustUpdated = isJustUpdated;
            _wizardPending = wizardPending;
            _isUpdateFailed = isUpdateFailed;
            _startMinimized = startMinimized;
            if (_startMinimized)
            {
                this.WindowState = FormWindowState.Minimized;
                this.ShowInTaskbar = false;
            }
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
            this.UpdateStyles();

            InitializeProfiles();
            InitializeDnsOptions();
            InitializeModernComponents();
            _currentTheme = LoadSavedTheme();
            ApplyTheme(_currentTheme, false);
            _isThemeDiscovered = LoadThemeDiscovered();
            if (!_isThemeDiscovered && _btnTheme != null)
            {
                _btnTheme.HeartbeatActive = true;
                _themePulseTimer = new System.Windows.Forms.Timer();
                _themePulseTimer.Interval = 35;
                _themePulseTimer.Tick += delegate
                {
                    if (this.IsDisposed || _btnTheme == null || _btnTheme.IsDisposed) return;
                    _themePulsePhase += 0.045f;
                    if (_themePulsePhase > 1.0f) _themePulsePhase = 0.0f;
                    _btnTheme.HeartbeatPhase = _themePulsePhase;
                };
                _themePulseTimer.Start();
            }
            CheckInitialStatus();
            StartPingMonitor();
            StartAnimationEngine();
            if (_isAutoScanCompleted || _userManuallySelectedIsp)
            {
                DetectIspAsync();
            }
            AppPaths.EnsureCoreNormal();
            EnsureWhitelistFile(AppPaths.Resolve("discord_whitelist.txt"));


            try
            {
                SystemEvents.PowerModeChanged += new PowerModeChangedEventHandler(OnPowerModeChanged);
                NetworkChange.NetworkAddressChanged += new NetworkAddressChangedEventHandler(OnNetworkAddressChanged);
                NetworkChange.NetworkAvailabilityChanged += new NetworkAvailabilityChangedEventHandler(OnNetworkAvailabilityChanged);
            }
            catch {}

            // İkinci örnek başlatıldığında (uygulama sistem tepsisindeyken kısayola tekrar tıklandığında)
            // pencereyi odak çalma kurallarına uygun şekilde ekrana getirir.
            try
            {
                _showInstanceEvent = new EventWaitHandle(false, EventResetMode.AutoReset, "Local\\GoodbyeDPI_Pro_MAX_Show_Event");
                _showInstanceWaitReg = ThreadPool.RegisterWaitForSingleObject(_showInstanceEvent, delegate(object state, bool timedOut)
                {
                    if (timedOut || _isDisposing || this.IsDisposed || !this.IsHandleCreated) return;
 // Oyundayken asla odak çalma
                    try
                    {
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (_isDisposing || this.IsDisposed) return;
                            TrayOpen_Click(this, EventArgs.Empty);
                        });
                    }
                    catch {}
                }, null, -1, false);
            }
            catch {}
        }


        private void OnPowerModeChanged(object sender, PowerModeChangedEventArgs e)
        {
            if (e.Mode == PowerModes.Suspend)
            {
                AppLogger.Log("WATCHDOG", "Sistem uyku/askı (Suspend) moduna geçti.", LogLevel.Info);
            }
            else if (e.Mode == PowerModes.Resume)
            {
                RequestAutomaticUpdateCheckFromBackgroundThread(5000);
                AppHealthMetrics.RecordSleepWake();
                AppLogger.Log("WATCHDOG", "Sistem uykudan uyandı (Resume). Ağ bağdaştırıcıları ve WinDivert sürücüsü yenileniyor...", LogLevel.Info);
                if (_isRunning)
                {
                    ThreadPool.QueueUserWorkItem(delegate
                    {
                        // Uyanma anında ağ kartı (DHCP/Wi-Fi) anında hazır olmayabilir.
                        // 1500ms bekleyip arka planda soketleri sıfırlayarak güvenli restart.
                        Thread.Sleep(1500);
                        if (_isDisposing || !_isRunning || _isManualStop) return;

                        try { CleanWinDivertDriverServices(); } catch {}
                        try { FlushDnsFast(); } catch {}

                        try
                        {
                            if (this.IsHandleCreated && !this.IsDisposed && !_isDisposing)
                            {
                                this.BeginInvoke((MethodInvoker)delegate
                                {
                                    if (_isRunning && !_isDisposing && !_isManualStop)
                                    {
                                        RestartProtectionAsync();
                                        ToastNotification.Show("Uykudan Uyanma", "Koruma ba\u015far\u0131yla tazelendi.", ToastType.Info, 2500);
                                    }
                                });
                            }
                        }
                        catch {}
                    });
                }
            }
        }

        private void OnNetworkAddressChanged(object sender, EventArgs e)
        {
            // Bu olay UI dışı bir iş parçacığından gelir; UI işlemlerine devredilmeden
            // dokunulmamalıdır. Ayrıca Wi-Fi/DHCP fırtınalarında tekrar tekrar DNS
            // temizlemeyi önlemek için ardışık değişiklikler seyreltilir.
            if (_isDisposing || this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (_isDisposing || this.IsDisposed) return;
                    if (AcceptUpdateNetworkSignal()) RequestAutomaticUpdateCheck(10000);
                    if (!_isRunning) return;
                    if ((DateTime.UtcNow - _lastNetworkAddressChange).TotalSeconds < 5) return;
                    _lastNetworkAddressChange = DateTime.UtcNow;
                    AppLogger.Log("NETWORK", "Ağ bağdaştırıcı veya IP değişikliği algılandı (Modern Standby / ağ geçişi). DNS önbelleği tazeleniyor...", LogLevel.Info);
                    FlushDnsFast();
                    AppHealthMetrics.RecordDnsRepair();
                    TriggerManualPing();
                });
            }
            catch {}
        }

        private void OnNetworkAvailabilityChanged(object sender, NetworkAvailabilityEventArgs e)
        {
            if (!e.IsAvailable || !AcceptUpdateNetworkSignal()) return;
            RequestAutomaticUpdateCheckFromBackgroundThread(5000);
        }

        private bool AcceptUpdateNetworkSignal()
        {
            lock (_updateNetworkSignalSync)
            {
                DateTime now = DateTime.UtcNow;
                if ((now - _lastUpdateNetworkEventUtc).TotalSeconds < 15) return false;
                _lastUpdateNetworkEventUtc = now;
                return true;
            }
        }

        private void RequestAutomaticUpdateCheckFromBackgroundThread(int delayMs)
        {
            if (_isDisposing || this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (!_isDisposing && !this.IsDisposed) RequestAutomaticUpdateCheck(delayMs);
                });
            }
            catch {}
        }

        private void RequestAutomaticUpdateCheck(int delayMs)
        {
            if (_isDisposing || this.IsDisposed || _autoUpdateTimer == null) return;
            if (_autoUpdateCheckInProgress)
            {
                _autoUpdateCheckRequested = true;
                if (delayMs < _autoUpdateRequestedDelayMs) _autoUpdateRequestedDelayMs = delayMs;
                return;
            }

            int safeDelay = Math.Max(1000, delayMs);
            if (_autoUpdateTimer.Enabled && _autoUpdateTimer.Interval <= safeDelay) return;
            _autoUpdateTimer.Stop();
            _autoUpdateTimer.Interval = safeDelay;
            _autoUpdateTimer.Start();
        }

        private void CompleteAutomaticUpdateCheck(bool succeeded)
        {
            if (this.IsDisposed || _isDisposing) return;
            if (!this.IsHandleCreated)
            {
                _autoUpdateCheckInProgress = false;
                return;
            }
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (_isDisposing || this.IsDisposed) return;
                    _autoUpdateCheckInProgress = false;

                    int nextDelay;
                    if (succeeded)
                    {
                        _autoUpdateFailureCount = 0;
                        nextDelay = 15 * 60 * 1000; // Başarılı kontrolde 15 dakikada bir yenile
                    }
                    else
                    {
                        int[] retryDelays = new int[] { 60 * 1000, 3 * 60 * 1000, 10 * 60 * 1000, 15 * 60 * 1000 };
                        int retryIndex = Math.Min(_autoUpdateFailureCount, retryDelays.Length - 1);
                        nextDelay = retryDelays[retryIndex];
                        _autoUpdateFailureCount++;
                    }

                    if (_autoUpdateCheckRequested)
                    {
                        nextDelay = Math.Min(nextDelay, _autoUpdateRequestedDelayMs);
                        _autoUpdateCheckRequested = false;
                        _autoUpdateRequestedDelayMs = int.MaxValue;
                    }
                    RequestAutomaticUpdateCheck(nextDelay);
                });
            }
            catch
            {
                _autoUpdateCheckInProgress = false;
            }
        }

        private bool IsGoodbyeDpiForeground()
        {
            try
            {
                if (!this.Visible || this.WindowState == FormWindowState.Minimized) return false;
                IntPtr foregroundWindow = GetForegroundWindow();
                if (foregroundWindow == IntPtr.Zero) return false;
                uint foregroundProcessId;
                GetWindowThreadProcessId(foregroundWindow, out foregroundProcessId);
                using (Process currentProcess = Process.GetCurrentProcess())
                {
                    return foregroundProcessId == (uint)currentProcess.Id;
                }
            }
            catch { return false; }
        }

