        private const string AppSettingsRegistryKey = @"Software\GoodbyeDPI_Pro_MAX";
        private const string LegacyAppSettingsRegistryKey = @"Software\GoodbyeDPI_Turkey";
        private const string ProfileRegistryValue = "SelectedProfile";
        private const string BestBenchmarkProfileRegistryValue = "BestBenchmarkProfile";
        private const string UserManualIspRegistryValue = "UserManualIspOverrideV2";
        private const string AutoScanCompletedRegistryValue = "SmartAutoScanCompletedV2";
        private const string DnsRegistryValue = "SelectedDns";
        private const string MinimizeToTrayRegistryValue = "MinimizeToTray";
        private const string LastVerifiedOverrideArgsRegistryValue = "LastVerifiedOverrideArgs";
        private const string LastVerifiedOverrideGatewayRegistryValue = "LastVerifiedOverrideGateway";
        private const string LastVerifiedOverrideProfileRegistryValue = "LastVerifiedOverrideProfile";
        private bool _isAutoScanCompleted = false;
        private volatile bool _startProtectionAfterBenchmark = false;
        private static readonly object _gatewayFpSync = new object();
        private static string _cachedGatewayFingerprint = null;
        private static DateTime _cachedGatewayFingerprintUtc = DateTime.MinValue;

        internal static void InvalidateGatewayFingerprintCache()
        {
            lock (_gatewayFpSync)
            {
                _cachedGatewayFingerprint = null;
                _cachedGatewayFingerprintUtc = DateTime.MinValue;
            }
        }

        // Aktif fiziksel bağdaştırıcının IPv4 ağ geçidi ve arayüz parmak izini döndürür.
        // Ağ değiştiğinde (ör. ev Ethernet'inden mobil erişim noktasına geçiş) kalıcı desync
        // önbelleğinin yalnızca eşleşen ağda devreye girmesini sağlar. 10 sn bellekte tutulur.
        private static string GetActiveGatewayFingerprint()
        {
            DateTime now = DateTime.UtcNow;
            lock (_gatewayFpSync)
            {
                if (!string.IsNullOrEmpty(_cachedGatewayFingerprint) &&
                    (now - _cachedGatewayFingerprintUtc).TotalSeconds < 10.0)
                {
                    return _cachedGatewayFingerprint;
                }
            }

            string resolvedFp = "default-gw";
            try
            {
                NetworkInterface[] adapters = NetworkInterface.GetAllNetworkInterfaces();
                if (adapters != null)
                {
                    for (int i = 0; i < adapters.Length; i++)
                    {
                        NetworkInterface nic = adapters[i];
                        if (!IsPhysicalNetworkAdapter(nic)) continue;
                        IPInterfaceProperties props = nic.GetIPProperties();
                        if (props == null || props.GatewayAddresses == null) continue;
                        foreach (GatewayIPAddressInformation gw in props.GatewayAddresses)
                        {
                            if (gw != null && gw.Address != null &&
                                gw.Address.AddressFamily == AddressFamily.InterNetwork &&
                                !IPAddress.Any.Equals(gw.Address))
                            {
                                resolvedFp = (nic.Id ?? nic.Name ?? "nic") + "|" + gw.Address.ToString();
                                break;
                            }
                        }
                        if (!string.Equals(resolvedFp, "default-gw", StringComparison.Ordinal)) break;
                    }
                }
            }
            catch {}

            lock (_gatewayFpSync)
            {
                _cachedGatewayFingerprint = resolvedFp;
                _cachedGatewayFingerprintUtc = now;
            }
            return resolvedFp;
        }

        private static void SaveVerifiedOverrideTemplate(int profileIndex, string gatewayFingerprint, string templateArgs)
        {
            if (string.IsNullOrEmpty(templateArgs) || !templateArgs.Contains("{0}")) return;
            try
            {
                using (RegistryKey key = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                {
                    if (key != null)
                    {
                        key.SetValue(LastVerifiedOverrideProfileRegistryValue, profileIndex, RegistryValueKind.DWord);
                        key.SetValue(LastVerifiedOverrideGatewayRegistryValue, gatewayFingerprint ?? "default-gw", RegistryValueKind.String);
                        key.SetValue(LastVerifiedOverrideArgsRegistryValue, templateArgs, RegistryValueKind.String);
                    }
                }
            }
            catch {}
        }

        private static bool TryLoadVerifiedOverrideTemplate(int profileIndex, string gatewayFingerprint, out string templateArgs)
        {
            templateArgs = null;
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false))
                {
                    if (key == null) return false;
                    object profObj = key.GetValue(LastVerifiedOverrideProfileRegistryValue);
                    object gwObj = key.GetValue(LastVerifiedOverrideGatewayRegistryValue);
                    object argsObj = key.GetValue(LastVerifiedOverrideArgsRegistryValue);
                    if (!(profObj is int) || (int)profObj != profileIndex) return false;
                    string savedGw = gwObj != null ? gwObj.ToString() : "";
                    if (!string.Equals(savedGw, gatewayFingerprint ?? "default-gw", StringComparison.OrdinalIgnoreCase)) return false;
                    string savedArgs = argsObj != null ? argsObj.ToString().Trim() : "";
                    if (string.IsNullOrEmpty(savedArgs) || !savedArgs.Contains("{0}")) return false;
                    templateArgs = savedArgs;
                    return true;
                }
            }
            catch {}
            return false;
        }

        private static void ClearVerifiedOverrideTemplate()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, true))
                {
                    if (key != null)
                    {
                        try { key.DeleteValue(LastVerifiedOverrideArgsRegistryValue, false); } catch {}
                        try { key.DeleteValue(LastVerifiedOverrideGatewayRegistryValue, false); } catch {}
                        try { key.DeleteValue(LastVerifiedOverrideProfileRegistryValue, false); } catch {}
                    }
                }
            }
            catch {}
        }

