        private int LoadSavedBestProfile()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false))
                {
                    if (key != null)
                    {
                        object val = key.GetValue(BestBenchmarkProfileRegistryValue);
                        if (val is int)
                        {
                            int idx = (int)val;
                            if (idx >= 0 && idx < _profiles.Count) return idx;
                        }
                    }
                }
            }
            catch {}
            return -1;
        }

        public void MarkBestIspProfile(int bestIdx, bool saveToRegistry = true)
        {
            if (_profiles == null || bestIdx < 0 || bestIdx >= _profiles.Count) return;
            for (int i = 0; i < _profiles.Count; i++)
            {
                bool isBest = (i == bestIdx);
                _profiles[i].IsBestForLine = isBest;
                _profiles[i].Tag = isBest ? "En İyi Profil" : "";
            }
            if (saveToRegistry)
            {
                try
                {
                    using (RegistryKey key = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                    {
                        if (key != null)
                        {
                            key.SetValue(BestBenchmarkProfileRegistryValue, bestIdx, RegistryValueKind.DWord);
                        }
                    }
                }
                catch {}
            }
            if (_selector != null && !_selector.IsDisposed)
            {
                _selector.IsAutoModePending = !_isAutoScanCompleted && !_userManuallySelectedIsp;
                _selector.IsAutoSelected = !_userManuallySelectedIsp;
                _selector.Invalidate();
            }
        }

        private int LoadSavedProfile()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false) ?? Registry.CurrentUser.OpenSubKey(LegacyAppSettingsRegistryKey, false))
                {
                    if (key != null)
                    {
                        object val = key.GetValue(ProfileRegistryValue);
                        if (val is int)
                        {
                            int idx = (int)val;
                            if (idx >= 0 && idx < _profiles.Count)
                            {
                                return idx;
                            }
                        }
                        if (val != null)
                        {
                            int parsed;
                            if (int.TryParse(val.ToString(), out parsed))
                            {
                                if (parsed >= 0 && parsed < _profiles.Count)
                                {
                                    return parsed;
                                }
                            }
                        }
                    }
                }
            }
            catch {}
            return 0; // Varsayılan: Türk Telekom (TTNet)
        }

        private void SaveSelectedProfile(int index)
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                {
                    if (key != null)
                    {
                        key.SetValue(ProfileRegistryValue, index, RegistryValueKind.DWord);
                        key.SetValue(UserManualIspRegistryValue, _userManuallySelectedIsp ? 1 : 0, RegistryValueKind.DWord);
                        object savedOverrideProf = key.GetValue(LastVerifiedOverrideProfileRegistryValue);
                        if (savedOverrideProf is int && (int)savedOverrideProf != index)
                        {
                            try { key.DeleteValue(LastVerifiedOverrideArgsRegistryValue, false); } catch {}
                            try { key.DeleteValue(LastVerifiedOverrideGatewayRegistryValue, false); } catch {}
                            try { key.DeleteValue(LastVerifiedOverrideProfileRegistryValue, false); } catch {}
                        }
                    }
                }
            }
            catch {}
        }

        // "Kapatıldığında tepsiye küçült" tercihi oturumlar arasında korunur; aksi hâlde
        // kullanıcı kapatsa bile bir sonraki açılışta yeniden "açık" olurdu.
        private bool LoadSavedMinimizeToTray()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false) ?? Registry.CurrentUser.OpenSubKey(LegacyAppSettingsRegistryKey, false))
                {
                    if (key != null)
                    {
                        object val = key.GetValue(MinimizeToTrayRegistryValue);
                        if (val is int) return ((int)val) != 0;
                        if (val != null)
                        {
                            int parsed;
                            if (int.TryParse(val.ToString(), out parsed)) return parsed != 0;
                        }
                    }
                }
            }
            catch {}
            return true; // Varsayılan: kapatınca tepsiye küçült
        }

