        private AppTheme LoadSavedTheme()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false) ?? Registry.CurrentUser.OpenSubKey(LegacyAppSettingsRegistryKey, false))
                {
                    if (key != null)
                    {
                        object val = key.GetValue(ThemeRegistryValue);
                        if (val is int)
                        {
                            int tVal = (int)val;
                            if (Enum.IsDefined(typeof(AppTheme), tVal))
                                return (AppTheme)tVal;
                        }
                        if (val != null)
                        {
                            int parsed;
                            if (int.TryParse(val.ToString(), out parsed))
                            {
                                if (Enum.IsDefined(typeof(AppTheme), parsed))
                                    return (AppTheme)parsed;
                            }
                        }
                    }
                }
            }
            catch {}
            return AppTheme.NightBlue;
        }

