        private void ApplyTheme(AppTheme theme, bool save)
        {
            _currentTheme = theme;
            ActiveTheme = theme;
            if (save) SaveSelectedTheme((int)theme);

            ThemePalette p = ThemePalette.Get(theme);
            this.BackColor = p.FormBg;
            this.ForeColor = p.TextPrimary;

            if (_titleBar != null && !_titleBar.IsDisposed)
            {
                _titleBar.BackColor = p.HeaderBg;
                _titleBar.Invalidate();
            }

            if (_headerPanel != null && !_headerPanel.IsDisposed)
            {
                _headerPanel.BackColor = p.HeaderBg;
                _headerPanel.Invalidate();
            }

            if (_lblSectionIsp != null && !_lblSectionIsp.IsDisposed)
            {
                _lblSectionIsp.ForeColor = p.TextMuted;
            }

            if (_btnToggle != null && !_btnToggle.IsDisposed)
            {
                if (!_isRunning)
                {
                    _btnToggle.BackColor = p.PrimaryAccent;
                    _btnToggle.HoverColor = p.PrimaryHover;
                    _btnToggle.BorderColor = p.BorderColor;
                    _btnToggle.HoverBorderColor = p.BorderHoverColor;
                    _btnToggle.GlowColor = p.GlowColor;
                }
                _btnToggle.Invalidate();
            }

            RoundedButton[] quickTools = new RoundedButton[] { _btnOpenWhitelist, _btnOptimizeGamingPing, _btnRepairNetworkAndDiscord, _btnDiagnostics };
            for (int i = 0; i < quickTools.Length; i++)
            {
                RoundedButton btn = quickTools[i];
                if (btn != null && !btn.IsDisposed)
                {
                    btn.BackColor = p.CardBg;
                    btn.HoverColor = p.CardHover;
                    btn.BorderColor = p.BorderColor;
                    btn.HoverBorderColor = p.BorderHoverColor;
                    btn.GlowColor = p.GlowColor;
                    btn.BackdropColor = p.FormBg;
                    btn.ForeColor = p.TextPrimary;
                    btn.Invalidate();
                }
            }

            if (_selector != null && !_selector.IsDisposed) _selector.Invalidate();
            if (_dnsSelector != null && !_dnsSelector.IsDisposed)
            {
                _dnsSelector.EffectiveDnsIndex = GetEffectiveDnsIndex();
                _dnsSelector.Invalidate();
            }

            if (_pnlSettings != null && !_pnlSettings.IsDisposed)
            {
                _pnlSettings.BackColor = p.FormBg;
                _pnlSettings.Invalidate(true);
            }

            if (_lblCredit != null && !_lblCredit.IsDisposed)
            {
                _lblCredit.BackColor = p.FormBg;
                _lblCredit.ForeColor = p.TextMuted;
            }

            this.Invalidate(true);
        }

