        public class ThemeMenuItem : ToolStripMenuItem
        {
            public Color SwatchColor { get; set; }
            public bool IsCurrentTheme { get; set; }

            public ThemeMenuItem(string text, Color swatch, bool isCurrent) : base(text)
            {
                this.SwatchColor = swatch;
                this.IsCurrentTheme = isCurrent;
            }
        }

        private void ShowThemeMenu()
        {
            if (this.IsDisposed || _isDisposing) return;

            // Toggle behavior: if already open, cleanly close and do not reopen
            if (_themeMenu != null && _themeMenu.Visible)
            {
                _lastThemeMenuCloseTime = DateTime.UtcNow;
                _themeMenu.Close();
                return;
            }

            // Debounce rapid double-click reopening
            if ((DateTime.UtcNow - _lastThemeMenuCloseTime).TotalMilliseconds < 250)
            {
                return;
            }

            // Mark theme feature as discovered so aggressive heartbeat beacon turns off
            if (!_isThemeDiscovered)
            {
                _isThemeDiscovered = true;
                SaveThemeDiscovered(true);
                if (_themePulseTimer != null)
                {
                    _themePulseTimer.Stop();
                    _themePulseTimer.Dispose();
                    _themePulseTimer = null;
                }
                if (_btnTheme != null && !_btnTheme.IsDisposed)
                {
                    _btnTheme.HeartbeatActive = false;
                }
            }

            if (_themeMenu == null)
            {
                _themeMenu = new ContextMenuStrip();
                _themeMenu.Renderer = new ModernThemeMenuRenderer();
                _themeMenu.ShowImageMargin = false;
                _themeMenu.ShowCheckMargin = false;
                _themeMenu.BackColor = ThemePalette.Get(ActiveTheme).FormBg;
                _themeMenu.ForeColor = ThemePalette.Get(ActiveTheme).TextPrimary;
                _themeMenu.Padding = new Padding(0, 4, 0, 4);
                _themeMenu.Font = new Font("Segoe UI", 10.5F, FontStyle.Regular);
                _themeMenu.AutoSize = false;

                AppTheme[] allThemes = new AppTheme[]
                {
                    AppTheme.NightBlue,
                    AppTheme.EmeraldOled,
                    AppTheme.CyberRed,
                    AppTheme.Pink,
                    AppTheme.Purple,
                    AppTheme.Black
                };

                const int itemWidth = 180;
                const int itemHeight = 35;
                _themeMenu.Size = new Size(itemWidth, (allThemes.Length * itemHeight) + 8);
                _themeMenu.DropShadowEnabled = true;

                _themeMenu.Closed += delegate
                {
                    _lastThemeMenuCloseTime = DateTime.UtcNow;
                };

                for (int i = 0; i < allThemes.Length; i++)
                {
                    AppTheme t = allThemes[i];
                    ThemePalette pal = ThemePalette.Get(t);
                    bool isCurrent = (_currentTheme == t);

                    string label = (t == AppTheme.NightBlue)
                        ? "Varsay\u0131lan"
                        : pal.Name.Replace("Koyu ", String.Empty).Replace(" (Varsay\u0131lan)", String.Empty);

                    ThemeMenuItem item = new ThemeMenuItem(label, pal.SecondaryAccent, isCurrent);
                    item.Height = itemHeight;
                    item.AutoSize = false;
                    item.Width = itemWidth;
                    item.Margin = Padding.Empty;
                    item.Padding = Padding.Empty;
                    item.Tag = t;
                    item.Click += delegate(object s, EventArgs e)
                    {
                        ThemeMenuItem clicked = s as ThemeMenuItem;
                        if (clicked != null && clicked.Tag is AppTheme)
                        {
                            AppTheme selectedT = (AppTheme)clicked.Tag;
                            ApplyTheme(selectedT, true);
                            ThemePalette sp = ThemePalette.Get(selectedT);
                            ToastNotification.Show("Tema De\u011fi\u015fti", sp.Name + " temas\u0131 aktif.", ToastType.Info, 2500);
                        }
                    };
                    _themeMenu.Items.Add(item);
                }
            }
            else
            {
                // Açılır menüde seçili temayı güncel tut.
                foreach (ToolStripItem itm in _themeMenu.Items)
                {
                    ThemeMenuItem tItem = itm as ThemeMenuItem;
                    if (tItem != null && tItem.Tag is AppTheme)
                    {
                        AppTheme t = (AppTheme)tItem.Tag;
                        tItem.IsCurrentTheme = (_currentTheme == t);
                        tItem.SwatchColor = ThemePalette.Get(t).SecondaryAccent;
                    }
                }
            }

            ThemePalette menuPalette = ThemePalette.Get(ActiveTheme);
            _themeMenu.BackColor = menuPalette.FormBg;
            _themeMenu.ForeColor = menuPalette.TextPrimary;
            ResizeThemeMenuToContent();

            // Pop up positioned cleanly under the theme button, safely inside form and screen bounds
            Point pt;
            if (_btnTheme != null && !_btnTheme.IsDisposed)
            {
                int popupX = _btnTheme.Width - _themeMenu.Width;
                pt = _btnTheme.PointToScreen(new Point(popupX, _btnTheme.Height + 4));
            }
            else
            {
                pt = this.PointToScreen(new Point(this.Width - _themeMenu.Width - 16, 36));
            }

            try
            {
                Screen scr = Screen.FromPoint(pt);
                Rectangle workArea = scr.WorkingArea;
                if (pt.X < workArea.Left + 4) pt.X = workArea.Left + 4;
                if (pt.X + _themeMenu.Width > workArea.Right - 4) pt.X = workArea.Right - _themeMenu.Width - 4;
                if (pt.Y + _themeMenu.Height > workArea.Bottom - 4)
                {
                    pt.Y = (_btnTheme != null && !_btnTheme.IsDisposed)
                        ? _btnTheme.PointToScreen(Point.Empty).Y - _themeMenu.Height - 4
                        : workArea.Bottom - _themeMenu.Height - 4;
                }
            }
            catch {}

            _themeMenu.Show(pt);
        }

        private void ResizeThemeMenuToContent()
        {
            if (_themeMenu == null || _themeMenu.IsDisposed || _themeMenu.Items.Count == 0) return;

            int itemWidth = 180;
            int itemHeight = Math.Max(35, _themeMenu.Font.Height + 12);
            using (Font selectedFont = new Font("Segoe UI Semibold", _themeMenu.Font.SizeInPoints, FontStyle.Regular))
            {
                itemHeight = Math.Max(itemHeight, selectedFont.Height + 12);
                foreach (ToolStripItem item in _themeMenu.Items)
                {
                    TextFormatFlags flags = TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine;
                    Size labelSize = TextRenderer.MeasureText(item.Text, _themeMenu.Font, Size.Empty, flags);
                    Size selectedSize = TextRenderer.MeasureText(item.Text, selectedFont, Size.Empty, flags);
                    itemWidth = Math.Max(itemWidth, Math.Max(labelSize.Width, selectedSize.Width) + 80);
                }
            }
            _themeMenu.Padding = new Padding(0, 4, 0, 4);
            foreach (ToolStripItem item in _themeMenu.Items)
            {
                item.Width = itemWidth;
                item.Height = itemHeight;
                item.Margin = Padding.Empty;
                item.Padding = Padding.Empty;
            }
            _themeMenu.Size = new Size(itemWidth, (_themeMenu.Items.Count * itemHeight) + 8);
        }

        private bool LoadSavedAutoFailover()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false) ?? Registry.CurrentUser.OpenSubKey(LegacyAppSettingsRegistryKey, false))
                {
                    if (key != null)
                    {
                        object val = key.GetValue(AutoFailoverRegistryValue);
                        if (val is int) return ((int)val) != 0;
                        if (val != null)
                        {
                            int parsed;
                            if (int.TryParse(val.ToString(), out parsed)) return parsed != 0;
                        }
                    }
                }
            }
            catch {}
            return true; // Varsayılan: Aktif
        }

        private void SaveAutoFailoverEnabled(bool enabled)
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                {
                    if (key != null)
                    {
                        key.SetValue(AutoFailoverRegistryValue, enabled ? 1 : 0, RegistryValueKind.DWord);
                    }
                }
            }
            catch {}
        }

        private string GetWatchdogHistoryValueName(IspProfile profile)
        {
            return "WatchdogProfileHistoryV1_" + profile.Id.ToString(CultureInfo.InvariantCulture);
        }

        private void EnsureWatchdogProfileHistoryLoaded()
        {
            lock (_watchdogHistorySync)
            {
                if (_watchdogHistoryLoaded) return;
                _watchdogHistoryLoaded = true;
                if (_profiles == null) return;

                try
                {
                    using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false))
                    {
                        for (int i = 0; i < _profiles.Count; i++)
                        {
                            IspProfile profile = _profiles[i];
                            if (profile == null) continue;
                            List<WatchdogProfileSample> samples = new List<WatchdogProfileSample>();
                            object stored = key == null ? null : key.GetValue(GetWatchdogHistoryValueName(profile));
                            string raw = stored == null ? null : stored.ToString();
                            if (!string.IsNullOrEmpty(raw))
                            {
                                string[] parts = raw.Split('|');
                                if (parts.Length == 3 && parts[0] == "v1")
                                {
                                    string storedName = Encoding.UTF8.GetString(Convert.FromBase64String(parts[1]));
                                    if (string.Equals(storedName, profile.Name, StringComparison.Ordinal))
                                    {
                                        string[] entries = parts[2].Split(';');
                                        for (int j = 0; j < entries.Length; j++)
                                        {
                                            string[] values = entries[j].Split(',');
                                            long ticks;
                                            long latency;
                                            if (values.Length != 3 || !long.TryParse(values[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out ticks) ||
                                                !long.TryParse(values[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out latency) ||
                                                ticks <= 0 || ticks > DateTime.UtcNow.AddMinutes(5).Ticks) continue;

                                            bool succeeded = values[1] == "S" && latency >= 0;
                                            if (!succeeded && values[1] != "F") continue;
                                            if (succeeded && latency > WatchdogMaximumSampleLatencyMs) continue;
                                            if (!succeeded) latency = -1;
                                            if (DateTime.UtcNow.Ticks - ticks > TimeSpan.FromDays(WatchdogHistoryMaxAgeDays).Ticks) continue;
                                            samples.Add(new WatchdogProfileSample { UtcTicks = ticks, Succeeded = succeeded, GatewayProbeElapsedMs = latency });
                                        }
                                    }
                                }
                            }
                            samples.Sort(delegate(WatchdogProfileSample left, WatchdogProfileSample right)
                            {
                                return left.UtcTicks.CompareTo(right.UtcTicks);
                            });
                            while (samples.Count > WatchdogHistoryMaxSamples) samples.RemoveAt(0);
                            _watchdogProfileHistory[profile.Id] = samples;
                        }
                    }
                }
                catch (Exception ex)
                {
                    AppLogger.Log("WATCHDOG", "Yerel profil geçmişi okunamadı; bu oturum yeni örneklerle başlayacak: " + ex.Message, LogLevel.Warn);
                }
            }
        }

        private void SaveWatchdogProfileHistoryLocked(IspProfile profile, List<WatchdogProfileSample> samples)
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                {
                    if (key == null) return;
                    StringBuilder value = new StringBuilder();
                    value.Append("v1|");
                    value.Append(Convert.ToBase64String(Encoding.UTF8.GetBytes(profile.Name ?? "")));
                    value.Append('|');
                    for (int i = 0; i < samples.Count; i++)
                    {
                        if (i > 0) value.Append(';');
                        value.Append(samples[i].UtcTicks.ToString(CultureInfo.InvariantCulture));
                        value.Append(',');
                        value.Append(samples[i].Succeeded ? 'S' : 'F');
                        value.Append(',');
                        value.Append(samples[i].GatewayProbeElapsedMs.ToString(CultureInfo.InvariantCulture));
                    }
                    key.SetValue(GetWatchdogHistoryValueName(profile), value.ToString(), RegistryValueKind.String);
                }
            }
            catch (Exception ex)
            {
                AppLogger.Log("WATCHDOG", "Yerel profil geçmişi kaydedilemedi: " + ex.Message, LogLevel.Warn);
            }
        }

        private void RecordWatchdogProfileSample(int profileIndex, bool succeeded, long gatewayProbeElapsedMs)
        {
            if (_profiles == null || profileIndex < 0 || profileIndex >= _profiles.Count) return;
            if (succeeded != (gatewayProbeElapsedMs >= 0)) return;
            EnsureWatchdogProfileHistoryLoaded();

            lock (_watchdogHistorySync)
            {
                IspProfile profile = _profiles[profileIndex];
                if (profile == null) return;
                List<WatchdogProfileSample> samples;
                if (!_watchdogProfileHistory.TryGetValue(profile.Id, out samples))
                {
                    samples = new List<WatchdogProfileSample>();
                    _watchdogProfileHistory[profile.Id] = samples;
                }

                long nowTicks = DateTime.UtcNow.Ticks;
                samples.RemoveAll(delegate(WatchdogProfileSample sample)
                {
                    return sample == null || sample.UtcTicks <= 0 || nowTicks - sample.UtcTicks > TimeSpan.FromDays(WatchdogHistoryMaxAgeDays).Ticks;
                });
                samples.Add(new WatchdogProfileSample { UtcTicks = nowTicks, Succeeded = succeeded, GatewayProbeElapsedMs = succeeded ? gatewayProbeElapsedMs : -1 });
                while (samples.Count > WatchdogHistoryMaxSamples) samples.RemoveAt(0);
                SaveWatchdogProfileHistoryLocked(profile, samples);
            }
        }

        private WatchdogProfileStats GetWatchdogProfileStats(IspProfile profile)
        {
            WatchdogProfileStats stats = new WatchdogProfileStats();
            if (profile == null) return stats;
            EnsureWatchdogProfileHistoryLoaded();

            lock (_watchdogHistorySync)
            {
                List<WatchdogProfileSample> samples;
                if (!_watchdogProfileHistory.TryGetValue(profile.Id, out samples) || samples == null) return stats;
                long cutoff = DateTime.UtcNow.AddHours(-WatchdogCandidateMaxAgeHours).Ticks;
                List<long> successfulLatencies = new List<long>();
                for (int i = 0; i < samples.Count; i++)
                {
                    WatchdogProfileSample sample = samples[i];
                    if (sample == null || sample.UtcTicks < cutoff) continue;
                    stats.SampleCount++;
                    if (sample.UtcTicks > stats.LatestSampleUtc.Ticks) stats.LatestSampleUtc = new DateTime(sample.UtcTicks, DateTimeKind.Utc);
                    if (sample.Succeeded && sample.GatewayProbeElapsedMs >= 0)
                    {
                        stats.SuccessCount++;
                        successfulLatencies.Add(sample.GatewayProbeElapsedMs);
                    }
                }
                if (stats.SampleCount > 0) stats.SuccessRatePercent = (stats.SuccessCount * 100) / stats.SampleCount;
                if (successfulLatencies.Count > 0)
                {
                    successfulLatencies.Sort();
                    int middle = successfulLatencies.Count / 2;
                    stats.MedianGatewayProbeElapsedMs = (successfulLatencies.Count % 2 == 1)
                        ? successfulLatencies[middle]
                        : successfulLatencies[middle - 1] +
                            ((successfulLatencies[middle] - successfulLatencies[middle - 1]) / 2);
                }
            }
            return stats;
        }

        private int SelectLearnedWatchdogProfile(int currentIndex, out WatchdogProfileStats selectedStats)
        {
            selectedStats = null;
            if (_profiles == null) return -1;
            int selected = -1;
            for (int i = 0; i < _profiles.Count; i++)
            {
                if (i == currentIndex) continue;
                IspProfile profile = _profiles[i];
                WatchdogProfileStats stats = GetWatchdogProfileStats(profile);
                if (stats.SampleCount < WatchdogMinimumCandidateSamples ||
                    stats.SuccessCount < WatchdogMinimumCandidateSuccesses ||
                    stats.SuccessRatePercent < 80 || stats.MedianGatewayProbeElapsedMs < 0 ||
                    stats.LatestSampleUtc == DateTime.MinValue ||
                    (DateTime.UtcNow - stats.LatestSampleUtc).TotalHours > WatchdogCandidateMaxAgeHours) continue;

                if (selected < 0 || stats.SuccessRatePercent > selectedStats.SuccessRatePercent ||
                    (stats.SuccessRatePercent == selectedStats.SuccessRatePercent && stats.MedianGatewayProbeElapsedMs < selectedStats.MedianGatewayProbeElapsedMs) ||
                    (stats.SuccessRatePercent == selectedStats.SuccessRatePercent && stats.MedianGatewayProbeElapsedMs == selectedStats.MedianGatewayProbeElapsedMs &&
                     stats.LatestSampleUtc > selectedStats.LatestSampleUtc))
                {
                    selected = i;
                    selectedStats = stats;
                }
            }
            return selected;
        }

        private bool IsWatchdogOperationCurrent(int expectedStamp, int profileIndex, int operationToken)
        {
            return !_isDisposing && !this.IsDisposed && !_isManualStop && _isRunning &&
                !_isSmartBenchmarkRunning && !_dnsPingScanRunning && !_isOperationRunning &&
                _engineOpStamp == expectedStamp && _selectedProfileIndex == profileIndex &&
                _watchdogFailoverOperationToken == operationToken;
        }

        // Arka planda periyodik DNS taraması (_dnsPingScanRunning) veya UI başlatma işlemi sürerken
        // motorun başlangıç doğrulamasının (VerifyAndFallbackProtectionAsync) ve RTC ses onarıcısının
        // yanlışlıkla iptal edilmesini önleyen bağlam denetimi.
        private bool IsEngineVerificationContextCurrent(int expectedStamp, int profileIndex, int operationToken)
        {
            return !_isDisposing && !this.IsDisposed && !_isManualStop && _isRunning &&
                !_isSmartBenchmarkRunning &&
                _engineOpStamp == expectedStamp && _selectedProfileIndex == profileIndex &&
                _watchdogFailoverOperationToken == operationToken;
        }

        private bool TrySetWatchdogProfileAndWait(int expectedProfileIndex, int targetProfileIndex, int expectedStamp,
            int operationToken, bool allowStoppedEngine, out int resultingStamp, out bool selectionApplied, out string error)
        {
            resultingStamp = expectedStamp;
            selectionApplied = false;
            error = null;
            if (_profiles == null || targetProfileIndex < 0 || targetProfileIndex >= _profiles.Count ||
                expectedProfileIndex < 0 || expectedProfileIndex >= _profiles.Count)
            {
                error = "Profil dizini geçersiz";
                return false;
            }
            if (_isDisposing || this.IsDisposed || !this.IsHandleCreated)
            {
                error = "Arayüz kapanıyor veya profil güncellemesi için hazır değil";
                return false;
            }

            DateTime previousStartUtc = _lastEngineStartUtc;
            object dispatchSync = new object();
            ManualResetEvent dispatchCompleted = new ManualResetEvent(false);
            bool dispatchCanceled = false;
            bool dispatchCallbackCompleted = false;
            bool dispatchCallerReturned = false;
            bool dispatchSelectionApplied = false;
            bool dispatchCallbackRan = false;
            string dispatchError = null;
            IAsyncResult uiCall = null;
            try
            {
                uiCall = this.BeginInvoke((MethodInvoker)delegate
                {
                    try
                    {
                        lock (dispatchSync)
                        {
                            if (dispatchCanceled) return;
                            dispatchCallbackRan = true;
                            if (_isDisposing || this.IsDisposed || _watchdogFailoverOperationToken != operationToken ||
                                _engineOpStamp != expectedStamp || _selectedProfileIndex != expectedProfileIndex ||
                                _isManualStop || _isOperationRunning || (!allowStoppedEngine && !_isRunning))
                            {
                                dispatchError = "Profil geçişi UI iş parçacığında güncel durum nedeniyle iptal edildi";
                                return;
                            }

                            _selectedProfileIndex = targetProfileIndex;
                            dispatchSelectionApplied = true;
                            try
                            {
                                UpdateIspMenuChecks();
                                if (_selector != null && !_selector.IsDisposed)
                                {
                                    _selector.Profile = _profiles[targetProfileIndex];
                                    _selector.Invalidate();
                                }
                                RestartProtectionAsync();
                            }
                            catch (Exception ex)
                            {
                                dispatchError = "Profil seçildi ancak yeniden başlatma isteği hata verdi: " + ex.Message;
                            }
                        }
                    }
                    finally
                    {
                        lock (dispatchSync)
                        {
                            dispatchCallbackCompleted = true;
                            try { dispatchCompleted.Set(); } catch {}
                            if (dispatchCallerReturned)
                            {
                                try { dispatchCompleted.Dispose(); } catch {}
                            }
                        }
                    }
                });

                bool callbackCompleted = dispatchCompleted.WaitOne(3000, true);
                lock (dispatchSync)
                {
                    dispatchCallerReturned = true;
                    if (dispatchCallbackCompleted) callbackCompleted = true;
                    if (!callbackCompleted) dispatchCanceled = true;
                    selectionApplied = dispatchSelectionApplied;
                    resultingStamp = _engineOpStamp;
                    if (dispatchCallbackCompleted)
                    {
                        try { dispatchCompleted.Dispose(); } catch {}
                    }
                }
                if (!callbackCompleted)
                {
                    error = "Profil güncellemesi UI sırasında zaman aşımına uğradı; sıradaki istek iptal edildi";
                    return false;
                }
                this.EndInvoke(uiCall);
            }
            catch (Exception ex)
            {
                lock (dispatchSync)
                {
                    dispatchCallerReturned = true;
                    dispatchCanceled = !dispatchCallbackCompleted;
                    selectionApplied = dispatchSelectionApplied;
                    resultingStamp = _engineOpStamp;
                    if (dispatchCallbackCompleted || uiCall == null)
                    {
                        try { dispatchCompleted.Dispose(); } catch {}
                    }
                }
                error = "Profil geçişi başlatılamadı: " + ex.Message;
                return false;
            }
            finally
            {
                if (uiCall == null)
                {
                    try { dispatchCompleted.Dispose(); } catch {}
                }
            }

            resultingStamp = _engineOpStamp;
            lock (dispatchSync)
            {
                selectionApplied = dispatchSelectionApplied;
                if (!string.IsNullOrEmpty(dispatchError)) error = dispatchError;
            }
            if (!dispatchCallbackRan || !selectionApplied || resultingStamp == expectedStamp)
            {
                if (string.IsNullOrEmpty(error)) error = "Motor yeniden başlatma isteği alınmadı";
                return false;
            }
            if (!string.IsNullOrEmpty(error))
            {
                return false;
            }

            Stopwatch wait = Stopwatch.StartNew();
            while (wait.ElapsedMilliseconds < 15000)
            {
                if (_isDisposing || this.IsDisposed || _isManualStop ||
                    _watchdogFailoverOperationToken != operationToken || _engineOpStamp != resultingStamp ||
                    _selectedProfileIndex != targetProfileIndex)
                {
                    error = "Profil geçişi kullanıcı işlemi veya yeni motor nesli nedeniyle iptal edildi";
                    return false;
                }
                if (_lastEngineStartUtc > previousStartUtc && _isRunning && _dpiProcess != null)
                {
                    try
                    {
                        if (!_dpiProcess.HasExited) return true;
                    }
                    catch {}
                }
                Thread.Sleep(75);
            }
            error = "Yeni profille motor başlangıcı 15 saniye içinde doğrulanamadı";
            return false;
        }

        private void ShowVerifiedWatchdogProfileToast(string profileName)
        {
            if (_isDisposing || this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (_isDisposing || this.IsDisposed) return;
                    ToastNotification.Show("Profil De\u011fi\u015fti",
                        string.Format("{0} profiline ge\u00e7ildi.", profileName), ToastType.Success, 3500);
                });
            }
            catch {}
        }

        private void PersistVerifiedWatchdogProfile(int profileIndex, int expectedStamp)
        {
            if (_isDisposing || this.IsDisposed || !this.IsHandleCreated || _profiles == null ||
                profileIndex < 0 || profileIndex >= _profiles.Count) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (_isDisposing || this.IsDisposed || !_isRunning || _isManualStop ||
                        _engineOpStamp != expectedStamp || _selectedProfileIndex != profileIndex) return;
                    SaveSelectedProfile(profileIndex);
                });
            }
            catch {}
        }

        private void RunVerifiedWatchdogFailover(WatchdogProbeSnapshot evidence)
        {
            if (!_autoFailoverEnabled || evidence == null || !evidence.IsGatewaySpecificFailure ||
                !_isRunning || _isFailoverRunning || _isDisposing || this.IsDisposed ||
                _isOperationRunning || _isSmartBenchmarkRunning || _dnsPingScanRunning) return;
            if ((DateTime.UtcNow - _lastFailoverTime).TotalSeconds < 45) return;
            if (!IsWatchdogOperationCurrent(evidence.OperationStamp, evidence.ProfileIndex, _watchdogFailoverOperationToken)) return;

            _isFailoverRunning = true;
            _lastFailoverTime = DateTime.UtcNow;
            int operationToken = Interlocked.Increment(ref _watchdogFailoverOperationToken);
            int originalIndex = evidence.ProfileIndex;
            int candidateIndex = -1;
            int trialStamp = evidence.OperationStamp;
            string transitionError = null;
            bool selectionApplied = false;
            bool candidateVerified = false;
            bool rollbackVerified = false;
            bool interventionRecorded = false;
            WatchdogProfileStats candidateStats = null;
            Stopwatch interventionTimer = Stopwatch.StartNew();

            try
            {
                candidateIndex = SelectLearnedWatchdogProfile(originalIndex, out candidateStats);
                if (candidateIndex >= 0)
                {
                    AppLogger.Log("FAILOVER", string.Format(
                        "Doğrulanmış geçiş adayı: {0}; {1} örnek, başarı %{2}, gateway uçtan uca bağlantı/TLS süresi medyanı {3} ms. Bu ölçüm ses UDP kalitesini anlatmaz.",
                        _profiles[candidateIndex].Name, candidateStats.SampleCount, candidateStats.SuccessRatePercent,
                        candidateStats.MedianGatewayProbeElapsedMs), LogLevel.Info);
                }
                else if (_profiles != null && _profiles.Count > 1)
                {
                    candidateIndex = (originalIndex + 1) % _profiles.Count;
                    AppLogger.Log("FAILOVER", string.Format(
                        "Yeterli yerel profil örneği yok; {0} yalnızca ölçülmemiş uyumluluk denemesi olarak seçiliyor, en iyi olduğu iddia edilmiyor.",
                        _profiles[candidateIndex].Name), LogLevel.Warn);
                }

                if (candidateIndex < 0 || candidateIndex >= _profiles.Count || candidateIndex == originalIndex)
                {
                    AppLogger.Log("FAILOVER", "Geçiş adayı bulunamadı; profil sırası başarı kanıtı sayılmadı.", LogLevel.Warn);
                    AppHealthMetrics.RecordWatchdogUnknown();
                    return;
                }

                IspProfile candidate = _profiles[candidateIndex];
                AppHealthMetrics.RecordWatchdogTrigger();
                AppLogger.Log("FAILOVER", string.Format("Gateway uçtan uca bağlantı/TLS yolunu doğrulama denemesi başlıyor: {0} -> {1}.",
                    _profiles[originalIndex].Name, candidate.Name), LogLevel.Info);

                bool started = TrySetWatchdogProfileAndWait(originalIndex, candidateIndex, evidence.OperationStamp,
                    operationToken, false, out trialStamp, out selectionApplied, out transitionError);
                if (!started)
                {
                    if (selectionApplied && _engineOpStamp == trialStamp && _selectedProfileIndex == candidateIndex && !_isManualStop)
                    {
                        int rollbackStamp;
                        bool rollbackApplied;
                        string rollbackError;
                        bool transitionRollbackStarted = TrySetWatchdogProfileAndWait(candidateIndex, originalIndex, trialStamp,
                            operationToken, true, out rollbackStamp, out rollbackApplied, out rollbackError);
                        if (!transitionRollbackStarted)
                        {
                            transitionError += rollbackApplied ? "; profil seçimi geri alındı ancak motor başlangıcı doğrulanmadı" : ("; geri alma: " + (rollbackError ?? "başlatılamadı"));
                        }
                    }
                    AppHealthMetrics.RecordWatchdogIntervention(false, false, interventionTimer.ElapsedMilliseconds);
                    interventionRecorded = true;
                    AppLogger.Log("FAILOVER", "Profil denemesi başlamadı veya iptal edildi; kullanıcı durdurma/ayar değişikliği korunuyor. " + (transitionError ?? ""), LogLevel.Warn);
                    return;
                }

                Thread.Sleep(650);
                if (!IsWatchdogOperationCurrent(trialStamp, candidateIndex, operationToken)) return;
                string candidateDnsServer;
                int candidateDnsPort;
                long candidateDnsMs;
                string candidateDnsError;
                int candidateDnsStatus = ProbeActiveDns("gateway.discord.gg", out candidateDnsServer, out candidateDnsPort,
                    out candidateDnsMs, out candidateDnsError);
                if (!IsWatchdogOperationCurrent(trialStamp, candidateIndex, operationToken)) return;
                string firstError = candidateDnsStatus == 1 ? null :
                    (candidateDnsStatus < 0 ? "aday DNS yanıtı şüpheli" : (candidateDnsError ?? "aday DNS doğrulanamadı"));
                string secondError = firstError;
                long firstTlsMs = -1;
                long secondTlsMs = -1;
                if (candidateDnsStatus == 1)
                {
                    firstTlsMs = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out firstError);
                    if (!IsWatchdogOperationCurrent(trialStamp, candidateIndex, operationToken)) return;
                    Thread.Sleep(350);
                    secondTlsMs = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out secondError);
                    if (!IsWatchdogOperationCurrent(trialStamp, candidateIndex, operationToken)) return;
                }

                if (firstTlsMs >= 0 && secondTlsMs >= 0)
                {
                    long medianTlsMs = Math.Min(firstTlsMs, secondTlsMs) +
                        (Math.Max(firstTlsMs, secondTlsMs) - Math.Min(firstTlsMs, secondTlsMs)) / 2;
                    RecordWatchdogProfileSample(candidateIndex, true, medianTlsMs);
                    Interlocked.Exchange(ref _connFailStrikes, 0);
                    _consecutiveDropCount = 0;
                    candidateVerified = true;
                    PersistVerifiedWatchdogProfile(candidateIndex, trialStamp);
                    AppHealthMetrics.RecordWatchdogIntervention(true, false, interventionTimer.ElapsedMilliseconds);
                    interventionRecorded = true;
                    AppLogger.Log("FAILOVER", string.Format(
                        "Profil geçişi doğrulandı: etkin DNS yanıtı geçerli, gateway bağlantı/TLS probu iki kez başarılı ({0} ms, {1} ms; örnek medyanı {2} ms). Bu sonuç Discord ses UDP kalitesini doğrulamaz.",
                        firstTlsMs, secondTlsMs, medianTlsMs), LogLevel.Info);
                    ShowVerifiedWatchdogProfileToast(candidate.Name);
                    return;
                }

                string failureControls = "iki gateway bağlantı/TLS ölçümü de başarısız değil; aday sonucu tutarsız";
                bool candidateFailureConfirmed = false;
                if (candidateDnsStatus == 1 && firstTlsMs < 0 && secondTlsMs < 0)
                {
                    candidateFailureConfirmed = TryConfirmGatewaySpecificFailure(trialStamp, candidateIndex, out failureControls);
                }
                if (candidateFailureConfirmed) RecordWatchdogProfileSample(candidateIndex, false, -1);
                AppLogger.Log("FAILOVER", string.Format(
                    "Aday profil doğrulanamadı (etkin DNS={0}:{1} {2}; gateway bağlantı/TLS {3}/{4}; hedef hata: {5}; sınıflandırma: {6}). Önceki profil geri yükleniyor.",
                    candidateDnsServer ?? "?", candidateDnsPort,
                    candidateDnsStatus == 1 ? candidateDnsMs + " ms geçerli" : (candidateDnsStatus < 0 ? "şüpheli" : "belirsiz"),
                    firstTlsMs < 0 ? "başarısız" : firstTlsMs + " ms", secondTlsMs < 0 ? "başarısız" : secondTlsMs + " ms",
                    secondError ?? firstError ?? candidateDnsError ?? "bilinmiyor",
                    candidateFailureConfirmed ? failureControls : "belirsiz; öğrenme örneği kaydedilmedi"), LogLevel.Warn);

                int rollbackResultStamp;
                bool rollbackSelectionApplied;
                string rollbackFailure;
                bool rollbackStarted = TrySetWatchdogProfileAndWait(candidateIndex, originalIndex, trialStamp,
                    operationToken, true, out rollbackResultStamp, out rollbackSelectionApplied, out rollbackFailure);
                bool rollbackHealthy = false;
                if (rollbackStarted)
                {
                    Thread.Sleep(650);
                    if (IsWatchdogOperationCurrent(rollbackResultStamp, originalIndex, operationToken))
                    {
                        string rollbackDnsServer;
                        int rollbackDnsPort;
                        long rollbackDnsMs;
                        string rollbackDnsError;
                        int rollbackDnsStatus = ProbeActiveDns("gateway.discord.gg", out rollbackDnsServer, out rollbackDnsPort,
                            out rollbackDnsMs, out rollbackDnsError);
                        string rollbackError1 = rollbackDnsStatus == 1 ? null :
                            (rollbackDnsError ?? "geri alma etkin DNS doğrulanamadı");
                        string rollbackError2 = null;
                        long rollbackMs1 = -1;
                        long rollbackMs2 = -1;
                        if (rollbackDnsStatus == 1 && IsWatchdogOperationCurrent(rollbackResultStamp, originalIndex, operationToken))
                        {
                            rollbackMs1 = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out rollbackError1);
                            rollbackMs2 = IsWatchdogOperationCurrent(rollbackResultStamp, originalIndex, operationToken)
                                ? NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out rollbackError2)
                                : -1;
                        }
                        if (rollbackMs2 < 0 && rollbackError2 == null) rollbackError2 = "Geri alma denetimi iptal edildi";
                        rollbackHealthy = rollbackDnsStatus == 1 && rollbackMs1 >= 0 && rollbackMs2 >= 0;
                        if (rollbackHealthy)
                        {
                            long rollbackMedian = Math.Min(rollbackMs1, rollbackMs2) +
                                (Math.Max(rollbackMs1, rollbackMs2) - Math.Min(rollbackMs1, rollbackMs2)) / 2;
                            RecordWatchdogProfileSample(originalIndex, true, rollbackMedian);
                        }
                        rollbackVerified = rollbackHealthy;
                        AppLogger.Log("FAILOVER", rollbackHealthy
                            ? string.Format("Önceki profil geri yüklendi; etkin DNS {0}:{1} ({2} ms) ve gateway TLS iki kez doğrulandı.",
                                rollbackDnsServer, rollbackDnsPort, rollbackDnsMs)
                            : "Önceki profil yeniden başlatıldı ancak etkin DNS + gateway bağlantı/TLS doğrulanamadı: " + (rollbackError1 ?? rollbackError2 ?? "zaman aşımı"),
                            rollbackHealthy ? LogLevel.Info : LogLevel.Error);
                    }
                }
                else if (rollbackSelectionApplied || !string.IsNullOrEmpty(rollbackFailure))
                {
                    AppLogger.Log("FAILOVER", "Önceki profile güvenli dönüş tamamlanamadı: " + (rollbackFailure ?? "profil seçimi geri alındı ancak motor doğrulanamadı"), LogLevel.Error);
                }
                AppHealthMetrics.RecordWatchdogIntervention(false, rollbackHealthy, interventionTimer.ElapsedMilliseconds);
                interventionRecorded = true;
            }
            catch (Exception ex)
            {
                AppLogger.Log("FAILOVER", "Doğrulanmış profil geçişi sırasında hata: " + ex.Message, LogLevel.Error);
                try
                {
                    if (!candidateVerified && _profiles != null && candidateIndex >= 0 && candidateIndex < _profiles.Count &&
                        selectionApplied && _selectedProfileIndex == candidateIndex &&
                        IsWatchdogOperationCurrent(trialStamp, candidateIndex, operationToken))
                    {
                        int rollbackStamp;
                        bool catchRollbackSelectionApplied;
                        string rollbackError;
                        if (TrySetWatchdogProfileAndWait(candidateIndex, originalIndex, trialStamp, operationToken,
                            true, out rollbackStamp, out catchRollbackSelectionApplied, out rollbackError))
                        {
                            Thread.Sleep(650);
                            if (IsWatchdogOperationCurrent(rollbackStamp, originalIndex, operationToken))
                            {
                                string rollbackDnsServer;
                                int rollbackDnsPort;
                                long rollbackDnsMs;
                                string rollbackDnsError;
                                int rollbackDnsStatus = ProbeActiveDns("gateway.discord.gg", out rollbackDnsServer, out rollbackDnsPort,
                                    out rollbackDnsMs, out rollbackDnsError);
                                string rollbackError1 = rollbackDnsStatus == 1 ? null :
                                    (rollbackDnsError ?? "geri alma etkin DNS doğrulanamadı");
                                string rollbackError2 = null;
                                long rollbackMs1 = -1;
                                long rollbackMs2 = -1;
                                if (rollbackDnsStatus == 1 && IsWatchdogOperationCurrent(rollbackStamp, originalIndex, operationToken))
                                {
                                    rollbackMs1 = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out rollbackError1);
                                    rollbackMs2 = IsWatchdogOperationCurrent(rollbackStamp, originalIndex, operationToken)
                                        ? NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out rollbackError2)
                                        : -1;
                                }
                                if (rollbackMs2 < 0 && rollbackError2 == null) rollbackError2 = "geri alma denetimi iptal edildi";
                                rollbackVerified = rollbackDnsStatus == 1 && rollbackMs1 >= 0 && rollbackMs2 >= 0;
                                if (rollbackVerified)
                                {
                                    long rollbackMedian = Math.Min(rollbackMs1, rollbackMs2) +
                                        (Math.Max(rollbackMs1, rollbackMs2) - Math.Min(rollbackMs1, rollbackMs2)) / 2;
                                    RecordWatchdogProfileSample(originalIndex, true, rollbackMedian);
                                    AppLogger.Log("FAILOVER", string.Format("Hata sonrası önceki profil ve DNS {0}:{1} ({2} ms) doğrulandı.",
                                        rollbackDnsServer, rollbackDnsPort, rollbackDnsMs), LogLevel.Info);
                                }
                                else rollbackError = rollbackError1 ?? rollbackError2;
                            }
                        }
                        if (!rollbackVerified)
                        {
                            AppLogger.Log("FAILOVER", "Hata sonrası önceki profile geçişi doğrulanamadı: " +
                                (rollbackError ?? (catchRollbackSelectionApplied ? "profil seçimi geri alındı ancak motor doğrulanmadı" : "gateway bağlantı/TLS denetimi başarısız")), LogLevel.Error);
                        }
                    }
                }
                catch (Exception rollbackEx)
                {
                    AppLogger.Log("FAILOVER", "Hata sonrası geri alma sırasında ek hata: " + rollbackEx.Message, LogLevel.Error);
                }
                if (!interventionRecorded)
                {
                    AppHealthMetrics.RecordWatchdogIntervention(false, rollbackVerified, interventionTimer.ElapsedMilliseconds);
                    interventionRecorded = true;
                }
            }
            finally
            {
                Interlocked.Increment(ref _watchdogFailoverOperationToken);
                _isFailoverRunning = false;
            }
        }

        private bool TryGetActiveDnsProbeEndpoint(out string server, out int port)
        {
            server = null;
            port = 53;
            lock (_dnsMeasurementSync)
            {
                if (_dnsOptions == null || _dnsOptions.Count == 0) return false;
                int dnsIndex = _selectedDnsIndex > 0 ? _selectedDnsIndex : _activeDnsIndex;
                if (dnsIndex <= 0 || dnsIndex >= _dnsOptions.Count) return false;
                DnsOption option = _dnsOptions[dnsIndex];
                if (option == null || string.IsNullOrWhiteSpace(option.PingTargetIp)) return false;
                IPAddress parsedAddress;
                if (!IPAddress.TryParse(option.PingTargetIp.Trim(), out parsedAddress)) return false;

                server = parsedAddress.ToString();
                string args = option.DpiArgs ?? "";
                int portMarker = args.IndexOf("--dns-port", StringComparison.OrdinalIgnoreCase);
                if (portMarker >= 0)
                {
                    string tail = args.Substring(portMarker + "--dns-port".Length).Trim();
                    string[] values = tail.Split(new char[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                    int parsedPort;
                    if (values.Length == 0 || !int.TryParse(values[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out parsedPort) ||
                        parsedPort < 1 || parsedPort > 65535) return false;
                    port = parsedPort;
                }
                return true;
            }
        }

        private int ProbeActiveDns(string queryName, out string server, out int port, out long elapsedMs, out string error)
        {
            elapsedMs = -1;
            error = null;
            if (!TryGetActiveDnsProbeEndpoint(out server, out port))
            {
                error = "Etkin DNS sunucusu belirlenemedi";
                return 0;
            }

            int responseBytes;
            elapsedMs = NetworkProbe.TestUdpDns(server, port, 1200, queryName, out responseBytes, out error);
            if (elapsedMs >= 0 && responseBytes > 0) return 1;
            if (elapsedMs >= 0)
            {
                error = "DNS yanıt gövdesi boş";
                return 0;
            }
            if (elapsedMs == -3) return -1;
            return 0;
        }

        private bool TryConfirmGatewaySpecificFailure(int expectedStamp, int profileIndex, out string explanation)
        {
            explanation = "doğrulama tamamlanmadı";
            if (!IsEngineVerificationContextCurrent(expectedStamp, profileIndex, _watchdogFailoverOperationToken)) return false;

            string discordError;
            long discordSiteTlsMs = NetworkProbe.TestTlsHandshake("discord.com", 443, 2000, out discordError);
            if (!IsEngineVerificationContextCurrent(expectedStamp, profileIndex, _watchdogFailoverOperationToken)) return false;

            string tcpError;
            long tcpMs = NetworkProbe.TestTcpConnect("1.1.1.1", 443, 1000, out tcpError);
            long alternateTcpMs = -1;
            if (tcpMs < 0 && IsEngineVerificationContextCurrent(expectedStamp, profileIndex, _watchdogFailoverOperationToken))
            {
                alternateTcpMs = NetworkProbe.TestTcpConnect("8.8.8.8", 443, 1000, out tcpError);
            }
            if (!IsEngineVerificationContextCurrent(expectedStamp, profileIndex, _watchdogFailoverOperationToken)) return false;

            string dnsServer;
            int dnsPort;
            long dnsMs;
            string dnsError;
            int dnsStatus = ProbeActiveDns("gateway.discord.gg", out dnsServer, out dnsPort, out dnsMs, out dnsError);
            if (!IsEngineVerificationContextCurrent(expectedStamp, profileIndex, _watchdogFailoverOperationToken))
            {
                explanation = "doğrulama sırasında motor nesli veya kullanıcı işlemi değişti";
                return false;
            }
            bool tcpReachable = tcpMs >= 0 || alternateTcpMs >= 0;
            bool confirmed = discordSiteTlsMs >= 0 && tcpReachable && dnsStatus == 1;
            explanation = string.Format("discord.com bağlantı/TLS={0}; IP TCP={1}; gateway DNS={2}",
                discordSiteTlsMs >= 0 ? discordSiteTlsMs + " ms" : "başarısız",
                tcpMs >= 0 ? "1.1.1.1:443 " + tcpMs + " ms" : (alternateTcpMs >= 0 ? "8.8.8.8:443 " + alternateTcpMs + " ms" : "başarısız"),
                dnsStatus == 1 ? dnsServer + ":" + dnsPort + " geçerli" : (dnsStatus < 0 ? "şüpheli yanıt" : "belirsiz"));
            if (!tcpReachable && !string.IsNullOrEmpty(tcpError)) explanation += "; TCP: " + tcpError;
            if (discordSiteTlsMs < 0 && !string.IsNullOrEmpty(discordError)) explanation += "; discord.com bağlantı/TLS: " + discordError;
            return confirmed;
        }

