        private int LoadSavedDns()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false) ?? Registry.CurrentUser.OpenSubKey(LegacyAppSettingsRegistryKey, false))
                {
                    if (key != null)
                    {
                        object val = key.GetValue(DnsRegistryValue);
                        if (val is int)
                        {
                            int idx = (int)val;
                            return Math.Max(0, Math.Min(idx, _dnsOptions.Count - 1));
                        }
                        if (val != null)
                        {
                            int parsed;
                            if (int.TryParse(val.ToString(), out parsed))
                            {
                                return Math.Max(0, Math.Min(parsed, _dnsOptions.Count - 1));
                            }
                        }
                    }
                }
            }
            catch {}
            return 0; // Default: Yandex (Port 1253)
        }

        private void SaveSelectedDns(int index)
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                {
                    if (key != null)
                    {
                        key.SetValue(DnsRegistryValue, index, RegistryValueKind.DWord);
                    }
                }
            }
            catch {}
        }

        public int GetEffectiveDnsIndex()
        {
            return GetEffectiveDnsIndex(_isRunning);
        }

        private int GetEffectiveDnsIndex(bool protectionActive)
        {
            lock (_dnsMeasurementSync)
            {
                if (_dnsOptions == null || _dnsOptions.Count == 0) return -1;
                if (_selectedDnsIndex != 0)
                {
                    return (_selectedDnsIndex >= 0 && _selectedDnsIndex < _dnsOptions.Count) ? _selectedDnsIndex : 1;
                }

                // 1. Motor zaten aktif bir çözücüyle çalışıyorsa ve bu çözücü geçerliyse/yanıt veriyorsa koru
                if (_isRunning && _activeDnsIndex > 0 && _activeDnsIndex < _dnsOptions.Count)
                {
                    if (_dnsOptions[_activeDnsIndex].PingMs >= 0)
                    {
                        return _activeDnsIndex;
                    }
                }

                // 2. En iyi yanıt veren canlı sunucuyu bul
                int bestIndex = GetBestRespondingDnsIndex(protectionActive);
                if (bestIndex >= 0) return bestIndex;

                // 3. Koruma durumu fark etmeksizin en son yanıt vermiş olan sunucu
                if (_lastResponsiveDnsIndex > 0 && _lastResponsiveDnsIndex < _dnsOptions.Count &&
                    _dnsOptions[_lastResponsiveDnsIndex].PingMs >= 0)
                {
                    return _lastResponsiveDnsIndex;
                }

                // 4. Listede ping değeri >= 0 olan herhangi bir canlı sunucu ara (en düşük pingli olanı al)
                long lowestMs = long.MaxValue;
                int lowestIdx = -1;
                for (int i = 1; i < _dnsOptions.Count; i++)
                {
                    if (_dnsOptions[i] != null && _dnsOptions[i].IsAutomaticCandidate && _dnsOptions[i].PingMs >= 0 && _dnsOptions[i].PingMs < lowestMs)
                    {
                        lowestMs = _dnsOptions[i].PingMs;
                        lowestIdx = i;
                    }
                }
                if (lowestIdx > 0) return lowestIdx;

                // 5. Kayıtlı şablonda engelsiz port (9953 / 443) varsa onu tercih et
                string savedTpl;
                if (TryLoadVerifiedOverrideTemplate(_selectedProfileIndex, GetActiveGatewayFingerprint(), out savedTpl) &&
                    !string.IsNullOrEmpty(savedTpl))
                {
                    int bypassMatch = _dnsOptions.FindIndex(d => d != null && d.IsAutomaticCandidate && d.DpiArgs != null &&
                        ((!string.IsNullOrEmpty(d.PingTargetIp) && savedTpl.IndexOf(d.PingTargetIp, StringComparison.OrdinalIgnoreCase) >= 0) ||
                         (savedTpl.IndexOf("9953", StringComparison.Ordinal) >= 0 && d.DpiArgs.Contains("9953")) ||
                         (savedTpl.IndexOf("443", StringComparison.Ordinal) >= 0 && d.DpiArgs.Contains("443"))));
                    if (bypassMatch > 0) return bypassMatch;
                }

                // 6. Hiçbir canlı ölçüm yoksa: Türkiye İSS port 53 engellerine karşı varsayılan olarak engelsiz Quad9 (Port 9953) tercih edilir
                int quad9Idx = _dnsOptions.FindIndex(d => d != null && d.IsAutomaticCandidate && d.DpiArgs != null && d.DpiArgs.Contains("9953"));
                if (quad9Idx > 0) return quad9Idx;

                // 7. Otomatik aday olan ilk seçenek
                int firstCand = _dnsOptions.FindIndex(d => d != null && d.IsAutomaticCandidate && d.Id > 0);
                if (firstCand > 0) return firstCand;

                return (_dnsOptions.Count > 1) ? 1 : 0;
            }
        }

        private int GetBestRespondingDnsIndex()
        {
            return GetBestRespondingDnsIndex(_isRunning);
        }

        private int GetBestRespondingDnsIndex(bool protectionActive)
        {
            lock (_dnsMeasurementSync)
            {
                if (_dnsOptions == null) return -1;
                int bestIndex = -1;
                int bestResponseCount = 0;
                long bestScore = long.MaxValue;
                long bestRawMs = long.MaxValue;
                for (int i = 1; i < _dnsOptions.Count; i++)
                {
                    DnsOption option = _dnsOptions[i];
                    if (option == null || !option.IsAutomaticCandidate ||
                        !IsDnsMeasurementCurrent(option, protectionActive) ||
                        option.DnsResponseCount < DnsOption.MinimumValidDnsSamples || option.PingMs < 0) continue;

                    // Anycast CDN & DNS Yerellik Puanı:
                    // Yalnızca DNS sorgu süresine değil, çözümlenen Discord/CDN IP'sinin
                    // Türkiye içi (İstanbul/Ankara Edge) veya yakın POP noktasına düşmesine göre ağırlıklandırır.
                    long effectiveScore = option.PingMs;
                    if (option.AnycastEdgeRttMs >= 0)
                    {
                        effectiveScore += (option.AnycastEdgeRttMs / 4);
                        if (option.IsLocalAnycastEdge)
                        {
                            effectiveScore = Math.Max(0, effectiveScore - 5);
                        }
                    }

                    if (effectiveScore < bestScore ||
                        (effectiveScore == bestScore && option.PingMs < bestRawMs) ||
                        (effectiveScore == bestScore && option.PingMs == bestRawMs && option.DnsResponseCount > bestResponseCount))
                    {
                        bestIndex = i;
                        bestResponseCount = option.DnsResponseCount;
                        bestScore = effectiveScore;
                        bestRawMs = option.PingMs;
                    }
                }
                return bestIndex;
            }
        }

        private bool IsDnsMeasurementCurrent(DnsOption option, bool protectionActive)
        {
            if (option == null || option.PingMeasuredUtc == DateTime.MinValue) return false;

            TimeSpan age = DateTime.UtcNow - option.PingMeasuredUtc;
            if (age.TotalSeconds < 0 || age.TotalSeconds > DnsOption.MaximumDnsMeasurementAgeSeconds) return false;

            // Koruma durumu tam eşleşiyorsa doğrudan geçerli
            if (option.DnsMeasurementProtectionActive == protectionActive) return true;

            // Engelsiz alternatif port kullanan çözücüler (örn. Quad9 9953, OpenDNS 443)
            // WinDivert UDP:53 yönlendirmesinden bağımsızdır; ölçümleri koruma durumundan etkilenmez.
            if (!string.IsNullOrEmpty(option.DpiArgs))
            {
                if (option.DpiArgs.IndexOf("9953", StringComparison.Ordinal) >= 0 ||
                    option.DpiArgs.IndexOf("443", StringComparison.Ordinal) >= 0)
                {
                    return true;
                }
            }

            // Ölçüm 90 saniyeden yeniyse koruma geçişleri sırasında da güvenilir kabul et
            return age.TotalSeconds <= 90;
        }

        private void SelectDnsProvider(int index)
        {
            if (_dnsOptions == null || index < 0 || index >= _dnsOptions.Count) return;
            bool isAlreadySelected = false;
            lock (_dnsMeasurementSync)
            {
                if (_selectedDnsIndex == index)
                {
                    isAlreadySelected = true;
                }
                else
                {
                    _selectedDnsIndex = index;
                    _pendingAutoDnsIndex = -1;
                    _pendingAutoDnsConfirmations = 0;
                    _activeDnsFailureStrikes = 0;
                    _lastAutoDnsSwitchUtc = DateTime.MinValue;
                }
            }

            if (isAlreadySelected)
            {
                string sameToastMsg = index == 0
                    ? "En hızlı DNS sunucusu otomatik seçiliyor."
                    : (_dnsOptions[index].DisplayName + " zaten etkin.");
                ToastNotification.Show("DNS Ayarı", sameToastMsg, ToastType.Info, 2200);
                return;
            }

            SaveSelectedDns(index);

            if (_dnsSelector != null)
            {
                _dnsSelector.SetSelected(index);
                _dnsSelector.EffectiveDnsIndex = GetEffectiveDnsIndex();
            }

            UpdateDnsMenuChecks();
            AppLogger.Log("DNS", "Kullanıcı DNS sunucusunu değiştirdi: " + _dnsOptions[index].DisplayName);

            string dnsToastMsg = index == 0
                ? "En hızlı DNS sunucusu otomatik seçilecek."
                : (_dnsOptions[index].DisplayName + " etkinleştirildi.");
            ToastNotification.Show("DNS Değiştirildi", dnsToastMsg, ToastType.Info, 2600);

            if (_isRunning)
            {
                RequestDebouncedProtectionRestart("DNS: " + _dnsOptions[index].DisplayName);
            }
        }

        private void UpdateDnsMenuChecks()
        {
            if (_trayDnsSubmenu != null && _trayDnsSubmenu.DropDownItems != null)
            {
                for (int i = 0; i < _trayDnsSubmenu.DropDownItems.Count; i++)
                {
                    ToolStripMenuItem item = _trayDnsSubmenu.DropDownItems[i] as ToolStripMenuItem;
                    if (item != null)
                    {
                        item.Checked = (i == _selectedDnsIndex);
                    }
                }
            }
        }

        private void ToggleDnsDropdown()
        {
            if (_isDnsMenuOpen)
            {
                if (_dnsDropdownPopup != null)
                {
                    _dnsDropdownPopup.Close();
                }
                return;
            }

            // Debounce if outside click just closed the popup
            if ((DateTime.UtcNow - _dnsMenuClosedTime).TotalMilliseconds < 250)
            {
                return;
            }

            OpenDnsDropdown();
        }

        private void OpenDnsDropdown()
        {
            if (_dnsSelector == null) return;

            if (_dnsDropdownPopup != null)
            {
                try { _dnsDropdownPopup.Dispose(); } catch {}
                _dnsDropdownPopup = null;
            }

            DnsDropdownMenuList menuList = new DnsDropdownMenuList(_dnsOptions, _selectedDnsIndex, _isRunning, delegate(int index)
            {
                SelectDnsProvider(index);
                if (_dnsDropdownPopup != null)
                {
                    _dnsDropdownPopup.Close();
                }
            });
            _dnsDropdownMenuList = menuList;

            Point finalPt = _dnsSelector.PointToScreen(new Point(0, _dnsSelector.Height + 4));
            Screen screen = Screen.FromControl(_dnsSelector);
            int availableHeight = screen.WorkingArea.Bottom - finalPt.Y - 8;
            if (availableHeight < DnsDropdownMenuList.RowHeight)
            {
                finalPt.Y = Math.Max(screen.WorkingArea.Top, screen.WorkingArea.Bottom - DnsDropdownMenuList.RowHeight - 8);
                availableHeight = screen.WorkingArea.Bottom - finalPt.Y - 8;
            }
            menuList.SetViewportHeight(Math.Min(menuList.Height, availableHeight));

            _dnsDropdownPopup = new ToolStripDropDown();
            _dnsDropdownPopup.AutoClose = true;
            _dnsDropdownPopup.DropShadowEnabled = true;
            _dnsDropdownPopup.Margin = Padding.Empty;
            _dnsDropdownPopup.Padding = Padding.Empty;
            _dnsDropdownPopup.Renderer = new DarkDropdownRenderer();

            ToolStripControlHost host = new ToolStripControlHost(menuList);
            host.Margin = Padding.Empty;
            host.Padding = Padding.Empty;
            host.AutoSize = false;
            host.Size = menuList.Size;

            _dnsDropdownPopup.Items.Clear();
            _dnsDropdownPopup.Items.Add(host);

            _dnsDropdownPopup.Opened += delegate
            {
                _isDnsMenuOpen = true;
                if (_dnsSelector != null) _dnsSelector.IsOpen = true;
            };

            _dnsDropdownPopup.Closed += delegate
            {
                _isDnsMenuOpen = false;
                _dnsMenuClosedTime = DateTime.UtcNow;
                if (_dnsSelector != null) _dnsSelector.IsOpen = false;
                if (object.ReferenceEquals(_dnsDropdownMenuList, menuList)) _dnsDropdownMenuList = null;
            };

            int menuW = menuList.Width;
            if (finalPt.X + menuW > screen.WorkingArea.Right)
            {
                // Shift left if overflowing right screen edge
                finalPt.X = Math.Max(screen.WorkingArea.Left, screen.WorkingArea.Right - menuW - 8);
            }
            _dnsDropdownPopup.Show(finalPt);
            EnsureDnsPingScanIfNeeded();
        }

        private void EnsureDnsPingScanIfNeeded()
        {
            if (_dnsPingScanRunning || _dnsOptions == null) return;
            for (int i = 1; i < _dnsOptions.Count; i++)
            {
                if (!IsDnsMeasurementCurrent(_dnsOptions[i], _isRunning))
                {
                    StartDnsPingScan();
            try { AppTelemetry.SendHeartbeatAsync(false); } catch {}
                    return;
                }
            }
        }

