        {
            if (dropDown == null) return;
            dropDown.Renderer = _trayMenu != null ? _trayMenu.Renderer : new ModernDarkMenuRenderer();
            dropDown.BackColor = Color.FromArgb(43, 43, 43);
            dropDown.Padding = new Padding(3, 5, 3, 5);
            dropDown.Font = GetMenuFont(11.5F, FontStyle.Regular);
            ToolStripDropDownMenu menu = dropDown as ToolStripDropDownMenu;
            if (menu != null)
            {
                menu.ShowImageMargin = false;
                menu.ShowCheckMargin = false;
            }
            dropDown.Opening += delegate
            {
                try
                {
                    if (dropDown.Handle != IntPtr.Zero)
                    {
                        int cornerPref = 2; // DWMWCP_ROUND
                        DwmSetWindowAttribute(dropDown.Handle, 33, ref cornerPref, sizeof(int));
                        int darkMode = 1;
                        DwmSetWindowAttribute(dropDown.Handle, 20, ref darkMode, sizeof(int));
                    }
                }
                catch {}
            };
        }

        private void PopulateTrayIspSubmenu()
        {
            if (_trayIspSubmenu == null || _profiles == null) return;
            _trayIspSubmenu.Enabled = !IsProfileBenchmarkBlocking();
            _trayIspSubmenu.DropDownItems.Clear();

            for (int i = 0; i < _profiles.Count; i++)
            {
                int capturedIdx = i;
                IspProfile p = _profiles[i];
                ToolStripMenuItem item = new ToolStripMenuItem(p.Name, null, delegate
                {
                    if (IsProfileBenchmarkBlocking()) return;
                    bool changed = (_selectedProfileIndex != capturedIdx);
                    _userManuallySelectedIsp = true;
                    SaveAutoScanCompleted(true);
                    SetSelectedProfile(capturedIdx);
                    if (changed && capturedIdx >= 0 && capturedIdx < _profiles.Count)
                    {
                        ToastNotification.Show("Profil Değiştirildi", _profiles[capturedIdx].Name + " profili etkinleştirildi.", ToastType.Info, 2600);
                    }
                });
                item.Padding = new Padding(0, 5, 0, 5);
                item.Checked = (i == _selectedProfileIndex);
                _trayIspSubmenu.DropDownItems.Add(item);
            }
        }

