        }

        private const int WS_MINIMIZEBOX = 0x00020000;
        private const int CS_DROPSHADOW = 0x00020000;
        private Point _dragStartPoint;
        private bool _isDraggingWindow;

        // Kenarlıksız pencereleri başlık alanından sürüklemek için ortak yardımcı:
        // tıklanan kontrolü kaynak alır, sol tuş bırakılıncaya kadar pencere konumunu günceller.
        public static void DragWindow(IntPtr handle)
        {
            Control dragSource = Control.FromHandle(handle);
            if (dragSource == null) return;
            Form frm = dragSource.FindForm();
            if (frm == null || frm.IsDisposed) return;

            Point startCursor = Cursor.Position;
            Point startLoc = frm.Location;

            MouseEventHandler onMove = null;
            MouseEventHandler onUp = null;
            EventHandler onCapture = null;
            onMove = delegate(object s, MouseEventArgs me)
            {
                if (frm.IsDisposed) return;
                // Düğme bırakılmışsa (olay kaybolmuşsa) sürüklemeyi bitir.
                if ((Control.MouseButtons & MouseButtons.Left) == 0)
                {
                    onUp(s, me);
                    return;
                }
                Point p = Cursor.Position;
                frm.Location = new Point(startLoc.X + (p.X - startCursor.X), startLoc.Y + (p.Y - startCursor.Y));
            };
            onUp = delegate(object s, MouseEventArgs me)
            {
                try
                {
                    dragSource.MouseMove -= onMove;
                    dragSource.MouseUp -= onUp;
                    dragSource.MouseCaptureChanged -= onCapture;
                }
                catch {}
            };
            onCapture = delegate(object s, EventArgs ev)
            {
                // Capture kaybı (Alt+Tab, başka pencereye geçiş) sürüklemeyi derhal bitirir;
                // aksi hâlde işleyiciler bir sonraki sürüklemeye kadar birikiyordu.
                if (!dragSource.Capture) onUp(s, null);
            };
            dragSource.MouseMove += onMove;
            dragSource.MouseUp += onUp;
            dragSource.MouseCaptureChanged += onCapture;
        }

