                // sessiz kalmaz; sonraki otomatik denetim güncellemeyi yeniden dener.
                ToastNotification.Show("G\u00fcncelleme Yap\u0131lamad\u0131", "Mevcut s\u00fcr\u00fcmle devam ediliyor.", ToastType.Warning, 5000);
            }
        }

        private bool IsDnsRefreshInBackground()
        {
            return !this.Visible || this.WindowState == FormWindowState.Minimized;
        }

        private void InitializeDnsPingScheduler()
        {
            if (_dnsPingTimer != null) return;
            _dnsPingScheduleIsBackground = IsDnsRefreshInBackground();
            _dnsBackgroundFirstScanPending = _dnsPingScheduleIsBackground;

            _dnsPingTimer = new System.Windows.Forms.Timer();
            _dnsPingTimer.Interval = _dnsPingScheduleIsBackground ? 60000 : 30000;
            _dnsPingTimer.Tick += new EventHandler(DnsPingTimer_Tick);
            _dnsPingTimer.Start();

            if (!_dnsPingScheduleIsBackground) StartDnsPingScan();
        }

        private void UpdateDnsPingSchedule()
        {
            if (_isDisposing || this.IsDisposed) return;
            bool isBackground = IsDnsRefreshInBackground();
            if (isBackground == _dnsPingScheduleIsBackground) return;

            _dnsPingScheduleIsBackground = isBackground;
            _dnsBackgroundFirstScanPending = isBackground;
            if (_dnsPingTimer != null)
            {
                _dnsPingTimer.Stop();
                _dnsPingTimer.Interval = isBackground ? 60000 : 30000;
                _dnsPingTimer.Start();
            }
        }

        private void DnsPingTimer_Tick(object sender, EventArgs e)
        {
            if (_isDisposing || this.IsDisposed || _dnsPingTimer == null) return;
            UpdateDnsPingSchedule();
            if (_dnsPingScheduleIsBackground && _dnsBackgroundFirstScanPending)
            {
                _dnsBackgroundFirstScanPending = false;
                _dnsPingTimer.Interval = 5 * 60 * 1000;
            }
            StartDnsPingScan();
            try { AppTelemetry.SendHeartbeatAsync(false); } catch {}
        }

        private void StartDnsPingScan()
        {
            if (_isDisposing || this.IsDisposed || _dnsOptions == null || _dnsOptions.Count < 2 || _dnsPingScanRunning) return;

            _dnsPingScanRunning = true;
            int optionCount;
            int engineOperationStamp = Interlocked.CompareExchange(ref _engineOpStamp, 0, 0);
            string[] targets;
            int[] ports;
            long[] measuredPings;
            long[] measuredTcpTotals;
            long[] latencySpreads;
            int[] responseCounts;
            string[] serverIdentifiers;
            string[] measurementTransports;
            string[] probeErrors;
            bool protectionActive = _isRunning;
            lock (_dnsMeasurementSync)
            {
                optionCount = _dnsOptions.Count;
                targets = new string[optionCount];
                ports = new int[optionCount];
                measuredPings = new long[optionCount];
                measuredTcpTotals = new long[optionCount];
                latencySpreads = new long[optionCount];
                responseCounts = new int[optionCount];
                serverIdentifiers = new string[optionCount];
                measurementTransports = new string[optionCount];
                probeErrors = new string[optionCount];
                for (int i = 0; i < optionCount; i++)
                {
                    DnsOption option = _dnsOptions[i];
                    targets[i] = (option != null) ? option.PingTargetIp : null;
                    int customPort = 53;
                    if (option != null && !string.IsNullOrEmpty(option.DpiArgs))
                    {
                        int portMarker = option.DpiArgs.IndexOf("--dns-port", StringComparison.OrdinalIgnoreCase);
                        if (portMarker >= 0)
                        {
                            string tail = option.DpiArgs.Substring(portMarker + "--dns-port".Length).Trim();
                            string[] values = tail.Split(new char[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                            int parsedPort;
                            if (values.Length > 0 && int.TryParse(values[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out parsedPort) &&
                                parsedPort >= 1 && parsedPort <= 65535)
                            {
                                customPort = parsedPort;
                            }
                        }
                    }
                    ports[i] = customPort;
                    measuredPings[i] = -1;
                    measuredTcpTotals[i] = -1;
                    measurementTransports[i] = protectionActive ? "TCP" : "UDP";
                    if (i > 0 && string.IsNullOrEmpty(targets[i])) probeErrors[i] = "DNS hedef IP'si tanımlı değil";
                }
            }

            string[] queryNames = new string[] { "discord.com", "gateway.discord.gg" };
            bool queued = ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                bool scanAborted = false;
                bool scanFailed = false;
                int scanFinishedFlag = 0;
                try
                {
                    int workerCount = Math.Min(4, Math.Max(1, optionCount - 1));
                    int nextResolverIndex = 0;
                    int remainingWorkers = workerCount;
                    ManualResetEvent allWorkersDone = new ManualResetEvent(false);
                    WaitCallback probeWorker = delegate(object workerState)
                    {
                        try
                        {
                            while (true)
                            {
                                int i = Interlocked.Increment(ref nextResolverIndex);
                                if (i >= optionCount) break;

                                if (_isDisposing || _isRunning != protectionActive ||
                                    Interlocked.CompareExchange(ref scanFinishedFlag, 0, 0) != 0 ||
                                    Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp)
                                {
                                    scanAborted = true;
                                    break;
                                }
                                if (string.IsNullOrEmpty(targets[i])) continue;

                                List<long> samples = new List<long>(DnsOption.MaximumDnsProbeSamples);
                                List<long> tcpTotalSamples = new List<long>(DnsOption.MaximumDnsProbeSamples);
                                string lastError = null;
                                string usedTransport = (protectionActive && ports[i] == 53) ? "TCP" : "UDP";

                                for (int round = 0; round < DnsOption.DnsProbeRounds; round++)
                                {
                                    for (int q = 0; q < queryNames.Length; q++)
                                    {
                                        if (_isDisposing || _isRunning != protectionActive ||
                                            Interlocked.CompareExchange(ref scanFinishedFlag, 0, 0) != 0 ||
                                            Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp)
                                        {
                                            scanAborted = true;
                                            break;
                                        }

                                        long ms = -1;
                                        long tcpTotalMs = -1;
                                        int bytes = 0;
                                        string error = null;
                                        string serverIdentifier = null;
                                        bool requestNsid = (round == 0 && q == 0);
                                        if (requestNsid) serverIdentifiers[i] = "";

                                        // Standart dışı port (1253 - Yandex DNS) WinDivert UDP:53 yönlendirmesine takılmaz;
                                        // bu nedenle koruma açıkken de doğrudan UDP:1253 ile gerçek gecikmesi ölçülür.
                                        bool useProtectedTcp = protectionActive && ports[i] == 53;
                                        if (useProtectedTcp)
                                        {
                                            if (requestNsid)
                                            {
                                                tcpTotalMs = NetworkProbe.TestTcpDnsWithNsid(targets[i], ports[i], 650,
                                                    queryNames[q], out bytes, out error, out ms, out serverIdentifier);
                                                // Bazı genel DNS sunucuları (Google/OpenDNS/AdGuard) EDNS0 NSID TCP sorgularını sıfırlayabilir;
                                                // ilk sorgu başarısızsa standart yalın TCP DNS sorgusuyla anında doğrula.
                                                if (ms < 0 && ms != -3)
                                                {
                                                    tcpTotalMs = NetworkProbe.TestTcpDns(targets[i], ports[i], 650,
                                                        queryNames[q], out bytes, out error, out ms);
                                                }
                                            }
                                            else
                                            {
                                                tcpTotalMs = NetworkProbe.TestTcpDns(targets[i], ports[i], 650,
                                                    queryNames[q], out bytes, out error, out ms);
                                            }

                                            // İSS şeffaf DPI katmanı TCP:53 üzerindeki Discord QNAME sorgusunu düşürüyorsa
                                            // ancak sunucu zehirleme (-3) dönmediyse, çözücü canlılığını nötr adla doğrula.
                                            if (ms < 0 && ms != -3 && q == queryNames.Length - 1 && samples.Count == 0)
                                            {
                                                long fallbackMs;
                                                int fallbackBytes;
                                                string fallbackErr;
                                                long fallbackTcpTotal = NetworkProbe.TestTcpDns(targets[i], ports[i], 600,
                                                    "cloudflare.com", out fallbackBytes, out fallbackErr, out fallbackMs);
                                                if (fallbackMs >= 0)
                                                {
                                                    ms = fallbackMs;
                                                    tcpTotalMs = fallbackTcpTotal;
                                                    error = null;
                                                }
                                            }
                                            usedTransport = "TCP";
                                        }
                                        else
                                        {
                                            if (requestNsid)
                                            {
                                                ms = NetworkProbe.TestUdpDnsWithNsid(targets[i], ports[i], 600,
                                                    queryNames[q], out bytes, out error, out serverIdentifier);
                                                if (ms < 0 && ms != -3)
                                                {
                                                    ms = NetworkProbe.TestUdpDns(targets[i], ports[i], 600,
                                                        queryNames[q], out bytes, out error);
                                                }
                                            }
                                            else
                                            {
                                                ms = NetworkProbe.TestUdpDns(targets[i], ports[i], 600,
                                                    queryNames[q], out bytes, out error);
                                            }

                                            // Port 1253 UDP yanıt vermezse TCP 1253 yedeğini dene
                                            if (ms < 0 && ports[i] != 53)
                                            {
                                                tcpTotalMs = NetworkProbe.TestTcpDns(targets[i], ports[i], 650,
                                                    queryNames[q], out bytes, out error, out ms);
                                                if (ms >= 0) usedTransport = "TCP";
                                            }
                                            else
                                            {
                                                usedTransport = "UDP";
                                            }
                                        }

                                        if (requestNsid && !string.IsNullOrEmpty(serverIdentifier))
                                        {
                                            serverIdentifiers[i] = serverIdentifier;
                                        }

                                        if (_isDisposing || _isRunning != protectionActive ||
                                            Interlocked.CompareExchange(ref scanFinishedFlag, 0, 0) != 0 ||
                                            Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp)
                                        {
                                            scanAborted = true;
                                            break;
                                        }
                                        if (ms >= 0)
                                        {
                                            samples.Add(ms);
                                            if (tcpTotalMs >= 0) tcpTotalSamples.Add(tcpTotalMs);
                                        }
                                        else
                                        {
                                            lastError = error;
                                            if (ports[i] == 53 && (string.IsNullOrEmpty(lastError) || lastError.IndexOf("zaman", StringComparison.OrdinalIgnoreCase) >= 0 || lastError.IndexOf("time", StringComparison.OrdinalIgnoreCase) >= 0))
                                            {
                                                lastError = "İSS Port 53 engeli (Zaman aşımı)";
                                            }
                                            if (!string.IsNullOrEmpty(lastError) && lastError.Length > 180)
                                            {
                                                lastError = lastError.Substring(0, 180);
                                            }
                                        }
                                        if (q < queryNames.Length - 1) Thread.Sleep(20);
                                    }

                                    if (scanAborted) break;
                                }

                                if (scanAborted || Interlocked.CompareExchange(ref scanFinishedFlag, 0, 0) != 0) break;

                                responseCounts[i] = samples.Count;
                                measurementTransports[i] = usedTransport;
                                probeErrors[i] = lastError;
                                if (samples.Count >= DnsOption.MinimumValidDnsSamples)
                                {
                                    samples.Sort();
                                    int middle = samples.Count / 2;
                                    measuredPings[i] = (samples.Count % 2 == 1)
                                        ? samples[middle]
                                        : (samples[middle - 1] + samples[middle]) / 2;
                                    latencySpreads[i] = (samples.Count > 1)
                                        ? Math.Max(0, samples[samples.Count - 1] - samples[0])
                                        : 0;
                                }
                                if (tcpTotalSamples.Count >= DnsOption.MinimumValidDnsSamples)
                                {
                                    tcpTotalSamples.Sort();
                                    int middle = tcpTotalSamples.Count / 2;
                                    measuredTcpTotals[i] = (tcpTotalSamples.Count % 2 == 1)
                                        ? tcpTotalSamples[middle]
                                        : (tcpTotalSamples[middle - 1] + tcpTotalSamples[middle]) / 2;
                                }

                                // Anycast CDN & DNS Yerellik Doğrulaması:
                                // Çözümlenen Discord/CDN IP'sine hızlı RTT yoklaması (5 dk önbellekli) yaparak
                                // Türkiye içi / yerel POP noktasını doğrular.
                                long edgeRttMs = -1;
                                bool isLocalEdge = false;
                                string resolvedEdgeIp = "";
                                if (measuredPings[i] >= 0)
                                {
                                    string candidateIp;
                                    if (NetworkProbe.TryGetLastResolvedEdgeIp(targets[i], out candidateIp) && !string.IsNullOrEmpty(candidateIp))
                                    {
                                        resolvedEdgeIp = candidateIp;
                                        edgeRttMs = NetworkProbe.ProbeAnycastEdgeRttMs(candidateIp, 420);
                                    }
                                    isLocalEdge = NetworkProbe.IsTurkishOrLocalAnycastPop(serverIdentifiers[i], edgeRttMs);
                                }

                                QueueDnsOptionMeasurementResult(i, measuredPings[i], latencySpreads[i],
                                    measuredTcpTotals[i], responseCounts[i], measurementTransports[i], probeErrors[i],
                                    serverIdentifiers[i], edgeRttMs, isLocalEdge, resolvedEdgeIp,
                                    protectionActive, engineOperationStamp, DateTime.UtcNow);
                            }
                        }
                        finally
                        {
                            if (Interlocked.Decrement(ref remainingWorkers) == 0)
                            {
                                try { allWorkersDone.Set(); } catch {}
                            }
                        }
                    };

                    for (int w = 0; w < workerCount - 1; w++)
                    {
                        if (!ThreadPool.QueueUserWorkItem(probeWorker))
                        {
                            if (Interlocked.Decrement(ref remainingWorkers) == 0)
                            {
                                try { allWorkersDone.Set(); } catch {}
                            }
                        }
                    }
                    probeWorker(null);
                    bool completedInTime = allWorkersDone.WaitOne(12000);
                    Interlocked.Exchange(ref scanFinishedFlag, 1);
                    if (completedInTime)
                    {
                        try { allWorkersDone.Close(); } catch {}
                    }
                }
                catch (Exception ex)
                {
                    scanFailed = true;
                    AppLogger.Log("DNS", "DNS ölçümü sırasında hata: " + ex.Message, LogLevel.Warn);
                }

                if (scanFailed || scanAborted || _isRunning != protectionActive ||
                    Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp)
                {
                    _dnsPingScanRunning = false;
                    // Koruma durumu tarama sırasında değiştiyse (ör. motor yeni başlatıldı/durduruldu),
                    // satırların "-- ms" olarak asılı kalmaması için yeni duruma uygun taramayı hemen tetikle.
                    if (!scanFailed && !_isDisposing && !this.IsDisposed && this.IsHandleCreated)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (!_isDisposing && !this.IsDisposed) EnsureDnsPingScanIfNeeded();
                            });
                        }
                        catch {}
                    }
                    return;
                }

                try
                {
                    if (_isDisposing || this.IsDisposed || !this.IsHandleCreated)
                    {
                        _dnsPingScanRunning = false;
                        return;
                    }
                    this.BeginInvoke((MethodInvoker)delegate
                    {
                        _dnsPingScanRunning = false;
                        if (_isDisposing || this.IsDisposed) return;
                        if (_isRunning != protectionActive ||
                            Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp) return;
                        ApplyDnsPingResults(measuredPings, measuredTcpTotals, latencySpreads, responseCounts,
                            measurementTransports, probeErrors, serverIdentifiers, protectionActive,
                            engineOperationStamp, DateTime.UtcNow);
                    });
                }
                catch
                {
                    _dnsPingScanRunning = false;
                }
            });

            if (!queued) _dnsPingScanRunning = false;
        }

        private void QueueDnsOptionMeasurementResult(int optionIndex, long measuredPing, long latencySpread, long tcpTotalMs,
            int responseCount, string measurementTransport, string probeError, string serverIdentifier,
            long edgeRttMs, bool isLocalEdge, string resolvedEdgeIp,
            bool protectionActive, int engineOperationStamp, DateTime measuredUtc)
        {
            if (_isDisposing || this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (_isDisposing || this.IsDisposed || _isRunning != protectionActive ||
                        Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp) return;
                    lock (_dnsMeasurementSync)
                    {
                        if (Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp) return;
                        if (_dnsOptions == null || optionIndex <= 0 || optionIndex >= _dnsOptions.Count) return;
                        DnsOption option = _dnsOptions[optionIndex];
                        if (option == null) return;
                        option.PingMs = measuredPing;
                        option.DnsLatencySpreadMs = latencySpread;
                        option.DnsTcpTotalMs = tcpTotalMs;
                        option.DnsResponseCount = responseCount;
                        option.PingMeasuredUtc = measuredUtc;
                        option.DnsMeasurementProtectionActive = protectionActive;
                        option.DnsMeasurementTransport = measurementTransport;
                        option.DnsLastProbeError = probeError;
                        option.DnsServerIdentifier = serverIdentifier ?? "";
                        option.AnycastEdgeRttMs = edgeRttMs;
                        option.IsLocalAnycastEdge = isLocalEdge;
                        option.ResolvedEdgeIp = resolvedEdgeIp ?? "";

                    }

                    if (_dnsSelector != null && !_dnsSelector.IsDisposed && _dnsSelector.EffectiveDnsIndex <= 0)
                    {
                        _dnsSelector.EffectiveDnsIndex = GetEffectiveDnsIndex();
                        _dnsSelector.Invalidate();
                    }
                    if (_dnsDropdownMenuList != null && !_dnsDropdownMenuList.IsDisposed)
                    {
                        _dnsDropdownMenuList.RefreshMeasuredDns();
                    }
                });
            }
            catch
            {
            }
        }

        private void ApplyDnsPingResults(long[] measuredPings, long[] measuredTcpTotals, long[] latencySpreads, int[] responseCounts,
            string[] measurementTransports, string[] probeErrors, string[] serverIdentifiers,
            bool protectionActive, int engineOperationStamp, DateTime measuredUtc)
        {
            if (measuredPings == null || measuredTcpTotals == null || latencySpreads == null || responseCounts == null ||
                measurementTransports == null || probeErrors == null || serverIdentifiers == null ||
                _isRunning != protectionActive ||
                Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp) return;
            lock (_dnsMeasurementSync)
            {
                if (_dnsOptions == null || Interlocked.CompareExchange(ref _engineOpStamp, 0, 0) != engineOperationStamp) return;
                int activeBeforeScan = (_activeDnsIndex > 0 && _activeDnsIndex < _dnsOptions.Count)
                    ? _activeDnsIndex
                    : GetEffectiveDnsIndex();

                int count = Math.Min(_dnsOptions.Count, Math.Min(measuredPings.Length,
                    Math.Min(measuredTcpTotals.Length, Math.Min(latencySpreads.Length,
                    Math.Min(responseCounts.Length, Math.Min(measurementTransports.Length,
                    Math.Min(probeErrors.Length, serverIdentifiers.Length)))))));
                for (int i = 1; i < count; i++)
                {
                    DnsOption option = _dnsOptions[i];
                    if (option == null) continue;
                    option.PingMs = measuredPings[i];
                    option.DnsLatencySpreadMs = latencySpreads[i];
                    option.DnsTcpTotalMs = measuredTcpTotals[i];
                    option.DnsResponseCount = responseCounts[i];
                    option.PingMeasuredUtc = measuredUtc;
                    option.DnsMeasurementProtectionActive = protectionActive;
                    option.DnsMeasurementTransport = measurementTransports[i];
                    option.DnsLastProbeError = probeErrors[i];
                    option.DnsServerIdentifier = serverIdentifiers[i] ?? "";
                }

                int bestIndex = GetBestRespondingDnsIndex();
                if (bestIndex > 0) _lastResponsiveDnsIndex = bestIndex;
                EvaluateAutomaticDnsFailover(activeBeforeScan, responseCounts);

                if (_dnsOptions.Count > 0 && _dnsOptions[0] != null)
                {
                    int autoDisplayIndex = bestIndex;
                    if (_isRunning && _selectedDnsIndex == 0 && _pendingAutoDnsConfirmations > 0 &&
                        _activeDnsIndex > 0 && _activeDnsIndex < _dnsOptions.Count)
                    {
                        autoDisplayIndex = _activeDnsIndex;
                    }
                    if (autoDisplayIndex <= 0 && _isRunning && _activeDnsIndex > 0 && _activeDnsIndex < _dnsOptions.Count &&
                        IsDnsMeasurementCurrent(_dnsOptions[_activeDnsIndex], protectionActive))
                    {
                        autoDisplayIndex = _activeDnsIndex;
                    }
                    if (autoDisplayIndex <= 0 || autoDisplayIndex >= _dnsOptions.Count) autoDisplayIndex = -1;

                    DnsOption autoOption = _dnsOptions[0];
                    autoOption.PingMs = (autoDisplayIndex > 0) ? _dnsOptions[autoDisplayIndex].PingMs : -1;
                    autoOption.DnsTcpTotalMs = (autoDisplayIndex > 0) ? _dnsOptions[autoDisplayIndex].DnsTcpTotalMs : -1;
                    autoOption.DnsResponseCount = (autoDisplayIndex > 0) ? _dnsOptions[autoDisplayIndex].DnsResponseCount : 0;
                    autoOption.DnsLatencySpreadMs = (autoDisplayIndex > 0) ? _dnsOptions[autoDisplayIndex].DnsLatencySpreadMs : 0;
                    autoOption.PingMeasuredUtc = measuredUtc;
                    autoOption.DnsMeasurementProtectionActive = protectionActive;
                    autoOption.DnsMeasurementTransport = (autoDisplayIndex > 0)
                        ? _dnsOptions[autoDisplayIndex].DnsMeasurementTransport
                        : (protectionActive ? "TCP" : "UDP");
                    autoOption.DnsLastProbeError = (autoDisplayIndex > 0) ? _dnsOptions[autoDisplayIndex].DnsLastProbeError : "";
                    autoOption.DnsServerIdentifier = (autoDisplayIndex > 0) ? _dnsOptions[autoDisplayIndex].DnsServerIdentifier : "";
                    autoOption.AnycastEdgeRttMs = (autoDisplayIndex > 0) ? _dnsOptions[autoDisplayIndex].AnycastEdgeRttMs : -1;
                    autoOption.IsLocalAnycastEdge = (autoDisplayIndex > 0) && _dnsOptions[autoDisplayIndex].IsLocalAnycastEdge;
                    autoOption.ResolvedEdgeIp = (autoDisplayIndex > 0) ? (_dnsOptions[autoDisplayIndex].ResolvedEdgeIp ?? "") : "";
                }
            }

            if (_dnsSelector != null && !_dnsSelector.IsDisposed)
            {
                _dnsSelector.EffectiveDnsIndex = GetEffectiveDnsIndex();
                _dnsSelector.Invalidate();
            }
            if (_dnsDropdownMenuList != null && !_dnsDropdownMenuList.IsDisposed)
            {
                _dnsDropdownMenuList.RefreshMeasuredDns();
            }
        }

        private void EvaluateAutomaticDnsFailover(int activeBeforeScan, int[] responseCounts)
        {
            if (!_isRunning || _selectedDnsIndex != 0)
            {
                _pendingAutoDnsIndex = -1;
                _pendingAutoDnsConfirmations = 0;
                _activeDnsFailureStrikes = 0;
                return;
            }

            // Hızlı ve gereksiz motor yeniden başlatmalarını (flapping) önleyen soğuma süresi (60 sn)
            double secondsSinceLastSwitch = (DateTime.UtcNow - _lastAutoDnsSwitchUtc).TotalSeconds;
            if (secondsSinceLastSwitch >= 0 && secondsSinceLastSwitch < AutoDnsSwitchCooldownSeconds)
            {
                return;
            }

            int candidateIndex = GetBestRespondingDnsIndex();
            if (candidateIndex < 1 || candidateIndex == activeBeforeScan)
            {
                _pendingAutoDnsIndex = -1;
                _pendingAutoDnsConfirmations = 0;
                _activeDnsFailureStrikes = 0;
                return;
            }

            bool activeResponded = activeBeforeScan > 0 && activeBeforeScan < responseCounts.Length &&
                responseCounts[activeBeforeScan] >= DnsOption.MinimumValidDnsSamples;
            if (!activeResponded)
            {
                _pendingAutoDnsIndex = -1;
                _pendingAutoDnsConfirmations = 0;
                _activeDnsFailureStrikes++;

                // Tek bir geçici gecikmede motoru anında devirme; en az 2 ardışık başarısız tarama turu bekle
                if (_activeDnsFailureStrikes < 2)
                {
                    return;
                }

                _activeDnsFailureStrikes = 0;
                _lastAutoDnsSwitchUtc = DateTime.UtcNow;
                AppLogger.Log("DNS", "Otomatik DNS geçişi: etkin çözücü yanıt vermedi (2 başarısız tarama); " + _dnsOptions[candidateIndex].DisplayName + " seçiliyor.");
                RequestDebouncedProtectionRestart("Otomatik DNS: " + _dnsOptions[candidateIndex].DisplayName);
                return;
            }

            // Aktif çözücü başarıyla yanıt verdi; başarısızlık sayacını sıfırla
            _activeDnsFailureStrikes = 0;

            // Motor şeffaf DNS vekil kalkanına (port != 53, örn. Quad9 9953, OpenDNS 443 veya Yandex 1253) kilitlendiyse
            // ve aktif çözücü yanıt veriyorsa, periyodik taramada standart Port 53 sunucusuna otomatik dönerek kalkanı bozma.
            if (activeBeforeScan >= 0 && activeBeforeScan < _dnsOptions.Count && candidateIndex != activeBeforeScan)
            {
                DnsOption curOpt = _dnsOptions[activeBeforeScan];
                bool isBypassPort = false;
                if (curOpt != null && !string.IsNullOrEmpty(curOpt.DpiArgs))
                {
                    int pm = curOpt.DpiArgs.IndexOf("--dns-port", StringComparison.OrdinalIgnoreCase);
                    if (pm >= 0)
                    {
                        string sub = curOpt.DpiArgs.Substring(pm + 10).Trim();
                        string[] parts = sub.Split(new char[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
                        int p;
                        if (parts.Length > 0 && int.TryParse(parts[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out p) && p != 53)
                        {
                            isBypassPort = true;
                        }
                    }
                }

                if (isBypassPort)
                {
                    string savedTpl;
                    if (TryLoadVerifiedOverrideTemplate(_selectedProfileIndex, GetActiveGatewayFingerprint(), out savedTpl) &&
                        !string.IsNullOrEmpty(savedTpl) &&
                        (savedTpl.IndexOf("9953", StringComparison.Ordinal) >= 0 ||
                         savedTpl.IndexOf("443", StringComparison.Ordinal) >= 0 ||
                         savedTpl.IndexOf("1253", StringComparison.Ordinal) >= 0))
                    {
                        _pendingAutoDnsIndex = -1;
                        _pendingAutoDnsConfirmations = 0;
                        return;
                    }
                }
            }

            DnsOption activeOption = _dnsOptions[activeBeforeScan];
            DnsOption candidateOption = _dnsOptions[candidateIndex];
            if (activeOption == null || candidateOption == null || activeOption.PingMs < 0 || candidateOption.PingMs < 0)
            {
                _pendingAutoDnsIndex = -1;
                _pendingAutoDnsConfirmations = 0;
                return;
            }

            long improvementMs = activeOption.PingMs - candidateOption.PingMs;
            // Çözücü zaten çalışırken geçiş için hem mutlak eşik (15 ms) hem de %25 bağıl iyileşme şartı
            long requiredImprovement = Math.Max(MinimumMeaningfulDnsImprovementMs, (long)(activeOption.PingMs * 0.25));
            long noiseFloorMs = Math.Max(requiredImprovement,
                Math.Max(activeOption.DnsLatencySpreadMs, candidateOption.DnsLatencySpreadMs));
            if (improvementMs <= noiseFloorMs)
            {
                _pendingAutoDnsIndex = -1;
                _pendingAutoDnsConfirmations = 0;
                return;
            }

            if (_pendingAutoDnsIndex == candidateIndex)
            {
                _pendingAutoDnsConfirmations++;
            }
            else
            {
                _pendingAutoDnsIndex = candidateIndex;
                _pendingAutoDnsConfirmations = 1;
            }

            // Kararlı geçiş için en az 3 ardışık tarama onay şartı (jitter koruması)
            if (_pendingAutoDnsConfirmations >= 3)
            {
                _pendingAutoDnsIndex = -1;
                _pendingAutoDnsConfirmations = 0;
                _lastAutoDnsSwitchUtc = DateTime.UtcNow;
                AppLogger.Log("DNS", "Otomatik DNS geçişi doğrulandı (" + improvementMs + " ms iyileşme): " + _dnsOptions[candidateIndex].DisplayName + ".");
                RequestDebouncedProtectionRestart("Otomatik DNS: " + _dnsOptions[candidateIndex].DisplayName);
            }
        }

        private void InitializeAppServices()
        {
            if (_appServicesInitialized) return;
            _appServicesInitialized = true;

            // Otomatik başlat kaydı taşınmış/bozulmuş olabilir: kayıtlı yol ile gerçek yol
            // eşitlenir (özellikle taşınabilir klasör yeniden konumlandırıldığında).
            try { EnsureAutoStartPathSync(); } catch {}

            // Windows Defender otomatik dışlama ve güvenlik sertifikası güveni senkronizasyonu
            try { WindowsSecurityHelper.EnsureFolderExclusionAsync(this); } catch {}

            // Anonim aktif cihaz ve kullanım telemetrisi sinyali (Cloudflare D1 Radar)
            try { AppTelemetry.SendHeartbeatAsync(true); } catch {}

            // OneDrive / Bulut dizini kontrolü: OneDrive masaüstü senkronizasyonu çekirdek sürücüsü (WinDivert)
            // dosyalarını kilitleyebileceği için kullanıcı bilgilendirilir.
            try
            {
                string baseDir = AppDomain.CurrentDomain.BaseDirectory;
                if (!string.IsNullOrEmpty(baseDir) && baseDir.IndexOf("OneDrive", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    AppLogger.Log("WARNING", "Uygulama OneDrive senkronizasyon klasörü altında çalışıyor: " + baseDir);
                    ToastNotification.Show("OneDrive Uyar\u0131s\u0131", "Kopma olmamas\u0131 i\u00e7in program\u0131 yerel diske ta\u015f\u0131y\u0131n.", ToastType.Info, 6000);
                }
            }
            catch {}

            // Sessiz arka plan güncelleme denetimi:
            // 1. İlk denetim açılıştan 3.5 saniye sonra sessizce başlar.
            // 2. Başarılı kontrolde 15 dakika; geçici ağ/feed hatasında artan kısa aralıklarla yinelenir.
            _autoUpdateTimer = new System.Windows.Forms.Timer();
            _autoUpdateTimer.Interval = 3500;
            _autoUpdateTimer.Tick += delegate
            {
                if (_autoUpdateTimer != null) _autoUpdateTimer.Stop();
                if (!_isDisposing && !this.IsDisposed)
                {
                    if (_autoUpdateCheckInProgress)
                    {
                        _autoUpdateCheckRequested = true;
                        _autoUpdateRequestedDelayMs = Math.Min(_autoUpdateRequestedDelayMs, 10000);
                    }
                    else
                    {
                        _autoUpdateCheckInProgress = true;
                        try { CheckForUpdates(silent: true); }
                        catch (Exception ex)
                        {
                            AppLogger.Log("UPDATE", "Arka plan güncelleme denetimi başlatılamadı: " + ex.Message);
                            CompleteAutomaticUpdateCheck(false);
                        }
                    }
                }
            };
            _autoUpdateTimer.Start();

            // Bağlantı Bekçisi: koruma açıkken dakikada bir ayrı DNS/TCP/TLS sinyallerini denetler.
            // Motor yeni başlatıldıysa ilk 2 dakika atlanır (başlangıç doğrulamasıyla çakışmaz).
            _connWatchTimer = new System.Windows.Forms.Timer();
            _connWatchTimer.Interval = 60 * 1000;
            _connWatchTimer.Tick += delegate { ConnWatchdog_Tick(); };
            _connWatchTimer.Start();

            // Discord RTC Otomatik İyileştirici: koruma açıkken 1.5 saniyede bir Discord ses/WebRTC
            // günlüklerini (renderer_js.log + discord-webrtc_*) artımlı okuyarak "RTC Bağlanıyor"
            // takılmasını, VOICE_STATE_UPDATE zaman aşımını ve ani UDP soket kopmalarını yakalar.
            _rtcWatchTimer = new System.Windows.Forms.Timer();
            _rtcWatchTimer.Interval = 1500;
            _rtcWatchTimer.Tick += delegate { RtcWatchdog_Tick(); };
            _rtcWatchTimer.Start();

            InitializeDnsPingScheduler();

            if (_startMinimized)
            {
                AppLogger.Log("SYSTEM", "GoodbyeDPI Pro MAX sistem tepsisinde sessiz başlatıldı.");
                _startProtectionAfterBenchmark = true;
                StartAutoBenchmarkCountdown(1200);
                try
                {
                    ToastNotification.Show("GoodbyeDPI Pro MAX", "Arka planda sistem tepsisinde koruma ba\u015flat\u0131ld\u0131.", ToastType.Info, 3000);
                }
                catch {}
            }
            else
            {
                // Sihirbaz hiç görülmediyse (taze kurulum VEYA v0.4.4'e güncelleyen kullanıcı):
                // ana pencere tamamen göründükten sonra bir kez açılır. Güncelleme sonrası
                // "başarıyla güncellendi" toast'ına nefes payı bırakmak için kısa gecikme eklenir.
                if (_wizardPending)
                {
                    StartWizardCountdown(_isJustUpdated ? 2200 : 900);
                }
                else
                {
                    StartAutoBenchmarkCountdown(1000);
                }
            }
        }

        private void StartAutoBenchmarkCountdown(int delayMs)
        {
            System.Windows.Forms.Timer t = new System.Windows.Forms.Timer();
            t.Interval = Math.Max(100, delayMs);
            t.Tick += delegate
            {
                t.Stop();
                t.Dispose();
                if (_isDisposing || this.IsDisposed) return;
                if (_isAutoScanCompleted || _isSmartBenchmarkRunning || _wizardOpen) return;
                RunSmartIspBenchmarkAsync();
            };
            t.Start();
        }

        public void CheckForUpdates(bool silent)
        {
            // 1. Manuel denetim (kullanıcı bizzat tıkladı): Animasyonlu ve esprili kontrol penceresini aç
            if (!silent)
            {
                using (UpdateCheckDialog checkDlg = new UpdateCheckDialog(this, delegate(UpdateInfo info)
                {
                    _pendingUpdateInfo = info;
                    if (_headerPanel != null && !_headerPanel.IsDisposed) _headerPanel.Invalidate();
                    if (UpdateDialog.IsOpen)
                    {
                        UpdateDialog.FocusCurrent();
                        return;
                    }
                    using (UpdateDialog dlg = new UpdateDialog(info, delegate { PrepareForUpdateStart(); }))
                    {
                        dlg.ShowDialog(this);
                    }
                }))
                {
                    checkDlg.ShowDialog(this);
                }
                return;
            }

            // 2. Arka plan otomatik periyodik denetim (silent):
            UpdateManager.CheckForUpdatesAsync(
                onUpdateFound: delegate(UpdateInfo info)
                {
                    if (silent) CompleteAutomaticUpdateCheck(true);
                    if (this.IsDisposed || _isDisposing) return;
                    if (silent && !info.Mandatory && UpdateManager.DismissedVersion != null && UpdateManager.CompareVersions(info.ParsedVersion, UpdateManager.DismissedVersion) <= 0)
                    {
                        return; // Kullanıcı bu oturumda "Daha sonra" seçti
                    }
                    try
                    {
                        // Handle'ı arka plan iş parçacığından ZORLAMAYIZ: çapraz iş parçacığında handle
                        // oluşturmak WinForms'ta tanımsız davranıştır. Pencere OnShown sonrası handle
                        // sahibidir; değilse bu tur sessizce atlanır, sonraki denetim devam eder.
                        if (this.IsDisposed || !this.IsHandleCreated) return;
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (this.IsDisposed || _isDisposing) return;

                            bool samePendingVersion = _pendingUpdateInfo != null
                                && UpdateManager.CompareVersions(info.ParsedVersion, _pendingUpdateInfo.ParsedVersion) == 0;
                            if (_pendingUpdateInfo != null
                                && UpdateManager.CompareVersions(info.ParsedVersion, _pendingUpdateInfo.ParsedVersion) < 0)
                            {
                                return; // Eski bir CDN cevabı bekleyen daha yeni sürümü geriye çekemez.
                            }
                            if (samePendingVersion && _pendingUpdateInfo.Mandatory)
                            {
                                info.Mandatory = true; // Aynı sürümün zorunlu durumu geriye alınmaz.
                            }
                            bool isNewOrEscalatedUpdate = _pendingUpdateInfo == null
                                || !samePendingVersion
                                || (info.Mandatory && !_pendingUpdateInfo.Mandatory);
                            bool shouldNotifyUpdate = isNewOrEscalatedUpdate || ShouldRepeatUpdateNotification(info);

                            _pendingUpdateInfo = info;
                            if (_headerPanel != null && !_headerPanel.IsDisposed) _headerPanel.Invalidate();

                            // Arka plan otomatik kontrolü (silent):
                            // Kullanıcı oyundaysa veya başka bir uygulamadayken (Chrome vb.) asla odak çalan modal dialog açılmaz!
                            if (shouldNotifyUpdate && ShowUpdateFoundNotification(info))
                            {
                                _lastUpdateNotificationVersion = info.ParsedVersion;
                                _lastUpdateNotificationTick = Environment.TickCount;
                            }

                            // Yalnızca kullanıcı zaten GoodbyeDPI penceresindeyse ve oyunda değilse diyaloğu aç
                            if (isNewOrEscalatedUpdate && !_isUpdateFailed && IsGoodbyeDpiForeground())
                            {
                                if (!UpdateDialog.IsOpen)
                                {
                                    using (UpdateDialog dlg = new UpdateDialog(info, delegate { PrepareForUpdateStart(); }))
                                    {
                                        dlg.StartPosition = FormStartPosition.CenterScreen;
                                        dlg.TopMost = true;
                                        dlg.ShowDialog(this);
                                    }
                                }
                            }
                        });
                    }
                    catch {}
                },
                onUpToDate: delegate
                {
                    if (silent)
                    {
                        CompleteAutomaticUpdateCheck(true);
                        ClearPendingUpdateNotification();
                    }
                },
                onError: delegate(string err)
                {
                    if (silent) CompleteAutomaticUpdateCheck(false);
                    AppLogger.Log("UPDATE", "Arka plan güncelleme denetimi hatası: " + err);
                }
            );
        }

        private bool ShouldRepeatUpdateNotification(UpdateInfo info)
        {
            if (info == null || info.ParsedVersion == null || UpdateDialog.IsOpen) return false;
            if (_lastUpdateNotificationVersion == null
                || UpdateManager.CompareVersions(info.ParsedVersion, _lastUpdateNotificationVersion) != 0)
            {
                return true;
            }

            int elapsedMs = unchecked(Environment.TickCount - _lastUpdateNotificationTick);
            return elapsedMs >= UpdateNotificationRepeatIntervalMs;
        }

        private void ClearPendingUpdateNotification()
        {
            if (this.IsDisposed || _isDisposing || !this.IsHandleCreated) return;
            if (this.InvokeRequired)
            {
                try { this.BeginInvoke((MethodInvoker)delegate { ClearPendingUpdateNotification(); }); } catch {}
                return;
            }

            _pendingUpdateInfo = null;
            _pendingUpdateBalloonTitle = null;
            _lastUpdateNotificationVersion = null;
            _lastUpdateNotificationTick = 0;
            if (_headerPanel != null && !_headerPanel.IsDisposed) _headerPanel.Invalidate();
        }

        private void PrepareForUpdateStart()
        {
            _pendingUpdateBalloonTitle = null;
            _lastUpdateNotificationVersion = null;
            _lastUpdateNotificationTick = 0;
            if (_isRunning) StopProtection();
        }

        private bool ShowUpdateFoundNotification(UpdateInfo info)
        {
            string title = info.Mandatory
                ? "Zorunlu güncelleme gerekli (v" + info.Version + ")"
                : "Yeni sürüm var (v" + info.Version + ")";
            string message = info.Mandatory
                ? "Uygulamayı kullanmaya devam etmek için bildirime tıklayıp güncelleyin."
                : "Güncellemek için bildirime tıklayın.";
            ToastType type = info.Mandatory ? ToastType.Warning : ToastType.Info;

            string queueKey = "update\u001f" + title + "\u001f" + message;
            if (GameNotificationDeferral.TryDefer(queueKey, 10000, delegate
            {
                RunNotificationOnUi(delegate
                {
                    if (!this.IsDisposed && !_isDisposing) ShowUpdateFoundNotification(info);
                });
            }, null)) return true;

            if (!IsGoodbyeDpiForeground() && _trayIcon != null && _trayIcon.Visible)
            {
                try
                {
                    _pendingUpdateBalloonTitle = title;
                    _trayIcon.BalloonTipTitle = title;
                    _trayIcon.BalloonTipText = message;
                    _trayIcon.BalloonTipIcon = info.Mandatory ? ToolTipIcon.Warning : ToolTipIcon.Info;
                    _trayIcon.ShowBalloonTip(10000);
                    return true;
                }
                catch { _pendingUpdateBalloonTitle = null; }
            }

            _pendingUpdateBalloonTitle = null;
            try
            {
                ToastNotification.Show(title, message, type, 7000, delegate
                {
                    if (this.IsDisposed || _isDisposing) return;
                    try
                    {
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (this.IsDisposed || _isDisposing) return;
                            if (_pendingUpdateInfo == null
                                || UpdateManager.CompareVersions(_pendingUpdateInfo.ParsedVersion, info.ParsedVersion) != 0) return;
                            if (UpdateDialog.IsOpen)
                            {
                                UpdateDialog.FocusCurrent();
                                return;
                            }
                            try
                            {
                                if (!this.Visible) this.Show();
                                if (this.WindowState == FormWindowState.Minimized) this.WindowState = FormWindowState.Normal;
                                this.BringToFront();
                                this.Activate();
                            }
                            catch {}

                            using (UpdateDialog dlg = new UpdateDialog(info, delegate { PrepareForUpdateStart(); }))
                            {
                                dlg.StartPosition = FormStartPosition.CenterScreen;
                                dlg.TopMost = true;
                                dlg.ShowDialog(this.Visible && this.WindowState != FormWindowState.Minimized ? this : null);
                            }
                        });
                    }
                    catch {}
                });
                return true;
            }
            catch
            {
                return false;
            }
        }

        private void RunNotificationOnUi(Action action)
        {
            if (action == null || this.IsDisposed || _isDisposing || !this.IsHandleCreated) return;
            try
            {
                if (this.InvokeRequired)
                {
                    this.BeginInvoke((MethodInvoker)delegate
                    {
                        if (!this.IsDisposed && !_isDisposing) action();
                    });
                }
                else
                {
                    action();
                }
            }
            catch {}
        }

        public static void ApplyImmersiveDarkMode(IntPtr handle)
        {
            try
            {
                int useImmersiveDarkMode = 1;
                if (DwmSetWindowAttribute(handle, DWMWA_USE_IMMERSIVE_DARK_MODE, ref useImmersiveDarkMode, sizeof(int)) != 0)
                {
                    DwmSetWindowAttribute(handle, DWMWA_USE_IMMERSIVE_DARK_MODE_BEFORE_20H1, ref useImmersiveDarkMode, sizeof(int));
                }

                // Windows 11 DWM: Donanımsal yuvarlatılmış pencere köşeleri (DWMWCP_ROUND = 2)
                int cornerPreference = 2;
                DwmSetWindowAttribute(handle, 33, ref cornerPreference, sizeof(int));

                // Windows 11 Build 22000+: Sistem temasıyla uyumlu koyu kenarlık rengi (DWMWA_BORDER_COLOR = 34)
                // COLORREF: 0x00BBGGRR -> #1e2636 = R:30, G:38, B:54 -> 0x0036261E
                int borderColor = 0x0036261E;
                DwmSetWindowAttribute(handle, 34, ref borderColor, sizeof(int));
            }
            catch {}
        }

