            PopulateTrayIspSubmenu();
            _trayMenu.Items.Add(_trayIspSubmenu);

            // 4. DNS sağlayıcısı (Açılır Alt Menü)
            _trayDnsSubmenu = new ToolStripMenuItem("DNS sağlayıcısı");
            _trayDnsSubmenu.Padding = new Padding(0, 7, 0, 7);
            ConfigureSubmenu(_trayDnsSubmenu.DropDown);
            _trayDnsSubmenu.DropDownOpening += delegate { PopulateTrayDnsSubmenu(); };
            PopulateTrayDnsSubmenu();
            _trayMenu.Items.Add(_trayDnsSubmenu);

            // 5. DNS önbelleğini temizle
            ToolStripMenuItem itemFlushDns = new ToolStripMenuItem("DNS önbelleğini temizle", null, new EventHandler(delegate(object s, EventArgs e)
            {
                try
                {
                    ModernMainForm.FlushDnsFast();
                    if (_trayIcon != null)
                    {
                        Action showDnsCacheCleared = null;
                        showDnsCacheCleared = delegate
                        {
                            if (GameNotificationDeferral.TryDefer("tray-dns-cache-cleared", 1500, showDnsCacheCleared, null)) return;
                            RunNotificationOnUi(delegate
                            {
                                if (GameNotificationDeferral.TryDefer("tray-dns-cache-cleared", 1500, showDnsCacheCleared, null)) return;
                                if (_trayIcon == null) return;
                                _pendingUpdateBalloonTitle = null;
                                _trayIcon.ShowBalloonTip(1500, "GoodbyeDPI ProMAX", "DNS önbelleği başarıyla temizlendi.", ToolTipIcon.Info);
                            });
                        };
                        showDnsCacheCleared();
                    }
                }
                catch {}
            }));
            itemFlushDns.Padding = new Padding(0, 7, 0, 7);
            _trayMenu.Items.Add(itemFlushDns);

            // 5b. Windows Defender dışlaması ekle / yenile
            ToolStripMenuItem itemDefender = new ToolStripMenuItem("Windows Defender iznini yenile", null, new EventHandler(delegate(object s, EventArgs e)
            {
                try
                {
                    WindowsSecurityHelper.ApplyExclusionManual(this);
                }
                catch {}
            }));
            itemDefender.Padding = new Padding(0, 7, 0, 7);
            _trayMenu.Items.Add(itemDefender);

            // 6. Ayırıcı
            ToolStripSeparator sep = new ToolStripSeparator();
            sep.Margin = new Padding(0, 3, 0, 3);
            _trayMenu.Items.Add(sep);

            // 7. Çıkış
            ToolStripMenuItem itemExit = new ToolStripMenuItem("Çıkış", null, new EventHandler(TrayExit_Click));
            itemExit.Tag = "EXIT";
            itemExit.Padding = new Padding(0, 7, 0, 7);
            _trayMenu.Items.Add(itemExit);

            _trayMenu.Opening += delegate
            {
                try
                {
                    if (_trayMenu.Handle != IntPtr.Zero)
                    {
                        int cornerPref = 2; // DWMWCP_ROUND
                        DwmSetWindowAttribute(_trayMenu.Handle, 33, ref cornerPref, sizeof(int));
                        int darkMode = 1;
                        DwmSetWindowAttribute(_trayMenu.Handle, 20, ref darkMode, sizeof(int));
                    }
                }
                catch {}

                if (_trayToggleItem != null)
                {
                    _trayToggleItem.Text = _isRunning ? "Korumayı durdur" : "Korumayı başlat / durdur";
                }
                UpdateIspMenuChecks();
                UpdateDnsMenuChecks();
            };

            _trayIcon = new NotifyIcon();
            _trayIcon.Text = "GoodbyeDPI Pro MAX";
            if (this.Icon != null)
            {
                _trayIcon.Icon = this.Icon;
            }
            _trayIcon.ContextMenuStrip = _trayMenu;
            _trayIcon.Visible = true;
            _trayIcon.DoubleClick += new EventHandler(TrayOpen_Click);
            _trayIcon.MouseClick += delegate(object s, MouseEventArgs me)
            {
                if (me.Button == MouseButtons.Left)
                {
                    TrayOpen_Click(s, EventArgs.Empty);
                }
            };
            _trayIcon.BalloonTipClicked += delegate
            {
                if (_pendingUpdateInfo != null
                    && _trayIcon != null
                    && !string.IsNullOrEmpty(_pendingUpdateBalloonTitle)
                    && string.Equals(_trayIcon.BalloonTipTitle, _pendingUpdateBalloonTitle, StringComparison.Ordinal)
                    && !this.IsDisposed && !_isDisposing)
                {
                    _pendingUpdateBalloonTitle = null;
                    this.BeginInvoke((MethodInvoker)delegate
                    {
                        if (this.IsDisposed || _isDisposing) return;
                        if (UpdateDialog.IsOpen)
                        {
                            UpdateDialog.FocusCurrent();
                            return;
                        }
                        try
                        {
                            if (!this.Visible) this.Show();
                            if (this.WindowState == FormWindowState.Minimized) this.WindowState = FormWindowState.Normal;
                            this.BringToFront();
                            this.Activate();
                        }
                        catch {}
                        using (UpdateDialog dlg = new UpdateDialog(_pendingUpdateInfo, delegate { PrepareForUpdateStart(); }))
                        {
                            dlg.StartPosition = FormStartPosition.CenterScreen;
                            dlg.TopMost = true;
                            dlg.ShowDialog(this.Visible && this.WindowState != FormWindowState.Minimized ? this : null);
                        }
                    });
                }
            };

            this.FormClosing += new FormClosingEventHandler(MainForm_FormClosing);
        }

        private void ApplyBenchmarkInteractionState()
        {
            if (_isDisposing || this.IsDisposed) return;

            if (this.InvokeRequired)
            {
                try
                {
                    this.BeginInvoke((MethodInvoker)delegate { ApplyBenchmarkInteractionState(); });
                }
                catch {}
                return;
            }

            bool benchmarkRunning = IsProfileBenchmarkBlocking();
            if (_trayIspSubmenu != null)
            {
                _trayIspSubmenu.Enabled = !benchmarkRunning;
                if (benchmarkRunning && _trayIspSubmenu.DropDown.Visible) _trayIspSubmenu.DropDown.Close();
            }

            if (benchmarkRunning && _dropdownPopup != null && _dropdownPopup.Visible)
            {
                _dropdownPopup.Close();
            }

            if (benchmarkRunning)
            {
                if (_btnToggle != null && !_btnToggle.IsDisposed && !_isRunning) _btnToggle.Enabled = false;
                if (_selector != null && !_selector.IsDisposed) _selector.IsLocked = true;
            }
            else if (!_isOperationRunning)
            {
                if (_btnToggle != null && !_btnToggle.IsDisposed) _btnToggle.Enabled = true;
                if (_selector != null && !_selector.IsDisposed)
                {
                    _selector.Enabled = !_isRunning;
                    _selector.IsLocked = _isRunning;
                }
            }
        }

        private bool IsProfileBenchmarkBlocking()
        {
            return _isProfileBenchmarkPending || _isSmartBenchmarkRunning;
        }

        private void SetToolsEnabled(bool enabled)
        {
            bool benchmarkBlocking = IsProfileBenchmarkBlocking();
            if (_btnToggle != null) _btnToggle.Enabled = enabled && (!benchmarkBlocking || _isRunning);
            if (_btnOptimizeGamingPing != null) _btnOptimizeGamingPing.Enabled = enabled;
            if (_btnOpenWhitelist != null) _btnOpenWhitelist.Enabled = enabled;
            if (_btnRepairNetworkAndDiscord != null) _btnRepairNetworkAndDiscord.Enabled = enabled;
            if (_btnOptimizeHardware != null) _btnOptimizeHardware.Enabled = enabled;
            if (_btnSmartBenchmark != null) _btnSmartBenchmark.Enabled = enabled;
            if (_selector != null && !_isRunning && !benchmarkBlocking) _selector.Enabled = enabled;
            if (_dnsSelector != null) _dnsSelector.Enabled = enabled;
            if (_btnDiagnostics != null) _btnDiagnostics.Enabled = enabled;
            this.Cursor = enabled ? Cursors.Default : Cursors.WaitCursor;
        }

        // Animation Engine (40 FPS smooth timer)
        private void StartAnimationEngine()
        {
            _animTimer = new System.Windows.Forms.Timer();
            _animTimer.Interval = 25; // 40 FPS
            _animTimer.Tick += new EventHandler(AnimTimer_Tick);
            _animTimer.Start();
        }

        private void AnimTimer_Tick(object sender, EventArgs e)
        {
            if (_isDisposing) return;

            // Zero-Lag Gaming Optimization:
            // If GoodbyeDPI is in the background while user is gaming or in another app,
            // immediately suspend the 40 FPS animation loop so it consumes 0% CPU and 0 interrupts.
            if (Form.ActiveForm != this && !_isPinging && !_isSmartBenchmarkRunning)
            {
                if (_animTimer != null && _animTimer.Enabled) _animTimer.Stop();
                return;
            }

            if (_isPinging)
            {
                _pingSpinnerAngle = (_pingSpinnerAngle + 18f) % 360f;
                if (_headerPanel != null && !_headerPanel.IsDisposed)
                {
                    _headerPanel.Invalidate();
                }
            }

            if (_pendingUpdateInfo != null && _headerPanel != null && !_headerPanel.IsDisposed)
            {
                _updatePulseTick = (_updatePulseTick + 1) % 56;
                _headerPanel.Invalidate(new Rectangle(8, 0, 124, 44));
            }

            if (_btnToggle != null) _btnToggle.UpdateAnimation();
            if (_btnOptimizeGamingPing != null) _btnOptimizeGamingPing.UpdateAnimation();
            if (_btnOpenWhitelist != null) _btnOpenWhitelist.UpdateAnimation();
            if (_btnRepairNetworkAndDiscord != null) _btnRepairNetworkAndDiscord.UpdateAnimation();
            if (_btnOptimizeHardware != null) _btnOptimizeHardware.UpdateAnimation();
            if (_btnSmartBenchmark != null) _btnSmartBenchmark.UpdateAnimation();
            if (_selector != null) _selector.UpdateAnimation();
            if (_dnsSelector != null) _dnsSelector.UpdateAnimation();
            if (_btnDiagnostics != null) _btnDiagnostics.UpdateAnimation();
        }

        private static Color LerpColor(Color a, Color b, float t)
        {
            if (t < 0f) t = 0f; if (t > 1f) t = 1f;
            return Color.FromArgb((int)(a.A + (b.A - a.A) * t), (int)(a.R + (b.R - a.R) * t), (int)(a.G + (b.G - a.G) * t), (int)(a.B + (b.B - a.B) * t));
        }

        private int GetVersionBadgeWidth()
        {
            string vNum = "v" + UpdateManager.DisplayVersion;
            Size sz = TextRenderer.MeasureText(vNum, _fontVersion, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
            return Math.Max(64, sz.Width + 24);
        }

        internal static float MeasureCrispTextWidth(Graphics g, string text, Font font)
        {
            using (StringFormat format = new StringFormat(StringFormat.GenericTypographic))
            {
                format.FormatFlags |= StringFormatFlags.NoWrap;
                return g.MeasureString(text, font, 1000, format).Width;
            }
        }

        internal static void DrawCrispText(Graphics g, string text, Font font, Rectangle bounds, Color color, StringAlignment alignment)
        {
            using (StringFormat format = new StringFormat(StringFormat.GenericTypographic))
            using (SolidBrush brush = new SolidBrush(color))
            {
                format.Alignment = alignment;
                format.LineAlignment = StringAlignment.Center;
                format.FormatFlags |= StringFormatFlags.NoWrap;
                g.DrawString(text, font, brush, bounds, format);
            }
        }

        private Rectangle GetHeaderStatusBounds()
        {
            Rectangle pingRect = GetHeaderPingBounds();
            int statusWidth = 72;
            int gap = 8;
            int statusX = Math.Max(0, pingRect.X - gap - statusWidth);
            return new Rectangle(statusX, pingRect.Y, statusWidth, pingRect.Height);
        }

        private Rectangle GetHeaderPingBounds()
        {
            int headerWidth = (_headerPanel != null) ? _headerPanel.ClientSize.Width : this.ClientSize.Width;
            int pingWidth = 92;
            int rightPadding = 20;
            int pingX = Math.Max(0, headerWidth - rightPadding - pingWidth);
            return new Rectangle(pingX, 9, pingWidth, 26);
        }

        // Header Panel Painting (Sürüm/Güncelleme on left, Status Pill & Ping Chip on right)
        private void HeaderPanel_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            // Sürüm / Güncelleme Rozeti (Sol Tarafta) - Kalp Atışı (Lub-Dub) Animasyonlu Uyarı
            if (_pendingUpdateInfo != null)
            {
                float pulse = 0f;
                int t = _updatePulseTick % 56;
                if (t < 8) pulse = (float)Math.Sin((t / 8.0) * Math.PI) * 0.7f;              // Lub
                else if (t < 12) pulse = 0f;
                else if (t < 22) pulse = (float)Math.Sin(((t - 12) / 10.0) * Math.PI);       // Dub (tepe)
                if (_isUpdateHovered) pulse = Math.Max(pulse, 0.55f);

                Rectangle updRect = new Rectangle(20, 9, 104, 26);
                RectangleF updF = new RectangleF(updRect.X, updRect.Y, updRect.Width, updRect.Height);
                Color accent = Color.FromArgb(56, 189, 248);

                // Dış parlama halesi (nefes alan)
                if (pulse > 0.01f)
                {
                    for (int i = 3; i >= 1; i--)
                    {
                        float grow = i * 2.2f * pulse;
                        int a = (int)(38 * pulse / i);
                        using (GraphicsPath hp = CreateRoundedRectangleF(new RectangleF(updF.X - grow, updF.Y - grow, updF.Width + grow * 2, updF.Height + grow * 2), 7f + grow))
                        using (SolidBrush hb = new SolidBrush(Color.FromArgb(a, accent)))
                        {
                            g.FillPath(hb, hp);
                        }
                    }
                }

                Color baseBg = _isUpdateHovered ? Color.FromArgb(30, 64, 110) : Color.FromArgb(14, 40, 72);
                Color peakBg = Color.FromArgb(22, 78, 130);
                Color uBg = LerpColor(baseBg, peakBg, pulse * 0.8f);
                Color uBorder = LerpColor(Color.FromArgb(36, 110, 170), Color.FromArgb(125, 211, 252), pulse);

                DrawSmoothRoundedBox(g, updF, 7.0f, uBg, uBorder, 1.0f);

                // Kalp atışı LED işaret noktası
                float dcx = updRect.X + 13f;
                float dcy = updRect.Y + updRect.Height / 2f;
                Color dotClr = _isUpdateHovered ? Color.White : LerpColor(accent, Color.FromArgb(224, 242, 254), pulse);
                float ringR = 3.5f + 5.5f * pulse;
                using (SolidBrush ring = new SolidBrush(Color.FromArgb((int)(90 * pulse), accent)))
                using (SolidBrush core = new SolidBrush(dotClr))
                {
                    g.FillEllipse(ring, dcx - ringR, dcy - ringR, ringR * 2, ringR * 2);
                    float r = 3.2f + 1.0f * pulse;
                    g.FillEllipse(core, dcx - r, dcy - r, r * 2, r * 2);
                }

                Color txtClr = _isUpdateHovered ? Color.White : LerpColor(Color.FromArgb(186, 230, 253), Color.White, pulse);
                Rectangle txtRect = new Rectangle(updRect.X + 24, updRect.Y, updRect.Width - 28, updRect.Height);
                DrawCrispText(g, "GÜNCELLE", _fontUpdate, txtRect, txtClr, StringAlignment.Center);
            }
            else
            {
                int verW = GetVersionBadgeWidth();
                Rectangle verRect = new Rectangle(20, 9, verW, 26);
                Color vBg = _isVersionHovered ? Color.FromArgb(26, 34, 50) : Color.FromArgb(18, 22, 31);
                Color vBorder = _isVersionHovered ? Color.FromArgb(59, 130, 246) : Color.FromArgb(36, 45, 62);
                DrawSmoothRoundedBox(g, new RectangleF(verRect.X, verRect.Y, verRect.Width, verRect.Height), 7.0f, vBg, vBorder, 1.0f);
                string vNum = "v" + UpdateManager.DisplayVersion;
                Color vNumClr = _isVersionHovered ? Color.FromArgb(125, 211, 252) : Color.FromArgb(226, 232, 240);
                DrawCrispText(g, vNum, _fontVersion, verRect, vNumClr, StringAlignment.Center);
            }

            // Status Pill — modern Fluent durum rozeti
            Rectangle statusBounds = GetHeaderStatusBounds();
            Rectangle pingBounds = GetHeaderPingBounds();
            int pillW = statusBounds.Width;
            int pillH = statusBounds.Height;
            int pillX = statusBounds.X;
            int pillY = statusBounds.Y;

            bool stOn = _isRunning;
            Color pillBg = stOn
                ? (_isPillHovered ? Color.FromArgb(20, 52, 40) : Color.FromArgb(15, 41, 32))
                : (_isPillHovered ? Color.FromArgb(26, 33, 46) : Color.FromArgb(20, 25, 36));
            Color pillBorder = stOn
                ? (_isPillHovered ? Color.FromArgb(52, 211, 153) : Color.FromArgb(36, 110, 78))
                : (_isPillHovered ? Color.FromArgb(70, 84, 110) : Color.FromArgb(38, 48, 64));
            Color pillText = stOn
                ? (_isPillHovered ? Color.FromArgb(167, 243, 208) : Color.FromArgb(110, 231, 183))
                : (_isPillHovered ? Color.FromArgb(226, 232, 240) : Color.FromArgb(148, 163, 184));
            string statusStr = stOn ? "Aktif" : "Kapalı";

            DrawSmoothRoundedBox(g, new RectangleF(pillX, pillY, pillW, pillH), 7.0f, pillBg, pillBorder, 1.0f);

            Rectangle stRect = new Rectangle(pillX, pillY, pillW, pillH);
            DrawCrispText(g, statusStr, _fontPill, stRect, pillText, StringAlignment.Center);

            // ==================== İnternet Ping Çipi ====================
            int chipX = pingBounds.X;
            int chipY = pingBounds.Y;
            int chipW = pingBounds.Width;
            int chipH = pingBounds.Height;
            float chipCy = chipY + (chipH / 2.0f);

            // Ağ Verisi
            int netVal;
            bool hasNetPing = int.TryParse(_pingMs, out netVal);

            // Çip Gövdesi ve Zarif Koyu Kenarlık (Gereksiz neon yeşil çerçeve kaldırıldı)
            Color chipBg = _isPingHovered ? Color.FromArgb(24, 31, 44) : Color.FromArgb(17, 22, 32);
            Color chipBorder = _isPinging ? Color.FromArgb(56, 189, 248) : (_isPingHovered ? Color.FromArgb(58, 72, 98) : Color.FromArgb(36, 46, 64));

            DrawSmoothRoundedBox(g, new RectangleF(chipX, chipY, chipW, chipH), 7.0f, chipBg, chipBorder, 1.0f);

            // Yumuşak hover ışığı
            if (_isPingHovered)
            {
                using (GraphicsPath lp = CreateRoundedRectangleF(new RectangleF(chipX + 1.5f, chipY + 1.5f, chipW - 3f, chipH - 3f), 5.5f))
                using (SolidBrush lbr = new SolidBrush(Color.FromArgb(15, 56, 189, 248)))
                {
                    g.FillPath(lbr, lp);
                }
            }

            // İnternet pingi
            if (_isPinging)
            {
                float sx = chipX + (chipW / 2.0f);
                float sy = chipCy;
                g.TranslateTransform(sx, sy);
                g.RotateTransform(_pingSpinnerAngle);
                using (Pen spinPen = new Pen(Color.FromArgb(56, 189, 248), 1.8f))
                {
                    g.DrawArc(spinPen, -6f, -6f, 12f, 12f, 0, 260);
                }
                g.ResetTransform();
            }
            else
            {
                string pTxt = (_pingMs == "--" || string.IsNullOrEmpty(_pingMs)) ? "-- ms" : string.Format("{0} ms", _pingMs);
                Rectangle ptRect = new Rectangle(chipX + 10, chipY, chipW - 20, chipH);
                DrawCrispText(g, pTxt, _fontPing, ptRect, hasNetPing ? Color.FromArgb(241, 245, 249) : Color.FromArgb(148, 163, 184), StringAlignment.Center);
            }

            // Bottom subtle divider line
            using (Pen divPen = new Pen(Color.FromArgb(28, 35, 48), 1f))
            {
                g.DrawLine(divPen, 20, 43, 420, 43);
            }
        }

        private string GetNetworkPingToolTipText()
        {
            IspProfile currentProfile = (_selectedProfileIndex >= 0 && _selectedProfileIndex < _profiles.Count) ? _profiles[_selectedProfileIndex] : null;
            string ispInfo = (currentProfile != null && !string.IsNullOrEmpty(currentProfile.Name)) ? string.Format(" ({0})", currentProfile.Name) : "";
            return string.Format("Gecikme: {0} ms{1}\nYeniden ölçmek için tıklayın.", _pingMs, ispInfo);
        }

        private void HeaderPanel_MouseMove(object sender, MouseEventArgs e)
        {
            Rectangle pillRect = GetHeaderStatusBounds();
            Rectangle netPingRect = GetHeaderPingBounds();
            Rectangle updRect = new Rectangle(20, 9, 104, 26);
            Rectangle verRect = new Rectangle(20, 9, GetVersionBadgeWidth(), 26);

            bool isOverNetPing = netPingRect.Contains(e.Location);
            bool isOverUpd = (_pendingUpdateInfo != null) && updRect.Contains(e.Location);
            bool isOverVer = (_pendingUpdateInfo == null) && verRect.Contains(e.Location);
            bool isOverPill = pillRect.Contains(e.Location);

            if (isOverNetPing != _isPingHovered || isOverUpd != _isUpdateHovered || isOverVer != _isVersionHovered || isOverPill != _isPillHovered)
            {
                _isPingHovered = isOverNetPing;
                _isUpdateHovered = isOverUpd;
                _isVersionHovered = isOverVer;
                _isPillHovered = isOverPill;
                _headerPanel.Cursor = (isOverNetPing || isOverUpd || isOverVer) ? Cursors.Hand : Cursors.Default;
                _headerPanel.Invalidate();

                if (_toolTip != null)
                {
                    if (isOverNetPing)
                    {
                        _toolTip.SetToolTip(_headerPanel, GetNetworkPingToolTipText());
                    }
                    else if (isOverUpd)
                    {
                        _toolTip.SetToolTip(_headerPanel, string.Format("Yeni sürüm hazır (v{0}). Yüklemek için tıklayın.", _pendingUpdateInfo.Version));
                    }
                    else if (isOverVer)
                    {
                        _toolTip.SetToolTip(_headerPanel, "Güncellemeleri kontrol et.");
                    }
                    else if (isOverPill)
                    {
                        string tipText = _isRunning
                            ? "Koruma açık\nDiscord ve sitelere erişim aktif."
                            : "Koruma kapalı";
                        _toolTip.SetToolTip(_headerPanel, tipText);
                    }
                    else
                    {
                        _toolTip.SetToolTip(_headerPanel, null);
                    }
                }
            }
        }

        private void HeaderPanel_MouseLeave(object sender, EventArgs e)
        {
            if (_isPingHovered || _isUpdateHovered || _isVersionHovered || _isPillHovered)
            {
                _isPingHovered = false;
                _isUpdateHovered = false;
                _isVersionHovered = false;
                _isPillHovered = false;
                _headerPanel.Cursor = Cursors.Default;
                _headerPanel.Invalidate();
                if (_toolTip != null)
                {
                    _toolTip.SetToolTip(_headerPanel, null);
                }
            }
        }

        private void HeaderPanel_MouseClick(object sender, MouseEventArgs e)
        {
            // Sağ tık / tekerlek tıklamaları ping veya güncelleme diyaloğunu tetiklemesin.
            if (e.Button != MouseButtons.Left) return;
            Rectangle netPingRect = GetHeaderPingBounds();
            Rectangle updRect = new Rectangle(20, 9, 104, 26);
            Rectangle verRect = new Rectangle(20, 9, GetVersionBadgeWidth(), 26);

            if (netPingRect.Contains(e.Location))
            {
                TriggerManualPing();
            }
            else if (_pendingUpdateInfo != null && updRect.Contains(e.Location))
            {
                if (UpdateDialog.IsOpen)
                {
                    UpdateDialog.FocusCurrent();
                }
                else
                {
                    using (UpdateDialog dlg = new UpdateDialog(_pendingUpdateInfo, delegate { PrepareForUpdateStart(); }))
                    {
                        dlg.StartPosition = FormStartPosition.CenterScreen;
                        dlg.TopMost = true;
                        dlg.ShowDialog(this);
                    }
                }
            }
            else if (_pendingUpdateInfo == null && verRect.Contains(e.Location))
            {
                CheckForUpdates(silent: false);
            }
        }

        public static void OptimizeGamingNetworkDirect()
        {
            // 1. Windows Multimedia Network Throttling Optimization
            try
            {
                using (RegistryKey key = Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"))
                {
                    if (key != null)
                    {
                        key.SetValue("NetworkThrottlingIndex", unchecked((int)0xffffffff), RegistryValueKind.DWord);
                        key.SetValue("SystemResponsiveness", 5, RegistryValueKind.DWord);
                    }
                }
            }
            catch {}

            // 2. Gaming Task Priority Optimization (MMCSS)
            try
            {
                using (RegistryKey key = Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games"))
                {
                    if (key != null)
                    {
                        key.SetValue("GPU Priority", 8, RegistryValueKind.DWord);
                        key.SetValue("Priority", 6, RegistryValueKind.DWord);
                        key.SetValue("Scheduling Category", "High", RegistryValueKind.String);
                        key.SetValue("SFIO Priority", "High", RegistryValueKind.String);
                    }
                }
            }
            catch {}

            // 3. Network Interface Latency Clean-up:
            // Agresif TcpAckFrequency=1 / TCPNoDelay=1 zorlamaları yüksek hızlı internette
            // DPC/ISR gecikme sıçramalarına ve rekabetçi oyunlarda fare takılmasına (stutter) yol açar.
            // Sihirbaz ve ana ekran tam tutarlı olacak şekilde bu zorlamalar temizlenir.
            try
            {
                using (RegistryKey interfacesKey = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces", true))
                {
                    if (interfacesKey != null)
                    {
                        foreach (string subName in interfacesKey.GetSubKeyNames())
                        {
                            try
                            {
                                using (RegistryKey nicKey = interfacesKey.OpenSubKey(subName, true))
                                {
                                    if (nicKey != null)
                                    {
                                        try { nicKey.DeleteValue("TcpAckFrequency", false); } catch {}
                                        try { nicKey.DeleteValue("TCPNoDelay", false); } catch {}
                                    }
                                }
                            }
                            catch {}
                        }
                    }
                }
            }
            catch {}

            // 4. Global TCP parameters (DefaultTTL = 64) & Geri Alınabilir Windows TCP Ağ Yığını İnce Ayarı
            SaveTcpStackBackupIfNeeded();
            try
            {
                using (RegistryKey tcpParamKey = Registry.LocalMachine.CreateSubKey(@"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters"))
                {
                    if (tcpParamKey != null)
                    {
                        tcpParamKey.SetValue("DefaultTTL", 64, RegistryValueKind.DWord);
                    }
                }
            }
            catch {}

            ApplyReversibleTcpStackOptimization();
            FlushDnsFast();
        }

        private const string TcpStackOptimizedValueName = "TcpStackOptimized";
        private const string TcpBackupDefaultTtlValueName = "TcpBackupDefaultTtl";
        private const string TcpBackupAutoTuningValueName = "TcpBackupAutoTuning";
        private const string TcpBackupRssValueName = "TcpBackupRss";
        private const string TcpBackupFastOpenValueName = "TcpBackupFastOpen";

        // TCP yığını ince ayarı uygulanmadan önce kullanıcının mevcut sistem değerlerini
        // Registry üzerinde yedekler; böylece "Ağ ve Discord'u onar" ile tam geri alma (Safe Rollback) sağlanır.
        private static void SaveTcpStackBackupIfNeeded()
        {
            try
            {
                using (RegistryKey appKey = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                {
                    if (appKey == null) return;
                    object alreadyBackedUp = appKey.GetValue(TcpStackOptimizedValueName);
                    if (alreadyBackedUp is int && ((int)alreadyBackedUp) == 1) return;

                    int prevTtl = -1;
                    try
                    {
                        using (RegistryKey tcpKey = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters", false))
                        {
                            if (tcpKey != null)
                            {
                                object ttlObj = tcpKey.GetValue("DefaultTTL");
                                if (ttlObj is int) prevTtl = (int)ttlObj;
                            }
                        }
                    }
                    catch {}

                    appKey.SetValue(TcpBackupDefaultTtlValueName, prevTtl, RegistryValueKind.DWord);
                    appKey.SetValue(TcpBackupAutoTuningValueName, "normal", RegistryValueKind.String);
                    appKey.SetValue(TcpBackupRssValueName, "enabled", RegistryValueKind.String);
                    appKey.SetValue(TcpBackupFastOpenValueName, "enabled", RegistryValueKind.String);
                    appKey.SetValue(TcpStackOptimizedValueName, 1, RegistryValueKind.DWord);
                }
            }
            catch {}
        }

        // Windows TCP Ağ Yığını İnce Ayar Motoru:
        // autotuninglevel=normal, rss=enabled (çok çekirdekli ağ işleme) ve fastopen=enabled
        // komutlarını tek bir toplu netsh oturumunda uygular.
        public static void ApplyReversibleTcpStackOptimization()
        {
            try
            {
                StringBuilder batch = new StringBuilder();
                batch.AppendLine("int tcp set global autotuninglevel=normal");
                batch.AppendLine("int tcp set global rss=enabled");
                batch.AppendLine("int tcp set global fastopen=enabled");
                batch.AppendLine("exit");

                ProcessStartInfo psi = new ProcessStartInfo(SystemTool("netsh"));
                psi.UseShellExecute = false;
                psi.CreateNoWindow = true;
                psi.WindowStyle = ProcessWindowStyle.Hidden;
                psi.RedirectStandardInput = true;
                psi.RedirectStandardOutput = false;
                psi.RedirectStandardError = false;

                using (Process p = Process.Start(psi))
                {
                    if (p != null)
                    {
                        try
                        {
                            p.StandardInput.Write(batch.ToString());
                            p.StandardInput.Flush();
                            p.StandardInput.Close();
                        }
                        catch {}
                        if (!p.WaitForExit(4000))
                        {
                            try { p.Kill(); p.WaitForExit(1000); } catch {}
                        }
                    }
                }
                AppLogger.Log("TCP_STACK", "Windows TCP Ağ Yığını İnce Ayarı uygulandı (AutoTuning=normal, RSS=enabled, FastOpen=enabled).");
            }
            catch (Exception ex)
            {
                AppLogger.Log("TCP_STACK", "TCP yığını ince ayarı uygulanırken hata: " + ex.Message, LogLevel.Warn);
            }
        }

        // Kayıtlı TCP yığını yedeğini geri yükler ve yedek bayrağını temizler (Safe Rollback).
        public static void RestoreTcpStackFromBackup()
        {
            try
            {
                int prevTtl = -1;
                using (RegistryKey appKey = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, true))
                {
                    if (appKey != null)
                    {
                        object ttlVal = appKey.GetValue(TcpBackupDefaultTtlValueName);
                        if (ttlVal is int) prevTtl = (int)ttlVal;
                        appKey.SetValue(TcpStackOptimizedValueName, 0, RegistryValueKind.DWord);
                    }
                }

                using (RegistryKey tcpKey = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters", true))
                {
                    if (tcpKey != null)
                    {
                        if (prevTtl > 0 && prevTtl <= 255)
                        {
                            tcpKey.SetValue("DefaultTTL", prevTtl, RegistryValueKind.DWord);
                        }
                        else
                        {
                            try { tcpKey.DeleteValue("DefaultTTL", false); } catch {}
                        }
                    }
                }
            }
            catch {}
        }

        // Dropdown Popup Handler (Click-to-open / Click-to-close dropdown toggle)
        private void Selector_Click(object sender, EventArgs e)
        {
            if (IsProfileBenchmarkBlocking()) return;

            if ((DateTime.UtcNow - _lastDropdownCloseTime).TotalMilliseconds < 350)
            {
                return;
            }

            ShowDropdownPopup();
        }

        private void ShowDropdownPopup()
        {
            if (IsProfileBenchmarkBlocking()) return;

            if (_dropdownPopup != null && _dropdownPopup.Visible)
            {
                _lastDropdownCloseTime = DateTime.UtcNow;
                _dropdownPopup.Close();
                return;
            }

            if (_dropdownPopup != null)
            {
                try { _dropdownPopup.Dispose(); } catch {}
                _dropdownPopup = null;
            }

            _selector.IsOpen = true;
            _selector.Invalidate();

            _dropdownPopup = new ToolStripDropDown();
            _dropdownPopup.AutoClose = true;
            _dropdownPopup.DropShadowEnabled = true;
            _dropdownPopup.Margin = Padding.Empty;
            _dropdownPopup.Padding = Padding.Empty;
            _dropdownPopup.Renderer = new DarkDropdownRenderer();

            IspDropdownMenuList menuList = new IspDropdownMenuList(_profiles, _selectedProfileIndex, delegate(int index)
            {
                if (IsProfileBenchmarkBlocking()) return;

                bool changed = (_selectedProfileIndex != index);
                _userManuallySelectedIsp = true;
                SaveAutoScanCompleted(true);
                SetSelectedProfile(index);
                if (_dropdownPopup != null) _dropdownPopup.Close();
                if (changed && index >= 0 && index < _profiles.Count)
                {
                    ToastNotification.Show("Profil Değiştirildi", _profiles[index].Name + " profili etkinleştirildi.", ToastType.Info, 2600);
                }
            }, delegate
            {
                _userManuallySelectedIsp = false;
                if (_selector != null && !_selector.IsDisposed)
                {
                    _selector.IsAutoModePending = true;
                    _selector.IsAutoSelected = true;
                    _selector.Invalidate();
                }
                if (_dropdownPopup != null) _dropdownPopup.Close();
                RunSmartIspBenchmarkAsync();
            }, !_userManuallySelectedIsp, delegate { return IsProfileBenchmarkBlocking(); });

            ToolStripControlHost host = new ToolStripControlHost(menuList);
            host.Margin = Padding.Empty;
            host.Padding = Padding.Empty;
            host.AutoSize = false;
            host.Size = menuList.Size;

            _dropdownPopup.Items.Clear();
            _dropdownPopup.Items.Add(host);

            _dropdownPopup.Closed += delegate
            {
                _lastDropdownCloseTime = DateTime.UtcNow;
                _selector.IsOpen = false;
                _selector.Invalidate();
            };

            Point ptDown = _selector.PointToScreen(new Point(0, _selector.Height + 4));
            Screen screen = Screen.FromControl(_selector);
            int menuH = menuList.Height;
            int menuW = menuList.Width;
            Point finalPt = ptDown;
            if (ptDown.Y + menuH > screen.WorkingArea.Bottom)
            {
                // Open upwards above button if near bottom edge of screen
                Point ptUp = _selector.PointToScreen(new Point(0, -menuH - 4));
                finalPt = ptUp;
            }
            if (finalPt.X + menuW > screen.WorkingArea.Right)
            {
                // Shift left if overflowing right screen edge
                finalPt.X = Math.Max(screen.WorkingArea.Left, screen.WorkingArea.Right - menuW - 8);
            }
            _dropdownPopup.Show(finalPt);
        }

        // Profil veya DNS arka arkaya hızlı değiştirildiğinde çekirdek sürücüsünün (WinDivert)
        // kilitlenmesini (Start=4) ve "Error receiving packet!" hatasını önlemek için 600ms debounce uygular.
        private void RequestDebouncedProtectionRestart(string reason)
        {
            if (!_isRunning || _isDisposing || this.IsDisposed) return;
            if (_profileSwitchDebounceTimer != null)
            {
                _profileSwitchDebounceTimer.Stop();
                _profileSwitchDebounceTimer.Dispose();
                _profileSwitchDebounceTimer = null;
            }

            _profileSwitchDebounceTimer = new System.Windows.Forms.Timer();
            _profileSwitchDebounceTimer.Interval = 800; // 800ms bekleme: sürücü kilitlenmesini ve seri yeniden başlatma çakışmalarını önler
            _profileSwitchDebounceTimer.Tick += delegate
            {
                if (_profileSwitchDebounceTimer != null)
                {
                    _profileSwitchDebounceTimer.Stop();
                    _profileSwitchDebounceTimer.Dispose();
                    _profileSwitchDebounceTimer = null;
                }
                if (_isRunning && !_isDisposing && !this.IsDisposed)
                {
                    AppLogger.Log("UI", "Ayarlar uygulandı, motor yeniden başlatılıyor: " + reason);
                    RestartProtectionAsync();
                    FlushDnsFast();
                }
            };
            _profileSwitchDebounceTimer.Start();
        }

        public void SyncActiveProfileLatency(long ms)
        {
            if (_selectedProfileIndex >= 0 && _selectedProfileIndex < _profiles.Count)
            {
                if (ms >= 0)
                {
                    _profiles[_selectedProfileIndex].PingMs = ms;
                    _profiles[_selectedProfileIndex].PingMeasuredUtc = DateTime.UtcNow;
                }
            }
            if (ms >= 0 && (_isRunning || _pingMs != "--"))
            {
                _pingMs = ms.ToString();
            }
            if (_headerPanel != null && !_headerPanel.IsDisposed) _headerPanel.Invalidate();
            if (_selector != null && !_selector.IsDisposed) _selector.Invalidate();
        }

        public void SetSelectedProfile(int index)
        {
            if (index < 0 || index >= _profiles.Count) return;
            bool sameIndex = (_selectedProfileIndex == index);

            _selectedProfileIndex = index;
            SaveSelectedProfile(index);
            UpdateIspMenuChecks();
            if (_selector != null)
            {
                _selector.IsAutoModePending = !_isAutoScanCompleted && !_userManuallySelectedIsp;
                _selector.IsAutoSelected = !_userManuallySelectedIsp;
                _selector.Profile = _profiles[_selectedProfileIndex];
                _selector.Invalidate();
            }
            if (_profiles[index].PingMs >= 0 && (_isRunning || _pingMs != "--"))
            {
                _pingMs = _profiles[index].PingMs.ToString();
                if (_headerPanel != null && !_headerPanel.IsDisposed) _headerPanel.Invalidate();
            }
            if (!sameIndex)
            {
                AppLogger.Log("ISP", "İSS Profili seçildi: " + _profiles[index].Name);
                try { AppTelemetry.SendHeartbeatAsync(true); } catch {}
            }
            TriggerManualPing();

            if (_isRunning && !sameIndex)
            {
                RequestDebouncedProtectionRestart("Profil: " + _profiles[index].Name);
            }
        }

        // ==================== İlk Açılış Sihirbazı Entegrasyonu ====================

        // Sihirbazı gecikmeli açar; oyun algılanırsa 5 dk erteler, pencere tepsideyse 30 sn sonra tekrar dener.
        private void StartWizardCountdown(int delayMs)
        {
            System.Windows.Forms.Timer t = new System.Windows.Forms.Timer();
            t.Interval = delayMs;
            t.Tick += delegate
            {
                t.Stop();
                t.Dispose();
                if (_isDisposing || this.IsDisposed) return;


                // Pencere gizli/minimize ise kısa aralıklarla tekrar dene (modal odak çalmamalı)
                if (!this.Visible || this.WindowState == FormWindowState.Minimized)
                {
                    StartWizardCountdown(30 * 1000);
                    return;
                }

                OpenWizard();
            };
            t.Start();
        }

        public void OpenWizard()
        {
            if (_wizardOpen || _isDisposing || this.IsDisposed) return;
            _wizardOpen = true;
            try
            {
                AppLogger.Log("WIZARD", "Kurulum sihirbazı açılıyor...");
                using (WizardForm wz = new WizardForm(_profiles, _dnsOptions, _selectedProfileIndex, _selectedDnsIndex))
                {
                    wz.ShowDialog(this);

                    // Sihirbaz hangi yolla kapanırsa kapansın (tamam / atla / ✕) bir daha otomatik açılmaz
                    WriteFirstRunMarker();

                    if (wz.Applied && !_isDisposing && !this.IsDisposed)
                    {
                        ApplyWizardSelection(wz.ResultProfileIdx, wz.ResultDnsIdx);

                        if (wz.ApplyGamingOptimization)
                        {
                            ToastNotification.Show("Oyun Optimizasyonu", "A\u011f ayarlar\u0131 uyguland\u0131. Bilgisayar\u0131 yeniden ba\u015flat\u0131n.", ToastType.Success, 4500);
                            OptimizeGamingNetworkDirect();
                        }

                        if (wz.StartProtection && !_isRunning)
                        {
                            RestartProtectionAsync();
                        }
                    }
                    else if (!_isAutoScanCompleted && !_isDisposing && !this.IsDisposed)
                    {
                        StartAutoBenchmarkCountdown(400);
                    }
                }
            }
            catch (Exception ex)
            {
                try { AppLogger.Log("WIZARD", "Sihirbaz hatası: " + ex.Message); } catch {}
                if (!_isAutoScanCompleted && !_isDisposing && !this.IsDisposed) StartAutoBenchmarkCountdown(400);
            }
            finally
            {
                _wizardOpen = false;
            }
        }

        // Sihirbaz sonucunu ana ekrana + registry'ye uygular (profil + DNS seçimi)
        public void ApplyWizardSelection(int profileIdx, int dnsIdx)
        {
            try
            {
                if (profileIdx >= 0 && profileIdx < _profiles.Count)
                {
                    _userManuallySelectedIsp = false;
                    SaveAutoScanCompleted(true);
                    MarkBestIspProfile(profileIdx, saveToRegistry: true);
                    SaveSelectedProfile(profileIdx);
                    if (profileIdx != _selectedProfileIndex)
                    {
                        SetSelectedProfile(profileIdx);
                    }
                    else if (_selector != null)
                    {
                        _selector.IsAutoModePending = false;
                        _selector.IsAutoSelected = true;
                        _selector.Profile = _profiles[profileIdx];
                        _selector.Invalidate();
                    }
                }

                if (dnsIdx >= 0 && dnsIdx < _dnsOptions.Count)
                {
                    SaveSelectedDns(dnsIdx);
                    if (dnsIdx != _selectedDnsIndex)
                    {
                        SelectDnsProvider(dnsIdx);
                    }
                    else if (_dnsSelector != null)
                    {
                        _dnsSelector.SetSelected(dnsIdx);
                    }
                }

                AppLogger.Log("WIZARD", string.Format("Sihirbaz seçimleri uygulandı: Profil={0}, DNS={1}",
                    (profileIdx >= 0 && profileIdx < _profiles.Count) ? _profiles[profileIdx].Name : "-",
                    (dnsIdx >= 0 && dnsIdx < _dnsOptions.Count) ? _dnsOptions[dnsIdx].DisplayName : "-"));
            }
            catch (Exception ex)
            {
                try { AppLogger.Log("WIZARD", "Seçim uygulama hatası: " + ex.Message); } catch {}
            }
            finally
            {
                _isProfileBenchmarkPending = false;
                ApplyBenchmarkInteractionState();
            }
        }

        // Sihirbaz görüldü işareti: oturum sona erdiğinde yazılır (tamam / atla / ✕).
        // Bu işaret varsa sihirbaz — güncelleme sonrası ilk açılışta bile — bir daha otomatik açılmaz.
        private static void WriteFirstRunMarker()
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                {
                    if (key != null)
                    {
                        key.SetValue("FirstRunCompleted", 1, RegistryValueKind.DWord);
                        key.SetValue("FirstRunVersion", UpdateManager.DisplayVersion, RegistryValueKind.String);
                    }
                }
            }
            catch {}
        }

        // ISP Auto-Detection (100% Offline / Local Network Interface & Next-Hop Omurga Probe)
        private void DetectIspAsync()
        {
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    int suggested = NetworkProbe.DetectIspLocalAndNextHop();
                    if (suggested < 0 || suggested >= _profiles.Count) return;

                    int lossPct;
                    long peerMs = NetworkProbe.MeasureTargetQuality(_profiles[suggested].PeeringTarget, 2, 550, out lossPct);
                    if (peerMs >= 0)
                    {
                        _profiles[suggested].PingMs = peerMs;
                        _profiles[suggested].PacketLossPct = lossPct;
                        _profiles[suggested].PingMeasuredUtc = DateTime.UtcNow;
                    }

                    if (!_isDisposing && !this.IsDisposed)
                    {
                        for (int retry = 0; retry < 30 && !this.IsHandleCreated && !this.IsDisposed && !_isDisposing; retry++)
                        {
                            Thread.Sleep(50);
                        }

                        if (!_isDisposing && !this.IsDisposed && this.IsHandleCreated)
                        {
                            try
                            {
                                this.BeginInvoke((MethodInvoker)delegate
                                {
                                    if (_isDisposing || this.IsDisposed) return;
                                    MarkBestIspProfile(suggested, saveToRegistry: true);
                                    if (!_isRunning && !_userManuallySelectedIsp)
                                    {
                                        AppLogger.Log("ISP", "Otomatik İSS algılandı: " + _profiles[suggested].Name);
                                        SetSelectedProfile(suggested);
                                    }
                                    else if (_selectedProfileIndex == suggested && peerMs >= 0)
                                    {
                                        // Do not overwrite header ping chip with local peering probe
                                    }
                                });
                            }
                            catch {}
                        }
                    }
                }
                catch {}
            });
        }

        // Akıllı Profil Önerici (Smart ISP Benchmark - 4 Katmanlı Sıfır-Takılma Algoritması):
        // 1) Hızlı Omurga (TTL 2..6) ASN Tespiti + Pasif DPI & DNS Parmak İzi Analizi:
        //    - DNS Zehirleme İmzası (195.175.254.2 / 212.156.x.x -> Türk Telekom altyapı imzası)
        //    - Şeffaf DNS Vekili (Port 53 kesintisi + Yandex 1253 kontrolü)
        //    - DPI Cihazı Mesafesi (RST RTT ms) ve TLS ClientHello tepki tipi (Anında RST vs Timeout/Drop Blackhole)
        // 2) Tekilleştirilmiş Hedef IP Medyan Gecikme + Jitter + Paket Kaybı + Sağlayıcı Öncelik Puanlaması
        // 3) Doğrudan SNI TLS Doğrulaması (162.159.135.234:443 -> gateway.discord.gg)
        public void RunSmartIspBenchmarkAsync()
        {
            lock (IspDropdownMenuList.ProfileMeasurementSync)
            {
                if (_isSmartBenchmarkRunning || _isDisposing || this.IsDisposed) return;
                _isProfileBenchmarkPending = true;
                _isSmartBenchmarkRunning = true;
            }

            ApplyBenchmarkInteractionState();

            if (this.Visible && _animTimer != null && !_animTimer.Enabled) _animTimer.Start();
            if (_selector != null && !_selector.IsDisposed)
            {
                _selector.StartBenchmark("Taranıyor...", 0.08f);
            }

            Thread benchThread = new Thread(delegate()
            {
                try
                {
                    Stopwatch swTotal = Stopwatch.StartNew();

                    // --- AŞAMA 1 (0.0s - 1.3s): Omurga Tespiti + Pasif DNS Zehirleme & Port 53 Vekil İmzası ---
                    UpdateBenchmarkProgressUI("Taranıyor...", 0.16f);
                    int detectedIsp = NetworkProbe.DetectIspLocalAndNextHop();
                    if (_isDisposing || this.IsDisposed) return;

                    UpdateBenchmarkProgressUI("Taranıyor...", 0.25f);
                    bool ttnetDnsPoisonSignature = NetworkProbe.DetectTtnetDnsPoisonSignature();
                    bool port53Intercepted = false;
                    try
                    {
                        int b1, b2;
                        string e1, e2;
                        // Port 53 testi iÃ§in dar zaman aÅŸÄ±mÄ± (380 ms) yerine gÃ¼venli 1200 ms kullanÄ±lÄ±r.
                        // Wi-Fi veya anlÄ±k dalgalanmalarda Yandex'e geÃ§memesi iÃ§in 1.1.1.1 ve 8.8.8.8 ile Ã§ift doÄŸrulama yapÄ±lÄ±r.
                        long dns53 = NetworkProbe.TestUdpDns("1.1.1.1", 53, 1200, out b1, out e1);
                        if (dns53 < 0)
                        {
                            dns53 = NetworkProbe.TestUdpDns("8.8.8.8", 53, 1200, out b1, out e1);
                        }
                        if (dns53 < 0)
                        {
                            Thread.Sleep(50);
                            dns53 = NetworkProbe.TestUdpDns("1.1.1.1", 53, 1200, out b1, out e1);
                        }
                        long dns9953 = NetworkProbe.TestUdpDns("9.9.9.9", 9953, 1200, out b2, out e2);
                        if (dns53 < 0 && dns9953 >= 0)
                        {
                            port53Intercepted = true;
                        }
                    }
                    catch {}

                    while (swTotal.ElapsedMilliseconds < 1200 && !_isDisposing)
                    {
                        float p1 = Math.Min(0.35f, 0.10f + (swTotal.ElapsedMilliseconds / 1200f) * 0.25f);
                        UpdateBenchmarkProgressUI("Taranıyor...", p1);
                        Thread.Sleep(60);
                    }
                    if (_isDisposing || this.IsDisposed) return;

                    // --- AŞAMA 2 (1.3s - 3.1s): Tekilleştirilmiş Hedef IP Medyan Gecikme, Jitter & Kayıp Ölçümü ---
                    UpdateBenchmarkProgressUI("Taranıyor...", 0.40f);

                    int totalProfiles = _profiles.Count;
                    long[] profileJitter = new long[totalProfiles];
                    Dictionary<string, long> ipRttCache = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
                    Dictionary<string, int> ipLossCache = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                    Dictionary<string, long> ipJitterCache = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);

                    List<string> uniqueTargets = new List<string>();
                    for (int i = 0; i < totalProfiles; i++)
                    {
                        string tIp = _profiles[i].PeeringTarget;
                        if (!string.IsNullOrEmpty(tIp) && !uniqueTargets.Contains(tIp))
                        {
                            uniqueTargets.Add(tIp);
                        }
                    }

                    for (int u = 0; u < uniqueTargets.Count && !_isDisposing; u++)
                    {
                        string targetIp = uniqueTargets[u];
                        float prog2 = Math.Min(0.72f, 0.40f + ((u + 1f) / Math.Max(1, uniqueTargets.Count)) * 0.32f);
                        UpdateBenchmarkProgressUI("Taranıyor...", prog2);

                        int lossPct;
                        long jitterMs;
                        long rtt = NetworkProbe.MeasureTargetQualityDetailed(targetIp, 3, 500, out lossPct, out jitterMs);
                        if (rtt < 0)
                        {
                            string altTarget = (targetIp == "66.22.244.2") ? "66.22.244.1" : "66.22.244.2";
                            rtt = NetworkProbe.MeasureTargetQualityDetailed(altTarget, 2, 600, out lossPct, out jitterMs);
                        }
                        ipRttCache[targetIp] = rtt;
                        ipLossCache[targetIp] = (rtt >= 0) ? lossPct : 100;
                        ipJitterCache[targetIp] = jitterMs;
                    }

                    for (int i = 0; i < totalProfiles; i++)
                    {
                        string tIp = _profiles[i].PeeringTarget;
                        long rtt;
                        if (!string.IsNullOrEmpty(tIp) && ipRttCache.TryGetValue(tIp, out rtt))
                        {
                            _profiles[i].PingMs = rtt;
                            _profiles[i].PacketLossPct = ipLossCache[tIp];
                            _profiles[i].PingMeasuredUtc = DateTime.UtcNow;
                            profileJitter[i] = ipJitterCache[tIp];
                        }
                    }

                    while (swTotal.ElapsedMilliseconds < 2900 && !_isDisposing)
                    {
                        float elapsedStage2 = Math.Max(0f, swTotal.ElapsedMilliseconds - 1200f);
                        float p2 = Math.Min(0.74f, 0.40f + (elapsedStage2 / 1700f) * 0.34f);
                        UpdateBenchmarkProgressUI("Taranıyor...", p2);
                        Thread.Sleep(60);
                    }
                    if (_isDisposing || this.IsDisposed) return;

                    // --- AŞAMA 3 (3.1s - 4.5s): Pasif DPI Tepki Analizi (OPEN / RST / DROP) & TLS Doğrulaması ---
                    UpdateBenchmarkProgressUI("Taranıyor...", 0.80f);

                    long dpiRstOrTlsMs = -1;
                    string dpiReaction = NetworkProbe.ProbeTlsDpiBehavior("gateway.discord.gg", 650, out dpiRstOrTlsMs);
                    UpdateBenchmarkProgressUI("Taranıyor...", 0.90f);

                    // --- 4 Katmanlı Akıllı Puanlama (Düşük puan = Daha iyi uyum) ---
                    int bestIdx = -1;
                    long bestScore = long.MaxValue;
                    for (int i = 0; i < _profiles.Count; i++)
                    {
                        long rtt = _profiles[i].PingMs;
                        if (rtt < 0) continue;

                        // 1. Katman: Paket Kaybı + Medyan RTT + Jitter (Dalgalanma)
                        long score = (_profiles[i].PacketLossPct * 6L) + rtt + (profileJitter[i] * 2L);

                        // 2. Katman: Gerçek Omurga / ASN Eşleşmesi ve Niş Sağlayıcı Koruması
                        if (detectedIsp == i)
                        {
                            score -= 120L; // Omurgadan kesin tespit edilen gerçek İSS'ye mutlak öncelik
                        }
                        else if (i >= 5 && detectedIsp < 0)
                        {
                            // Millenicom(5), Netspeed(6), GıbırNet(7), Diğer(8) omurgadan bizzat tespit edilmediyse
                            // rastgele 1-2 ms ping farkıyla ana sağlayıcıların önüne geçmesini engelle
                            score += 35L;
                        }

                        // 3. Katman: Pasif DPI & DNS Parmak İzi Analizi (Koruma kapalıyken bile çalışır)
                        // Omurga kesin tespit edildiyse diğer sağlayıcıların bu kuraldan haksız bonus almasını engelle
                        if (detectedIsp < 0 || detectedIsp == i)
                        {
                            // - DNS Zehirleme İmzası (195.175.254.2 veya 212.156.x.x -> Türk Telekom altyapı imzası)
                            if (ttnetDnsPoisonSignature)
                            {
                                if (i == 0) score -= 45L;      // Türk Telekom (TTNet)
                                else if (i == 4) score -= 18L; // TTNet VDSL omurgası kullanan TurkNet (-1 -p)
                            }

                            // - Şeffaf DNS Vekili (Port 53 Drop/Intercept) + TLS ClientHello Timeout (Drop/Blackhole)
                            //   -> Superonline / Vodafone / Netspeed derin paket inceleme (DPI) imzası
                            if (port53Intercepted && dpiReaction == "DROP")
                            {
                                if (i == 1) score -= 42L;      // Turkcell Superonline (-5 --wrong-chksum)
                                else if (i == 2) score -= 36L; // Vodafone Türkiye (-9 --auto-ttl)
                                else if (i == 6) score -= 38L; // Netspeed (-9 -q --native-frag --auto-ttl)
                                else if (i == 8) score -= 15L; // Diğer (-9 --wrong-chksum --wrong-seq)
                            }
                            else if (dpiReaction == "DROP")
                            {
                                if (i == 1) score -= 24L;
                                else if (i == 2) score -= 20L;
                                else if (i == 6) score -= 22L;
                            }

                            // - DPI Cihazı Mesafesi (RST RTT): ClientHello sonrası anında sahte TCP Reset (ör. 4-18 ms)
                            //   -> Yakın mesafeli inline RST kutularına karşı -1 ve -1 -p / --native-frag önceliği
                            if (dpiReaction == "RST")
                            {
                                if (i == 0) score -= 28L;      // Türk Telekom (-1 --auto-ttl)
                                else if (i == 4) score -= 24L; // TurkNet (-1 -p --auto-ttl)
                                else if (i == 3) score -= 16L; // Kablonet (-1 --native-frag)
                            }
                        }

                        if (score < bestScore)
                        {
                            bestScore = score;
                            bestIdx = i;
                        }
                    }

                    if (bestIdx < 0 || bestIdx >= _profiles.Count)
                    {
                        bestIdx = (detectedIsp >= 0 && detectedIsp < _profiles.Count)
                            ? detectedIsp
                            : ((_selectedProfileIndex >= 0 && _selectedProfileIndex < _profiles.Count) ? _selectedProfileIndex : 0);
                    }

                    // 4. Katman: Koruma açıkken mevcut profilde TLS el sıkışması başarısızsa (dpiReaction != "OPEN")
                    // WinDivert sürücüsünü art arda 5 kez kapatıp açarak sistemi dondurmak yerine,
                    // DPI tepki imzasına (DROP vs RST) en uygun alternatif stratejiyi seç!
                    long verifiedTlsMs = (dpiReaction == "OPEN") ? dpiRstOrTlsMs : -1;
                    if (_isRunning && dpiReaction != "OPEN" && bestIdx == _selectedProfileIndex)
                    {
                        int[] orderedStrategies = (dpiReaction == "DROP" || bestIdx == 1 || bestIdx == 2)
                            ? new int[] { 1, 2, 4, 0, 3 }
                            : new int[] { 4, 0, 1, 2, 3 };
                        for (int k = 0; k < orderedStrategies.Length; k++)
                        {
                            if (orderedStrategies[k] != _selectedProfileIndex)
                            {
                                bestIdx = orderedStrategies[k];
                                break;
                            }
                        }
                    }

                    while (swTotal.ElapsedMilliseconds < 4300 && !_isDisposing)
                    {
                        float elapsedStage3 = Math.Max(0f, swTotal.ElapsedMilliseconds - 2900f);
                        float p3 = Math.Min(0.98f, 0.80f + (elapsedStage3 / 1400f) * 0.18f);
                        UpdateBenchmarkProgressUI("Taranıyor...", p3);
                        Thread.Sleep(60);
                    }
                    if (_isDisposing || this.IsDisposed) return;

                    _profiles[bestIdx].TlsHandshakeMs = verifiedTlsMs;

                    AppLogger.Log("ISP-BENCH", string.Format(
                        "Parmak İzi Özeti -> OmurgaİSS={0}, TTNetDnsİmzası={1}, Port53Vekil={2}, DpiTepki={3} ({4} ms), Seçilen={5}",
                        (detectedIsp >= 0 && detectedIsp < _profiles.Count) ? _profiles[detectedIsp].Name : "Belirsiz",
                        ttnetDnsPoisonSignature ? "Evet" : "Hayır",
                        port53Intercepted ? "Evet" : "Hayır",
                        dpiReaction,
                        dpiRstOrTlsMs,
                        _profiles[bestIdx].Name));

                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        int finalBestIdx = bestIdx;
                        bool finalPort53Blocked = port53Intercepted;
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (_isDisposing || this.IsDisposed) return;

                            _userManuallySelectedIsp = false;
                            SaveAutoScanCompleted(true);
                            MarkBestIspProfile(finalBestIdx, saveToRegistry: true);
                            SetSelectedProfile(finalBestIdx);

                            // Eğer İSS Port 53'ü şeffaf vekille kesiyorsa veya düşürüyorsa, engelsiz porta sahip Quad9 (Port 9953) veya OpenDNS (443)'e otomatik yönlendir
                            if (finalPort53Blocked && _dnsOptions != null && _dnsOptions.Count > 0)
                            {
                                int bypassIdx = _dnsOptions.FindIndex(d => d.DpiArgs != null && d.DpiArgs.Contains("9953"));
                                if (bypassIdx < 0) bypassIdx = _dnsOptions.FindIndex(d => d.DpiArgs != null && d.DpiArgs.Contains("443"));
                                if (bypassIdx >= 0 && _selectedDnsIndex != bypassIdx)
                                {
                                    SelectDnsProvider(bypassIdx);
                                    ToastNotification.Show(
                                        "İSS Port 53 Engeli",
                                        "İSS standart DNS portunu (53) engellediği için Quad9 (Port 9953) otomatik etkinleştirildi.",
                                        ToastType.Warning,
                                        4000);
                                }
                            }

                            if (_selector != null && !_selector.IsDisposed)
                            {
                                _selector.IsAutoModePending = false;
                                _selector.IsAutoSelected = true;
                                _selector.CompleteBenchmark();
                            }

                            IspProfile winProf = _profiles[finalBestIdx];
                            long winMs = winProf.PingMs;
                            int winLoss = (winMs >= 0) ? winProf.PacketLossPct : 0;

                            string detailMsg = string.Format(
                                "{0}{1} se\u00e7ildi.",
                                winProf.Name,
                                winMs >= 0 ? string.Format(" ({0} ms)", winMs) : "");

                            AppLogger.Log("ISP-BENCH", "Profil se\u00e7ildi -> " + detailMsg);
                            ToastNotification.Show("Profil Se\u00e7ildi", detailMsg, ToastType.Success, 3500);

                            if (_startProtectionAfterBenchmark && !_isRunning)
                            {
                                _startProtectionAfterBenchmark = false;
                                _isOperationRunning = true;
                                bool startQueued = ThreadPool.QueueUserWorkItem(delegate
                                {
                                    try
                                    {
                                        _watchdogRecoveryCount = 0;
                                        StartProtection();
                                    }
                                    catch {}
                                    finally
                                    {
                                        _isOperationRunning = false;
                                        try
                                        {
                                            if (this.IsHandleCreated && !this.IsDisposed && !_isDisposing)
                                            {
                                                this.BeginInvoke((MethodInvoker)delegate
                                                {
                                                    if (!_isDisposing && !this.IsDisposed)
                                                    {
                                                        UpdateUIState();
                                                    }
                                                });
                                            }
                                        }
                                        catch {}
                                    }
                                });
                                if (!startQueued)
                                {
                                    _isOperationRunning = false;
                                    AppLogger.Log("ISP-BENCH", "Otomatik koruma başlatma işi kuyruğa alınamadı.");
                                }
                            }
                        });
                    }
                }
                catch (Exception ex)
                {
                    AppLogger.Log("ISP-BENCH", "Akıllı Profil Testi hatası: " + ex.Message);
                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_selector != null && !_selector.IsDisposed)
                                {
                                    _selector.IsAutoModePending = false;
                                    _selector.CompleteBenchmark();
                                }
                                if (_startProtectionAfterBenchmark)
                                {
                                    _startProtectionAfterBenchmark = false;
                                    _isOperationRunning = false;
                                    UpdateUIState();
                                }
                            });
                        }
                        catch {}
                    }
                }
                finally
                {
                    lock (IspDropdownMenuList.ProfileMeasurementSync)
                    {
                        _isSmartBenchmarkRunning = false;
                        _isProfileBenchmarkPending = false;
                    }
                    ApplyBenchmarkInteractionState();
                }
            });
            benchThread.IsBackground = true;
            benchThread.Priority = ThreadPriority.BelowNormal;
            benchThread.Start();
        }

        private void UpdateBenchmarkProgressUI(string stageText, float progress)
        {
            if (_isDisposing || this.IsDisposed) return;
            try
            {
                IspDropdownSelector sel = _selector;
                if (sel != null && !sel.IsDisposed)
                {
                    sel.UpdateProgress(stageText, progress);
                }
            }
            catch {}
        }

        // Ping Monitor with dual target fallback (9.9.9.9 and 1.1.1.1)
        private void StartPingMonitor()
        {
            _pingTimer = new System.Windows.Forms.Timer();
            _pingTimer.Interval = 30000;
            _pingTimer.Tick += new EventHandler(PingTimer_Tick);
        }

        private void PingTimer_Tick(object sender, EventArgs e)
        {
            if (_isDisposing || !this.Visible || this.WindowState == FormWindowState.Minimized || !_isRunning)
            {
                if (_pingTimer != null) _pingTimer.Stop();
                return;
            }
            // If user is playing a game or focused in another application, skip background ICMP pings.
            Form af = Form.ActiveForm;
            if (af != this)
            {
                // Arka planda örneklemeyi seyrelt (Gaming Zero-Lag: arka planda ICMP yok)
                if (_pingTimer != null && _pingTimer.Interval != 30000) _pingTimer.Interval = 30000;
                return;
            }
            // Yenileme: sabit 30 saniyede bir ölçüm (ağı ve pingi yormayan dengeli aralık)
            int liveInterval = 30000;
            if (_pingTimer != null && _pingTimer.Interval != liveInterval) _pingTimer.Interval = liveInterval;
            TriggerManualPing();
        }

        private volatile bool _pingRerunRequested = false;

        private void TriggerManualPing()
        {
            if (_isDisposing) return;
            if (_isPinging)
            {
                _pingRerunRequested = true;
                return;
            }
            _isPinging = true;
            _pingRerunRequested = false;
            if (_headerPanel != null && !_headerPanel.IsDisposed) _headerPanel.Invalidate();

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                string freshPing = "--";
                long measuredMs = -1;
                int measuredProfileIdx = _selectedProfileIndex;
                try
                {
                    IspProfile currentProfile = (measuredProfileIdx >= 0 && measuredProfileIdx < _profiles.Count)
                        ? _profiles[measuredProfileIdx]
                        : null;

                    long pingTime = -1;
                    int lossPct;

                    if (currentProfile != null && !string.IsNullOrEmpty(currentProfile.PeeringTarget))
                    {
                        pingTime = NetworkProbe.MeasureTargetQuality(currentProfile.PeeringTarget, 2, 550, out lossPct);
                    }

                    if (pingTime < 0)
                    {
                        string[] fallbackTargets = new string[] {
                            "66.22.244.2",   // Discord Official Voice RTC Europe (AS49544)
                            "66.22.244.1",   // Discord Official Voice RTC Europe 2 (AS49544)
                            "80.81.192.137", // DE-CIX Frankfurt Core
                            "80.81.192.82"   // DE-CIX Frankfurt Peering Core
                        };

                        using (Ping ping = new Ping())
                        {
                            for (int i = 0; i < fallbackTargets.Length; i++)
                            {
                                try
                                {
                                    PingReply reply = ping.Send(fallbackTargets[i], 650);
                                    if (reply != null && reply.Status == IPStatus.Success)
                                    {
                                        pingTime = reply.RoundtripTime;
                                        break;
                                    }
                                }
                                catch {}
                            }
                        }
                    }

                    measuredMs = pingTime;
                    if (pingTime >= 0)
                    {
                        freshPing = pingTime.ToString();
                        _consecutiveDropCount = 0;
                        if (currentProfile != null)
                        {
                            lock (IspDropdownMenuList.ProfileMeasurementSync)
                            {
                                if (!_isSmartBenchmarkRunning)
                                {
                                    currentProfile.PingMs = pingTime;
                                    currentProfile.PingMeasuredUtc = DateTime.UtcNow;
                                }
                            }
                        }
                    }
                    else
                    {
                        freshPing = "--";
                        if (_isRunning)
                        {
                            _consecutiveDropCount++;
                            if (_consecutiveDropCount >= 2)
                            {
                                _consecutiveDropCount = 0;
                                AppLogger.Log("CONNWATCH", "ICMP hedefi yanıt vermedi; tek başına profil geçişi için yeterli kanıt sayılmadı.", LogLevel.Debug);
                            }
                        }
                    }
                    _pingMs = freshPing;

                }
                catch
                {
                    freshPing = "--";
                    _pingMs = freshPing;
                }
                finally
                {
                    _isPinging = false;
                }

                if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                {
                    try
                    {
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (_isDisposing || this.IsDisposed) return;

                            if (measuredProfileIdx == _selectedProfileIndex && measuredMs >= 0)
                            {
                                _pingMs = measuredMs.ToString();
                            }
                            else if (_selectedProfileIndex >= 0 && _selectedProfileIndex < _profiles.Count && _profiles[_selectedProfileIndex].PingMs >= 0)
                            {
                                _pingMs = _profiles[_selectedProfileIndex].PingMs.ToString();
                            }

                            if (_headerPanel != null && !_headerPanel.IsDisposed)
                            {
                                _headerPanel.Invalidate();
                                if (_isPingHovered && _toolTip != null)
                                {
                                    _toolTip.SetToolTip(_headerPanel, GetNetworkPingToolTipText());
                                }
                            }
                            if (_selector != null && !_selector.IsDisposed)
                            {
                                _selector.Invalidate();
                            }

                            if (_pingRerunRequested)
                            {
                                _pingRerunRequested = false;
                                TriggerManualPing();
                            }
                        });
                    }
                    catch {}
                }
            });
        }

        private void CheckInitialStatus()
        {
            try
            {
                // Önceki oturumdan/çökmeden kalan motor süreçleri yalnızca bizim/yolunda
                // GoodbyeDPI geçen kurulumlardan ise kapatılır (yanlış süreç öldürülmez).
                int leftovers = KillStrayDpiProcesses();
                if (leftovers > 0)
                {
                    AppLogger.Log("SYSTEM", string.Format("Başlangıçta {0} kalıntı goodbyedpi motor süreci kapatıldı.", leftovers));
                }
                DiscordMediaAccelerator.CleanupStaleShieldOnStartup();
            }
            catch {}
            _isRunning = false;
            _dpiProcess = null;
            UpdateUIState();
        }

        private void SyncUIStateSafe()
        {
            if (_isDisposing || this.IsDisposed) return;
            try
            {
                if (this.IsHandleCreated && !this.IsDisposed && !_isDisposing)
                {
                    if (this.InvokeRequired)
                    {
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (!_isDisposing && !this.IsDisposed) UpdateUIState();
                        });
                    }
                    else
                    {
                        UpdateUIState();
                    }
                }
            }
            catch {}
        }

        private void UpdateUIState()
        {
            if (_isDisposing || this.IsDisposed) return;

            if (_dnsDropdownMenuList != null && !_dnsDropdownMenuList.IsDisposed)
            {
                _dnsDropdownMenuList.SetProtectionState(_isRunning);
                EnsureDnsPingScanIfNeeded();
            }
            else if (!_isRunning && this.Visible && this.WindowState != FormWindowState.Minimized)
            {
                EnsureDnsPingScanIfNeeded();
            }

            if (_isRunning)
            {
                if (_btnToggle != null && !_btnToggle.IsDisposed)
                {
                    _btnToggle.IconType = "stop";
                    _btnToggle.Text = "Discord Korumasını Durdur";
                    _btnToggle.BackColor = Color.FromArgb(138, 26, 34);
                    _btnToggle.HoverColor = Color.FromArgb(165, 36, 44);
                    _btnToggle.BorderColor = Color.FromArgb(118, 22, 28);
                    _btnToggle.HoverBorderColor = Color.FromArgb(205, 55, 65);
                    _btnToggle.GlowColor = Color.FromArgb(138, 26, 34);
                }

                if (this.Visible && this.WindowState != FormWindowState.Minimized)
                {
                    if (_pingTimer != null && !_pingTimer.Enabled) _pingTimer.Start();
                }
            }
            else
            {
                if (_btnToggle != null && !_btnToggle.IsDisposed)
                {
                    ThemePalette pal = ThemePalette.Get(ActiveTheme);
                    _btnToggle.IconType = "play";
                    _btnToggle.Text = "Discord Korumasını Başlat";
                    _btnToggle.BackColor = pal.PrimaryAccent;
                    _btnToggle.HoverColor = pal.PrimaryHover;
                    _btnToggle.BorderColor = pal.BorderColor;
                    _btnToggle.HoverBorderColor = pal.BorderHoverColor;
                    _btnToggle.GlowColor = pal.GlowColor;
                }

                if (_pingTimer != null) _pingTimer.Stop();
            }

            if (_selector != null && !_selector.IsDisposed) _selector.IsLocked = false;
            if (_dnsSelector != null && !_dnsSelector.IsDisposed)
            {
                _dnsSelector.EffectiveDnsIndex = GetEffectiveDnsIndex();
                _dnsSelector.Invalidate();
            }
            if (_headerPanel != null && !_headerPanel.IsDisposed) _headerPanel.Invalidate();

            if (_trayToggleItem != null)
            {
                _trayToggleItem.Text = _isRunning ? "Korumayı durdur" : "Korumayı başlat / durdur";
            }
            if (_trayIcon != null)
            {
                _trayIcon.Text = _isRunning ? "GoodbyeDPI Pro MAX • Discord Aktif" : "GoodbyeDPI Pro MAX • Devre Dışı";
            }
            if (_trayMenu != null && !_trayMenu.IsDisposed)
            {
                _trayMenu.Invalidate();
            }

            ApplyBenchmarkInteractionState();

            // İşlem (onarım/optimize/temizlik) sürerken ertelenen yeniden başlatma isteğini şimdi uygula.
            if (_restartPending && !_isOperationRunning)
            {
                RestartProtectionAsync();
            }
        }

        private void BtnToggle_Click(object sender, EventArgs e)
        {
            if (_isOperationRunning || _isDisposing || (!_isRunning && IsProfileBenchmarkBlocking())) return;

            if (!_isRunning && (!_isAutoScanCompleted || _isSmartBenchmarkRunning))
            {
                _isOperationRunning = true;
                _startProtectionAfterBenchmark = true;
                if (_btnToggle != null && !_btnToggle.IsDisposed)
                {
                    _btnToggle.Enabled = false;
                    _btnToggle.Text = "En İyi Profil Bulunuyor...";
                    _btnToggle.Invalidate();
                }
                if (!_isSmartBenchmarkRunning)
                {
                    RunSmartIspBenchmarkAsync();
                }
                return;
            }

            _isOperationRunning = true;
            if (_btnToggle != null && !_btnToggle.IsDisposed) _btnToggle.Enabled = false;

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    if (_isRunning)
                    {
                        StopProtection();
                    }
                    else
                    {
                        // Kullanıcı korumayı elle başlattı: watchdog kurtarma sayacı sıfırlanır.
                        _watchdogRecoveryCount = 0;
                        StartProtection();
                    }
                }
                catch (Exception ex)
                {
                    AppLogger.Log("ERROR", "Geçiş hatası: " + ex.Message);
                }
                finally
                {
                    try
                    {
                        if (this.IsHandleCreated && !this.IsDisposed && !_isDisposing)
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (!_isDisposing && !this.IsDisposed)
                                {
                                    UpdateUIState();
                                    if (_btnToggle != null && !_btnToggle.IsDisposed) _btnToggle.Enabled = !_isSmartBenchmarkRunning || _isRunning;
                                }
                                _isOperationRunning = false;
                                ApplyBenchmarkInteractionState();
                            });
                        }
                        else
                        {
                            _isOperationRunning = false;
                        }
                    }
                    catch
                    {
                        _isOperationRunning = false;
                    }
                }
            });
        }

        // Motoru arka plan iş parçacığında yeniden başlatır: profil/DNS/güç olaylarında
        // UI donmasını önler ve eşzamanlı başlat/durdur çakışmalarını engeller.
        private void RestartProtectionAsync()
        {
            if (_isDisposing || this.IsDisposed) return;

            // Onarım/optimize/temizlik sürerken gelen istek kaybolmasın: işlem bitince
            // UpdateUIState bekleyen yeniden başlatmayı uygular.
            if (_isOperationRunning)
            {
                _restartPending = true;
                AppLogger.Log("UI", "Koruma yeniden başlatma isteği alındı; işlem bitince uygulanacak.");
                return;
            }
            _restartPending = false;

            // Niyet nesli: bu istek kuyruğa girdikten sonra kullanıcı Durdur/Başlat derse
            // (nesil artar) işçi motoru geri getirmez — "Durdur" komutu ezilemez.
            int stamp = Interlocked.Increment(ref _engineOpStamp);

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    lock (_engineSync)
                    {
                        if (_engineOpStamp != stamp) return;
                        _watchdogRecoveryCount = 0; // elle yeniden başlatma: kurtarma bütçesi tazelenir
                        StartProtectionCore(true);
                    }
                }
                catch (Exception ex)
                {
                    AppLogger.Log("ERROR", "Koruma yeniden başlatılırken hata oluştu: " + ex.Message);
                }
                finally
                {
                    try
                    {
                        if (this.IsHandleCreated && !this.IsDisposed && !_isDisposing)
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (!_isDisposing && !this.IsDisposed) UpdateUIState();
                            });
                        }
                    }
                    catch {}
                }
            });
        }

        // goodbyedpi.exe sürecini güvenli ve standart parametrelerle başlatır (lock(_engineSync) altında çağrılır)
        private bool LaunchDpiProcessCore(string safeExePath, string args)
        {
            try
            {
                if (_dpiProcess != null)
                {
                    try
                    {
                        _dpiProcess.EnableRaisingEvents = false;
                        try { _dpiProcess.CancelOutputRead(); } catch {}
                        try { _dpiProcess.CancelErrorRead(); } catch {}
                        if (!_dpiProcess.HasExited)
                        {
                            _dpiProcess.Kill();
                            _dpiProcess.WaitForExit(1000);
                        }
                        _dpiProcess.Dispose();
                    }
                    catch {}
                    _dpiProcess = null;
                }

                ProcessStartInfo psi = new ProcessStartInfo();
                psi.FileName = safeExePath;
                psi.Arguments = args;
                psi.WorkingDirectory = Path.GetDirectoryName(safeExePath);
                psi.CreateNoWindow = true;
                psi.UseShellExecute = false;
                psi.WindowStyle = ProcessWindowStyle.Hidden;
                psi.RedirectStandardOutput = true;
                psi.RedirectStandardError = true;

                _dpiProcess = Process.Start(psi);
                if (_dpiProcess != null)
                {
                    try
                    {
                        bool gamePassthroughActive;
                        string activeGameName;
                        ConfigureGigabitEngineProcess(_dpiProcess, out gamePassthroughActive, out activeGameName);
                        _lastEngineGamePassthroughState = gamePassthroughActive;
                        if (gamePassthroughActive)
                        {
                            AppLogger.Log("ENGINE", string.Format(
                                "Oyun İçi Sıfır Gecikme & Anti-Cheat Kalkanı aktif ({0}): oyun UDP portları kernel passthrough ile izole edildi.",
                                activeGameName ?? "Rekabetçi Oyun"));
                        }
                        else
                        {
                            AppLogger.Log("ENGINE", "Gigabit P-Core Motor Önceliği aktif (AboveNormal + P-Core Affinity + I/O Boost).");
                        }
                    }
                    catch {}

                    _dpiProcess.OutputDataReceived += new DataReceivedEventHandler(delegate(object s, DataReceivedEventArgs ev)
                    {
                        if (!string.IsNullOrEmpty(ev.Data))
                        {
                            AppLogger.LogEngine(ev.Data);
                            CheckEngineDriverError(ev.Data);
                        }
                    });
                    _dpiProcess.ErrorDataReceived += new DataReceivedEventHandler(delegate(object s, DataReceivedEventArgs ev)
                    {
                        if (!string.IsNullOrEmpty(ev.Data))
                        {
                            AppLogger.LogEngine("[ERR] " + ev.Data);
                            CheckEngineDriverError(ev.Data);
                        }
                    });
                    _dpiProcess.BeginOutputReadLine();
                    _dpiProcess.BeginErrorReadLine();

                    // Abonelik ÖNCE kurulur, sonra olay yükseltme açılır: süreç arada ölse bile
                    // çıkış olayı kaybolmaz (bekçi ölümü asla kaçırmaz).
                    _dpiProcess.Exited += new EventHandler(DpiProcess_Exited);
                    _dpiProcess.EnableRaisingEvents = true;
                    return true;
                }
            }
            catch (System.ComponentModel.Win32Exception w32ex)
            {
                AppLogger.Log("ERROR", "LaunchDpiProcessCore Win32 hatası (" + w32ex.NativeErrorCode + "): " + w32ex.Message);
                if (w32ex.NativeErrorCode == 740) // ERROR_ELEVATION_REQUIRED
                {
                    _lastLaunchError = "Korumanın başlaması için Yönetici izni gerekiyor.\nLütfen programı 'Yönetici olarak çalıştır' seçeneğiyle açın.";
                }
                else
                {
                    _lastLaunchError = "goodbyedpi.exe başlatılamadı: " + w32ex.Message;
                }
            }
            catch (Exception ex)
            {
                AppLogger.Log("ERROR", "LaunchDpiProcessCore hatası: " + ex.Message);
                _lastLaunchError = ex.Message;
            }
            return false;
        }

        internal void StartProtection()
        {
            // Eşzamanlı başlat/durdur çağrılarını serileştir (UI + ThreadPool + watchdog).
            // Nesil artışı: kuyruktaki bekleyen restart işçileri iptal olur.
            lock (_engineSync) { Interlocked.Increment(ref _engineOpStamp); StartProtectionCore(true); }
        }

        // gateway.discord.gg:443 ve cdn.discordapp.com:443 kanallarını eşzamanlı (dual-probe) doğrular.
        private static long ProbeGatewayAndMediaCdnDual(int timeoutMs, out long cdnMs, out string gwError, out string cdnError)
        {
            long localCdnMs = -1;
            string localCdnErr = null;
            int remainingParticipants = 2;
            ManualResetEvent cdnDone = new ManualResetEvent(false);
            bool queued = ThreadPool.QueueUserWorkItem(delegate(object s)
            {
                try
                {
                    string cErr;
                    localCdnMs = NetworkProbe.TestTlsHandshake("cdn.discordapp.com", 443, timeoutMs, out cErr);
                    localCdnErr = cErr;
                }
                catch (Exception ex)
                {
                    localCdnMs = -1;
                    localCdnErr = ex.Message;
                }
                finally
                {
                    try { cdnDone.Set(); } catch {}
                    if (Interlocked.Decrement(ref remainingParticipants) == 0)
                    {
                        try { cdnDone.Close(); } catch {}
                    }
                }
            });

            if (!queued)
            {
                Interlocked.Decrement(ref remainingParticipants);
            }

            gwError = null;
            long gwMs = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, timeoutMs, out gwError);
            if (queued)
            {
                try { cdnDone.WaitOne(timeoutMs + 250); } catch {}
            }
            else
            {
                localCdnMs = NetworkProbe.TestTlsHandshake("cdn.discordapp.com", 443, timeoutMs, out localCdnErr);
            }

            if (Interlocked.Decrement(ref remainingParticipants) == 0)
            {
                try { cdnDone.Close(); } catch {}
            }

            cdnMs = localCdnMs;
            cdnError = localCdnErr;
            if (cdnMs >= 0)
            {
                AppHealthMetrics.RecordMediaCdnProbe(cdnMs, -1);
            }
            return gwMs;
        }

        private void VerifyAndFallbackProtectionAsync(int verifyStamp, string safeExePath, string cleanWhitelistPath, string initialArgs)
        {
            int effDnsIdx = GetEffectiveDnsIndex(true);
            string preservedDnsArgs = (effDnsIdx >= 0 && effDnsIdx < _dnsOptions.Count && _dnsOptions[effDnsIdx] != null)
                ? (_dnsOptions[effDnsIdx].DpiArgs ?? "")
                : "";
            VerifyAndFallbackProtectionAsync(verifyStamp, safeExePath, cleanWhitelistPath,
                initialArgs, initialArgs, preservedDnsArgs, _selectedProfileIndex, GetActiveGatewayFingerprint(), false);
        }

        // Koruma başlatıldıktan sonra aşamalı hazırlık yoklamasıyla (450 ms + 450 ms) gateway.discord.gg:443
        // ve cdn.discordapp.com:443 adreslerine gerçek TCP/TLS (SNI) bağlantısı dener; seçili profil ile
        // bağlantı kurulamazsa kullanıcının DNS tercihini koruyarak (Pass 1) ve gerekirse güvenli port 1253
        // yedeğiyle (Pass 2) alternatif DPI stratejilerini (Mod 1..4) otomatik deneyip çalışan kipi kalıcı önbelleğe alır.
        private void VerifyAndFallbackProtectionAsync(int verifyStamp, string safeExePath, string cleanWhitelistPath,
            string initialArgs, string baseProfileArgs, string preservedDnsArgs, int profileIndex, string gatewayFingerprint, bool startedWithSavedOverride)
        {
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    // Aşamalı hazırlık yoklaması (Progressive Readiness Polling):
                    // Sabit 1200 ms beklemek yerine 450 ms'de ilk yoklamayı yapar; WinDivert henüz yerleşiyorsa 450 ms sonra yineler.
                    Thread.Sleep(450);
                    if (_isDisposing || this.IsDisposed || !_isRunning || _isManualStop || _isFailoverRunning || _engineOpStamp != verifyStamp) return;

                    string err;
                    string cdnErr;
                    long cdnMs;
                    long gwMs = ProbeGatewayAndMediaCdnDual(2200, out cdnMs, out err, out cdnErr);
                    if (gwMs < 0)
                    {
                        Thread.Sleep(450);
                        if (_isDisposing || this.IsDisposed || !_isRunning || _isManualStop || _isFailoverRunning || _engineOpStamp != verifyStamp) return;
                        gwMs = ProbeGatewayAndMediaCdnDual(2300, out cdnMs, out err, out cdnErr);
                    }

                    if (gwMs >= 0 && cdnMs >= 0)
                    {
                        AppLogger.Log("ENGINE", string.Format(
                            "Çift kanallı motor doğrulaması başarılı (Gateway: {0} ms | Medya CDN: {1} ms).", gwMs, cdnMs));
                        if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                        {
                            try { this.BeginInvoke((MethodInvoker)delegate { if (!_isDisposing && !this.IsDisposed) EnsureDnsPingScanIfNeeded(); }); } catch {}
                        }
                        return;
                    }
                    if (gwMs >= 0 && cdnMs < 0)
                    {
                        AppLogger.Log("ENGINE", string.Format(
                            "Gateway TLS başarılı ({0} ms) ancak Medya CDN (cdn.discordapp.com) yanıt vermedi ({1}); QUIC/CDN kalkanı tazeleniyor...",
                            gwMs, cdnErr ?? "zaman aşımı"), LogLevel.Warn);
                        DiscordMediaAccelerator.ApplyMediaAccelerationCore(false);
                        FlushDnsFast();
                        string retryCdnErr;
                        long retryCdnMs = NetworkProbe.TestTlsHandshake("cdn.discordapp.com", 443, 2000, out retryCdnErr);
                        if (retryCdnMs >= 0)
                        {
                            AppHealthMetrics.RecordMediaCdnProbe(retryCdnMs, -1);
                            AppLogger.Log("ENGINE", string.Format(
                                "Medya CDN kanalı QUIC kalkanı tazelemesi sonrası kurtarıldı ({0} ms).", retryCdnMs));
                            if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                            {
                                try { this.BeginInvoke((MethodInvoker)delegate { if (!_isDisposing && !this.IsDisposed) EnsureDnsPingScanIfNeeded(); }); } catch {}
                            }
                            return;
                        }
                        AppHealthMetrics.RecordMediaCdnProbe(-1, -1);
                    }

                    // Eğer kayıtlı adaptif override ile başlatıldıysa ve bu ağda artık yanıt vermiyorsa önbelleği temizle.
                    if (startedWithSavedOverride && gwMs < 0)
                    {
                        ClearVerifiedOverrideTemplate();
                        AppLogger.Log("ENGINE", "Kayıtlı adaptif desync kipi bu oturumda yanıt vermedi; önbellek sıfırlandı ve taban profil deneniyor.", LogLevel.Info);
                    }

                    // Ping yanıtı DPI veya Discord erişimini kanıtlamaz. Discord web alanı,
                    // etkin DNS ve DNS'ten bağımsız dış TCP yolu birlikte doğrulanmadan mod değiştirme.
                    string controlExplanation = null;
                    if (gwMs < 0 && !TryConfirmGatewaySpecificFailure(verifyStamp, profileIndex, out controlExplanation))
                    {
                        AppLogger.Log("ENGINE", "gateway bağlantı/TLS probu başarısız ancak bağımsız DNS/TCP/discord.com kontrolleri sorunu gateway yoluna özgü olarak doğrulamadı; otomatik mod değişikliği atlandı. " + controlExplanation, LogLevel.Warn);
                        return;
                    }
                    else if (gwMs >= 0)
                    {
                        // Gateway zaten çalışıyor, yalnızca CDN yanıt vermediyse çalışan oturumu bozma.
                        return;
                    }
                    if (_isDisposing || this.IsDisposed || !_isRunning || _isManualStop || _isFailoverRunning || _engineOpStamp != verifyStamp) return;

                    AppLogger.Log("ENGINE", "Seçili profilde gateway.discord.gg bağlantı/TLS probu başarısız (" + (err ?? "zaman aşımı") + "); bağımsız kontroller gateway yoluna özgü sorun gösterdi (" + controlExplanation + "). Smart DPI Fallback (Mod 1..4) deneniyor...");

                    const string bypassSafeDns = "--dns-addr 9.9.9.9 --dns-port 9953 --dnsv6-addr 2620:fe::fe --dnsv6-port 9953";
                    string[] fallbackDpiTemplates = new string[]
                    {
                        // Mod 1: -9 -q --auto-ttl
                        "-9 -q --auto-ttl 1-4-10 --max-payload 1200 --allow-no-sni --blacklist \"{0}\"",
                        // Mod 2: -5 -q --wrong-chksum
                        "-5 -q --wrong-chksum --max-payload 1200 --allow-no-sni --blacklist \"{0}\"",
                        // Mod 3: -1 --native-frag
                        "-1 --native-frag --max-payload 1200 --allow-no-sni --blacklist \"{0}\"",
                        // Mod 4: CGNAT & Katı SPI Modem dostu (--wrong-chksum olmadan ters + doğal parçalama)
                        "-e 2 -q --native-frag --reverse-frag --auto-ttl 1-4-10 --max-payload 1200 --allow-no-sni --blacklist \"{0}\""
                    };

                    // Kayıtlı override başarısız olduysa önce kullanıcının seçtiği profilin kendi taban argümanını dene
                    if (startedWithSavedOverride && !string.IsNullOrEmpty(baseProfileArgs) &&
                        !string.Equals(baseProfileArgs, initialArgs, StringComparison.OrdinalIgnoreCase))
                    {
                        bool baseLaunched;
                        lock (_engineSync)
                        {
                            if (_isDisposing || !_isRunning || _isManualStop || _engineOpStamp != verifyStamp) return;
                            _lastEngineArgs = baseProfileArgs;
                            baseLaunched = LaunchDpiProcessCore(safeExePath, baseProfileArgs);
                        }
                        if (baseLaunched)
                        {
                            _lastEngineStartUtc = DateTime.UtcNow;
                            FlushDnsFast();
                            Thread.Sleep(550);
                            if (_isDisposing || !_isRunning || _isManualStop || _engineOpStamp != verifyStamp) return;
                            long baseCdnMs;
                            string baseCdnErr;
                            long baseGwMs = ProbeGatewayAndMediaCdnDual(2200, out baseCdnMs, out err, out baseCdnErr);
                            if (baseGwMs >= 0)
                            {
                                AppLogger.Log("ENGINE", string.Format("Taban profil doğrulandı (Gateway: {0} ms | Medya CDN: {1} ms).", baseGwMs, baseCdnMs));
                                if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                                {
                                    try { this.BeginInvoke((MethodInvoker)delegate { if (!_isDisposing && _isRunning) TriggerManualPing(); }); } catch {}
                                }
                                return;
                            }
                        }
                    }

                    // 1. Aşama (Smart Resolver Preservation): Kullanıcının seçtiği / en hızlı doğrulanan DNS'i koruyarak Mod 1..4 dene
                    // 2. Aşama (Bypass Port 9953 Escalation): Yalnızca 1. aşama başarısız olursa (şeffaf Port 53 DNS engeli şüphesi) Quad9 9953 ile dene
                    string userDnsSuffix = string.IsNullOrEmpty(preservedDnsArgs) ? "" : (" " + preservedDnsArgs.Trim());
                    string bypassDnsSuffix = " " + bypassSafeDns;
                    bool userAlreadyOnBypassPort = !string.IsNullOrEmpty(preservedDnsArgs) && (preservedDnsArgs.IndexOf("9953", StringComparison.Ordinal) >= 0 || preservedDnsArgs.IndexOf("1253", StringComparison.Ordinal) >= 0 || preservedDnsArgs.IndexOf("443", StringComparison.Ordinal) >= 0);
                    string[] dnsPasses = userAlreadyOnBypassPort
                        ? new string[] { userDnsSuffix }
                        : new string[] { userDnsSuffix, bypassDnsSuffix };

                    for (int pass = 0; pass < dnsPasses.Length; pass++)
                    {
                        string activeDnsSuffix = dnsPasses[pass];
                        string passLabel = (pass == 0 && !userAlreadyOnBypassPort) ? "Seçili DNS Korunarak" : "Port 9953 Engelsiz DNS Kalkanı";

                        for (int i = 0; i < fallbackDpiTemplates.Length; i++)
                        {
                            if (_isDisposing || this.IsDisposed || !_isRunning || _isManualStop || _engineOpStamp != verifyStamp) return;

                            string dpiOnlyArgs = string.Format(fallbackDpiTemplates[i], cleanWhitelistPath);
                            string candidateArgs = dpiOnlyArgs + activeDnsSuffix;
                            if (string.Equals(candidateArgs, initialArgs, StringComparison.OrdinalIgnoreCase)) continue;

                            bool launched;
                            lock (_engineSync)
                            {
                                if (_isDisposing || !_isRunning || _isManualStop || _engineOpStamp != verifyStamp) return;
                                _lastEngineArgs = candidateArgs;
                                launched = LaunchDpiProcessCore(safeExePath, candidateArgs);
                            }
                            if (!launched)
                            {
                                AppLogger.Log("ENGINE", string.Format("Yedek mod başlatılamadı (Mod {0}); sıradaki mod deneniyor.", i + 1));
                                continue;
                            }
                            _lastEngineStartUtc = DateTime.UtcNow;

                            FlushDnsFast();
                            Thread.Sleep(550);

                            if (_isDisposing || !_isRunning || _isManualStop || _engineOpStamp != verifyStamp) return;
                            long retryCdnMs;
                            string retryCdnErr;
                            long retryMs = ProbeGatewayAndMediaCdnDual(2300, out retryCdnMs, out err, out retryCdnErr);
                            if (retryMs < 0)
                            {
                                Thread.Sleep(400);
                                if (_isDisposing || !_isRunning || _isManualStop || _engineOpStamp != verifyStamp) return;
                                retryMs = ProbeGatewayAndMediaCdnDual(2300, out retryCdnMs, out err, out retryCdnErr);
                            }
                            if (retryMs >= 0)
                            {
                                bool usedBypassPortShield = (pass == 1 && !userAlreadyOnBypassPort);
                                string templateToPersist = usedBypassPortShield
                                    ? (fallbackDpiTemplates[i] + " " + bypassSafeDns)
                                    : fallbackDpiTemplates[i];
                                if (usedBypassPortShield)
                                {
                                    lock (_dnsMeasurementSync)
                                    {
                                        if (_dnsOptions != null && _dnsOptions.Count > 3)
                                        {
                                            _activeDnsIndex = 3;
                                        }
                                    }
                                }
                                // Çalıştığı doğrulanan DPI şablonunu ağ geçidi parmak iziyle birlikte kalıcı önbelleğe kaydet
                                SaveVerifiedOverrideTemplate(profileIndex, gatewayFingerprint, templateToPersist);
                                AppLogger.Log("ENGINE", string.Format(
                                    "Smart DPI Fallback (Mod {0} • {1}) başarılı ve ağ hafızasına kaydedildi! Gateway: {2} ms | Medya CDN: {3} ms.",
                                    i + 1, passLabel, retryMs, retryCdnMs >= 0 ? (retryCdnMs + " ms") : "tekrar deneniyor"));
                                if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                                {
                                    try
                                    {
                                        this.BeginInvoke((MethodInvoker)delegate
                                        {
                                            if (!_isDisposing && _isRunning)
                                            {
                                                TriggerManualPing();
                                                EnsureDnsPingScanIfNeeded();
                                            }
                                        });
                                    }
                                    catch {}
                                }
                                return;
                            }
                        }
                    }

                    // Hiçbir yedek kip yanıt alamadıysa kullanıcının seçtiği orijinal kipe dön ve dönüşü doğrula.
                    string restoreTargetArgs = (!string.IsNullOrEmpty(baseProfileArgs)) ? baseProfileArgs : initialArgs;
                    bool restoreAttempted = false;
                    bool originalModeRestored = false;
                    lock (_engineSync)
                    {
                        if (!_isDisposing && _isRunning && !_isManualStop && _engineOpStamp == verifyStamp)
                        {
                            restoreAttempted = true;
                            _lastEngineArgs = restoreTargetArgs;
                            originalModeRestored = LaunchDpiProcessCore(safeExePath, restoreTargetArgs);
                            if (originalModeRestored)
                            {
                                _lastEngineStartUtc = DateTime.UtcNow;
                            }
                            else
                            {
                                _isRunning = false;
                                AppLogger.Log("ENGINE", "UYARI: Orijinal profile dönülemedi; koruma durduruldu çünkü motor yeniden başlatılamadı.", LogLevel.Error);
                            }
                            FlushDnsFast();
                        }
                    }
                    if (restoreAttempted && !originalModeRestored)
                    {
                        SyncUIStateSafe();
                        return;
                    }
                    if (!restoreAttempted) return;

                    Thread.Sleep(750);
                    if (_isDisposing || this.IsDisposed || !_isRunning || _isManualStop || _engineOpStamp != verifyStamp) return;
                    string restoreError1;
                    long restoreTlsMs1 = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out restoreError1);
                    long restoreTlsMs2 = -1;
                    string restoreError2 = null;
                    if (restoreTlsMs1 >= 0 && _isRunning && !_isManualStop && _engineOpStamp == verifyStamp)
                    {
                        Thread.Sleep(350);
                        if (_isRunning && !_isManualStop && _engineOpStamp == verifyStamp)
                        {
                            restoreTlsMs2 = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out restoreError2);
                        }
                    }
                    if (restoreTlsMs1 >= 0 && restoreTlsMs2 >= 0)
                    {
                        AppLogger.Log("ENGINE", string.Format("Özgün DPI kipine dönüş sonrası gateway bağlantı/TLS probu iki kez başarılı ({0} ms, {1} ms).", restoreTlsMs1, restoreTlsMs2), LogLevel.Info);
                    }
                    else
                    {
                        string restoreControls;
                        bool pathSpecificFailure = TryConfirmGatewaySpecificFailure(verifyStamp, _selectedProfileIndex, out restoreControls);
                        AppLogger.Log("ENGINE", "Özgün DPI kipi geri yüklendi ancak gateway bağlantı/TLS doğrulaması tamamlanmadı; " +
                            (pathSpecificFailure ? "gateway yolu sorunu bağımsız kontrollerle doğrulandı: " : "sonuç belirsiz: ") +
                            restoreControls + "; hata: " + (restoreError2 ?? restoreError1 ?? "ikinci ölçüm tamamlanmadı"), LogLevel.Warn);
                    }
                }
                catch (Exception ex)
                {
                    AppLogger.Log("ENGINE", "Smart DPI Fallback sırasında istisna: " + ex.Message);
                }
            });
        }

        private void StartProtectionCore(bool showErrorDialogs)
        {
            // Kapanış yarışı: form kapanırken kuyruktan gelen başlatma motoru diriltmemeli.
            if (_isDisposing || this.IsDisposed) return;

            string archDir;
            string driverFileName;
            string nativeArchitecture;
            string architectureError;
            if (!AppPaths.TryGetEngineArchitecture(out archDir, out driverFileName, out nativeArchitecture, out architectureError))
            {
                _lastLaunchError = architectureError;
                AppLogger.Log("ARCH", "Koruma başlatılmadı. " + architectureError, LogLevel.Error);
                if (!_isRunning) SyncUIStateSafe();
                if (showErrorDialogs && !_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                {
                    try
                    {
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (_isDisposing || this.IsDisposed) return;
                            if (this.Visible && this.WindowState != FormWindowState.Minimized)
                            {
                                MessageBox.Show(this, architectureError, "İşlemci Desteği", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                            }
                            else
                            {
                                ToastNotification.Show("İşlemci Desteği", architectureError, ToastType.Warning, 6000);
                            }
                        });
                    }
                    catch {}
                }
                return;
            }

            // Fast-Boot Engine Pipeline: Motor zaten kapalıysa gereksiz StopProtectionCore + 200 ms uykuyu atla.
            if (_isRunning || _dpiProcess != null)
            {
                StopProtectionCore();
                // Çekirdek sürücüsü (WinDivert) tutamaçlarının Windows çekirdeğinde temizce çözülmesi için süre tanı
                Thread.Sleep(200);
            }
            if (_isDisposing) return;
            _isManualStop = false;

            // [ZIRH] WinDivert servis sağlığı kontrolü: Eğer servis Windows tarafından Start=4 (Devre Dışı)
            // yapılmışsa veya kilitlenmişse, motor başlatılmadan önce sessizce temizlenip sıfırlanır.
            try
            {
                if (GetWinDivertServiceHealth() == 2)
                {
                    AppLogger.Log("WATCHDOG", "WinDivert servisi devre dışı (Start=4) tespit edildi! Başlatma öncesi otomatik onarılıyor...");
                    CleanWinDivertDriverServices();
                    Thread.Sleep(300);
                }
            }
            catch {}

            if (_profiles == null || _profiles.Count == 0)
            {
                AppLogger.Log("ERROR", "Profil listesi boş, koruma başlatılamadı.");
                _isRunning = false;
                SyncUIStateSafe();
                return;
            }
            if (_selectedProfileIndex < 0 || _selectedProfileIndex >= _profiles.Count) _selectedProfileIndex = 0;
            IspProfile prof = _profiles[_selectedProfileIndex];

            string exeName = "goodbyedpi.exe";
            string exePath = AppPaths.Resolve(Path.Combine(archDir, exeName));
            string sysPath = AppPaths.Resolve(Path.Combine(archDir, driverFileName));
            AppLogger.Log("DRIVER", string.Format("WinDivert hedefi: {0} | yerel mimari: {1} | motor: {2}", sysPath, nativeArchitecture, exeName), LogLevel.Info);
            string whitelistPath = AppPaths.Resolve("discord_whitelist.txt");
            EnsureWhitelistFile(whitelistPath);

            if (!File.Exists(exePath))
            {
                AppLogger.Log("ERROR", exeName + " bulunamadı: " + exePath);
                if (showErrorDialogs && !_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                {
                    this.BeginInvoke((MethodInvoker)delegate
                    {
                        if (!_isDisposing && !this.IsDisposed)
                        {
                            string missingEngineMessage = exeName + " bulunamadı:\n" + exePath;
                            if (archDir == "x86")
                            {
                                missingEngineMessage += "\n\nBu dağıtımda 32-bit Windows motoru bulunmuyor. Paketin core\\x86\\" + exeName + " ve WinDivert dosyalarını içermesi gerekir.";
                            }
                            MessageBox.Show(this, missingEngineMessage, "Hata", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        }
                    });
                }
                _isRunning = false;
                SyncUIStateSafe();
                return;
            }

            if (!File.Exists(sysPath))
            {
                AppLogger.Log("ERROR", "WinDivert sürücü dosyası bulunamadı: " + sysPath, LogLevel.Error);
            }

            string safeWhitelistPath = GetShortPath(whitelistPath);
            string cleanWhitelist = safeWhitelistPath.Trim('\"');
            int effDnsIdx = GetEffectiveDnsIndex(true);
            string preservedDnsArgs = "";
            if (effDnsIdx >= 0 && effDnsIdx < _dnsOptions.Count && !string.IsNullOrEmpty(_dnsOptions[effDnsIdx].DpiArgs))
            {
                preservedDnsArgs = _dnsOptions[effDnsIdx].DpiArgs;
            }

            string baseProfileArgs = string.Format(prof.DpiArgs, cleanWhitelist);
            if (!string.IsNullOrEmpty(preservedDnsArgs))
            {
                baseProfileArgs += " " + preservedDnsArgs;
            }

            string gatewayFingerprint = GetActiveGatewayFingerprint();
            string savedOverrideTemplate;
            bool startedWithSavedOverride = TryLoadVerifiedOverrideTemplate(_selectedProfileIndex, gatewayFingerprint, out savedOverrideTemplate);
            string args;
            if (startedWithSavedOverride)
            {
                args = string.Format(savedOverrideTemplate, cleanWhitelist);
                bool overrideIncludesDns = args.IndexOf("--dns-addr", StringComparison.OrdinalIgnoreCase) >= 0;
                if (!overrideIncludesDns && !string.IsNullOrEmpty(preservedDnsArgs))
                {
                    args += " " + preservedDnsArgs;
                }
                else if (overrideIncludesDns && _selectedDnsIndex == 0 && _dnsOptions != null)
                {
                    for (int d = 1; d < _dnsOptions.Count; d++)
                    {
                        if (!string.IsNullOrEmpty(_dnsOptions[d].PingTargetIp) && args.IndexOf(_dnsOptions[d].PingTargetIp, StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            effDnsIdx = d;
                            break;
                        }
                    }
                }
                AppLogger.Log("ENGINE", string.Format(
                    "Kalıcı Adaptif Desync Hafızası: Ağ ({0}) için doğrulanmış parametreler doğrudan yüklendi.", gatewayFingerprint));
            }
            else
            {
                args = baseProfileArgs;
            }

            _lastEngineArgs = args;
            string dnsName = (_selectedDnsIndex >= 0 && _selectedDnsIndex < _dnsOptions.Count) ? _dnsOptions[_selectedDnsIndex].Name : "Varsayılan";
            string engineDisplayName = "GoodbyeDPI";
            _lastEngineInfo = string.Format("Motor: {0} | Profil: {1} | DNS: {2}", engineDisplayName, prof.Name, dnsName);

            AppLogger.Log("UI", string.Format("Koruma Başlatılıyor | Motor: {0} | Profil: {1} | DNS: {2} | Parametreler: {3}", engineDisplayName, prof.Name, dnsName, args));

            try
            {
                string safeExePath = GetShortPath(exePath);
                _lastLaunchError = null;
                if (!LaunchDpiProcessCore(safeExePath, args) || _dpiProcess == null)
                {
                    string errDetail = !string.IsNullOrEmpty(_lastLaunchError)
                        ? _lastLaunchError
                        : (exeName + " süreci başlatılamadı.");
                    throw new InvalidOperationException(errDetail);
                }

                AppLogger.Log("UI", exeName + " süreci başlatıldı (PID: " + _dpiProcess.Id + ")");

                _isManualStop = false;
                _isRunning = true;
                _lastEngineStartUtc = DateTime.UtcNow;
                // Hızlı ölüm yarışı: süreç, çıkış olayı işlenmeden hemen ölmüş olabilir.
                // UI asla "çalışıyor" durumunda kilitli kalmaz; motor gerçekten ayakta mı?
                bool engineAlive;
                try { engineAlive = _dpiProcess != null && !_dpiProcess.HasExited; }
                catch { engineAlive = false; }
                if (!engineAlive)
                {
                    _isRunning = false;
                    try
                    {
                        if (_dpiProcess != null)
                        {
                            try { if (!_dpiProcess.HasExited) { _dpiProcess.Kill(); _dpiProcess.WaitForExit(1000); } } catch {}
                            _dpiProcess.Dispose();
                        }
                    }
                    catch {}
                    _dpiProcess = null;
                    AppLogger.Log("ENGINE", "Motor süreci başlatma sonrası hemen kapandı; koruma başlatılamadı.");
                    throw new InvalidOperationException("Motor süreci başlatıldıktan hemen sonra kapandı (WinDivert sürücü hatası veya antivirüs engeli).");
                }
                else
                {
                    lock (_dnsMeasurementSync)
                    {
                        _activeDnsIndex = effDnsIdx;
                        _pendingAutoDnsIndex = -1;
                        _pendingAutoDnsConfirmations = 0;
                        _activeDnsFailureStrikes = 0;
                    }

                    try
                    {
                        if (this.InvokeRequired)
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_dnsSelector != null && !_dnsSelector.IsDisposed)
                                {
                                    _dnsSelector.EffectiveDnsIndex = effDnsIdx;
                                    _dnsSelector.Invalidate();
                                }
                            });
                        }
                        else if (_dnsSelector != null && !_dnsSelector.IsDisposed)
                        {
                            _dnsSelector.EffectiveDnsIndex = effDnsIdx;
                            _dnsSelector.Invalidate();
                        }
                    }
                    catch {}

                    try { AppTelemetry.SendHeartbeatAsync(false); } catch {}

                    // Discord WebRTC & UDP Ses Koruyucu + Medya CDN QUIC Hızlandırıcı arka planda devreye alınır.
                    ThreadPool.QueueUserWorkItem(delegate(object voiceState)
                    {
                        try
                        {
                            lock (_engineSync)
                            {
                                if (_isDisposing || !_isRunning || _isManualStop) return;
                                DiscordVoiceGuard.ApplyVoiceProtection();
                            }
                            if (!_isDisposing && _isRunning && !_isManualStop)
                            {
                                DiscordMediaAccelerator.ApplyMediaAccelerationCore(true);
                            }
                        }
                        catch (Exception voiceEx)
                        {
                            AppLogger.Log("VOICE_GUARD", "Discord ses koruyucu başlatılamadı: " + voiceEx.Message, LogLevel.Warn);
                        }
                    });
                }
                FlushDnsFast();


                int verifyStamp = _engineOpStamp;
                VerifyAndFallbackProtectionAsync(verifyStamp, safeExePath, cleanWhitelist, args,
                    baseProfileArgs, preservedDnsArgs, _selectedProfileIndex, gatewayFingerprint, startedWithSavedOverride);

                // Ping zamanlayıcısı yalnızca UI iş parçacığında başlatılır:
                // WinForms Timer etkinleştirildiği iş parçacığına bağlanır; UI dışı (mesaj
                // pompası olmayan) bir iş parçacığında başlatılırsa Tick olayı hiç tetiklenmez.
                if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                {
                    try
                    {
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (_isDisposing || this.IsDisposed) return;
                            UpdateUIState();
                            if (_isRunning) TriggerManualPing();
                        });
                    }
                    catch {}
                }

            }
            catch (Exception ex)
            {
                AppLogger.Log("ERROR", "Motor başlatılırken hata oluştu: " + ex.Message);
                if (showErrorDialogs && !_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                {
                    this.BeginInvoke((MethodInvoker)delegate
                    {
                        if (!_isDisposing && !this.IsDisposed)
                        {
                            MessageBox.Show(this, "Başlatma sırasında hata oluştu:\n" + ex.Message, "Hata", MessageBoxButtons.OK, MessageBoxIcon.Error);
                        }
                    });
                }
                // Yarı açılmış motor sürecini UI "durduruldu" derken arkada bırakma:
                // aksi halde görünmez şekilde paket filtrelemeye devam eder.
                try
                {
                    if (_dpiProcess != null)
                    {
                        try { if (!_dpiProcess.HasExited) { _dpiProcess.Kill(); _dpiProcess.WaitForExit(1500); } } catch {}
                        _dpiProcess.Dispose();
                    }
                }
                catch {}
                _dpiProcess = null;
                _isRunning = false;
            }
            finally
            {
                SyncUIStateSafe();
            }
        }

        private void CheckEngineDriverError(string log)
        {
            if (string.IsNullOrEmpty(log)) return;
            if (log.IndexOf("WinDivertOpen failed", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                // Hata numarasını ayrıştır ("error 1058" / "error 5: ...").
                // Alt dizi araması yerine sayısal karşılaştırma kullanılır; örn. "1058" içindeki
                // "5" yüzünden yanlış dala düşme veya "32" içindeki "3" gibi yanlış eşleşmeler önlenir.
                int code = -1;
                int idx = log.IndexOf("error", StringComparison.OrdinalIgnoreCase);
                if (idx >= 0)
                {
                    int j = idx + 5;
                    while (j < log.Length && !char.IsDigit(log[j])) j++;
                    int k = j;
                    while (k < log.Length && char.IsDigit(log[k])) k++;
                    if (k > j) int.TryParse(log.Substring(j, k - j), out code);
                }

                if (code == 1275 || code == 577)
                {
                    AppLogger.Log("WARNING", "Windows sürücü bütünlüğü veya bir güvenlik ilkesi WinDivert yüklemesini reddetti (Hata " + code + "). İmza, HVCI, sürücü engel listesi veya kuruluş ilkesi etkili olabilir; korumaları kapatmayın.");
                }
                else if (code == 1058)
                {
                    AppLogger.Log("WARNING", "Uygulamaya ait WinDivert sürücü servisi devre dışı (Hata 1058). Uygulama onarımı başlangıç türünü talep üzerine (Start=3) geri alır; ardından korumayı yeniden başlatın.");
                }
                else if (code == 1753 || code == 3 || code == 1060)
                {
                    AppLogger.Log("WARNING", "Uygulamaya ait WinDivert sürücü servisi meşgul veya takılı kaldı (Hata " + code + "). Onarım yalnızca paket sürücü dosyamızla eşleşen hizmeti temizler; ardından korumayı yeniden başlatın.");
                }
                else if (code == 5)
                {
                    AppLogger.Log("WARNING", "WinDivert erişim engellendi (Hata 5). Yönetici yetkisi veya antivirüs istisnası gereklidir.");
                }
                else
                {
                    AppLogger.Log("WARNING", "WinDivert sürücüsü açılamadı (Hata " + code + "). Tanılama raporundaki sürücü yolunu ve Windows Code Integrity kayıtlarını kontrol edin.");
                }
            }
        }

        // ==================== WinDivert Servis Temizliği ====================

        // Sistem araçları (netsh/sc/ipconfig/schtasks...) her zaman System32'den tam yolla
        // çağrılır: uygulama dizini kullanıcı tarafından yazılabilir olduğundan PATH/çalışma
        // dizini ele geçirme (binary planting) ile yükseltilmiş komut çalıştırma engellenir.
        internal static string SystemTool(string fileName)
        {
            try
            {
                if (string.IsNullOrEmpty(fileName) || fileName.IndexOf('\\') >= 0 || fileName.IndexOf('/') >= 0) return fileName;
                string sys = Environment.GetFolderPath(Environment.SpecialFolder.System);
                if (!string.IsNullOrEmpty(sys))
                {
                    string full = Path.Combine(sys, fileName);
                    if (File.Exists(full)) return full;
                }
            }
            catch {}
            return fileName;
        }

        // Komutu çalıştırıp çıkış kodunu döndürür (-1: başlatılamadı/zaman aşımı). Çıktı yutulur.
        private static int RunCommandGetExit(string cmd, string args)
        {
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo(SystemTool(cmd), args);
                // Konsol penceresi hiç oluşturulmaz (kısa 'sc' komutlarında göz kırpan siyah kutu yok).
                psi.UseShellExecute = false;
                psi.CreateNoWindow = true;
                psi.WindowStyle = ProcessWindowStyle.Hidden;
                using (Process p = Process.Start(psi))
                {
                    if (p == null) return -1;
                    if (!p.WaitForExit(4000))
                    {
                        try { p.Kill(); p.WaitForExit(1000); } catch {}
                        return -1;
                    }
                    return p.ExitCode;
                }
            }
            catch { return -1; }
        }

        // Yalnız bu uygulamanın paketlediği sürücü dosyasına işaret eden WinDivert hizmetlerini temizler.
        // Başka uygulamaların WinDivert hizmetleri ImagePath eşleşmediği için değiştirilmez.
        // Sahiplik registry'deki ImagePath ile doğrulanır; sc çıktısı konsola basılmaz (CreateNoWindow).
        internal static void CleanWinDivertDriverServices()
        {
            try
            {
                List<string> candidates = new List<string>();
                int skippedForeignServices = 0;
                using (RegistryKey services = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services", false))
                {
                    if (services == null) return;
                    string[] names = services.GetSubKeyNames();
                    for (int i = 0; i < names.Length; i++)
                    {
                        if (!names[i].StartsWith("WinDivert", StringComparison.OrdinalIgnoreCase)) continue;
                        bool isBundledDriver = false;
                        try
                        {
                            using (RegistryKey service = services.OpenSubKey(names[i], false))
                            {
                                string imagePath = service == null ? null : Convert.ToString(service.GetValue("ImagePath"));
                                isBundledDriver = AppPaths.IsBundledWinDivertDriverPath(imagePath);
                            }
                        }
                        catch {}
                        if (isBundledDriver) candidates.Add(names[i]);
                        else skippedForeignServices++;
                    }
                }
                if (skippedForeignServices > 0)
                {
                    AppLogger.Log("SERVICE", string.Format("Bu uygulamanın sürücü dosyasıyla eşleşmeyen {0} WinDivert hizmetine dokunulmadı.", skippedForeignServices), LogLevel.Info);
                }
                if (candidates.Count == 0) return;

                // Motor az önce durdurulduysa çekirdeğin sürücü tutamaçlarını bırakmasına fırsat ver:
                // yüklü sürücü varken silme isteği "silinmeyi bekliyor" durumuna düşebilir.
                Thread.Sleep(400);

                for (int i = 0; i < candidates.Count; i++)
                {
                    string name = candidates[i];
                    int start = -1;
                    bool ownershipConfirmed = false;
                    try
                    {
                        using (RegistryKey svc = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\" + name, true))
                        {
                            if (svc != null)
                            {
                                string imagePath = Convert.ToString(svc.GetValue("ImagePath"));
                                ownershipConfirmed = AppPaths.IsBundledWinDivertDriverPath(imagePath);
                                if (!ownershipConfirmed)
                                {
                                    AppLogger.Log("SERVICE", name + " hizmetinin sürücü yolu değişti; güvenlik için işlem yapılmadı.", LogLevel.Warn);
                                    continue;
                                }
                                object v = svc.GetValue("Start");
                                if (v != null) start = Convert.ToInt32(v);
                                if (start == 4)
                                {
                                    // Sürücü servisi devre dışı (Start=4) kalmışsa, öncelikle 'İsteğe Bağlı' (Start=3)
                                    // durumuna döndürülerek doğrudan kurtarılır. Böylece silme/kilitlenme (1072) ve
                                    // bilgisayarı yeniden başlatma zorunluluğu tamamen ortadan kalkar.
                                    try
                                    {
                                        svc.SetValue("Start", 3, RegistryValueKind.DWord);
                                        RunCommandGetExit("sc", "config " + name + " start= demand");
                                        AppLogger.Log("SERVICE", name + " sürücü servisi başarıyla yeniden etkinleştirildi (Start=3).");
                                        continue;
                                    }
                                    catch {}
                                }
                            }
                        }
                    }
                    catch {}

                    if (!ownershipConfirmed) continue;

                    int exit = RunCommandGetExit("sc", "delete " + name);
                    if (exit == 0 || exit == 1060 || exit == 1072) // 1060: yok, 1072: silinmek üzere işaretlendi
                    {
                        AppLogger.Log("SERVICE", "WinDivert sürücü servisi temizlendi (" + name + (exit == 1072 ? ", silinmek üzere işaretlendi" : (start == 4 ? ", devre dışıydı" : "")) + "); bir sonraki koruma başlatması temiz kurar.");
                    }
                    else
                    {
                        AppLogger.Log("WARNING", "Uygulamaya ait WinDivert sürücü servisi silinemedi (" + name + ", sc exit=" + exit + "). Uygulama kapatıldıktan sonra onarımı yeniden deneyin.");
                    }
                }
            }
            catch {}
        }

        // Adı verilen eski Windows hizmeti registry'de varsa siler (yoksa hiçbir şey yapmaz).
        private static void RemoveLegacyServiceIfExists(string serviceName)
        {
            try
            {
                bool exists = false;
                using (RegistryKey svc = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\" + serviceName, false))
                {
                    exists = (svc != null);
                }
                if (!exists) return;
                int exit = RunCommandGetExit("sc", "delete " + serviceName);
                if (exit == 0 || exit == 1060) // 1060: servis zaten yok
                {
                    AppLogger.Log("SERVICE", "Eski Windows hizmeti kaldırıldı: " + serviceName);
                }
                else
                {
                    AppLogger.Log("WARNING", "Eski Windows hizmeti kaldırılamadı (" + serviceName + ", sc exit=" + exit + "). Yönetici olarak 'sc delete " + serviceName + "' çalıştırın.");
                }
            }
            catch {}
        }

        public struct ExitCodeDiagnosis
        {
            public int ExitCode;
            public string Title;
            public string Description;
            public string RecommendedAction;
            public bool IsDriverConflict;
            public bool IsServiceDisabled;
            public bool IsSignatureOrHvci;
            public bool IsAccessDenied;
            public bool IsFileNotFound;
        }

        public static ExitCodeDiagnosis DiagnoseExitCode(int exitCode)
        {
            ExitCodeDiagnosis d = new ExitCodeDiagnosis();
            d.ExitCode = exitCode;
            d.IsDriverConflict = false;
            d.IsServiceDisabled = false;
            d.IsSignatureOrHvci = false;
            d.IsAccessDenied = false;
            d.IsFileNotFound = false;

            switch (exitCode)
            {
                case 5:
                case unchecked((int)0xC0000022): // STATUS_ACCESS_DENIED
                    d.Title = "Erişim Engellendi";
                    d.Description = "Yönetici izni eksik veya antivirüs programı engelliyor.";
                    d.RecommendedAction = "Programı yönetici olarak çalıştırın veya antivirüsten izin verin.";
                    d.IsAccessDenied = true;
                    break;

                case 577:
                case 1275:
                case unchecked((int)0xC0000428): // STATUS_INVALID_IMAGE_HASH
                    d.Title = "Windows Güvenlik Engeli";
                    d.Description = "Windows güvenlik ayarları koruma sürücüsünü engelledi.";
                    d.RecommendedAction = "Sorun Giderme Asistanı'ndan durumu kontrol edin.";
                    d.IsSignatureOrHvci = true;
                    break;

                case 1058:
                case unchecked((int)0x80070422): // ERROR_SERVICE_DISABLED
                    d.Title = "Koruma Servisi Kapalı";
                    d.Description = "Koruma servisi devre dışı kalmış.";
                    d.RecommendedAction = "Otomatik olarak yeniden açılıyor.";
                    d.IsServiceDisabled = true;
                    break;

                case 1753:
                case 1056:
                case 32:
                    d.Title = "Program Çakışması";
                    d.Description = "Arka planda açık kalan eski bir işlem var.";
                    d.RecommendedAction = "Eski işlem kapatılıp yeniden başlatılıyor.";
                    d.IsDriverConflict = true;
                    break;

                case 2:
                case 3:
                    d.Title = "Eksik Dosya";
                    d.Description = "Program dosyalarından biri bulunamadı.";
                    d.RecommendedAction = "Antivirüs programınızın dosyaları silmediğinden emin olun.";
                    d.IsFileNotFound = true;
                    break;

                default:
                    d.Title = string.Format("Beklenmeyen Durum ({0})", exitCode);
                    d.Description = "Koruma beklenmedik şekilde kapandı.";
                    d.RecommendedAction = "Otomatik olarak yeniden başlatılıyor.";
                    break;
            }
            return d;
        }

        private void DpiProcess_Exited(object sender, EventArgs e)
        {
            if (_isDisposing) return;

            // Gecikmiş bir çıkış olayı eski bir motor sürecinden geliyorsa yeni sürece dokunmamalı.
            Process proc = sender as Process;
            if (proc == null || !object.ReferenceEquals(proc, _dpiProcess)) return;
            int crashOperationStamp = Interlocked.Increment(ref _engineOpStamp);

            int exitCode = -1;
            try { exitCode = proc.ExitCode; } catch {}
            try { proc.Dispose(); } catch {}
            _dpiProcess = null;

            ExitCodeDiagnosis diag = DiagnoseExitCode(exitCode);
            AppLogger.Log("ENGINE", "goodbyedpi.exe işlemi kapandı (" + diag.Title + ")", (exitCode == 0 ? LogLevel.Info : LogLevel.Warn));

            if (_isRunning && !_isManualStop)
            {
                AppHealthMetrics.RecordWatchdogTrigger();

                if ((DateTime.UtcNow - _lastWatchdogRecovery).TotalSeconds > 45)
                {
                    _watchdogRecoveryCount = 0;
                }

                int currentAttempt = _watchdogRecoveryCount + 1;
                // Kademeli Bekleme (Exponential Backoff): 1. deneme 500ms, 2. deneme 2000ms, 3. deneme 5000ms
                int delayMs = (currentAttempt == 1) ? 500 : ((currentAttempt == 2) ? 2000 : 5000);

                AppLogger.Log("WATCHDOG", string.Format("Teşhis: {0} | {1} | Kademeli bekleme: {2}ms (Kurtarma {3}/3)",
                    diag.Title, diag.Description, delayMs, currentAttempt), LogLevel.Warn);

                // Smart Watchdog: Sıfır paket kayıplı pasif olay-odaklı kendi kendini onarma
                ThreadPool.QueueUserWorkItem(delegate(object state)
                {
                    // Kademeli bekleme: Windows kernel filtre soketinin serbest kalması beklenir
                    Thread.Sleep(delayMs);
                    if (_isDisposing || _engineOpStamp != crashOperationStamp) return;

                    // 1058: Servis devre dışı ise hemen DemandStart'a al
                    if (diag.IsServiceDisabled)
                    {
                        AppLogger.Log("WATCHDOG", "WinDivert servisi otomatik DemandStart (Start=3) moduna getiriliyor...", LogLevel.Info);
                        try
                        {
                            string serviceName = AppLogger.FindWinDivertServiceName();
                            using (RegistryKey sc = string.IsNullOrEmpty(serviceName) ? null : Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\" + serviceName, true))
                            {
                                if (sc != null) sc.SetValue("Start", 3, RegistryValueKind.DWord);
                            }
                            if (!string.IsNullOrEmpty(serviceName)) RunCommandGetExit("sc", "config " + serviceName + " start= demand");
                        }
                        catch {}
                    }

                    // 1753/Çakışma veya 2.+ denemede sürücü soketlerini ve takılı süreçleri temizle
                    if (diag.IsDriverConflict || diag.IsServiceDisabled || currentAttempt >= 2)
                    {
                        lock (_engineSync)
                        {
                            if (_isDisposing || _engineOpStamp != crashOperationStamp || !_isRunning || _isManualStop || _dpiProcess != null) return;
                            AppLogger.Log("WATCHDOG", "Sürücü kilit çözme devrede: çakışan süreçler ve WinDivert sürücü servisleri temizleniyor...", LogLevel.Info);
                            try { KillStrayDpiProcesses(); } catch {}
                            try { CleanWinDivertDriverServices(); } catch {}
                            Thread.Sleep(300);
                        }
                    }

                    try
                    {
                        if (this.IsHandleCreated && !this.IsDisposed && !_isDisposing)
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed || _engineOpStamp != crashOperationStamp) return;
                                // Kullanıcı bu arada elle yeniden başlattıysa (yeni süreç atandıysa)
                                // bayat çökme bildirimi motoru gereksiz yere diriltmemeli.
                                if (_dpiProcess != null) return;
                                if (_isRunning && !_isManualStop)
                                {
                                    if (_watchdogRecoveryCount < 3)
                                    {
                                        _watchdogRecoveryCount++;
                                        _lastWatchdogRecovery = DateTime.UtcNow;
                                        AppLogger.Log("WATCHDOG", string.Format("Otomatik kurtarma devrede (Kurtarma {0}/3)...", _watchdogRecoveryCount), LogLevel.Info);

                                        int recoveryStamp = _engineOpStamp;
                                        bool recoveryQueued = ThreadPool.QueueUserWorkItem(delegate(object recoveryState)
                                        {
                                            bool recovered = false;
                                            int resultStamp = recoveryStamp;
                                            try
                                            {
                                                lock (_engineSync)
                                                {
                                                    if (_isDisposing || this.IsDisposed || _engineOpStamp != recoveryStamp ||
                                                        _dpiProcess != null || !_isRunning || _isManualStop) return;
                                                    resultStamp = Interlocked.Increment(ref _engineOpStamp);
                                                    StartProtectionCore(false);
                                                    recovered = _isRunning && _dpiProcess != null;
                                                }
                                            }
                                            catch (Exception recoveryEx)
                                            {
                                                AppLogger.Log("WATCHDOG", "Otomatik kurtarma başlatılırken hata: " + recoveryEx.Message, LogLevel.Error);
                                            }

                                            bool retryQueued = false;
                                            if (!recovered)
                                            {
                                                if (_engineOpStamp != resultStamp) return;
                                                int stoppedStamp = StopProtection();
                                                resultStamp = stoppedStamp;
                                                if (!_isDisposing && _watchdogRecoveryCount < 3)
                                                {
                                                    retryQueued = QueueWatchdogRecoveryRetry(diag, exitCode, stoppedStamp);
                                                }
                                            }
                                            if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                                            {
                                                try
                                                {
                                                    this.BeginInvoke((MethodInvoker)delegate
                                                    {
                                                        if (_isDisposing || this.IsDisposed || _engineOpStamp != resultStamp) return;
                                                        // Kurtarma başlatma işlemi arka planda yapılır; UI yalnızca sonucu gösterir.
                                                        if (recovered && _isRunning && _dpiProcess != null)
                                                        {
                                                            AppHealthMetrics.RecordCrashRecovered();
                                                            ToastNotification.Show("Ba\u011flant\u0131 Yenilendi", "Koruma yeniden ba\u015flat\u0131ld\u0131.", ToastType.Success, 3000);
                                                        }
                                                        else if (retryQueued)
                                                        {
                                                            ToastNotification.Show("Kurtarma S\u00fcr\u00fcyor", "Koruma yeniden deneniyor...", ToastType.Warning, 3000);
                                                        }
                                                        else
                                                        {
                                                            AppLogger.Log("WATCHDOG", "Otomatik kurtarma başlatma çağrısı başarısız; koruma güvenli biçimde durduruldu.", LogLevel.Error);
                                                            string toastMsg = !string.IsNullOrEmpty(diag.RecommendedAction)
                                                                ? diag.RecommendedAction
                                                                : ("Koruma otomatik başlatılamadı. Hata kodu: " + exitCode + ". Detay için tıklayın.");
                                                            ToastNotification.Show("Koruma Durdu", toastMsg, ToastType.Error, 7000, delegate
                                                            {
                                                                if (this.IsDisposed || _isDisposing || !this.Enabled) return;
                                                                OpenDiagnostics();
                                                            });
                                                        }
                                                    });
                                                }
                                                catch (Exception notifyEx)
                                                {
                                                    AppLogger.Log("WATCHDOG", "Kurtarma sonucu arayüze aktarılamadı: " + notifyEx.Message, LogLevel.Warn);
                                                }
                                            }
                                        });
                                        if (!recoveryQueued)
                                        {
                                            StopProtection();
                                            AppLogger.Log("WATCHDOG", "Otomatik kurtarma iş parçacığı kuyruğa alınamadı; koruma güvenli biçimde durduruldu.", LogLevel.Error);
                                            ToastNotification.Show("Koruma Durdu", "Otomatik kurtarma başlatılamadı. Detay için tıklayın.", ToastType.Error, 7000, delegate
                                            {
                                                if (this.IsDisposed || _isDisposing || !this.Enabled) return;
                                                OpenDiagnostics();
                                            });
                                        }
                                    }
                                    else
                                    {
                                        AppLogger.Log("WATCHDOG", "Arka arkaya 3 kurtarma denemesi yapıldı. Sürücü servisi sıfırlanıyor ve koruma güvenli durduruluyor.", LogLevel.Error);
                                        // Sürücü temizliği deneme öncesi iş parçacığında yapıldı; durdurma kalan süreci de kapatır.
                                        _isManualStop = true;
                                        StopProtection();
                                        if (!_isDisposing)
                                        {
                                            string toastTitle = (diag.IsSignatureOrHvci || diag.IsAccessDenied) ? diag.Title : "Koruma Durdu";
                                            string toastMsg = !string.IsNullOrEmpty(diag.RecommendedAction) ? diag.RecommendedAction : ("Hata kodu: " + exitCode + ". Detay i\u00e7in t\u0131klay\u0131n.");
                                            ToastNotification.Show(toastTitle, toastMsg, ToastType.Error, 7000, delegate
                                            {
                                                if (this.IsDisposed || _isDisposing || !this.Enabled) return;
                                                OpenDiagnostics();
                                            });
                                        }
                                    }
                                }
                            });
                        }
                        else
                        {
                            _isRunning = false;
                            _isManualStop = true;
                            StopProtection();
                        }
                    }
                    catch {}
                });
            }
            else if (_isManualStop)
            {
                _isRunning = false;
                SyncUIStateSafe();
            }
        }

        private bool QueueWatchdogRecoveryRetry(ExitCodeDiagnosis diag, int exitCode, int expectedStamp)
        {
            int previousCount = _watchdogRecoveryCount;
            if (_isDisposing || this.IsDisposed || previousCount >= 3) return false;

            int nextAttempt = previousCount + 1;
            int delayMs = nextAttempt == 2 ? 2000 : 5000;
            return ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                Thread.Sleep(delayMs);
                if (_isDisposing || this.IsDisposed || _engineOpStamp != expectedStamp || _dpiProcess != null) return;

                bool recovered = false;
                bool superseded = false;
                int resultStamp = expectedStamp;
                try
                {
                    lock (_engineSync)
                    {
                        if (_isDisposing || this.IsDisposed || _engineOpStamp != expectedStamp ||
                            _dpiProcess != null || _watchdogRecoveryCount != previousCount) return;

                        if (diag.IsDriverConflict || diag.IsServiceDisabled || nextAttempt >= 2)
                        {
                            AppLogger.Log("WATCHDOG", "Yeniden denemeden önce WinDivert ve kalıntı süreçler temizleniyor...", LogLevel.Info);
                            try { KillStrayDpiProcesses(); } catch {}
                            try { CleanWinDivertDriverServices(); } catch {}
                            Thread.Sleep(300);
                        }

                        _watchdogRecoveryCount = nextAttempt;
                        _lastWatchdogRecovery = DateTime.UtcNow;
                        _isManualStop = false;
                        AppLogger.Log("WATCHDOG", string.Format("Otomatik kurtarma yeniden deneniyor (Kurtarma {0}/3)...", nextAttempt), LogLevel.Info);
                        int attemptStamp = Interlocked.Increment(ref _engineOpStamp);
                        resultStamp = attemptStamp;
                        StartProtectionCore(false);
                        if (_engineOpStamp != attemptStamp)
                        {
                            superseded = true;
                        }
                        else
                        {
                            recovered = _isRunning && _dpiProcess != null;
                        }
                    }
                }
                catch (Exception recoveryEx)
                {
                    AppLogger.Log("WATCHDOG", "Otomatik kurtarma yeniden denemesinde hata: " + recoveryEx.Message, LogLevel.Error);
                }

                if (superseded) return;

                bool retryQueued = false;
                if (!recovered)
                {
                    if (_engineOpStamp != resultStamp) return;
                    resultStamp = StopProtection();
                    if (!_isDisposing && _watchdogRecoveryCount < 3)
                    {
                        retryQueued = QueueWatchdogRecoveryRetry(diag, exitCode, resultStamp);
                    }
                }

                if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                {
                    try
                    {
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            if (_isDisposing || this.IsDisposed || _engineOpStamp != resultStamp) return;
                            if (recovered && _isRunning && _dpiProcess != null)
                            {
                                AppHealthMetrics.RecordCrashRecovered();
                                ToastNotification.Show("Ba\u011flant\u0131 Yenilendi", "Koruma yeniden ba\u015flat\u0131ld\u0131.", ToastType.Success, 3000);
                            }
                            else if (retryQueued)
                            {
                                ToastNotification.Show("Kurtarma S\u00fcr\u00fcyor", "Koruma yeniden deneniyor...", ToastType.Warning, 3000);
                            }
                            else
                            {
                                string toastMsg = !string.IsNullOrEmpty(diag.RecommendedAction)
                                    ? diag.RecommendedAction
                                    : ("Koruma otomatik başlatılamadı. Hata kodu: " + exitCode + ". Detay için tıklayın.");
                                ToastNotification.Show("Koruma Durdu", toastMsg, ToastType.Error, 7000, delegate
                                {
                                    if (this.IsDisposed || _isDisposing || !this.Enabled) return;
                                    OpenDiagnostics();
                                });
                            }
                        });
                    }
                    catch (Exception notifyEx)
                    {
                        AppLogger.Log("WATCHDOG", "Yeniden deneme sonucu arayüze aktarılamadı: " + notifyEx.Message, LogLevel.Warn);
                    }
                }
            });
        }

        private volatile bool _lastEngineGamePassthroughState = false;

        // Rekabetçi oyun açıldığında/kapandığında WinDivert sürücüsünü yeniden başlatmadan
        // (oyun ortasında sürücü yükleme takılması veya anti-cheat taraması tetiklemeden)
        // motor sürecinin öncelik ve çekirdek yakınlığı (P-Core / Passthrough) durumunu senkronize eder.
        private void SyncEngineGamingPassthroughState()
        {
            try
            {
                string gameName;
                bool gameRunning = GameNotificationDeferral.IsCompetitiveGameActive(out gameName);
                if (gameRunning == _lastEngineGamePassthroughState) return;

                lock (_engineSync)
                {
                    if (_dpiProcess == null || _dpiProcess.HasExited) return;
                    bool appliedPassthrough;
                    string detectedName;
                    ConfigureGigabitEngineProcess(_dpiProcess, out appliedPassthrough, out detectedName);
                    _lastEngineGamePassthroughState = appliedPassthrough;
                    if (appliedPassthrough)
                    {
                        AppLogger.Log("ENGINE", string.Format(
                            "Oyun İçi Sıfır Gecikme & Anti-Cheat Kalkanı devreye alındı ({0}): oyun paketleri 0.00 ms kernel passthrough ile izole edildi.",
                            detectedName ?? "Rekabetçi Oyun"));
                    }
                    else
                    {
                        AppLogger.Log("ENGINE", "Oyun kapandı: Gigabit P-Core Motor Önceliği (AboveNormal + P-Core Affinity) yeniden etkinleştirildi.");
                    }
                }
            }
            catch {}
        }

        // Ayrı gateway/Discord TLS, etkin DNS ve IP TCP kontrolleri belirsizliği azaltır;
        // profil geçişi üç ardışık doğrulanmış gözlemden sonra ölçülerek sınanır.
        private void ConnWatchdog_Tick()
        {
            if (_isDisposing || this.IsDisposed) return;
            if (!_isRunning || _isManualStop) { Interlocked.Exchange(ref _connFailStrikes, 0); return; }
            if (_isSmartBenchmarkRunning || _dnsPingScanRunning || _isOperationRunning || _isFailoverRunning) return;
            bool engineGone;
            // HasExited atılmış (Dispose edilmiş) bir süreçte istisna atabilir: bekçi turu
            // sessizce atlanır, istisna UI iş parçacığına sızıp kullanıcıya hata olarak yansımaz.
            try { engineGone = _dpiProcess == null || _dpiProcess.HasExited; }
            catch { engineGone = true; }
            if (engineGone) return; // ölü süreç: motor bekçisinin işi
            SyncEngineGamingPassthroughState();
            if ((DateTime.UtcNow - _lastEngineStartUtc).TotalSeconds < 120) return; // başlangıç doğrulamasına karışma
            if (_connCheckRunning) return;

            int operationStamp = _engineOpStamp;
            int profileIndex = _selectedProfileIndex;
            _connCheckRunning = true;
            bool queued = ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken)) return;

                    WatchdogProbeSnapshot evidence = new WatchdogProbeSnapshot();
                    evidence.OperationStamp = operationStamp;
                    evidence.ProfileIndex = profileIndex;
                    evidence.DnsStatus = ProbeActiveDns("gateway.discord.gg", out evidence.DnsServer, out evidence.DnsPort,
                        out evidence.DnsElapsedMs, out evidence.DnsError);

                    string gatewayError;
                    evidence.GatewayProbeElapsedMs = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out gatewayError);
                    AppHealthMetrics.RecordTlsProbe(evidence.GatewayProbeElapsedMs);
                    if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken)) return;

                    if (evidence.DnsStatus < 0)
                    {
                        DnsGuardTick("gateway.discord.gg", evidence.DnsServer, evidence.DnsPort,
                            operationStamp, profileIndex, evidence.DnsError);
                    }

                    if (evidence.GatewayProbeElapsedMs >= 0)
                    {
                        if (evidence.DnsStatus == 1)
                        {
                            RecordWatchdogProfileSample(profileIndex, true, evidence.GatewayProbeElapsedMs);
                        }
                        else
                        {
                            AppLogger.Log("CONNWATCH", "Gateway bağlantı/TLS erişilebilir; etkin DNS probu doğrulanmadığı için bu tur profil öğrenme geçmişine eklenmedi.", LogLevel.Info);
                        }
                        int previousStrikes = Interlocked.Exchange(ref _connFailStrikes, 0);
                        if (previousStrikes != 0) AppLogger.Log("CONNWATCH", "gateway.discord.gg bağlantı/TLS erişimi normale döndü.", LogLevel.Info);
                        _lastConnIntervention = DateTime.MinValue;
                        return;
                    }

                    string tcpError;
                    evidence.InternetTcpMs = NetworkProbe.TestTcpConnect("1.1.1.1", 443, 1200, out tcpError);
                    evidence.InternetTcpError = tcpError;
                    if (evidence.InternetTcpMs < 0 && IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken))
                    {
                        evidence.AlternateInternetTcpMs = NetworkProbe.TestTcpConnect("8.8.8.8", 443, 1200, out tcpError);
                        evidence.AlternateInternetTcpError = tcpError;
                    }
                    if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken)) return;

                    string discordSiteError;
                    evidence.DiscordSiteTlsMs = NetworkProbe.TestTlsHandshake("discord.com", 443, 2000, out discordSiteError);
                    if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken)) return;

                    if (evidence.DnsStatus < 0)
                    {
                        Interlocked.Exchange(ref _connFailStrikes, 0);
                        AppHealthMetrics.RecordWatchdogUnknown();
                        AppLogger.Log("CONNWATCH", string.Format(
                            "DNS yanıtı şüpheli; gateway bağlantı/TLS probu={0}, etkin DNS={1}:{2}. Profil geçişi yapılmadı.",
                            gatewayError ?? "başarısız", evidence.DnsServer ?? "?", evidence.DnsPort), LogLevel.Warn);
                        return;
                    }

                    if (evidence.DnsStatus != 1 || !evidence.HasIndependentInternetPath)
                    {
                        Interlocked.Exchange(ref _connFailStrikes, 0);
                        AppHealthMetrics.RecordWatchdogUnknown();
                        AppLogger.Log("CONNWATCH", string.Format(
                            "Bağlantı durumu belirsiz; DNS={0}, IP TCP 1.1.1.1:443={1}, 8.8.8.8:443={2}, gateway bağlantı/TLS probu başarısız. ICMP/DNS/TLS sinyalleri birbirinin yerine kullanılmadı; müdahale yok. TCP yanıtı: {3}",
                            evidence.DnsStatus == 1 ? "geçerli" : "ölçülemedi",
                            evidence.InternetTcpMs >= 0 ? evidence.InternetTcpMs + " ms" : "başarısız",
                            evidence.AlternateInternetTcpMs >= 0 ? evidence.AlternateInternetTcpMs + " ms" : "ölçülmedi",
                            evidence.InternetTcpError ?? evidence.AlternateInternetTcpError ?? "hata ayrıntısı yok"), LogLevel.Warn);
                        return;
                    }

                    if (evidence.DiscordSiteTlsMs < 0)
                    {
                        Interlocked.Exchange(ref _connFailStrikes, 0);
                        AppHealthMetrics.RecordWatchdogUnknown();
                        AppLogger.Log("CONNWATCH", string.Format(
                            "Discord gateway ve discord.com bağlantı/TLS ölçümleri başarısız; DNS ve dış IP TCP erişimi var. Hizmet kesintisi ile Discord yolu ayırt edilemedi; profil değiştirilmedi. discord.com: {0}",
                            discordSiteError ?? "zaman aşımı"), LogLevel.Warn);
                        return;
                    }

                    int strikeCount = Interlocked.Increment(ref _connFailStrikes);
                    AppHealthMetrics.RecordWatchdogConfirmedGatewayFailure();
                    AppLogger.Log("CONNWATCH", string.Format(
                        "Yalnızca gateway bağlantı/TLS probu başarısız; discord.com bağlantı/TLS={0} ms, gateway DNS={1}:{2} geçerli ({3} ms), IP TCP 1.1.1.1:443={4}, 8.8.8.8:443={5}; ardışık doğrulama {6}/{7}. Bu DPI kanıtı değildir.",
                        evidence.DiscordSiteTlsMs, evidence.DnsServer, evidence.DnsPort, evidence.DnsElapsedMs,
                        evidence.InternetTcpMs >= 0 ? evidence.InternetTcpMs + " ms" : "başarısız",
                        evidence.AlternateInternetTcpMs >= 0 ? evidence.AlternateInternetTcpMs + " ms" : "ölçülmedi",
                        strikeCount, WatchdogConfirmationCount), LogLevel.Warn);

                    if (strikeCount < WatchdogConfirmationCount) return;
                    if ((DateTime.UtcNow - _lastConnIntervention).TotalMinutes < WatchdogInterventionCooldownMinutes)
                    {
                        Interlocked.Exchange(ref _connFailStrikes, 0);
                        AppLogger.Log("CONNWATCH", "Doğrulanmış gateway arızası için 5 dakikalık geri çekilme aralığı sürüyor; yeni müdahale ertelendi.", LogLevel.Info);
                        return;
                    }
                    if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken)) return;

                    RecordWatchdogProfileSample(profileIndex, false, -1);
                    _lastConnIntervention = DateTime.UtcNow;
                    Interlocked.Exchange(ref _connFailStrikes, 0);
                    if (_autoFailoverEnabled) RunVerifiedWatchdogFailover(evidence);
                    else AppLogger.Log("CONNWATCH", "Otomatik geçiş kapalı; doğrulanmış gateway yolu sorunu kaydedildi, motor değiştirilmedi.", LogLevel.Info);
                }
                catch (Exception ex)
                {
                    AppLogger.Log("CONNWATCH", "İstisna: " + ex.Message, LogLevel.Error);
                }
                finally
                {
                    _connCheckRunning = false;
                }
            });
            if (!queued)
            {
                _connCheckRunning = false;
                AppLogger.Log("CONNWATCH", "Denetim iş parçacığı kuyruğa alınamadı; sonraki zamanlayıcı turunda yeniden denenir.", LogLevel.Warn);
            }
        }

        // ==================== Discord RTC Otomatik İyileştirici (Silent Watchdog & Auto-Healer) ====================
        // Discord'un gerçek zamanlı ses/WebRTC günlüklerini (renderer_js.log ve discord-webrtc_*) artımlı okuyarak
        // "RTC Bağlanıyor" takılması (>=6.5 sn), VOICE_STATE_UPDATE zaman aşımı, ani soket kopması (Kod 1006 / AVError)
        // ve ağır UDP paket kaybı sıçramalarını tespit eder; kullanıcının korumasını kapatıp açmasına gerek kalmadan
        // arka planda ~500 ms içinde DNS + Ses Koruyucu + WinDivert tünelini tazeler.
        private void RtcWatchdog_Tick()
        {
            if (_isDisposing || this.IsDisposed) return;
            if (!_isRunning || _isManualStop)
            {
                _rtcLogMonitor.ResetState();
                return;
            }
            if (_isSmartBenchmarkRunning || _dnsPingScanRunning || _isOperationRunning || _isFailoverRunning) return;
            if (_rtcCheckRunning || _rtcHealInProgress) return;
            if ((DateTime.UtcNow - _lastEngineStartUtc).TotalSeconds < 10) return;

            bool engineGone;
            try { engineGone = _dpiProcess == null || _dpiProcess.HasExited; }
            catch { engineGone = true; }
            if (engineGone) return;

            _rtcCheckRunning = true;
            bool queued = ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    if (_isDisposing || this.IsDisposed || !_isRunning || _isManualStop) return;
                    DiscordMediaAccelerator.EnsureRunningDiscordProtected();
                    DiscordRtcFailureTrigger trigger = _rtcLogMonitor.PollForFailure();
                    if (trigger == null) return;
                    if (!CanTriggerRtcHeal()) return;

                    ExecuteRtcAutoHeal(trigger);
                }
                catch (Exception ex)
                {
                    AppLogger.Log("RTC_HEAL", "RTC izleyici turunda hata: " + ex.Message, LogLevel.Debug);
                }
                finally
                {
                    _rtcCheckRunning = false;
                }
            });
            if (!queued)
            {
                _rtcCheckRunning = false;
            }
        }

        private bool CanTriggerRtcHeal()
        {
            lock (_rtcHealSync)
            {
                DateTime now = DateTime.UtcNow;
                if ((now - _lastRtcHealUtc).TotalSeconds < 30.0) return false;
                _recentRtcHealTimesUtc.RemoveAll(delegate(DateTime t)
                {
                    return (now - t).TotalMinutes >= 5.0;
                });
                if (_recentRtcHealTimesUtc.Count >= 3) return false;
                _lastRtcHealUtc = now;
                _recentRtcHealTimesUtc.Add(now);
                return true;
            }
        }

        private bool TrySoftResetDpiEngineForRtcHeal(int expectedStamp, out long resetElapsedMs)
        {
            Stopwatch sw = Stopwatch.StartNew();
            resetElapsedMs = -1;
            string archDir;
            string driverFileName;
            string nativeArchitecture;
            string architectureError;
            if (!AppPaths.TryGetEngineArchitecture(out archDir, out driverFileName, out nativeArchitecture, out architectureError))
            {
                return false;
            }

            string exePath = AppPaths.Resolve(Path.Combine(archDir, "goodbyedpi.exe"));
            if (!File.Exists(exePath)) return false;
            string safeExePath = GetShortPath(exePath);

            lock (_engineSync)
            {
                if (_isDisposing || this.IsDisposed || !_isRunning || _isManualStop || _isFailoverRunning || _engineOpStamp != expectedStamp)
                {
                    return false;
                }
                if (string.IsNullOrEmpty(_lastEngineArgs)) return false;

                bool launched = LaunchDpiProcessCore(safeExePath, _lastEngineArgs);
                sw.Stop();
                resetElapsedMs = sw.ElapsedMilliseconds;
                return launched && _dpiProcess != null;
            }
        }

        private void ExecuteRtcAutoHeal(DiscordRtcFailureTrigger trigger)
        {
            if (trigger == null || _rtcHealInProgress || _isDisposing || this.IsDisposed) return;
            _rtcHealInProgress = true;
            Stopwatch totalSw = Stopwatch.StartNew();
            try
            {
                int operationStamp = _engineOpStamp;
                int profileIndex = _selectedProfileIndex;
                if (!IsEngineVerificationContextCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken)) return;

                string endpointInfo = !string.IsNullOrEmpty(trigger.EndpointHost)
                    ? (trigger.EndpointHost + ":" + trigger.EndpointPort)
                    : "varsayılan ses rotası";
                AppLogger.Log("RTC_HEAL", string.Format(
                    "Discord ses arızası algılandı [{0}]: {1} | Hedef: {2}. Otomatik 500 ms yumuşak tünel sıfırlama başlatılıyor...",
                    trigger.ReasonCode, trigger.ReasonDisplay, endpointInfo), LogLevel.Warn);

                // 1. Yerel DNS önbelleğini temizle (yeni medya sunucusu IP'sinin anında çözülmesi için)
                FlushDnsFast();

                // 2. MMCSS Ses Önceliği, MTU 1420 ve Medya QUIC kalkanını tazele
                try
                {
                    lock (_engineSync)
                    {
                        if (!_isDisposing && _isRunning && !_isManualStop)
                        {
                            DiscordVoiceGuard.ApplyVoiceProtection();
                        }
                    }
                    if (!_isDisposing && _isRunning && !_isManualStop)
                    {
                        DiscordMediaAccelerator.ApplyMediaAccelerationCore(false);
                    }
                }
                catch {}

                // 3. WinDivert paket tünelini koruma durumunu düşürmeden ~500 ms içinde yerinde yenile
                long softResetMs;
                bool resetOk = TrySoftResetDpiEngineForRtcHeal(operationStamp, out softResetMs);
                if (!resetOk)
                {
                    totalSw.Stop();
                    AppHealthMetrics.RecordRtcHeal(false, totalSw.ElapsedMilliseconds, trigger.ReasonDisplay);
                    AppLogger.Log("RTC_HEAL", "Yumuşak tünel sıfırlama tamamlanamadı (motor durumu değişti veya meşgul).", LogLevel.Warn);
                    return;
                }

                FlushDnsFast();
                Thread.Sleep(320);

                if (!IsEngineVerificationContextCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken))
                {
                    totalSw.Stop();
                    AppHealthMetrics.RecordRtcHeal(true, totalSw.ElapsedMilliseconds, trigger.ReasonDisplay);
                    return;
                }

                // 4. Medya kontrol sunucusu ve Discord Gateway erişimini doğrula
                long mediaTlsMs = -1;
                string mediaErr = null;
                if (!string.IsNullOrEmpty(trigger.EndpointHost) && trigger.EndpointPort > 0)
                {
                    mediaTlsMs = NetworkProbe.TestTlsHandshake(trigger.EndpointHost, trigger.EndpointPort, 1800, out mediaErr);
                }

                string gwErr;
                long gwTlsMs = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2000, out gwErr);
                AppHealthMetrics.RecordTlsProbe(gwTlsMs);
                totalSw.Stop();

                bool healVerified = (gwTlsMs >= 0) || (mediaTlsMs >= 0);
                AppHealthMetrics.RecordRtcHeal(healVerified, totalSw.ElapsedMilliseconds, trigger.ReasonDisplay);

                if (healVerified)
                {
                    AppLogger.Log("RTC_HEAL", string.Format(
                        "Discord ses tüneli {0} ms içinde başarıyla tazelendi (tünel reset: {1} ms, gateway TLS: {2} ms{3}).",
                        totalSw.ElapsedMilliseconds,
                        softResetMs,
                        gwTlsMs,
                        mediaTlsMs >= 0 ? (", medya TLS: " + mediaTlsMs + " ms") : ""), LogLevel.Info);

                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed || !_isRunning) return;
                                ToastNotification.Show(
                                    "Discord Ses Onar\u0131ld\u0131",
                                    "Tak\u0131lan ses ba\u011flant\u0131s\u0131 arka planda yenilendi.",
                                    ToastType.Success,
                                    3500);
                            });
                        }
                        catch {}
                    }
                    return;
                }

                // 5. Yumuşak sıfırlamaya rağmen gateway.discord.gg erişilemiyorsa 3 dakika beklemek yerine
                // bağımsız DNS/TCP/discord.com kanıtlarını kontrol edip doğrulanmış profil geçişini hemen başlat.
                AppLogger.Log("RTC_HEAL", string.Format(
                    "Yumuşak sıfırlama sonrası gateway TLS yanıt vermedi ({0}). Gateway'e özgü engel kontrol ediliyor...",
                    gwErr ?? mediaErr ?? "zaman aşımı"), LogLevel.Warn);

                if (_autoFailoverEnabled && !_isOperationRunning &&
                    IsEngineVerificationContextCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken))
                {
                    WatchdogProbeSnapshot evidence = new WatchdogProbeSnapshot();
                    evidence.OperationStamp = operationStamp;
                    evidence.ProfileIndex = profileIndex;
                    evidence.GatewayProbeElapsedMs = gwTlsMs;
                    evidence.DnsStatus = ProbeActiveDns("gateway.discord.gg", out evidence.DnsServer, out evidence.DnsPort,
                        out evidence.DnsElapsedMs, out evidence.DnsError);

                    string tcpErr;
                    evidence.InternetTcpMs = NetworkProbe.TestTcpConnect("1.1.1.1", 443, 1200, out tcpErr);
                    evidence.InternetTcpError = tcpErr;
                    if (evidence.InternetTcpMs < 0)
                    {
                        evidence.AlternateInternetTcpMs = NetworkProbe.TestTcpConnect("8.8.8.8", 443, 1200, out tcpErr);
                        evidence.AlternateInternetTcpError = tcpErr;
                    }

                    string siteErr;
                    evidence.DiscordSiteTlsMs = NetworkProbe.TestTlsHandshake("discord.com", 443, 1800, out siteErr);

                    if (evidence.IsGatewaySpecificFailure && !_isOperationRunning &&
                        IsEngineVerificationContextCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken))
                    {
                        AppHealthMetrics.RecordWatchdogConfirmedGatewayFailure();
                        AppLogger.Log("RTC_HEAL", "Ses kopması sonrası aktif profilin gateway erişimini engellediği doğrulandı; 3 dakika beklenmeden yedek profile geçiliyor.", LogLevel.Warn);
                        _lastConnIntervention = DateTime.UtcNow;
                        Interlocked.Exchange(ref _connFailStrikes, 0);
                        RunVerifiedWatchdogFailover(evidence);
                    }
                }
            }
            catch (Exception ex)
            {
                AppLogger.Log("RTC_HEAL", "RTC otomatik onarım hatası: " + ex.Message, LogLevel.Warn);
            }
            finally
            {
                _rtcHealInProgress = false;
            }
        }

        private sealed class DiscordRtcFailureTrigger
        {
            public string ReasonCode;
            public string ReasonDisplay;
            public string EndpointHost;
            public int EndpointPort;
        }

        // Discord'un renderer_js.log ve discord-webrtc_* günlük dosyalarını kilitlemeden
        // (FileShare.ReadWrite | FileShare.Delete) yalnızca yeni eklenen satırları okuyarak izler.
        private sealed class DiscordRtcLogMonitor
        {
            private readonly object _sync = new object();
            private string _activeLogDir = null;
            private DateTime _lastDirResolveUtc = DateTime.MinValue;
            private DateTime _lastProcessCheckUtc = DateTime.MinValue;
            private bool _discordRunningCached = false;

            private string _rendererLogPath = null;
            private long _rendererLogOffset = -1;

            private string _webrtcLogPath = null;
            private long _webrtcLogOffset = -1;
            private DateTime _lastWebrtcFileScanUtc = DateTime.MinValue;

            private DateTime _connectingEnteredUtc = DateTime.MinValue;
            private DateTime _lastConnectedUtc = DateTime.MinValue;
            private bool _stuckTriggeredForCurrentAttempt = false;
            private string _lastEndpointHost = null;
            private int _lastEndpointPort = 443;

            private long _prevOutboundSent = -1;
            private long _prevOutboundFailed = -1;
            private long _prevOutboundLost = -1;
            private long _prevInboundReceived = -1;
            private long _prevInboundLost = -1;
            private int _consecutiveHighLossSamples = 0;

            public void ResetState()
            {
                lock (_sync)
                {
                    _connectingEnteredUtc = DateTime.MinValue;
                    _stuckTriggeredForCurrentAttempt = false;
                    _consecutiveHighLossSamples = 0;
                    _rendererLogOffset = -1;
                    _webrtcLogOffset = -1;
                }
            }

            public DiscordRtcFailureTrigger PollForFailure()
            {
                lock (_sync)
                {
                    if (!IsDiscordProcessRunning())
                    {
                        _connectingEnteredUtc = DateTime.MinValue;
                        _stuckTriggeredForCurrentAttempt = false;
                        return null;
                    }

                    string logDir = ResolveDiscordLogDirectory();
                    if (string.IsNullOrEmpty(logDir)) return null;

                    DiscordRtcFailureTrigger rendererTrigger = PollRendererLog(logDir);
                    if (rendererTrigger != null) return rendererTrigger;

                    DiscordRtcFailureTrigger webrtcTrigger = PollWebRtcLog(logDir);
                    if (webrtcTrigger != null) return webrtcTrigger;

                    // "RTC Bağlanıyor" / "AWAITING_ENDPOINT" / "AUTHENTICATING" aşamasında >= 6.5 saniye asılı kalma kontrolü
                    if (_connectingEnteredUtc != DateTime.MinValue && !_stuckTriggeredForCurrentAttempt)
                    {
                        double stuckSeconds = (DateTime.UtcNow - _connectingEnteredUtc).TotalSeconds;
                        if (stuckSeconds >= 6.5 && stuckSeconds <= 45.0)
                        {
                            _stuckTriggeredForCurrentAttempt = true;
                            return CreateTrigger("StuckConnecting", "Ses bağlantısı 'RTC Bağlanıyor' aşamasında takıldı");
                        }
                        if (stuckSeconds > 45.0)
                        {
                            _connectingEnteredUtc = DateTime.MinValue;
                            _stuckTriggeredForCurrentAttempt = false;
                        }
                    }

                    return null;
                }
            }

            private DiscordRtcFailureTrigger CreateTrigger(string code, string display)
            {
                DiscordRtcFailureTrigger t = new DiscordRtcFailureTrigger();
                t.ReasonCode = code;
                t.ReasonDisplay = display;
                t.EndpointHost = _lastEndpointHost;
                t.EndpointPort = _lastEndpointPort > 0 ? _lastEndpointPort : 443;
                return t;
            }

            public void GetLastEndpoint(out string host, out int port)
            {
                lock (_sync)
                {
                    host = _lastEndpointHost;
                    port = _lastEndpointPort > 0 ? _lastEndpointPort : 443;
                }
            }

            public bool IsConnectingStuckNow()
            {
                lock (_sync)
                {
                    if (_connectingEnteredUtc == DateTime.MinValue) return false;
                    double sec = (DateTime.UtcNow - _connectingEnteredUtc).TotalSeconds;
                    return sec >= 5.0 && sec <= 60.0;
                }
            }

            private bool IsDiscordProcessRunning()
            {
                DateTime now = DateTime.UtcNow;
                if ((now - _lastProcessCheckUtc).TotalSeconds < 4.0)
                {
                    return _discordRunningCached;
                }
                _lastProcessCheckUtc = now;
                bool running = false;
                string[] names = new string[] { "Discord", "DiscordCanary", "DiscordPTB" };
                for (int i = 0; i < names.Length; i++)
                {
                    Process[] procs = null;
                    try
                    {
                        procs = Process.GetProcessesByName(names[i]);
                        if (procs != null && procs.Length > 0)
                        {
                            running = true;
                        }
                    }
                    catch {}
                    finally
                    {
                        if (procs != null)
                        {
                            for (int j = 0; j < procs.Length; j++)
                            {
                                try { if (procs[j] != null) procs[j].Dispose(); } catch {}
                            }
                        }
                    }
                    if (running) break;
                }
                _discordRunningCached = running;
                return running;
            }

            private string ResolveDiscordLogDirectory()
            {
                DateTime now = DateTime.UtcNow;
                if (!string.IsNullOrEmpty(_activeLogDir) && (now - _lastDirResolveUtc).TotalSeconds < 20.0)
                {
                    return _activeLogDir;
                }
                _lastDirResolveUtc = now;

                try
                {
                    string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
                    string[] candidates = new string[]
                    {
                        Path.Combine(appData, "discord\\logs"),
                        Path.Combine(appData, "discordcanary\\logs"),
                        Path.Combine(appData, "discordptb\\logs")
                    };

                    string bestDir = null;
                    DateTime bestWriteUtc = DateTime.MinValue;
                    for (int i = 0; i < candidates.Length; i++)
                    {
                        string rPath = Path.Combine(candidates[i], "renderer_js.log");
                        if (File.Exists(rPath))
                        {
                            DateTime wt = File.GetLastWriteTimeUtc(rPath);
                            if (wt > bestWriteUtc)
                            {
                                bestWriteUtc = wt;
                                bestDir = candidates[i];
                            }
                        }
                    }
                    _activeLogDir = bestDir;
                }
                catch
                {
                    _activeLogDir = null;
                }
                return _activeLogDir;
            }

            private DiscordRtcFailureTrigger PollRendererLog(string logDir)
            {
                string path = Path.Combine(logDir, "renderer_js.log");
                if (!File.Exists(path)) return null;

                List<string> newLines = ReadAppendedLines(path, ref _rendererLogPath, ref _rendererLogOffset);
                if (newLines == null || newLines.Count == 0) return null;

                DiscordRtcFailureTrigger pendingTrigger = null;
                for (int i = 0; i < newLines.Count; i++)
                {
                    string line = newLines[i];
                    if (string.IsNullOrEmpty(line)) continue;

                    // RTC medya sunucusu adresini güncel tut (örn. wss://c-otp02-1473a404.discord.media:443/)
                    if (line.IndexOf("wss://", StringComparison.OrdinalIgnoreCase) >= 0 &&
                        (line.IndexOf("[RTCControlSocket", StringComparison.Ordinal) >= 0 ||
                         line.IndexOf("Connecting to RTC server", StringComparison.Ordinal) >= 0))
                    {
                        TryExtractWssEndpoint(line, out _lastEndpointHost, out _lastEndpointPort);
                    }

                    double ageSeconds;
                    bool isFresh = TryGetLogLineAgeSeconds(line, out ageSeconds) && ageSeconds <= 22.0;

                    // 1. Durum makinesi güncellemeleri (yalnızca ana ses bağlantısı: default)
                    if (line.IndexOf("[RTCConnection(", StringComparison.Ordinal) >= 0 &&
                        line.IndexOf("default)]", StringComparison.Ordinal) >= 0)
                    {
                        if (line.IndexOf("=> RTC_CONNECTED", StringComparison.Ordinal) >= 0 ||
                            line.IndexOf("RTC connected to media server", StringComparison.Ordinal) >= 0)
                        {
                            _connectingEnteredUtc = DateTime.MinValue;
                            _stuckTriggeredForCurrentAttempt = false;
                            _consecutiveHighLossSamples = 0;
                            if (isFresh) _lastConnectedUtc = DateTime.UtcNow;
                            pendingTrigger = null;
                            continue;
                        }

                        if (line.IndexOf("=> DISCONNECTED", StringComparison.Ordinal) >= 0 ||
                            line.IndexOf("=> RTC_DISCONNECTED", StringComparison.Ordinal) >= 0 ||
                            line.IndexOf("Destroy RTCConnection", StringComparison.Ordinal) >= 0)
                        {
                            _connectingEnteredUtc = DateTime.MinValue;
                            _stuckTriggeredForCurrentAttempt = false;
                            continue;
                        }

                        if (isFresh &&
                            (line.IndexOf("=> AWAITING_ENDPOINT", StringComparison.Ordinal) >= 0 ||
                             line.IndexOf("=> CONNECTING", StringComparison.Ordinal) >= 0 ||
                             line.IndexOf("=> AUTHENTICATING", StringComparison.Ordinal) >= 0 ||
                             line.IndexOf("=> RTC_CONNECTING", StringComparison.Ordinal) >= 0))
                        {
                            if (_connectingEnteredUtc == DateTime.MinValue)
                            {
                                _connectingEnteredUtc = DateTime.UtcNow;
                                _stuckTriggeredForCurrentAttempt = false;
                            }
                        }

                        if (isFresh &&
                            (line.IndexOf("ICE_CHECKING => FAILED", StringComparison.Ordinal) >= 0 ||
                             line.IndexOf("=> NO_ROUTE", StringComparison.Ordinal) >= 0 ||
                             line.IndexOf("DTLS handshake failed", StringComparison.OrdinalIgnoreCase) >= 0))
                        {
                            pendingTrigger = CreateTrigger("IceOrRouteFailed", "Discord ses ICE/rota el sıkışması başarısız oldu");
                        }
                    }

                    if (!isFresh) continue;

                    // 2. VOICE_STATE_UPDATE 30sn zaman aşımı veya ses kurulumu sırasında Gateway kopması
                    if (line.IndexOf("[RTCConnectionStore] No VOICE_STATE_UPDATE received within", StringComparison.Ordinal) >= 0)
                    {
                        _connectingEnteredUtc = DateTime.MinValue;
                        pendingTrigger = CreateTrigger("VoiceStateTimeout", "Ses kanalı yanıt vermedi (VOICE_STATE_UPDATE zaman aşımı)");
                        continue;
                    }

                    bool voiceActiveOrConnecting = (_connectingEnteredUtc != DateTime.MinValue) ||
                        ((DateTime.UtcNow - _lastConnectedUtc).TotalMinutes <= 5.0);
                    if (voiceActiveOrConnecting &&
                        (line.IndexOf("[GatewaySocket] [ACK TIMEOUT]", StringComparison.Ordinal) >= 0 ||
                         line.IndexOf("[GatewaySocket] [RESET] (false", StringComparison.Ordinal) >= 0))
                    {
                        pendingTrigger = CreateTrigger("GatewayZombie", "Discord ağ geçidi ses oturumu sırasında koptu");
                        continue;
                    }

                    // 3. Beklenmeyen RTC kontrol soketi kopması (normal kullanıcı çıkışları hariç)
                    if (line.IndexOf("[RTCControlSocket(default)] [WS CLOSED]", StringComparison.Ordinal) >= 0)
                    {
                        // Normal kapanış kodlarını (1000, 4014 kanaldan ayrılma, 4022) ve clean: true durumunu yoksay
                        if (line.IndexOf("clean: false", StringComparison.Ordinal) >= 0 &&
                            line.IndexOf("code: 1000", StringComparison.Ordinal) < 0 &&
                            line.IndexOf("code: 4014", StringComparison.Ordinal) < 0 &&
                            line.IndexOf("code: 4022", StringComparison.Ordinal) < 0)
                        {
                            pendingTrigger = CreateTrigger("AbnormalSocketDrop", "Discord ses kontrol soketi beklenmedik şekilde koptu (Kod 1006)");
                            continue;
                        }
                    }

                    if (line.IndexOf("[AVError] AV error reported: stream-reconnecting", StringComparison.Ordinal) >= 0)
                    {
                        pendingTrigger = CreateTrigger("StreamReconnecting", "Discord ses/yayın akışı koptu (stream-reconnecting)");
                    }
                }

                return pendingTrigger;
            }

            private DiscordRtcFailureTrigger PollWebRtcLog(string logDir)
            {
                DateTime now = DateTime.UtcNow;
                if (string.IsNullOrEmpty(_webrtcLogPath) || (now - _lastWebrtcFileScanUtc).TotalSeconds >= 10.0)
                {
                    _lastWebrtcFileScanUtc = now;
                    string newestWebrtc = FindNewestWebRtcLog(logDir);
                    if (!string.IsNullOrEmpty(newestWebrtc) &&
                        !string.Equals(newestWebrtc, _webrtcLogPath, StringComparison.OrdinalIgnoreCase))
                    {
                        _webrtcLogPath = newestWebrtc;
                        _webrtcLogOffset = -1;
                        _prevOutboundSent = -1;
                        _prevInboundReceived = -1;
                        _consecutiveHighLossSamples = 0;
                    }
                }

                if (string.IsNullOrEmpty(_webrtcLogPath) || !File.Exists(_webrtcLogPath)) return null;

                List<string> newLines = ReadAppendedLines(_webrtcLogPath, ref _webrtcLogPath, ref _webrtcLogOffset);
                if (newLines == null || newLines.Count == 0) return null;

                for (int i = 0; i < newLines.Count; i++)
                {
                    string line = newLines[i];
                    if (string.IsNullOrEmpty(line)) continue;

                    double ageSeconds;
                    if (!TryGetLogLineAgeSeconds(line, out ageSeconds) || ageSeconds > 22.0) continue;

                    // 1. UDP soketi yeniden bağlanma hatası
                    if (line.IndexOf("udp_socket.cpp", StringComparison.Ordinal) >= 0 &&
                        line.IndexOf("ReconnectionAttemptFinished:", StringComparison.Ordinal) >= 0 &&
                        line.IndexOf("succeeded: 0", StringComparison.Ordinal) >= 0)
                    {
                        return CreateTrigger("UdpReconnectFailed", "Discord UDP ses soketi yeniden bağlanamadı");
                    }

                    // 2. Giden ses paket kaybı / gönderim hatası analizi
                    if (line.IndexOf("[default] Outbound audio stats for user:", StringComparison.Ordinal) >= 0)
                    {
                        long sent = ExtractMetricValue(line, "packets sent:");
                        long failed = ExtractMetricValue(line, "packets failed to send:");
                        long lost = ExtractMetricValue(line, "packets lost:");
                        if (sent >= 0 && failed >= 0 && lost >= 0)
                        {
                            if (_prevOutboundSent >= 0 && sent >= _prevOutboundSent &&
                                failed >= _prevOutboundFailed && lost >= _prevOutboundLost)
                            {
                                long deltaSent = sent - _prevOutboundSent;
                                long deltaBad = (failed - _prevOutboundFailed) + (lost - _prevOutboundLost);
                                long deltaTotal = deltaSent + deltaBad;
                                if (deltaTotal >= 35)
                                {
                                    long lossPct = (deltaBad * 100L) / deltaTotal;
                                    if (lossPct >= 30)
                                    {
                                        _consecutiveHighLossSamples++;
                                        if (lossPct >= 45 || _consecutiveHighLossSamples >= 2)
                                        {
                                            _consecutiveHighLossSamples = 0;
                                            _prevOutboundSent = sent;
                                            _prevOutboundFailed = failed;
                                            _prevOutboundLost = lost;
                                            return CreateTrigger("HighPacketLoss", string.Format("Discord giden ses paket kaybı sıçradı (%{0})", lossPct));
                                        }
                                    }
                                    else
                                    {
                                        _consecutiveHighLossSamples = 0;
                                    }
                                }
                            }
                            _prevOutboundSent = sent;
                            _prevOutboundFailed = failed;
                            _prevOutboundLost = lost;
                        }
                    }

                    // 3. Gelen ses paket kaybı analizi
                    if (line.IndexOf("[default] Inbound stats for user:", StringComparison.Ordinal) >= 0)
                    {
                        long received = ExtractMetricValue(line, "packets received:");
                        long lost = ExtractMetricValue(line, "lost:");
                        if (received >= 0 && lost >= 0)
                        {
                            if (_prevInboundReceived >= 0 && received >= _prevInboundReceived && lost >= _prevInboundLost)
                            {
                                long deltaRecv = received - _prevInboundReceived;
                                long deltaLost = lost - _prevInboundLost;
                                long deltaTotal = deltaRecv + deltaLost;
                                if (deltaTotal >= 35)
                                {
                                    long lossPct = (deltaLost * 100L) / deltaTotal;
                                    if (lossPct >= 30)
                                    {
                                        _consecutiveHighLossSamples++;
                                        if (lossPct >= 45 || _consecutiveHighLossSamples >= 2)
                                        {
                                            _consecutiveHighLossSamples = 0;
                                            _prevInboundReceived = received;
                                            _prevInboundLost = lost;
                                            return CreateTrigger("HighPacketLoss", string.Format("Discord gelen ses paket kaybı sıçradı (%{0})", lossPct));
                                        }
                                    }
                                    else
                                    {
                                        _consecutiveHighLossSamples = 0;
                                    }
                                }
                            }
                            _prevInboundReceived = received;
                            _prevInboundLost = lost;
                        }
                    }
                }

                return null;
            }

            private static string FindNewestWebRtcLog(string logDir)
            {
                try
                {
                    string[] files = Directory.GetFiles(logDir, "discord-webrtc_*");
                    if (files == null || files.Length == 0) return null;
                    string newest = null;
                    DateTime newestWrite = DateTime.MinValue;
                    for (int i = 0; i < files.Length; i++)
                    {
                        DateTime wt = File.GetLastWriteTimeUtc(files[i]);
                        if (wt > newestWrite)
                        {
                            newestWrite = wt;
                            newest = files[i];
                        }
                    }
                    return newest;
                }
                catch
                {
                    return null;
                }
            }

            private static List<string> ReadAppendedLines(string path, ref string trackedPath, ref long trackedOffset)
            {
                try
                {
                    FileInfo fi = new FileInfo(path);
                    if (!fi.Exists) return null;
                    long len = fi.Length;

                    // İlk kez bağlanırken dosya sonundan (EOF) başla: geçmiş günlük kayıtları asla yanlış alarm üretmez.
                    if (!string.Equals(path, trackedPath, StringComparison.OrdinalIgnoreCase) || trackedOffset < 0)
                    {
                        trackedPath = path;
                        trackedOffset = len;
                        return null;
                    }

                    // Dosya sıfırlandıysa (log rotasyonu) baştan oku
                    if (len < trackedOffset)
                    {
                        trackedOffset = Math.Max(0L, len - 16384L);
                    }
                    if (len == trackedOffset) return null;

                    // Tek turda en fazla son 64 KB'ı oku
                    if (len - trackedOffset > 65536L)
                    {
                        trackedOffset = len - 65536L;
                    }

                    List<string> lines = new List<string>();
                    using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
                    {
                        fs.Seek(trackedOffset, SeekOrigin.Begin);
                        using (StreamReader sr = new StreamReader(fs, Encoding.UTF8, true, 4096))
                        {
                            string line;
                            while ((line = sr.ReadLine()) != null)
                            {
                                lines.Add(line);
                            }
                        }
                        trackedOffset = fs.Position;
                    }
                    return lines;
                }
                catch
                {
                    return null;
                }
            }

            private static bool TryGetLogLineAgeSeconds(string line, out double ageSeconds)
            {
                ageSeconds = double.MaxValue;
                if (string.IsNullOrEmpty(line) || line.Length < 25 || line[0] != '[') return false;
                int closeIdx = line.IndexOf(']');
                if (closeIdx < 19 || closeIdx > 28) return false;
                string ts = line.Substring(1, closeIdx - 1);
                DateTime parsedLocal;
                if (DateTime.TryParseExact(ts, "yyyy-MM-dd HH:mm:ss.fff", CultureInfo.InvariantCulture, DateTimeStyles.AssumeLocal, out parsedLocal) ||
                    DateTime.TryParse(ts, CultureInfo.InvariantCulture, DateTimeStyles.AssumeLocal, out parsedLocal))
                {
                    ageSeconds = Math.Abs((DateTime.Now - parsedLocal).TotalSeconds);
                    return true;
                }
                return false;
            }

            private static void TryExtractWssEndpoint(string line, out string host, out int port)
            {
                host = null;
                port = 443;
                int idx = line.IndexOf("wss://", StringComparison.OrdinalIgnoreCase);
                if (idx < 0) return;
                int start = idx + 6;
                int end = start;
                while (end < line.Length && line[end] != '/' && line[end] != ' ' && line[end] != '"' && line[end] != ')')
                {
                    end++;
                }
                if (end <= start) return;
                string authority = line.Substring(start, end - start).Trim();
                int colon = authority.IndexOf(':');
                if (colon > 0)
                {
                    host = authority.Substring(0, colon);
                    int parsedPort;
                    if (int.TryParse(authority.Substring(colon + 1), NumberStyles.Integer, CultureInfo.InvariantCulture, out parsedPort) &&
                        parsedPort > 0 && parsedPort <= 65535)
                    {
                        port = parsedPort;
                    }
                }
                else
                {
                    host = authority;
                }
            }

            private static long ExtractMetricValue(string line, string marker)
            {
                int idx = line.IndexOf(marker, StringComparison.Ordinal);
                if (idx < 0) return -1;
                int pos = idx + marker.Length;
                while (pos < line.Length && line[pos] == ' ') pos++;
                int end = pos;
                while (end < line.Length && line[end] >= '0' && line[end] <= '9') end++;
                if (end <= pos) return -1;
                long val;
                if (long.TryParse(line.Substring(pos, end - pos), NumberStyles.Integer, CultureInfo.InvariantCulture, out val))
                {
                    return val;
                }
                return -1;
            }
        }

        // Etkin çözücüye önbelleği atlayan DNS sorgusu gönderilir; şüpheli yanıt iki kez
        // doğrulanmadan yerel önbellek temizlenmez. Sonuç belirsizse otomatik onarım yapılmaz.
        private void DnsGuardTick(string queryName, string server, int port, int operationStamp, int profileIndex, string initialError)
        {
            if (string.IsNullOrWhiteSpace(queryName) || string.IsNullOrEmpty(server) || port < 1 || port > 65535 ||
                _dnsGuardRunning || _dnsPingScanRunning) return;
            if ((DateTime.UtcNow - _lastDnsRepairUtc).TotalMinutes < 30) return;
            if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken)) return;

            _dnsGuardRunning = true;
            bool queued = ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                bool repairAttempted = false;
                try
                {
                    if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken) || _dnsPingScanRunning) return;
                    Thread.Sleep(150);
                    int bytes;
                    string firstError;
                    long firstMs = NetworkProbe.TestUdpDns(server, port, 1000, queryName, out bytes, out firstError);
                    if (firstMs != -3)
                    {
                        AppLogger.Log("DNSGUARD", "İlk şüpheli DNS yanıtı ikinci sorguda doğrulanmadı; işlem yapılmadı. " + (firstError ?? initialError ?? ""), LogLevel.Info);
                        return;
                    }
                    if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken) || _dnsPingScanRunning) return;

                    _lastDnsRepairUtc = DateTime.UtcNow;
                    AppHealthMetrics.RecordDnsRepair();
                    repairAttempted = true;
                    AppLogger.Log("DNSGUARD", string.Format(
                        "Etkin çözücü {0}:{1}, {2} sorgusunda iki kez şüpheli/engelli yanıt verdi. Yerel DNS önbelleği temizleniyor; bu, sunucu yanıtının kaynağını tek başına belirlemez.",
                        server, port, queryName), LogLevel.Warn);
                    FlushDnsFast();

                    Thread.Sleep(2500);
                    if (!IsWatchdogOperationCurrent(operationStamp, profileIndex, _watchdogFailoverOperationToken))
                    {
                        AppHealthMetrics.RecordDnsRepairResult(false);
                        repairAttempted = false;
                        return;
                    }
                    string verifyError;
                    long verifyMs = NetworkProbe.TestUdpDns(server, port, 1200, queryName, out bytes, out verifyError);
                    if (verifyMs >= 0 && bytes > 0)
                    {
                        AppLogger.Log("DNSGUARD", "Önbellek temizliği sonrası etkin çözücüden geçerli DNS yanıtı alındı.", LogLevel.Info);
                        AppHealthMetrics.RecordDnsRepairResult(true);
                        repairAttempted = false;
                        return;
                    }

                    if (verifyMs >= 0)
                    {
                        AppHealthMetrics.RecordDnsRepairResult(false);
                        repairAttempted = false;
                        AppLogger.Log("DNSGUARD", "DNS sorgusu süre döndürdü ancak yanıt gövdesi doğrulanamadı.", LogLevel.Warn);
                        return;
                    }

                    if (verifyMs == -3)
                    {
                        AppLogger.Log("DNSGUARD", "Önbellek temizliği etkin çözücünün şüpheli yanıtını değiştirmedi; sonuç başarısız olarak kaydedildi.", LogLevel.Warn);
                        AppHealthMetrics.RecordDnsRepairResult(false);
                        repairAttempted = false;
                        if (this.IsHandleCreated && !this.IsDisposed && !_isDisposing)
                        {
                            try
                            {
                                this.BeginInvoke((MethodInvoker)delegate
                                {
                                    if (_isDisposing || this.IsDisposed) return;
                                    ToastNotification.Show("DNS Engeli",
                                        "DNS yan\u0131t vermiyor. Onarmak i\u00e7in t\u0131klay\u0131n.",
                                        ToastType.Warning, 7000,
                                        delegate { try { OpenTroubleshooter(); } catch {} });
                                });
                            }
                            catch {}
                        }
                        return;
                    }

                    AppHealthMetrics.RecordDnsRepairResult(false);
                    repairAttempted = false;
                    AppLogger.Log("DNSGUARD", "Önbellek temizliği sonrası DNS sonucu belirsiz; düzeldiği varsayılmadı. " + (verifyError ?? ""), LogLevel.Warn);
                }
                catch (Exception ex)
                {
                    if (repairAttempted) AppHealthMetrics.RecordDnsRepairResult(false);
                    AppLogger.Log("DNSGUARD", "Sınırlı DNS denetimi başarısız: " + ex.Message, LogLevel.Warn);
                }
                finally
                {
                    _dnsGuardRunning = false;
                }
            });
            if (!queued)
            {
                _dnsGuardRunning = false;
                AppLogger.Log("DNSGUARD", "DNS doğrulama işi kuyruğa alınamadı; sonraki turda yeniden denenecek.", LogLevel.Warn);
            }
        }

        private int StopProtection()
        {
            // Niyet nesli artar: kuyruktaki yeniden başlatma işçileri iptal olur ("Durdur" ezilmez).
            lock (_engineSync)
            {
                int stopStamp = Interlocked.Increment(ref _engineOpStamp);
                StopProtectionCore();
                return stopStamp;
            }
        }

        private void StopProtectionCore()
        {
            _isManualStop = true;
            if (_isRunning) AppLogger.Log("UI", "Koruma durduruluyor...");
            _isRunning = false;
            lock (_dnsMeasurementSync)
            {
                _activeDnsIndex = -1;
                _pendingAutoDnsIndex = -1;
                _pendingAutoDnsConfirmations = 0;
                _activeDnsFailureStrikes = 0;
            }

            // Ping timer'ı UI thread'deki UpdateUIState() durdurur; burada çapraz-thread
            // timer erişimi yapılmaz (WinForms Timer UI thread'e bağlıdır).
            _pingMs = "--";

            try
            {
                if (_dpiProcess != null)
                {
                    _dpiProcess.EnableRaisingEvents = false;
                    try { _dpiProcess.CancelOutputRead(); } catch {}
                    try { _dpiProcess.CancelErrorRead(); } catch {}
                    if (!_dpiProcess.HasExited)
                    {
                        _dpiProcess.Kill();
                        _dpiProcess.WaitForExit(1000);
                    }
                    _dpiProcess.Dispose();
                    _dpiProcess = null;
                }
            }
            catch {}

            try { KillStrayDpiProcesses(); }
            catch {}

            DiscordVoiceGuard.RestoreVoiceProtection();
            DiscordMediaAccelerator.RestoreMediaAcceleration(false);

            FlushDnsFast();
            SyncUIStateSafe();
        }

        // Aynı adlı TÜM süreçleri körlemesine öldürmek yerine yalnızca GoodbyeDPI
        // kurulumlarından çalışan motor süreçleri hedeflenir; başka araçların aynı adlı
        // süreçleri korunur. Yol okunamazsa güvenli taraf seçilir: dokunulmaz.
        internal static bool IsOurDpiEngineProcess(Process p)
        {
            if (p == null) return false;
            try
            {
                string path = p.MainModule != null ? p.MainModule.FileName : null;
                if (!string.IsNullOrEmpty(path))
                {
                    string full = Path.GetFullPath(path);
                    string baseDir = Path.GetFullPath(AppDomain.CurrentDomain.BaseDirectory).TrimEnd('\\', '/');
                    // 1) Bu uygulamanın kök klasörü altındaki motor (klasör adı değişse bile yakalanır).
                    if (full.StartsWith(baseDir + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase)) return true;
                    // 2) Adresinde GoodbyeDPI geçen dizinlerden çalışan motorlar (taşınmış kurulumlar dahil).
                    string dir = Path.GetDirectoryName(full);
                    if (dir != null && dir.IndexOf("GoodbyeDPI", StringComparison.OrdinalIgnoreCase) >= 0) return true;
                }
            }
            catch
            {
                // MainModule okunamadıysa (erişim kısıtı/bitlik farkı), GoodbyeDPI sürecini sahiplen.
                try { return p.ProcessName.Equals("goodbyedpi", StringComparison.OrdinalIgnoreCase); } catch { return false; }
            }
            return false;
        }

        // "goodbyedpi" adlı süreçleri tarar; yalnızca bu uygulamanın/GoodbyeDPI klasörlerinin
        // motor süreçlerini kapatır ve kapatılan süreç sayısını döndürür.
        internal static int KillStrayDpiProcesses()
        {
            int killed = 0;
            string[] engineNames = new string[] { "goodbyedpi" };
            for (int k = 0; k < engineNames.Length; k++)
            {
                try
                {
                    Process[] procs = Process.GetProcessesByName(engineNames[k]);
                    for (int i = 0; i < procs.Length; i++)
                    {
                        Process p = procs[i];
                        try
                        {
                            if (IsOurDpiEngineProcess(p))
                            {
                                p.Kill();
                                p.WaitForExit(1000);
                                killed++;
                            }
                        }
                        catch {}
                        try { p.Dispose(); } catch {}
                    }
                }
                catch {}
            }
            return killed;
        }

        private static void RunNetsh(string arguments)
        {
            RunCommandDirect("netsh", arguments);
        }

        // Tüm aktif fiziksel ağ kartlarının DNS/MTU sıfırlamasını ve isteğe bağlı TCP global
        // ayarlarını 8-10 ayrı netsh.exe süreci açmak yerine TEK BİR netsh oturumunda toplu çalıştırır.
        private static void ResetPhysicalAdaptersAndTcpFast(bool includeTcpGlobal)
        {
            try
            {
                StringBuilder batch = new StringBuilder();
                NetworkInterface[] adapters = NetworkInterface.GetAllNetworkInterfaces();
                if (adapters != null)
                {
                    foreach (NetworkInterface adapter in adapters)
                    {
                        if (IsPhysicalNetworkAdapter(adapter))
                        {
                            // CR/LF ve tırnak temizliği: bağdaştırıcı adı netsh oturumuna satır olarak
                            // gömülür; satır sonu kaçışıyla ek komut enjeksiyonu engellenir.
                            string safeName = (adapter.Name ?? "").Replace("\"", "").Replace("\r", "").Replace("\n", "");
                            if (string.IsNullOrEmpty(safeName)) continue;
                            batch.AppendFormat("interface ipv4 set dns name=\"{0}\" dhcp\r\n", safeName);
                            batch.AppendFormat("interface ipv6 set dns name=\"{0}\" dhcp\r\n", safeName);
                            batch.AppendFormat("interface ipv4 set subinterface \"{0}\" mtu=1500 store=persistent\r\n", safeName);
                            batch.AppendFormat("interface ipv6 set subinterface \"{0}\" mtu=1500 store=persistent\r\n", safeName);
                        }
                    }
                }
                if (includeTcpGlobal)
                {
                    batch.AppendLine("int tcp set global autotuninglevel=normal");
                    batch.AppendLine("int tcp set global rss=enabled");
                    batch.AppendLine("int tcp set global fastopen=enabled");
                    batch.AppendLine("int tcp set heuristics default");
                }
                batch.AppendLine("exit");

                ProcessStartInfo psi = new ProcessStartInfo(SystemTool("netsh"));
                psi.UseShellExecute = false;
                psi.CreateNoWindow = true;
                psi.WindowStyle = ProcessWindowStyle.Hidden;
                psi.RedirectStandardInput = true;
                psi.RedirectStandardOutput = false;
                psi.RedirectStandardError = false;

                using (Process p = Process.Start(psi))
                {
                    if (p != null)
                    {
                        try
                        {
                            p.StandardInput.Write(batch.ToString());
                            p.StandardInput.Flush();
                            p.StandardInput.Close();
                        }
                        catch {}
                        if (!p.WaitForExit(6000))
                        {
                            try { p.Kill(); p.WaitForExit(1000); } catch {}
                        }
                    }
                }
            }
            catch {}
        }

        private static bool IsPhysicalNetworkAdapter(NetworkInterface adapter)
        {
            if (adapter == null) return false;
            if (adapter.OperationalStatus != OperationalStatus.Up) return false;
            if (adapter.NetworkInterfaceType != NetworkInterfaceType.Ethernet &&
                adapter.NetworkInterfaceType != NetworkInterfaceType.Wireless80211) return false;

            string desc = (adapter.Description ?? "").ToLowerInvariant();
            string name = (adapter.Name ?? "").ToLowerInvariant();

            if (desc.Contains("virtual") || desc.Contains("wsl") || desc.Contains("hyper-v") ||
                desc.Contains("vmware") || desc.Contains("tap-") || desc.Contains("loopback") ||
                desc.Contains("pseudo") || desc.Contains("wireguard") || desc.Contains("tailscale") ||
                desc.Contains("zerotier") || desc.Contains("vpn") || desc.Contains("npcap") ||
                desc.Contains("bluetooth") ||
                name.Contains("vethernet") || name.Contains("wsl") || name.Contains("loopback") ||
                name.Contains("vmnet") || name.Contains("tailscale") || name.Contains("wireguard"))
            {
                return false;
            }
            return true;
        }

        internal static void RunCommandDirect(string cmd, string args)
        {
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo(SystemTool(cmd), args);
                psi.UseShellExecute = false;
                psi.CreateNoWindow = true;
                psi.WindowStyle = ProcessWindowStyle.Hidden;
                using (Process p = Process.Start(psi))
                {
                    if (p != null && !p.WaitForExit(3000))
                    {
                        p.Kill();
                        p.WaitForExit(1000);
                    }
                }
            }
            catch {}
        }

        // Gecikme optimizasyonu çekirdeği: kayıt defteri gecikme ayarları + DNS önbelleği + rota ölçümü.
        // Tepsi menüsü ("Gecikmeyi optimize et") ve ana penceredeki birleşik optimizasyon butonu ortak kullanır.
        private void OptimizeLatencyDirect(out long avgPing, out string routeStatus, out string routeAdvice)
        {
            long minPing = -1;
            long maxPing = -1;
            long totalPing = 0;
            int successfulPings = 0;
            avgPing = -1;
            routeStatus = "Ping ölçülemedi.";
            routeAdvice = "Sunucuya ulaşılamadı ama ayarlar bilgisayarınıza sorunsuz uygulandı.";

            // Sihirbaz ve ana ekran arasında %100 tutarlı merkezi oyun ağı optimizasyonu:
            // MMCSS Games öncelikleri + NetworkThrottling kaldırma + DPC gecikmesi yapan
            // TcpAckFrequency/TCPNoDelay kayıtlarını temizleme + DefaultTTL=64 + DNS Flush
            OptimizeGamingNetworkDirect();

            // 5. Benchmark Frankfurt & European Core Latency (DE-CIX Voice / Game Hub)
            string[] testTargets = new string[] {
                "66.22.244.2",  // Discord Official Voice RTC Europe (Frankfurt)
                "80.81.192.82"  // DE-CIX Frankfurt Peering Core
            };

            using (Ping ping = new Ping())
            {
                for (int t = 0; t < testTargets.Length; t++)
                {
                    for (int s = 0; s < 3; s++)
                    {
                        try
                        {
                            PingReply reply = ping.Send(testTargets[t], 700);
                            if (reply != null && reply.Status == IPStatus.Success)
                            {
                                long rtt = reply.RoundtripTime;
                                if (minPing == -1 || rtt < minPing) minPing = rtt;
                                if (maxPing == -1 || rtt > maxPing) maxPing = rtt;
                                totalPing += rtt;
                                successfulPings++;
                            }
                        }
                        catch {}
                        Thread.Sleep(80);
                    }
                    if (successfulPings >= 3) break;
                }
            }

            if (successfulPings > 0)
            {
                avgPing = totalPing / successfulPings;
            }

            // 6. Evaluate Route & Latency
            if (avgPing > 0 && avgPing <= 55)
            {
                routeStatus = "Bağlantın oldukça iyi ve stabil.";
                routeAdvice = "Avrupa oyun sunucularına gecikmen ideal seviyede.";
            }
            else if (avgPing > 55 && avgPing <= 68)
            {
                routeStatus = "Pingin orta seviyede.";
                routeAdvice = "Modemi kapatıp 30 saniye sonra açarsan operatörün seni daha hızlı bir hatta bağlayabilir.";
            }
            else if (avgPing > 68)
            {
                routeStatus = "Gecikme biraz yüksek.";
                routeAdvice = "Wi-Fi yerine kablo kullanmak veya modemi yeniden başlatmak pingini düşürebilir.";
            }
        }

        // Tepsi menüsü "Gecikmeyi optimize et": yalnızca gecikme ayarları + rota ölçümü.
        private void BtnOptimizeGamingPing_Click(object sender, EventArgs e)
        {
            if (_isOperationRunning) return;
            _isOperationRunning = true;
            SetToolsEnabled(false);
            if (_btnOptimizeGamingPing != null) _btnOptimizeGamingPing.Text = "Optimize Ediliyor...";

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                string routeStatus = "";
                string routeAdvice = "";
                long avgPing = -1;

                try
                {
                    OptimizeLatencyDirect(out avgPing, out routeStatus, out routeAdvice);
                }
                catch {}
                finally
                {
                    _isOperationRunning = false;
                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed) return;
                                if (_btnOptimizeGamingPing != null && !_btnOptimizeGamingPing.IsDisposed) _btnOptimizeGamingPing.Text = "İnterneti optimize et";
                                SetToolsEnabled(true);
                                TriggerManualPing();

                                string pingSummary = (avgPing > 0)
                                    ? string.Format("• Ölçülen Gecikme: ~{0} ms ({1})\n\n", avgPing, routeStatus)
                                    : "";

                                string message = string.Format(
                                    "İnternet ve oyun bağlantınız optimize edildi!\n\n" +
                                    "{0}" +
                                    "• Bağlantı gecikmesini artıran kısıtlamalar kapatıldı.\n" +
                                    "• İnternet önbelleği temizlendi.",
                                    pingSummary
                                );

                                IWin32Window completedOwner = (this.Visible && !this.IsDisposed && this.WindowState != FormWindowState.Minimized) ? (IWin32Window)this : null;
                                MessageBox.Show(completedOwner, message, "İnternet Optimizasyonu", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            });
                        }
                        catch {}
                    }
                }
            });
        }

