        private void BtnRepairNetworkAndDiscord_Click(object sender, EventArgs e)
        {
            if (_isOperationRunning) return;
            bool wasRunning = _isRunning; // onarım öncesi koruma durumu: bitişte otomatik geri getirilir

            IWin32Window owner = (this.Visible && !this.IsDisposed && this.WindowState != FormWindowState.Minimized) ? (IWin32Window)this : null;
            DialogResult dr = MessageBox.Show(
                owner,
                "Bağlantı ve Discord sorunlarını çözmek için şu işlemler yapılacak:\n\n" +
                "• Koruma servisi yenilenir.\n" +
                "• Discord ve Roblox'un bozuk önbellek dosyaları temizlenir (hesabınızdan çıkış yapılmaz).\n" +
                "• Ağ ve DNS ayarlarınız varsayılan haline döndürülür.\n\n" +
                "Başlatmak istiyor musunuz?",
                "Ağ ve Discord'u Onar",
                MessageBoxButtons.YesNo,
                MessageBoxIcon.Question
            );

            if (dr != DialogResult.Yes) return;

            _isOperationRunning = true;
            SetToolsEnabled(false);
            if (_btnRepairNetworkAndDiscord != null) _btnRepairNetworkAndDiscord.Text = "Onarılıyor...";

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                int deletedFiles = 0;
                long freedBytes = 0;

                try
                {
                    // 1. Stop active DPI protection
                    StopProtection();

                    // 2. Kill orphan goodbyedpi processes & old WinDivert services
                    try { KillStrayDpiProcesses(); }
                    catch {}

                    // 2b. Yalnızca uygulamanın paket sürücüsüne ait WinDivert hizmetini onar/temizle.
                    CleanWinDivertDriverServices();
                    try { WindowsSecurityHelper.AddDefenderExclusion(AppDomain.CurrentDomain.BaseDirectory); } catch {}
                    DiscordMediaAccelerator.RestoreMediaAcceleration(true);

                    // 3. Terminate running Discord processes to release file locks
                    string[] procNames = new string[] { "Discord", "DiscordCanary", "DiscordPTB" };
                    foreach (string name in procNames)
                    {
                        Process[] procs = Process.GetProcessesByName(name);
                        if (procs != null)
                        {
                            foreach (Process p in procs)
                            {
                                try { p.Kill(); p.WaitForExit(1000); }
                                catch {}
                                try { p.Dispose(); } catch {}
                            }
                        }
                    }
                    Thread.Sleep(300);

                    // 4. Clean Roblox stuck processes & corrupted temp cache
                    try { WhitelistHelper.CleanRobloxCacheAndProcesses(); } catch {}

                    // 5. Clean Discord targeted cache folders (Preserving Local Storage & Cookies)
                    string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
                    string[] discordDirs = new string[] {
                        Path.Combine(appData, "discord"),
                        Path.Combine(appData, "discordcanary"),
                        Path.Combine(appData, "discordptb")
                    };

                    // Network klasörü içindeki Cookies ve Network Persistent State (QUIC broken_alternative_services)
                    // KORUNUR; böylece hem oturum çerezleri silinmez hem de Discord'un bozuk QUIC kaydı sıfırlanmaz.
                    string[] targetCacheFolders = new string[] {
                        "Cache",
                        "Code Cache",
                        "GPUCache",
                        "DawnCache",
                        "blob_storage",
                        "Network Action Predictor Databases"
                    };

                    foreach (string dDir in discordDirs)
                    {
                        if (!Directory.Exists(dDir)) continue;

                        foreach (string cacheName in targetCacheFolders)
                        {
                            string targetPath = Path.Combine(dDir, cacheName);
                            if (Directory.Exists(targetPath))
                            {
                                try
                                {
                                    DirectoryInfo di = new DirectoryInfo(targetPath);
                                    foreach (FileInfo fi in di.GetFiles("*", SearchOption.AllDirectories))
                                    {
                                        try
                                        {
                                            long len = fi.Length;
                                            fi.Attributes = FileAttributes.Normal;
                                            fi.Delete();
                                            freedBytes += len;
                                            deletedFiles++;
                                        }
                                        catch {}
                                    }
                                    foreach (DirectoryInfo sub in di.GetDirectories("*", SearchOption.AllDirectories))
                                    {
                                        try { sub.Delete(true); } catch {}
                                    }
                                }
                                catch {}
                            }
                        }
                    }

                    // 5. Reset all active physical network interfaces, multimedia throttling, and TCP defaults in a single batched netsh session
                    RestoreWindowsNetworkDefaultsAndResetAdapters();

                    // 6. Fast DNS Flush
                    FlushDnsFast();

                    AppLogger.Log("REPAIR", string.Format("Ağ ve Discord onarıldı: {0} dosya silindi, {1:F1} MB alan kazanıldı, ağ ve DNS yenilendi.", deletedFiles, (double)freedBytes / (1024 * 1024)));
                }
                catch (Exception ex)
                {
                    AppLogger.Log("ERROR", "Ağ ve Discord onarım hatası: " + ex.Message);
                }
                finally
                {
                    _isOperationRunning = false;
                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed) return;
                                SetToolsEnabled(true);
                                if (_btnRepairNetworkAndDiscord != null && !_btnRepairNetworkAndDiscord.IsDisposed) _btnRepairNetworkAndDiscord.Text = "Ağ ve Discord'u onar";
                                UpdateUIState();
                                // Koruma onarım öncesinde çalışıyorduysa otomatik geri getir.
                                if (wasRunning && !_isRunning)
                                {
                                    StartProtection();
                                }
                                TriggerManualPing();

                                double mbFreed = (double)freedBytes / (1024 * 1024);
                                string msg = string.Format(
                                    "Onarım tamamlandı!\n\n" +
                                    "• {0} adet bozuk önbellek dosyası temizlendi ({1:F1} MB).\n" +
                                    "• Ağ ve DNS ayarlarınız yenilendi.\n" +
                                    "• Discord oturumunuz korundu.\n\n" +
                                    "Discord'u şimdi açmak ister misiniz?",
                                    deletedFiles,
                                    mbFreed
                                );

                                IWin32Window completedOwner = (this.Visible && !this.IsDisposed && this.WindowState != FormWindowState.Minimized) ? (IWin32Window)this : null;
                                DialogResult launchDr = MessageBox.Show(completedOwner, msg, "Onarım Tamamlandı", MessageBoxButtons.YesNo, MessageBoxIcon.Information);
                                if (launchDr == DialogResult.Yes)
                                {
                                    BtnLaunchDiscord_Click(null, null);
                                }
                            });
                        }
                        catch {}
                    }
                }
            });
        }

        // Fiziksel ağ bağdaştırıcılarını (DHCP + MTU 1500), MMCSS zamanlayıcısını ve TCP yığınını
        // tek bir toplu netsh oturumuyla varsayılanlara döndürür (8-10 ayrı süreç açılmasını önler).
        private static void RestoreWindowsNetworkDefaultsAndResetAdapters()
        {
            ClearVerifiedOverrideTemplate();
            InvalidateGatewayFingerprintCache();
            RestoreTcpStackFromBackup();
            ResetPhysicalAdaptersAndTcpFast(includeTcpGlobal: true);

            try
            {
                using (RegistryKey key = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile", true))
                {
                    if (key != null)
                    {
                        key.SetValue("NetworkThrottlingIndex", 10, RegistryValueKind.DWord);
                        key.SetValue("SystemResponsiveness", 20, RegistryValueKind.DWord);
                    }
                }
            }
            catch {}

            try
            {
                using (RegistryKey gamesKey = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games", true))
                {
                    if (gamesKey != null)
                    {
                        gamesKey.SetValue("GPU Priority", 8, RegistryValueKind.DWord);
                        gamesKey.SetValue("Priority", 2, RegistryValueKind.DWord);
                        gamesKey.SetValue("Scheduling Category", "Medium", RegistryValueKind.String);
                        gamesKey.SetValue("SFIO Priority", "Normal", RegistryValueKind.String);
                    }
                }
            }
            catch {}

            try
            {
                using (RegistryKey interfacesKey = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces", true))
                {
                    if (interfacesKey != null)
                    {
                        string[] subkeys = interfacesKey.GetSubKeyNames();
                        foreach (string sub in subkeys)
                        {
                            try
                            {
                                using (RegistryKey iface = interfacesKey.OpenSubKey(sub, true))
                                {
                                    if (iface != null)
                                    {
                                        try { iface.DeleteValue("TcpAckFrequency", false); } catch {}
                                        try { iface.DeleteValue("TCPNoDelay", false); } catch {}
                                    }
                                }
                            }
                            catch {}
                        }
                    }
                }
            }
            catch {}
        }

        private void BtnOptimizeHardware_Click(object sender, EventArgs e)
        {
            if (_isOperationRunning) return;

            IWin32Window owner = (this.Visible && !this.IsDisposed && this.WindowState != FormWindowState.Minimized) ? (IWin32Window)this : null;
            DialogResult dr = MessageBox.Show(
                owner,
                "Ağ kartınızın güç tasarrufu ve uyku modları kapatılarak oyun ve ses gecikmesi düşürülecek.\n\n" +
                "Devam etmek istiyor musunuz?",
                "Ağ Kartı Optimizasyonu",
                MessageBoxButtons.YesNo,
                MessageBoxIcon.Question
            );

            if (dr != DialogResult.Yes) return;

            _isOperationRunning = true;
            SetToolsEnabled(false);
            if (_btnOptimizeHardware != null) _btnOptimizeHardware.Text = "Optimize Ediliyor...";

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                int modified = 0;
                try
                {
                    modified = OptimizeNetworkHardwareDirect();
                    AppLogger.Log("HW_OPTIMIZE", "Ağ donanımı optimizasyonu uygulandı: " + modified + " ayar güncellendi.");
                }
                catch (Exception ex)
                {
                    AppLogger.Log("ERROR", "Ağ Optimizasyonu hatası: " + ex.Message);
                }
                finally
                {
                    _isOperationRunning = false;
                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed) return;
                                SetToolsEnabled(true);
                                if (_btnOptimizeHardware != null && !_btnOptimizeHardware.IsDisposed) _btnOptimizeHardware.Text = "Ağ Optimizasyonu";
                                UpdateUIState();
                                TriggerManualPing();

                                string message;
                                if (modified > 0)
                                {
                                    message = string.Format(
                                        "Ağ kartınız optimize edildi!\n\n" +
                                        "• Güç tasarrufu ve uyku gecikmeleri kapatıldı ({0} ayar güncellendi).\n" +
                                        "• Ağ kartınız artık daha düşük gecikmeyle çalışacak.",
                                        modified);
                                }
                                else
                                {
                                    message = "Ağ kartı ayarlarınız zaten en iyi durumda.";
                                }

                                IWin32Window completedOwner = (this.Visible && !this.IsDisposed && this.WindowState != FormWindowState.Minimized) ? (IWin32Window)this : null;
                                MessageBox.Show(completedOwner, message, "Ağ Kartı Optimizasyonu", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            });
                        }
                        catch {}
                    }
                }
            });
        }

        public static int OptimizeNetworkHardwareDirect()
        {
            int modifiedCount = 0;
            try
            {
                RegistryKey baseKey = null;
                try
                {
                    if (Environment.Is64BitOperatingSystem)
                    {
                        baseKey = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry64);
                    }
                    else
                    {
                        baseKey = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Default);
                    }
                }
                catch
                {
                    // Paylaşılan Registry.LocalMachine örneği ASLA using ile dispose edilmemeli:
                    // süreç genelinde paylaşılır, kapatılırsa diğer çağrılar ObjectDisposedException alır.
                    baseKey = RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Default);
                }

                using (baseKey)
                using (RegistryKey classKey = baseKey.OpenSubKey(@"SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}", true))
                {
                    if (classKey != null)
                    {
                        string[] subNames = classKey.GetSubKeyNames();
                        foreach (string sub in subNames)
                        {
                            if (sub.Length != 4) continue;
                            try
                            {
                                using (RegistryKey adapterKey = classKey.OpenSubKey(sub, true))
                                {
                                    if (adapterKey == null) continue;
                                    object netCfg = adapterKey.GetValue("NetCfgInstanceId");
                                    object driverDesc = adapterKey.GetValue("DriverDesc");
                                    if (netCfg == null || driverDesc == null) continue;

                                    // Filter virtual miniports (NCF_PHYSICAL flag = 0x4)
                                    object charObj = adapterKey.GetValue("Characteristics");
                                    if (charObj != null)
                                    {
                                        try
                                        {
                                            int characteristics = Convert.ToInt32(charObj);
                                            if ((characteristics & 0x4) == 0) continue;
                                        }
                                        catch {}
                                    }

                                    string descLower = driverDesc.ToString().ToLowerInvariant();
                                    if (descLower.Contains("wan miniport") || descLower.Contains("kernel debug") ||
                                        descLower.Contains("virtual") || descLower.Contains("wsl") ||
                                        descLower.Contains("hyper-v") || descLower.Contains("vmware") ||
                                        descLower.Contains("tap-") || descLower.Contains("loopback") ||
                                        descLower.Contains("pseudo") || descLower.Contains("wireguard") ||
                                        descLower.Contains("tailscale") || descLower.Contains("zerotier") ||
                                        descLower.Contains("vpn") || descLower.Contains("npcap") ||
                                        descLower.Contains("bluetooth"))
                                    {
                                        continue;
                                    }

                                    string[] keywordsToZero = new string[] {
                                        "*EEE", "AdvancedEEE", "EnableGreenEthernet", "GigaLite",
                                        "AutoDisableGigabit", "PowerSavingMode", "*InterruptModeration",
                                        "EEELinkAdvertisement", "EnergyEfficientEthernet", "ReduceSpeedOnPowerDown",
                                        "SystemIdlePowerSaver", "SavePowerNowEnabled", "AutoPowerSaveModeV2",
                                        "UltraLowPowerMode", "WakeOnLink", "*FlowControl"
                                    };

                                    bool adapterModified = false;
                                    foreach (string kw in keywordsToZero)
                                    {
                                        try
                                        {
                                            object curVal = adapterKey.GetValue(kw);
                                            if (curVal != null && curVal.ToString() != "0")
                                            {
                                                adapterKey.SetValue(kw, "0", RegistryValueKind.String);
                                                adapterModified = true;
                                            }
                                        }
                                        catch {}
                                    }

                                    try
                                    {
                                        object pnp = adapterKey.GetValue("PnPCapabilities");
                                        if (pnp == null || Convert.ToInt32(pnp) != 24)
                                        {
                                            adapterKey.SetValue("PnPCapabilities", 24, RegistryValueKind.DWord);
                                            adapterModified = true;
                                        }
                                    }
                                    catch {}

                                    if (adapterModified) modifiedCount++;
                                }
                            }
                            catch {}
                        }
                    }
                }
            }
            catch {}

            return modifiedCount;
        }

        private void BtnResetNetwork_Click(object sender, EventArgs e)
        {
            if (_isOperationRunning) return;
            _isOperationRunning = true;
            SetToolsEnabled(false);

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    StopProtection();

                    NetworkInterface[] adapters = NetworkInterface.GetAllNetworkInterfaces();
                    foreach (NetworkInterface adapter in adapters)
                    {
                        if (IsPhysicalNetworkAdapter(adapter))
                        {
                            string safeName = (adapter.Name ?? "").Replace("\"", "").Replace("\r", "").Replace("\n", "");
                            RunNetsh(string.Format("interface ipv4 set dns name=\"{0}\" dhcp", safeName));
                            RunNetsh(string.Format("interface ipv6 set dns name=\"{0}\" dhcp", safeName));
                            RunNetsh(string.Format("interface ipv4 set subinterface \"{0}\" mtu=1500 store=persistent", safeName));
                            RunNetsh(string.Format("interface ipv6 set subinterface \"{0}\" mtu=1500 store=persistent", safeName));
                        }
                    }

                    // Restore default Windows Multimedia Network Throttling
                    try
                    {
                        using (RegistryKey key = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile", true))
                        {
                            if (key != null)
                            {
                                key.SetValue("NetworkThrottlingIndex", 10, RegistryValueKind.DWord);
                                key.SetValue("SystemResponsiveness", 20, RegistryValueKind.DWord);
                            }
                        }
                    }
                    catch {}

                    // Restore Tasks\Games priority to Windows defaults
                    try
                    {
                        using (RegistryKey gamesKey = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games", true))
                        {
                            if (gamesKey != null)
                            {
                                gamesKey.SetValue("GPU Priority", 8, RegistryValueKind.DWord);
                                gamesKey.SetValue("Priority", 2, RegistryValueKind.DWord);
                                gamesKey.SetValue("Scheduling Category", "Medium", RegistryValueKind.String);
                                gamesKey.SetValue("SFIO Priority", "Normal", RegistryValueKind.String);
                            }
                        }
                    }
                    catch {}

                    // Remove interface TCP latency overrides
                    try
                    {
                        using (RegistryKey interfacesKey = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces", true))
                        {
                            if (interfacesKey != null)
                            {
                                string[] subkeys = interfacesKey.GetSubKeyNames();
                                foreach (string sub in subkeys)
                                {
                                    try
                                    {
                                        using (RegistryKey iface = interfacesKey.OpenSubKey(sub, true))
                                        {
                                            if (iface != null)
                                            {
                                                try { iface.DeleteValue("TcpAckFrequency", false); } catch {}
                                                try { iface.DeleteValue("TCPNoDelay", false); } catch {}
                                            }
                                        }
                                    }
                                    catch {}
                                }
                            }
                        }
                    }
                    catch {}

                    RunNetsh("int tcp set global autotuninglevel=normal");
                    RunNetsh("int tcp set heuristics default");

                    FlushDnsFast();
                }
                catch {}
                finally
                {
                    _isOperationRunning = false;
                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed) return;
                                SetToolsEnabled(true);
                                UpdateUIState();
                                TriggerManualPing();

                                if (!_isDisposing)
                                {
                                    ToastNotification.Show("A\u011f S\u0131f\u0131rland\u0131", "DNS ve \u00f6nbellek temizlendi.", ToastType.Success, 3000);
                                }
                            });
                        }
                        catch {}
                    }
                }
            });
        }

