        private void CleanOldLegacyGoodbyeDpi()
        {
            if (_isOperationRunning) return;
            _isOperationRunning = true;
            SetToolsEnabled(false);

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    StopProtection();

                    // 1. Kill orphan goodbyedpi processes (yalnızca bizim/GoodbyeDPI kurulumlarının)
                    KillStrayDpiProcesses();

                    // 2. Remove legacy registry startup entries
                    string[] legacyRegNames = new string[] {
                        "GoodbyeDPI", "goodbyedpi", "GoodbyeDPI Turkey", "GoodbyeDPI_Turkey", "GoodbyeDPI-Turkey", "GoodbyeDPI_Turkey_GUI"
                    };

                    try
                    {
                        using (RegistryKey key = Registry.CurrentUser.OpenSubKey(RunRegistryKey, true))
                        {
                            if (key != null)
                            {
                                foreach (string name in legacyRegNames)
                                {
                                    try { key.DeleteValue(name, false); } catch {}
                                }
                            }
                        }
                    }
                    catch {}

                    try
                    {
                        using (RegistryKey key = Registry.LocalMachine.OpenSubKey(RunRegistryKey, true))
                        {
                            if (key != null)
                            {
                                foreach (string name in legacyRegNames)
                                {
                                    try { key.DeleteValue(name, false); } catch {}
                                }
                            }
                        }
                    }
                    catch {}

                    // 3b. Eski zamanlanmış görev kalıntıları: çıktı metniyle tutarlı olarak
                    // gerçekten silinir (eskiden mesaj görevlerin kaldırıldığını söylüyordu
                    // ama hiçbir silme çağrısı yoktu).
                    string[] legacyTaskNames = new string[] { "GoodbyeDPI", "GoodbyeDPI Turkey", "GoodbyeDPI_Turkey", "GoodbyeDPI-Turkey", "GoodbyeDPI_Turkey_GUI" };
                    for (int ti = 0; ti < legacyTaskNames.Length; ti++)
                    {
                        RunCommandGetExit("schtasks", "/delete /tn \"" + legacyTaskNames[ti] + "\" /f");
                    }

                    // 4. Eski Windows hizmetlerini kaldır (varsa) — çıktı metniyle tutarlı hale getirildi
                    RemoveLegacyServiceIfExists("GoodbyeDPI");
                    CleanWinDivertDriverServices(); // Yalnızca bu uygulamanın paket sürücüsüne ait hizmetler temizlenir.
                    DiscordMediaAccelerator.RestoreMediaAcceleration(true);

                    // 5. Reset all active physical network interfaces DNS to DHCP
                    NetworkInterface[] adapters = NetworkInterface.GetAllNetworkInterfaces();
                    foreach (NetworkInterface adapter in adapters)
                    {
                        if (IsPhysicalNetworkAdapter(adapter))
                        {
                            string safeName = (adapter.Name ?? "").Replace("\"", "").Replace("\r", "").Replace("\n", "");
                            RunNetsh(string.Format("interface ipv4 set dns name=\"{0}\" dhcp", safeName));
                            RunNetsh(string.Format("interface ipv6 set dns name=\"{0}\" dhcp", safeName));
                            RunNetsh(string.Format("interface ipv4 set subinterface \"{0}\" mtu=1500 store=persistent", safeName));
                            RunNetsh(string.Format("interface ipv6 set subinterface \"{0}\" mtu=1500 store=persistent", safeName));
                        }
                    }

                    // 6. Restore default Windows Multimedia Network Throttling & Gaming Tasks
                    try
                    {
                        using (RegistryKey key = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile", true))
                        {
                            if (key != null)
                            {
                                key.SetValue("NetworkThrottlingIndex", 10, RegistryValueKind.DWord);
                                key.SetValue("SystemResponsiveness", 20, RegistryValueKind.DWord);
                            }
                        }
                    }
                    catch {}

                    try
                    {
                        using (RegistryKey gamesKey = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games", true))
                        {
                            if (gamesKey != null)
                            {
                                gamesKey.SetValue("GPU Priority", 8, RegistryValueKind.DWord);
                                gamesKey.SetValue("Priority", 2, RegistryValueKind.DWord);
                                gamesKey.SetValue("Scheduling Category", "Medium", RegistryValueKind.String);
                                gamesKey.SetValue("SFIO Priority", "Normal", RegistryValueKind.String);
                            }
                        }
                    }
                    catch {}

                    RunNetsh("int tcp set global autotuninglevel=normal");
                    RunNetsh("int tcp set heuristics default");

                    // 7. Flush DNS cache
                    FlushDnsFast();
                }
                catch {}
                finally
                {
                    _isOperationRunning = false;
                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed) return;
                                SetToolsEnabled(true);
                                UpdateUIState();
                                TriggerManualPing();

                                MessageBox.Show(
                                    this,
                                    "Eski sürüm kalıntıları temizlendi!\n\n" +
                                    "• Eski servisler ve başlangıç kayıtları kaldırıldı.\n" +
                                    "• Ağ ve DNS ayarlarınız varsayılan haline döndürüldü.",
                                    "Temizleme Tamamlandı",
                                    MessageBoxButtons.OK,
                                    MessageBoxIcon.Information
                                );
                            });
                        }
                        catch {}
                    }
                }
            });
        }

        private bool _discordBusy = false;

        private void BtnLaunchDiscord_Click(object sender, EventArgs e)
        {
            // Re-entrancy koruması: çift tıklama veya onarım sonrası otomatik çağrı,
            // aynı anda ikinci bir Discord başlatma zincirini tetiklemesin.
            if (_discordBusy) return;
            _discordBusy = true;
            try
            {
                BtnLaunchDiscordCore(sender, e);
            }
            finally
            {
                _discordBusy = false;
            }
        }

        private void BtnLaunchDiscordCore(object sender, EventArgs e)
        {
            try
            {
                // 1. If Discord is already running
                Process[] stuckDiscords = Process.GetProcessesByName("Discord");
                try
                {
                    if (stuckDiscords != null && stuckDiscords.Length > 0)
                    {
                        bool hasActiveWindow = false;
                        foreach (Process p in stuckDiscords)
                        {
                            if (p.MainWindowHandle != IntPtr.Zero)
                            {
                                hasActiveWindow = true;
                                break;
                            }
                        }

                        if (hasActiveWindow)
                        {
                            DialogResult dr = MessageBox.Show(this,
                                "Discord şu anda açık görünüyor.\n\n" +
                                "Bağlanamıyor veya güncelleme ekranında takılıyorsa kapatıp temiz şekilde yeniden başlatmak ister misiniz?\n\n" +
                                "• Evet: Kapat ve yeniden başlat (Önerilen)\n" +
                                "• Hayır: Olduğu gibi bırak",
                                "Discord Başlatıcı",
                                MessageBoxButtons.YesNo,
                                MessageBoxIcon.Question);

                            if (dr == DialogResult.Yes)
                            {
                                for (int i = 0; i < stuckDiscords.Length; i++)
                                {
                                    try { stuckDiscords[i].Kill(); stuckDiscords[i].WaitForExit(800); }
                                    catch {}
                                }
                                Thread.Sleep(300);
                            }
                            else
                            {
                                bool brought = false;
                                foreach (Process p in stuckDiscords)
                                {
                                    if (p.MainWindowHandle != IntPtr.Zero)
                                    {
                                        brought = true;
                                        break;
                                    }
                                }
                                if (brought) return;
                            }
                        }
                        else
                        {
                            // Sadece arka planda asılı kalmış süreçler var, temizle
                            for (int i = 0; i < stuckDiscords.Length; i++)
                            {
                                try { stuckDiscords[i].Kill(); stuckDiscords[i].WaitForExit(500); }
                                catch {}
                            }
                            Thread.Sleep(200);
                        }
                    }
                }
                finally
                {
                    if (stuckDiscords != null)
                    {
                        for (int i = 0; i < stuckDiscords.Length; i++)
                        {
                            try { if (stuckDiscords[i] != null) stuckDiscords[i].Dispose(); } catch {}
                        }
                    }
                }
                FlushDnsFast();

                string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                string discordFolder = Path.Combine(localAppData, "Discord");

                // 1. Check official updater launcher (Recommended by Discord)
                // --disable-quic parametresi ile Chromium'un UDP 443 QUIC zaman aşımında takılması
                // motor seviyesinde de engellenir; resim, video ve yayın önizlemeleri doğrudan TCP/TLS kullanır.
                string updateExe = Path.Combine(discordFolder, "Update.exe");
                if (File.Exists(updateExe))
                {
                    ProcessStartInfo psi = new ProcessStartInfo();
                    psi.FileName = updateExe;
                    psi.Arguments = "--processStart Discord.exe --process-start-args \"--disable-quic\"";
                    psi.WorkingDirectory = discordFolder;
                    using (Process discProc = Process.Start(psi)) { }
                    return;
                }

                // 2. Direct app-* search with date-modified sorting (avoids alphabetical 99 vs 100 bug)
                if (Directory.Exists(discordFolder))
                {
                    string[] subDirs = Directory.GetDirectories(discordFolder, "app-*");
                    if (subDirs.Length > 0)
                    {
                        Array.Sort(subDirs, (a, b) => Directory.GetLastWriteTime(a).CompareTo(Directory.GetLastWriteTime(b)));
                        string directExe = Path.Combine(subDirs[subDirs.Length - 1], "Discord.exe");
                        if (File.Exists(directExe))
                        {
                            using (Process discProc = Process.Start(directExe, "--disable-quic")) { }
                            return;
                        }
                    }
                }

                // 3. Check Discord Canary
                string canaryFolder = Path.Combine(localAppData, "DiscordCanary");
                string canaryUpdate = Path.Combine(canaryFolder, "Update.exe");
                if (File.Exists(canaryUpdate))
                {
                    using (Process discProc = Process.Start(canaryUpdate, "--processStart DiscordCanary.exe --process-start-args \"--disable-quic\"")) { }
                    return;
                }

                // 4. Check Discord PTB
                string ptbFolder = Path.Combine(localAppData, "DiscordPTB");
                string ptbUpdate = Path.Combine(ptbFolder, "Update.exe");
                if (File.Exists(ptbUpdate))
                {
                    using (Process discProc = Process.Start(ptbUpdate, "--processStart DiscordPTB.exe --process-start-args \"--disable-quic\"")) { }
                    return;
                }

                // 5. Check desktop shortcut
                string desktopLnk = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory), "Discord.lnk");
                if (File.Exists(desktopLnk))
                {
                    using (Process discProc = Process.Start(desktopLnk)) { }
                    return;
                }

                // 6. Check Start Menu Programs (Common Windows location)
                string startMenuProg = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs), "Discord Inc", "Discord.lnk");
                if (File.Exists(startMenuProg))
                {
                    using (Process discProc = Process.Start(startMenuProg)) { }
                    return;
                }
                string commonProg = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonPrograms), "Discord Inc", "Discord.lnk");
                if (File.Exists(commonProg))
                {
                    using (Process discProc = Process.Start(commonProg)) { }
                    return;
                }
            }
            catch {}

            MessageBox.Show("Discord yükleme konumu otomatik bulunamadı.\nLütfen masaüstünüzdeki Discord kısayolundan başlatın.", "Bilgi", MessageBoxButtons.OK, MessageBoxIcon.Information);
        }

        private void BtnCleanDiscordCache_Click(object sender, EventArgs e)
        {
            if (_isOperationRunning) return;

            DialogResult dr = MessageBox.Show(
                "Discord'un bozuk görüntü ve bağlantı önbelleği temizlenecek.\n\n" +
                "• Hesabınızdan çıkış yapılmaz (tekrar şifre girmeniz gerekmez).\n" +
                "• Açık Discord pencereleri kapatılıp yenilenir.\n\n" +
                "Devam etmek istiyor musunuz?",
                "Discord Önbellek Temizleme",
                MessageBoxButtons.YesNo,
                MessageBoxIcon.Question
            );

            if (dr != DialogResult.Yes) return;

            _isOperationRunning = true;
            SetToolsEnabled(false);
            if (_btnRepairNetworkAndDiscord != null) _btnRepairNetworkAndDiscord.Text = "Temizleniyor...";

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                int deletedFiles = 0;
                long freedBytes = 0;

                try
                {
                    // 1. Terminate running Discord processes to release file locks
                    string[] procNames = new string[] { "Discord", "DiscordCanary", "DiscordPTB" };
                    foreach (string name in procNames)
                    {
                        Process[] procs = Process.GetProcessesByName(name);
                        if (procs != null)
                        {
                            foreach (Process p in procs)
                            {
                                try { p.Kill(); p.WaitForExit(1000); }
                                catch {}
                                try { p.Dispose(); } catch {}
                            }
                        }
                    }
                    Thread.Sleep(300); // Allow OS to release NTFS file locks

                    // 2. Identify Discord user data paths
                    string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
                    string[] discordDirs = new string[] {
                        Path.Combine(appData, "discord"),
                        Path.Combine(appData, "discordcanary"),
                        Path.Combine(appData, "discordptb")
                    };

                    // Strictly targeted cache folders (NEVER touch Local Storage or Cookies)
                    string[] targetCacheFolders = new string[] {
                        "Cache",
                        "Code Cache",
                        "GPUCache",
                        "DawnCache",
                        "blob_storage"
                    };

                    foreach (string dDir in discordDirs)
                    {
                        if (!Directory.Exists(dDir)) continue;

                        foreach (string cacheName in targetCacheFolders)
                        {
                            string targetPath = Path.Combine(dDir, cacheName);
                            if (Directory.Exists(targetPath))
                            {
                                try
                                {
                                    DirectoryInfo di = new DirectoryInfo(targetPath);
                                    foreach (FileInfo fi in di.GetFiles("*", SearchOption.AllDirectories))
                                    {
                                        try
                                        {
                                            long len = fi.Length;
                                            fi.Attributes = FileAttributes.Normal;
                                            fi.Delete();
                                            freedBytes += len;
                                            deletedFiles++;
                                        }
                                        catch {}
                                    }
                                    foreach (DirectoryInfo sub in di.GetDirectories("*", SearchOption.AllDirectories))
                                    {
                                        try { sub.Delete(true); } catch {}
                                    }
                                }
                                catch {}
                            }
                        }
                    }

                    // 3. Fast DNS Flush
                    FlushDnsFast();

                    AppLogger.Log("DISCORD", string.Format("Önbellek temizlendi: {0} dosya silindi, {1:F1} MB alan kazanıldı.", deletedFiles, (double)freedBytes / (1024 * 1024)));
                }
                catch (Exception ex)
                {
                    AppLogger.Log("ERROR", "Discord önbellek temizleme hatası: " + ex.Message);
                }
                finally
                {
                    _isOperationRunning = false;
                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed) return;
                                SetToolsEnabled(true);
                                if (_btnRepairNetworkAndDiscord != null && !_btnRepairNetworkAndDiscord.IsDisposed) _btnRepairNetworkAndDiscord.Text = "Ağ ve Discord'u onar";

                                double mbFreed = (double)freedBytes / (1024 * 1024);
                                string msg = string.Format(
                                    "Discord önbelleği temizlendi!\n\n" +
                                    "• {0} adet geçici dosya silindi ({1:F1} MB).\n" +
                                    "• Hesabınız ve oturumunuz korundu.\n\n" +
                                    "Discord'u şimdi açmak ister misiniz?",
                                    deletedFiles,
                                    mbFreed
                                );

                                DialogResult launchDr = MessageBox.Show(this, msg, "Önbellek Temizliği Tamamlandı", MessageBoxButtons.YesNo, MessageBoxIcon.Information);
                                if (launchDr == DialogResult.Yes)
                                {
                                    BtnLaunchDiscord_Click(null, null);
                                }
                            });
                        }
                        catch {}
                    }
                }
            });
        }

