        private static void EnsureWhitelistFile(string path)
        {
            try
            {
                if (!File.Exists(path) || new FileInfo(path).Length == 0)
                {
                    File.WriteAllLines(path, DefaultDiscordDomains, new UTF8Encoding(false));
                    return;
                }

                HashSet<string> existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                string[] lines = File.ReadAllLines(path);
                for (int i = 0; i < lines.Length; i++)
                {
                    string t = lines[i].Trim();
                    if (!string.IsNullOrEmpty(t)) existing.Add(t);
                }

                List<string> toAppend = new List<string>();
                for (int i = 0; i < DefaultDiscordDomains.Length; i++)
                {
                    if (!existing.Contains(DefaultDiscordDomains[i]))
                    {
                        toAppend.Add(DefaultDiscordDomains[i]);
                    }
                }

                if (toAppend.Count > 0)
                {
                    File.AppendAllLines(path, toAppend.ToArray(), new UTF8Encoding(false));
                }
            }
            catch {}
        }

