        private void ChkAutoStart_CheckedChanged(object sender, EventArgs e)
        {
            try
            {
                string exePath = Application.ExecutablePath;
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(RunRegistryKey, true))
                {
                    if (key != null)
                    {
                        if (_chkAutoStart.Checked)
                        {
                            key.SetValue(AppRegistryName, "\"" + exePath + "\" --minimized");
                            try { key.DeleteValue(LegacyAppRegistryName, false); } catch {}
                        }
                        else
                        {
                            key.DeleteValue(AppRegistryName, false);
                            try { key.DeleteValue(LegacyAppRegistryName, false); } catch {}
                        }
                    }
                }
            }
            catch {}
        }

        private void EnsureAutoStartPathSync()
        {
            try
            {
                if (_chkAutoStart != null && _chkAutoStart.Checked)
                {
                    string exePath = Application.ExecutablePath;
                    string expectedVal = "\"" + exePath + "\" --minimized";
                    using (RegistryKey key = Registry.CurrentUser.OpenSubKey(RunRegistryKey, true))
                    {
                        if (key != null)
                        {
                            object val = key.GetValue(AppRegistryName) ?? key.GetValue(LegacyAppRegistryName);
                            if (val != null)
                            {
                                string registered = val.ToString().Trim();
                                if (!string.Equals(registered, expectedVal, StringComparison.OrdinalIgnoreCase))
                                {
                                    key.SetValue(AppRegistryName, expectedVal);
                                    try { key.DeleteValue(LegacyAppRegistryName, false); } catch {}
                                    AppLogger.Log("SYSTEM", "Otomatik ba\u015flatma kay\u0131t girdisi g\u00fcncellendi: " + expectedVal);
                                }
                            }
                        }
                    }
                }
            }
            catch {}
        }

