        // Asistan "Otomatik onar" aksiyonu: Bağlantı Bekçisi ile aynı akış.
        internal void TriggerSmartFallbackRepair()
        {
            string archDir;
            string driverFileName;
            string nativeArchitecture;
            string architectureError;
            if (!AppPaths.TryGetEngineArchitecture(out archDir, out driverFileName, out nativeArchitecture, out architectureError))
            {
                AppLogger.Log("TROUBLE", "Otomatik onarım başlatılmadı: " + architectureError, LogLevel.Warn);
                ToastNotification.Show("İşlemci Desteği", architectureError, ToastType.Warning, 6000);
                return;
            }
            AppLogger.Log("TROUBLE", string.Format("Otomatik onarım hedefi: {0} / {1}", nativeArchitecture, driverFileName), LogLevel.Info);
            string safeExe = GetShortPath(AppPaths.Resolve(Path.Combine(archDir, "goodbyedpi.exe")));
            string whitelist = GetShortPath(AppPaths.Resolve("discord_whitelist.txt")).Trim('"');
            VerifyAndFallbackProtectionAsync(_engineOpStamp, safeExe, whitelist, _lastEngineArgs);
        }

        internal bool CheckDiscordRtcVoiceHealthForTroubleshooter(out string statusDetail)
        {
            statusDetail = null;
            if (_rtcLogMonitor == null) return true;
            try
            {
                _rtcLogMonitor.PollForFailure();
                if (_rtcLogMonitor.IsConnectingStuckNow())
                {
                    statusDetail = "Discord ses bağlantısı takılı kalmış.";
                    return false;
                }
                string host;
                int port;
                _rtcLogMonitor.GetLastEndpoint(out host, out port);
                if (!string.IsNullOrEmpty(host) && port > 0)
                {
                    string err;
                    long rtcMs = NetworkProbe.TestTlsHandshake(host, port, 1600, out err);
                    if (rtcMs < 0)
                    {
                        statusDetail = "Discord açık ancak ses sunucusuna bağlanılamıyor.";
                        return false;
                    }
                }
            }
            catch {}
            return true;
        }

        internal void TriggerManualRtcVoiceHeal()
        {
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                string host = null;
                int port = 443;
                if (_rtcLogMonitor != null) _rtcLogMonitor.GetLastEndpoint(out host, out port);
                DiscordRtcFailureTrigger manualTrigger = new DiscordRtcFailureTrigger();
                manualTrigger.ReasonCode = "ManualVoiceHeal";
                manualTrigger.ReasonDisplay = "Sorun Giderme Asistanı üzerinden ses bağlantısı yenilendi";
                manualTrigger.EndpointHost = host;
                manualTrigger.EndpointPort = port;
                ExecuteRtcAutoHeal(manualTrigger);
            });
        }

        internal bool CheckDiscordMediaCdnHealthForTroubleshooter(out string statusDetail)
        {
            statusDetail = null;
            try
            {
                string cdnErr;
                long cdnMs = NetworkProbe.TestTlsHandshake("cdn.discordapp.com", 443, 1800, out cdnErr);
                string mediaErr;
                long mediaMs = NetworkProbe.TestTlsHandshake("media.discordapp.net", 443, 1800, out mediaErr);
                AppHealthMetrics.RecordMediaCdnProbe(cdnMs, mediaMs);

                if (cdnMs < 0 || mediaMs < 0)
                {
                    statusDetail = "Mesajlar açık ancak resim ve yayınlar yüklenemiyor.";
                    return false;
                }
            }
            catch {}
            return true;
        }

        internal void TriggerManualMediaCdnHeal()
        {
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    EnsureWhitelistFile(AppPaths.Resolve("discord_whitelist.txt"));
                    FlushDnsFast();
                    DiscordMediaAccelerator.ApplyMediaAccelerationCore(true);
                    long resetMs;
                    TrySoftResetDpiEngineForRtcHeal(_engineOpStamp, out resetMs);
                    FlushDnsFast();

                    if (!_isDisposing && this.IsHandleCreated && !this.IsDisposed)
                    {
                        try
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (_isDisposing || this.IsDisposed) return;
                                ToastNotification.Show(
                                    "Discord Medya Onar\u0131ld\u0131",
                                    "Resim, video ve yay\u0131n \u00f6nizleme ak\u0131\u015f\u0131 yenilendi.",
                                    ToastType.Success,
                                    3500);
                            });
                        }
                        catch {}
                    }
                }
                catch {}
            });
        }

        // WinDivert sürücü sağlığı: 0=yok, 1=hazır, 2=devre dışı (Start=4)
        internal static int GetWinDivertServiceHealth()
        {
            try
            {
                string name = AppLogger.FindWinDivertServiceName();
                if (name == null) return 0;
                using (RegistryKey svc = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\" + name, false))
                {
                    if (svc == null) return 0;
                    object v = svc.GetValue("Start");
                    int start = (v == null) ? 3 : Convert.ToInt32(v);
                    return start == 4 ? 2 : 1;
                }
            }
            catch { return 0; }
        }

