        protected override void OnVisibleChanged(EventArgs e)
        {
            base.OnVisibleChanged(e);
            UpdateDnsPingSchedule();
            if (!this.Visible)
            {
                if (_animTimer != null) _animTimer.Stop();
                if (_pingTimer != null) _pingTimer.Stop();
            }
            else
            {
                if (this.Visible && _animTimer != null && !_animTimer.Enabled) _animTimer.Start();
                if (_isRunning && this.WindowState != FormWindowState.Minimized)
                {
                    TriggerManualPing();
                    if (_pingTimer != null && !_pingTimer.Enabled) _pingTimer.Start();
                }
            }
        }

        protected override void OnResize(EventArgs e)
        {
            base.OnResize(e);
            UpdateDnsPingSchedule();
            if (_titleBar != null)
            {
                _titleBar.Width = this.ClientSize.Width;
                _titleBar.Invalidate();
            }
            if (_headerPanel != null)
            {
                _headerPanel.Width = this.ClientSize.Width;
                _headerPanel.Invalidate();
            }
            if (this.WindowState == FormWindowState.Minimized)
            {
                if (_animTimer != null) _animTimer.Stop();
                if (_pingTimer != null) _pingTimer.Stop();
                ThreadPool.QueueUserWorkItem(delegate
                {
                    Thread.Sleep(300);
                    TrimProcessMemory();
                });
            }
            else if (this.Visible)
            {
                if (this.Visible && _animTimer != null && !_animTimer.Enabled) _animTimer.Start();
                if (_isRunning && _pingTimer != null && !_pingTimer.Enabled) _pingTimer.Start();
            }
        }

        protected override void OnDeactivate(EventArgs e)
        {
            base.OnDeactivate(e);
            // Gaming Zero-Lag Optimization:
            // When user switches to another window (e.g., CS2, Valorant, or full-screen app),
            // immediately freeze the 40 FPS UI animation timer to eliminate background CPU wakeups,
            // DPC interruptions, and unnecessary UI polling.
            if (_animTimer != null && _animTimer.Enabled && !_isPinging && !_isSmartBenchmarkRunning)
            {
                _animTimer.Stop();
            }
        }

        protected override void OnActivated(EventArgs e)
        {
            base.OnActivated(e);
            if (this.Visible && this.WindowState != FormWindowState.Minimized)
            {
                if (this.Visible && _animTimer != null && !_animTimer.Enabled) _animTimer.Start();
                if (_isRunning && _pingTimer != null && !_pingTimer.Enabled) _pingTimer.Start();
                // Canlı grafik modu: pencere ön plandayken 4 sn'de bir örnek
                if (_pingTimer != null) _pingTimer.Interval = 4000;
            }
        }

        private void MainForm_FormClosing(object sender, FormClosingEventArgs e)
        {
            if (e.CloseReason == CloseReason.UserClosing && _chkMinimizeToTray.Checked)
            {
                e.Cancel = true;
                if (_animTimer != null) _animTimer.Stop();
                if (_pingTimer != null) _pingTimer.Stop();
                this.Hide();
                if (!_isDisposing)
                {
                    ToastNotification.Show("Arka Planda A\u00e7\u0131k", "Uygulama sistem tepsisinde \u00e7al\u0131\u015f\u0131yor.", ToastType.Info, 2500);
                }
                return;
            }

            _isDisposing = true;
            StopProtection();
            if (_trayIcon != null)
            {
                _trayIcon.Visible = false;
                _trayIcon.Dispose();
                _trayIcon = null;
            }
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                _isDisposing = true;
                try { if (_isRunning || _dpiProcess != null) StopProtection(); } catch {}
                try
                {
                    SystemEvents.PowerModeChanged -= new PowerModeChangedEventHandler(OnPowerModeChanged);
                    NetworkChange.NetworkAddressChanged -= new NetworkAddressChangedEventHandler(OnNetworkAddressChanged);
                    NetworkChange.NetworkAvailabilityChanged -= new NetworkAvailabilityChangedEventHandler(OnNetworkAvailabilityChanged);
                }
                catch {}

                if (_showInstanceWaitReg != null)
                {
                    try { _showInstanceWaitReg.Unregister(null); } catch {}
                    _showInstanceWaitReg = null;
                }
                if (_showInstanceEvent != null)
                {
                    try { _showInstanceEvent.Close(); } catch {}
                    _showInstanceEvent = null;
                }
                if (_animTimer != null) { _animTimer.Stop(); _animTimer.Dispose(); _animTimer = null; }
                if (_pingTimer != null) { _pingTimer.Stop(); _pingTimer.Dispose(); _pingTimer = null; }
                if (_autoUpdateTimer != null) { _autoUpdateTimer.Stop(); _autoUpdateTimer.Dispose(); _autoUpdateTimer = null; }
                if (_connWatchTimer != null) { _connWatchTimer.Stop(); _connWatchTimer.Dispose(); _connWatchTimer = null; }
                if (_rtcWatchTimer != null) { _rtcWatchTimer.Stop(); _rtcWatchTimer.Dispose(); _rtcWatchTimer = null; }
                if (_dnsPingTimer != null) { _dnsPingTimer.Stop(); _dnsPingTimer.Dispose(); _dnsPingTimer = null; }
                if (_themePulseTimer != null) { try { _themePulseTimer.Stop(); _themePulseTimer.Dispose(); } catch {} _themePulseTimer = null; }
                if (_profileSwitchDebounceTimer != null) { try { _profileSwitchDebounceTimer.Stop(); _profileSwitchDebounceTimer.Dispose(); } catch {} _profileSwitchDebounceTimer = null; }
                if (_dropdownPopup != null) { try { _dropdownPopup.Dispose(); } catch {} _dropdownPopup = null; }
                if (_dnsDropdownPopup != null) { try { _dnsDropdownPopup.Dispose(); } catch {} _dnsDropdownPopup = null; }
                if (_themeMenu != null) { try { _themeMenu.Dispose(); } catch {} _themeMenu = null; }
                if (_dnsSelector != null) { try { _dnsSelector.Dispose(); } catch {} _dnsSelector = null; }
                if (_btnDiagnostics != null) { try { _btnDiagnostics.Dispose(); } catch {} _btnDiagnostics = null; }
                if (_btnOptimizeHardware != null) { try { _btnOptimizeHardware.Dispose(); } catch {} _btnOptimizeHardware = null; }
                if (_fontTitle != null) _fontTitle.Dispose();
                if (_fontPill != null) _fontPill.Dispose();
                if (_fontPing != null) _fontPing.Dispose();
                if (_fontUpdate != null) _fontUpdate.Dispose();
                if (_fontVersion != null) _fontVersion.Dispose();
                if (_fontSettingsOption != null) _fontSettingsOption.Dispose();
                if (_trayIcon != null) { _trayIcon.Visible = false; _trayIcon.Dispose(); _trayIcon = null; }
                if (_toolTip != null) { _toolTip.Dispose(); _toolTip = null; }
                if (_trayMenu != null) { try { _trayMenu.Dispose(); } catch {} _trayMenu = null; }
                // _appLogoImg, statik logo önbelleğini (_cachedLogoImage) işaret edebilir;
                // paylaşılan bu nesne asla dispose edilmemeli, yalnızca referans bırakılmalı.
                if (_appLogoImg != null && !object.ReferenceEquals(_appLogoImg, _cachedLogoImage)) { try { _appLogoImg.Dispose(); } catch {} }
                _appLogoImg = null;
                if (_titleFont != null) { try { _titleFont.Dispose(); } catch {} _titleFont = null; }
                if (object.ReferenceEquals(_instance, this)) _instance = null;
                try { AppLogger.Shutdown(); } catch {}
            }
            base.Dispose(disposing);
        }

        internal static Font GetTitleFont()
        {
            string[] preferred = new string[] { "Segoe UI Variable Display", "Segoe UI Semibold", "Bahnschrift SemiBold", "Segoe UI" };
            foreach (string name in preferred)
            {
                try
                {
                    using (Font test = new Font(name, 10F))
                    {
                        if (test.Name.Equals(name, StringComparison.OrdinalIgnoreCase))
                        {
                            return new Font(name, 10F, FontStyle.Bold);
                        }
                    }
                }
                catch {}
            }
            return new Font("Segoe UI", 10F, FontStyle.Bold);
        }

        internal static Font GetMenuFont(float size, FontStyle style)
        {
            string[] preferred = new string[] { "Segoe UI Variable Text", "Segoe UI", "Tahoma" };
            for (int i = 0; i < preferred.Length; i++)
            {
                try
                {
                    using (Font test = new Font(preferred[i], size, style))
                    {
                        if (test.Name.Equals(preferred[i], StringComparison.OrdinalIgnoreCase))
                        {
                            return new Font(preferred[i], size, style);
                        }
                    }
                }
                catch {}
            }
            return new Font("Segoe UI", size, style);
        }

        private void TrayOpen_Click(object sender, EventArgs e)
        {
            _allowVisible = true;
            _startMinimized = false;
            this.ShowInTaskbar = true;
            bool wasHidden = !this.Visible;
            this.Show();
            this.WindowState = FormWindowState.Normal;
            this.BringToFront();
            try { this.Activate(); } catch {}
            if (this.Visible && _animTimer != null && !_animTimer.Enabled) _animTimer.Start();
            if (_wizardPending && !_wizardOpen)
            {
                StartWizardCountdown(600);
            }
            if (wasHidden && !_isRunning && !_isSmartBenchmarkRunning)
            {
                _isAutoScanCompleted = false;
                _userManuallySelectedIsp = false;
                _isProfileBenchmarkPending = true;
                ApplyBenchmarkInteractionState();
                if (_selector != null && !_selector.IsDisposed)
                {
                    _selector.IsAutoModePending = true;
                    _selector.IsAutoSelected = true;
                    _selector.Invalidate();
                }
                StartAutoBenchmarkCountdown(250);
            }
            else
            {
                TriggerManualPing();
            }
            if (_isRunning && _pingTimer != null && !_pingTimer.Enabled) _pingTimer.Start();
        }

        private void TrayExit_Click(object sender, EventArgs e)
        {
            // Düzenli kapanış yolu: FormClosing + Dispose zinciri çalışır (çift tıklama kaydı
            // temizliği, motor süreç denetimi dahil); süreç Environment.Exit ile aniden öldürülmez.
            _isDisposing = true;
            StopProtection();
            if (_trayIcon != null)
            {
                _trayIcon.Visible = false;
                _trayIcon.Dispose();
                _trayIcon = null;
            }
            Application.Exit();
        }

        public static GraphicsPath CreateRoundedRectangleF(RectangleF rect, float radius)
        {
            GraphicsPath path = new GraphicsPath();
            if (radius <= 0f || rect.Width <= 0f || rect.Height <= 0f)
            {
                path.AddRectangle(rect);
                return path;
            }
            float d = Math.Min(radius * 2f, Math.Min(rect.Width, rect.Height));
            path.AddArc(rect.X, rect.Y, d, d, 180, 90);
            path.AddArc(rect.Right - d, rect.Y, d, d, 270, 90);
            path.AddArc(rect.Right - d, rect.Bottom - d, d, d, 0, 90);
            path.AddArc(rect.X, rect.Bottom - d, d, d, 90, 90);
            path.CloseFigure();
            return path;
        }

        public static Color BlendOver(Color bg, Color fg, int fgAlpha)
        {
            float a = Math.Max(0f, Math.Min(1f, fgAlpha / 255f));
            int r = (int)Math.Round(bg.R * (1f - a) + fg.R * a);
            int g = (int)Math.Round(bg.G * (1f - a) + fg.G * a);
            int b = (int)Math.Round(bg.B * (1f - a) + fg.B * a);
            return Color.FromArgb(255, Math.Max(0, Math.Min(255, r)), Math.Max(0, Math.Min(255, g)), Math.Max(0, Math.Min(255, b)));
        }

        public static Color BlendOver(Color bg, Color fg)
        {
            if (fg.A >= 255) return fg;
            if (fg.A <= 0) return bg;
            return BlendOver(bg, fg, fg.A);
        }

        public static void DrawSmoothRoundedBox(Graphics g, RectangleF rect, float radius, Color fillColor, Color borderColor, float borderThickness = 1.0f)
        {
            DrawSmoothRoundedBox(g, (int)Math.Round(rect.X), (int)Math.Round(rect.Y), (int)Math.Round(rect.Width), (int)Math.Round(rect.Height), radius, fillColor, borderColor, borderThickness);
        }

        // Çift katmanlı eş-merkezli (concentric) FillPath tekniği:
        // GDI+ DrawPath(Pen) köşelerde ve yarım-piksel kenarlarda tırtıklı/çift çizgili basamaklar üretir.
        // Bunun yerine dış sınır (outerPath) kenarlık rengiyle, 1px içerideki eş-merkezli iç sınır (innerPath)
        // dolgu rengiyle FillPath kullanılarak çizildiğinde üst/alt/yan düz kenarlar tam 1px keskinliğinde,
        // 4 yuvarlatılmış köşe ise pürüzsüz anti-alias ile sıfır tırtıklı görünür.
        public static void DrawSmoothRoundedBox(Graphics g, int x, int y, int w, int h, float radius, Color fillColor, Color borderColor, float borderThickness = 1.0f)
        {
            if (w <= 2 || h <= 2) return;
            SmoothingMode oldSmooth = g.SmoothingMode;
            PixelOffsetMode oldOffset = g.PixelOffsetMode;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;

            Color opaqueFill = (fillColor.A < 255)
                ? BlendOver(Color.FromArgb(16, 20, 29), fillColor, fillColor.A)
                : fillColor;

            RectangleF outerRect = new RectangleF(x, y, w, h);
            float maxR = Math.Min(w, h) / 2f;
            float rOut = Math.Min(radius, maxR);

            if (borderColor.A == 0 || borderThickness <= 0f)
            {
                using (GraphicsPath outerPath = CreateRoundedRectangleF(outerRect, rOut))
                using (SolidBrush fb = new SolidBrush(opaqueFill))
                {
                    g.FillPath(fb, outerPath);
                }
            }
            else
            {
                Color opaqueBorder = (borderColor.A < 255)
                    ? BlendOver(opaqueFill, borderColor, borderColor.A)
                    : borderColor;

                using (GraphicsPath outerPath = CreateRoundedRectangleF(outerRect, rOut))
                using (SolidBrush bb = new SolidBrush(opaqueBorder))
                {
                    g.FillPath(bb, outerPath);
                }

                float t = borderThickness;
                RectangleF innerRect = new RectangleF(x + t, y + t, w - 2f * t, h - 2f * t);
                float rIn = Math.Max(1f, rOut - t);
                if (innerRect.Width > 0f && innerRect.Height > 0f)
                {
                    using (GraphicsPath innerPath = CreateRoundedRectangleF(innerRect, rIn))
                    using (SolidBrush fb = new SolidBrush(opaqueFill))
                    {
                        g.FillPath(fb, innerPath);
                    }
                }
            }

            g.SmoothingMode = oldSmooth;
            g.PixelOffsetMode = oldOffset;
        }

        // Ping kalite rengi: ping çipindeki LED ile aynı eşikler (≤60 iyi, ≤95 orta, üstü kötü)
        public static Color GetPingQualityColor(int ms)
        {
            if (ms <= 60) return Color.FromArgb(52, 211, 153);
            if (ms <= 95) return Color.FromArgb(245, 158, 11);
            return Color.FromArgb(239, 68, 68);
        }

    }

    public class WindowControlButton : Control
    {
        public enum ButtonType { Minimize, Close, Theme }
        private ButtonType _type;
        private bool _isHovered = false;
        private bool _isPressed = false;
        private bool _isHeartbeatActive = false;
        private float _heartbeatPhase = 0f;

        public bool HeartbeatActive
        {
            get { return _isHeartbeatActive; }
            set { _isHeartbeatActive = value; Invalidate(); }
        }

        public float HeartbeatPhase
        {
            get { return _heartbeatPhase; }
            set { _heartbeatPhase = value; if (_isHeartbeatActive) Invalidate(); }
        }

        public WindowControlButton(ButtonType type)
        {
            _type = type;
            this.Size = (_type == ButtonType.Theme) ? new Size(38, 32) : new Size(46, 32);
            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.StandardDoubleClick, true);
            this.Cursor = Cursors.Default;
        }

        protected override void OnMouseEnter(EventArgs e) { _isHovered = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { _isHovered = false; _isPressed = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseDown(MouseEventArgs e) { if (e.Button == MouseButtons.Left) { _isPressed = true; Invalidate(); } base.OnMouseDown(e); }
        protected override void OnMouseUp(MouseEventArgs e) { _isPressed = false; Invalidate(); base.OnMouseUp(e); }
        protected override void OnMouseDoubleClick(MouseEventArgs e)
        {
            base.OnMouseDoubleClick(e);
        }

        // Tuş kontrol dışında bırakılırsa (sürükleme/odak kaybı) basılı durum takılı kalmasın.
        protected override void OnMouseCaptureChanged(EventArgs e) { if (!this.Capture) { _isPressed = false; Invalidate(); } base.OnMouseCaptureChanged(e); }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;

            if (_isHovered)
            {
                if (_type == ButtonType.Theme)
                {
                    // Modern rounded button hover card for Theme button (avoids harsh window-edge blockiness)
                    RectangleF hRect = new RectangleF(3.5f, 2.5f, this.Width - 7f, this.Height - 5f);
                    Color tBg = _isPressed ? Color.FromArgb(38, 48, 68) : Color.FromArgb(24, 32, 48);
                    Color tBrd = _isPressed ? Color.FromArgb(60, 80, 114) : Color.FromArgb(42, 54, 76);
                    using (GraphicsPath hp = ModernMainForm.CreateRoundedRectangleF(hRect, 6f))
                    using (SolidBrush hb = new SolidBrush(tBg))
                    using (Pen hpPen = new Pen(tBrd, 1f))
                    {
                        g.FillPath(hb, hp);
                        g.DrawPath(hpPen, hp);
                    }
                }
                else
                {
                    Color hoverBg;
                    if (_type == ButtonType.Close)
                    {
                        hoverBg = _isPressed ? Color.FromArgb(178, 36, 23) : Color.FromArgb(196, 43, 28);
                    }
                    else
                    {
                        hoverBg = _isPressed ? Color.FromArgb(42, 52, 74) : Color.FromArgb(24, 255, 255, 255);
                    }

                    // Pencereler düz köşeli olduğundan Minimize/Close için dolgu düz dikdörtgen çizilir
                    using (SolidBrush b = new SolidBrush(hoverBg))
                    {
                        g.FillRectangle(b, 0, 0, this.Width, this.Height);
                    }
                }
            }

            Color iconClr = _isHovered ? Color.White : Color.FromArgb(226, 232, 240);
            int cx = this.Width / 2;
            int cy = this.Height / 2;

            if (_type == ButtonType.Minimize)
            {
                g.PixelOffsetMode = PixelOffsetMode.Half;
                using (Pen mp = new Pen(iconClr, 1.6f))
                {
                    mp.StartCap = LineCap.Round;
                    mp.EndCap = LineCap.Round;
                    g.DrawLine(mp, cx - 5, cy, cx + 5, cy);
                }
            }
            else if (_type == ButtonType.Close)
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                g.PixelOffsetMode = PixelOffsetMode.Half;
                using (Pen p = new Pen(iconClr, 1.6f))
                {
                    p.StartCap = LineCap.Round;
                    p.EndCap = LineCap.Round;
                    int r = 5;
                    g.DrawLine(p, cx - r, cy - r, cx + r, cy + r);
                    g.DrawLine(p, cx + r, cy - r, cx - r, cy + r);
                }
            }
            else if (_type == ButtonType.Theme)
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;

                if (_isHeartbeatActive)
                {
                    // Gentle breathing heartbeat aura (well contained, no messy blur)
                    float pulse = (float)Math.Sin(_heartbeatPhase * Math.PI);
                    if (pulse > 0.05f)
                    {
                        float glowR = 10.5f + pulse * 2.5f;
                        int glowAlpha = (int)(pulse * 45);
                        using (SolidBrush gb = new SolidBrush(Color.FromArgb(glowAlpha, 56, 189, 248)))
                        {
                            g.FillEllipse(gb, cx - glowR, cy - glowR, glowR * 2, glowR * 2);
                        }
                        using (SolidBrush gb2 = new SolidBrush(Color.FromArgb((int)(pulse * 65), 245, 158, 11)))
                        {
                            float innerR = 8.5f + pulse * 1.5f;
                            g.FillEllipse(gb2, cx - innerR, cy - innerR, innerR * 2, innerR * 2);
                        }
                    }
                }

                g.PixelOffsetMode = PixelOffsetMode.HighQuality;
                using (Pen pp = new Pen(iconClr, 1.4f))
                {
                    pp.StartCap = LineCap.Round;
                    pp.EndCap = LineCap.Round;
                    g.DrawEllipse(pp, cx - 6.5f, cy - 6.5f, 13f, 13f);
                }
                // Renk paleti içindeki 3 minik canlı renk noktası
                using (SolidBrush dot1 = new SolidBrush(Color.FromArgb(244, 63, 94)))   // Gül Kırmızısı
                using (SolidBrush dot2 = new SolidBrush(Color.FromArgb(245, 158, 11)))  // Altın Kehribar
                using (SolidBrush dot3 = new SolidBrush(Color.FromArgb(56, 189, 248)))  // Gökyüzü Mavisi
                {
                    g.FillEllipse(dot1, cx - 3.5f, cy - 4.2f, 2.7f, 2.7f);
                    g.FillEllipse(dot2, cx + 0.9f, cy - 2.8f, 2.7f, 2.7f);
                    g.FillEllipse(dot3, cx - 1.8f, cy + 1.2f, 2.7f, 2.7f);
                }

                if (_isHeartbeatActive)
                {
                    // Perfectly balanced beacon badge at top-right (no window edge clipping)
                    float pulse = (float)Math.Sin(_heartbeatPhase * Math.PI);
                    float bx = cx + 6.5f;
                    float by = cy - 6.5f;
                    float bRadius = 4.0f;

                    // Expanding ripple ring
                    if (pulse > 0.15f)
                    {
                        float waveR = bRadius + pulse * 3.8f;
                        int waveAlpha = (int)((1f - pulse * 0.7f) * 150);
                        if (waveAlpha > 0)
                        {
                            using (Pen wavePen = new Pen(Color.FromArgb(waveAlpha, 239, 68, 68), 1.2f))
                            {
                                g.DrawEllipse(wavePen, bx - waveR, by - waveR, waveR * 2, waveR * 2);
                            }
                        }
                    }

                    // Solid badge circle
                    using (SolidBrush badgeBrush = new SolidBrush(Color.FromArgb(239, 68, 68)))
                    {
                        g.FillEllipse(badgeBrush, bx - bRadius, by - bRadius, bRadius * 2, bRadius * 2);
                    }

                    // Crisp vector exclamation mark (no ClearType chromatic fringe)
                    using (Pen exclPen = new Pen(Color.White, 1.2f))
                    {
                        exclPen.StartCap = LineCap.Round;
                        exclPen.EndCap = LineCap.Round;
                        g.DrawLine(exclPen, bx, by - 2.0f, bx, by + 0.3f);
                    }
                    using (SolidBrush dotBrush = new SolidBrush(Color.White))
                    {
                        g.FillEllipse(dotBrush, bx - 0.75f, by + 1.6f, 1.5f, 1.5f);
                    }
                }
            }
        }
    }

