    public class ModernThemeMenuRenderer : ToolStripProfessionalRenderer
    {
        private static readonly Font _fontRegular = new Font("Segoe UI", 10.5F, FontStyle.Regular);
        private static readonly Font _fontBold = new Font("Segoe UI Semibold", 10.5F, FontStyle.Regular);

        public ModernThemeMenuRenderer() : base(new ThemeMenuColorTable())
        {
        }

        protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            ThemePalette palette = ThemePalette.Get(ModernMainForm.ActiveTheme);
            using (SolidBrush bg = new SolidBrush(palette.FormBg))
            {
                g.FillRectangle(bg, e.AffectedBounds);
            }
        }

        protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e)
        {
            Rectangle borderRect = new Rectangle(0, 0, e.ToolStrip.Width - 1, e.ToolStrip.Height - 1);
            using (Pen borderPen = new Pen(ThemePalette.Get(ModernMainForm.ActiveTheme).BorderColor, 1f))
            {
                e.Graphics.DrawRectangle(borderPen, borderRect);
            }
        }

        protected override void OnRenderImageMargin(ToolStripRenderEventArgs e)
        {
            // Suppress image margin strip
        }

        protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e)
        {
            ModernMainForm.ThemeMenuItem item = e.Item as ModernMainForm.ThemeMenuItem;
            if (item == null)
            {
                base.OnRenderMenuItemBackground(e);
                return;
            }

            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;

            bool isHovered = e.Item.Selected;
            bool isCurrent = item.IsCurrentTheme;
            ThemePalette palette = ThemePalette.Get(ModernMainForm.ActiveTheme);

            Rectangle itemRect = new Rectangle(0, 0, e.Item.Width, e.Item.Height);
            RectangleF rowRect = new RectangleF(4f, 2f, itemRect.Width - 8f, itemRect.Height - 4f);

            // Card highlight with smooth rounded corners
            if (isCurrent)
            {
                Color rowBg = ModernMainForm.BlendOver(palette.CardBg, item.SwatchColor, isHovered ? 28 : 18);
                ModernMainForm.DrawSmoothRoundedBox(g, rowRect, 6f, rowBg, Color.Transparent, 0f);
            }
            else if (isHovered)
            {
                ModernMainForm.DrawSmoothRoundedBox(g, rowRect, 6f, palette.CardHover, Color.Transparent, 0f);
            }

            // Left Swatch: clean circular color marker
            int swatchCx = 20;
            int swatchCy = itemRect.Y + itemRect.Height / 2;

            // Solid color disc
            using (SolidBrush dot = new SolidBrush(item.SwatchColor))
            {
                g.FillEllipse(dot, swatchCx - 6, swatchCy - 6, 12, 12);
            }

            // Subtle inner rim
            using (Pen innerPen = new Pen(Color.FromArgb(70, 255, 255, 255), 1f))
            {
                g.DrawEllipse(innerPen, swatchCx - 6, swatchCy - 6, 12, 12);
            }

            // Right-Side Vector Checkmark for Active Theme
            if (isCurrent)
            {
                int checkX = itemRect.Width - 18;
                int checkY = itemRect.Y + itemRect.Height / 2;
                using (Pen checkPen = new Pen(item.SwatchColor, 2f))
                {
                    checkPen.StartCap = LineCap.Round;
                    checkPen.EndCap = LineCap.Round;
                    checkPen.LineJoin = LineJoin.Round;
                    g.DrawLines(checkPen, new Point[] {
                        new Point(checkX - 5, checkY),
                        new Point(checkX - 2, checkY + 3),
                        new Point(checkX + 4, checkY - 4)
                    });
                }
            }
        }

        protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e)
        {
            ModernMainForm.ThemeMenuItem item = e.Item as ModernMainForm.ThemeMenuItem;
            if (item == null)
            {
                base.OnRenderItemText(e);
                return;
            }

            Graphics g = e.Graphics;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;

            bool isCurrent = item.IsCurrentTheme;
            bool isHovered = e.Item.Selected;
            ThemePalette palette = ThemePalette.Get(ModernMainForm.ActiveTheme);

            Color textClr;
            if (isCurrent)
            {
                textClr = palette.TextPrimary;
            }
            else if (isHovered)
            {
                textClr = palette.TextPrimary;
            }
            else
            {
                textClr = ModernMainForm.BlendOver(palette.TextMuted, palette.TextPrimary, 220);
            }

            Font f = isCurrent ? _fontBold : _fontRegular;

            Rectangle textBounds = new Rectangle(40, 0, e.Item.Width - 70, e.Item.Height);
            TextRenderer.DrawText(g, e.Text, f, textBounds, textClr,
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        }

    }

    // Modern Dark Context Menu Renderer for Tray Menu (Windows 11 Native Dark Flyout Style)
    public class ModernDarkMenuRenderer : ToolStripProfessionalRenderer
    {
        private static readonly Font _menuItemFont = new Font("Segoe UI", 11.5F, FontStyle.Regular);

        public ModernDarkMenuRenderer() : base(new DarkColorTable())
        {
        }

        public ModernDarkMenuRenderer(Func<bool> getIsRunning) : this(getIsRunning, null, null, null)
        {
        }

        public ModernDarkMenuRenderer(Func<bool> getIsRunning, Func<int> getSelectedDnsIndex, List<DnsOption> dnsOptions, Func<string> getPing = null) : base(new DarkColorTable())
        {
        }

        protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e)
        {
            using (SolidBrush b = new SolidBrush(Color.FromArgb(43, 43, 43)))
            {
                e.Graphics.FillRectangle(b, e.AffectedBounds);
            }
        }

        protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e)
        {
            using (Pen borderPen = new Pen(Color.FromArgb(58, 58, 58), 1f))
            {
                e.Graphics.DrawRectangle(borderPen, 0, 0, e.ToolStrip.Width - 1, e.ToolStrip.Height - 1);
            }
        }

        protected override void OnRenderImageMargin(ToolStripRenderEventArgs e)
        {
            // Suppress default WinForms image gutter
        }

        protected override void OnRenderItemCheck(ToolStripItemImageRenderEventArgs e)
        {
            // Suppress Windows default check box, rendered custom in OnRenderItemText
        }

        protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            if (e.Item.Selected && e.Item.Enabled)
            {
                int itemW = e.Item.Width;
                if (e.ToolStrip != null && e.ToolStrip.ClientSize.Width > 0)
                {
                    int clientW = e.ToolStrip.ClientSize.Width - (e.Item.Bounds.Left * 2);
                    if (clientW > itemW) itemW = clientW;
                }
                RectangleF itemRect = new RectangleF(3f, 1f, itemW - 6f, e.Item.Height - 2f);
                using (GraphicsPath path = ModernMainForm.CreateRoundedRectangleF(itemRect, 4f))
                using (SolidBrush b = new SolidBrush(Color.FromArgb(56, 56, 56)))
                {
                    g.FillPath(b, path);
                }
            }
        }

        protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            ToolStripMenuItem menuItem = e.Item as ToolStripMenuItem;
            bool isSubmenuItem = (menuItem != null && menuItem.OwnerItem != null);
            bool isChecked = (menuItem != null && menuItem.Checked);

            int itemW = e.Item.Width;
            if (e.ToolStrip != null && e.ToolStrip.ClientSize.Width > 0)
            {
                int clientW = e.ToolStrip.ClientSize.Width - (e.Item.Bounds.Left * 2);
                if (clientW > itemW) itemW = clientW;
            }

            bool hasSubmenu = menuItem != null && (menuItem.HasDropDownItems || menuItem.DropDownItems.Count > 0);
            int textX = isSubmenuItem ? 28 : 14;
            int textRightPadding = hasSubmenu ? 22 : (isSubmenuItem ? 14 : 12);
            int textW = Math.Max(0, itemW - textX - textRightPadding);
            Rectangle textRect = new Rectangle(textX, 0, textW, e.Item.Height);

            // Submenu checked indicator: clean crisp vector checkmark
            if (isSubmenuItem && isChecked)
            {
                int cy = e.Item.Height / 2;
                using (Pen checkPen = new Pen(Color.FromArgb(242, 242, 242), 1.7f))
                {
                    checkPen.StartCap = LineCap.Round;
                    checkPen.EndCap = LineCap.Round;
                    g.DrawLine(checkPen, 11, cy, 14, cy + 3);
                    g.DrawLine(checkPen, 14, cy + 3, 20, cy - 3);
                }
            }

            // Top-level submenu chevron: crisp thin vector chevron
            if (!isSubmenuItem && menuItem != null && (menuItem.HasDropDownItems || menuItem.DropDownItems.Count > 0))
            {
                int cx = itemW - 14;
                float cy = e.Item.Height / 2f;
                Color arrowColor = e.Item.Selected ? Color.White : Color.FromArgb(170, 170, 170);
                using (Pen ap = new Pen(arrowColor, 1.4f))
                {
                    ap.StartCap = LineCap.Round;
                    ap.EndCap = LineCap.Round;
                    g.DrawLine(ap, cx - 2.5f, cy - 3.5f, cx + 1f, cy);
                    g.DrawLine(ap, cx + 1f, cy, cx - 2.5f, cy + 3.5f);
                }
            }

            Color textColor = (e.Item.Tag as string == "EXIT" && e.Item.Selected)
                ? Color.FromArgb(254, 202, 202)
                : (e.Item.Selected ? Color.White : Color.FromArgb(238, 238, 238));

            Font fontToUse = e.Item.Font;
            if (fontToUse == null && e.ToolStrip != null) fontToUse = e.ToolStrip.Font;
            if (fontToUse == null) fontToUse = _menuItemFont;

            TextRenderer.DrawText(g, e.Text, fontToUse, textRect, textColor,
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        }

        protected override void OnRenderArrow(ToolStripArrowRenderEventArgs e)
        {
            // Fully suppressed: drawn custom in OnRenderItemText with exact positioning
        }

        protected override void OnRenderSeparator(ToolStripSeparatorRenderEventArgs e)
        {
            using (Pen sepPen = new Pen(Color.FromArgb(52, 52, 52), 1f))
            {
                int itemW = e.Item.Width;
                if (e.ToolStrip != null && e.ToolStrip.ClientSize.Width > 0)
                {
                    int clientW = e.ToolStrip.ClientSize.Width - (e.Item.Bounds.Left * 2);
                    if (clientW > itemW) itemW = clientW;
                }
                int y = e.Item.Height / 2;
                e.Graphics.DrawLine(sepPen, 10, y, itemW - 10, y);
            }
        }
    }

