    // 1. Sleek Dropdown Selector Box (Closed state, flawless anti-aliased corners)
    public class IspDropdownSelector : Panel
    {
        private IspProfile _profile;
        public IspProfile Profile
        {
            get { return _profile; }
            set { _profile = value; this.Invalidate(); }
        }

        private bool _isOpen = false;
        public bool IsOpen
        {
            get { return _isOpen; }
            set { _isOpen = value; this.Invalidate(); }
        }

        private bool _isLocked = false;
        public bool IsLocked
        {
            get { return _isLocked; }
            set { _isLocked = value; this.Cursor = value ? Cursors.Default : Cursors.Hand; this.Invalidate(); }
        }

        private bool _isAutoModePending = false;
        public bool IsAutoModePending
        {
            get { return _isAutoModePending; }
            set { _isAutoModePending = value; this.Invalidate(); }
        }

        private bool _isAutoSelected = false;
        public bool IsAutoSelected
        {
            get { return _isAutoSelected; }
            set { _isAutoSelected = value; this.Invalidate(); }
        }

        private bool _isHovered = false;
        private float _hoverProgress = 0f;
        private volatile bool _isBenchmarkRunning = false;
        private volatile float _benchProgress = 0f;
        private volatile float _benchTargetProgress = 0f;
        private float _benchSpinnerAngle = 0f;
        private volatile string _benchStageText = "";

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == 0x0021) // WM_MOUSEACTIVATE
            {
                m.Result = (IntPtr)1; // MA_ACTIVATE
                return;
            }
            base.WndProc(ref m);
        }

        public IspDropdownSelector()
        {
            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
            this.UpdateStyles();
            this.Cursor = Cursors.Hand;
        }

        public void StartBenchmark(string initialStage, float initialProgress)
        {
            _benchStageText = initialStage;
            _benchProgress = initialProgress;
            _benchTargetProgress = initialProgress;
            _isBenchmarkRunning = true;
            this.Invalidate();
        }

        public void UpdateProgress(string stageText, float progress)
        {
            _benchStageText = stageText;
            _benchTargetProgress = Math.Max(0f, Math.Min(1f, progress));
            _isBenchmarkRunning = true;
        }

        public void CompleteBenchmark()
        {
            _isBenchmarkRunning = false;
            _benchProgress = 0f;
            _benchTargetProgress = 0f;
            _benchStageText = "";
            this.Invalidate();
        }

        public void UpdateAnimation()
        {
            bool needRepaint = false;
            if (_isBenchmarkRunning)
            {
                _benchSpinnerAngle = (_benchSpinnerAngle + 18f) % 360f;
                float tgt = _benchTargetProgress;
                if (_benchProgress < tgt)
                {
                    _benchProgress = Math.Min(tgt, _benchProgress + Math.Max(0.008f, (tgt - _benchProgress) * 0.22f));
                }
                needRepaint = true;
            }

            if (this.Visible && this.Enabled && !this.IsDisposed && this.IsHandleCreated)
            {
                Form parent = this.FindForm();
                if (parent != null && parent.Visible && parent.WindowState != FormWindowState.Minimized)
                {
                    Point curPos = Cursor.Position;
                    Point clientPt = this.PointToClient(curPos);
                    if (this.ClientRectangle.Contains(clientPt))
                    {
                        _isHovered = true;
                    }
                    else
                    {
                        _isHovered = false;
                    }
                }
                else
                {
                    _isHovered = false;
                }
            }
            else
            {
                _isHovered = false;
            }

            float target = (!_isLocked && (_isHovered || _isOpen)) ? 1.0f : 0.0f;
            if (Math.Abs(_hoverProgress - target) > 0.02f)
            {
                _hoverProgress += (target - _hoverProgress) * 0.25f;
                needRepaint = true;
            }
            else if (_hoverProgress != target)
            {
                _hoverProgress = target;
                needRepaint = true;
            }

            if (needRepaint) this.Invalidate();
        }

        protected override void OnMouseEnter(EventArgs e)
        {
            base.OnMouseEnter(e);
            if (_isLocked) return;
            _isHovered = true;
            this.Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            _isHovered = false;
            this.Invalidate();
        }

        private static readonly Font _selTitleFont = new Font("Segoe UI Semibold", 10.5F, FontStyle.Regular);
        private static readonly Font _selNumFont = new Font("Segoe UI Semibold", 9.5F, FontStyle.Regular);
        private static readonly Font _selBadgeFont = new Font("Segoe UI Semibold", 9.25F, FontStyle.Regular);

        internal static void DrawCrispStar(Graphics g, float cx, float cy, float outerR, float innerR, Color color)
        {
            PointF[] pts = new PointF[10];
            for (int i = 0; i < 10; i++)
            {
                double angle = -Math.PI / 2.0 + i * (Math.PI / 5.0);
                float r = (i % 2 == 0) ? outerR : innerR;
                pts[i] = new PointF(cx + (float)(Math.Cos(angle) * r), cy + (float)(Math.Sin(angle) * r));
            }
            using (SolidBrush sb = new SolidBrush(color))
            {
                g.FillPolygon(sb, pts);
            }
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            // Clear to parent background color to eliminate any edge artifacts
            Color parentBg = this.Parent != null ? this.Parent.BackColor : Color.FromArgb(14, 17, 24);
            g.Clear(parentBg);

            // Interpolated colors
            ThemePalette tp = ThemePalette.Get(ModernMainForm.ActiveTheme);
            Color normalBg = tp.CardBg;
            Color hoverBg = tp.CardHover;
            Color bg = InterpolateColor(normalBg, hoverBg, _isLocked ? 0f : _hoverProgress);

            Color normalBorder = tp.BorderColor;
            Color activeBorder = (_isOpen || _isBenchmarkRunning) ? tp.SecondaryAccent : (_isLocked ? tp.BorderColor : tp.BorderHoverColor);
            float borderProgress = (_isOpen || _isBenchmarkRunning) ? 1f : (_isLocked ? 0f : _hoverProgress);
            Color border = InterpolateColor(normalBorder, activeBorder, borderProgress);

            ModernMainForm.DrawSmoothRoundedBox(g, 0, 0, this.Width, this.Height, 10f, bg, border, 1.0f);

            if (_isBenchmarkRunning && _benchProgress > 0.01f)
            {
                RectangleF innerClipRect = new RectangleF(1f, 1f, this.Width - 2f, this.Height - 2f);
                using (GraphicsPath innerClipPath = ModernMainForm.CreateRoundedRectangleF(innerClipRect, 9f))
                using (Region oldClip = g.Clip)
                {
                    g.SetClip(innerClipPath);
                    float fillW = Math.Max(8f, (this.Width - 2f) * _benchProgress);
                    RectangleF fillRect = new RectangleF(1f, this.Height - 3.5f, fillW, 2.5f);
                    using (SolidBrush fb = new SolidBrush(Color.FromArgb(215, tp.SecondaryAccent)))
                    {
                        g.FillRectangle(fb, fillRect);
                    }
                    g.Clip = oldClip;
                }
            }

            if (_profile == null) return;

            int centerY = this.Height / 2;
            int numBoxX = 14;
            int numBoxY = centerY - 11;
            bool showAutoHeaderMode = _isAutoModePending || _isBenchmarkRunning;

            if (showAutoHeaderMode)
            {
                Color starAccent = (_isLocked && !_isBenchmarkRunning) ? Color.FromArgb(120, 132, 150) : Color.FromArgb(245, 158, 11);
                Color starBg = ModernMainForm.BlendOver(bg, starAccent, 36);
                Color starBrd = ModernMainForm.BlendOver(bg, starAccent, 105);
                ModernMainForm.DrawSmoothRoundedBox(g, numBoxX, numBoxY, 22, 22, 5f, starBg, starBrd, 1.0f);
                DrawCrispStar(g, numBoxX + 11f, centerY, 5.4f, 2.4f, starAccent);
            }
            else
            {
                Color skyAccent = tp.SecondaryAccent;
                Color numBg = ModernMainForm.BlendOver(bg, skyAccent, 32);
                Color numBrd = ModernMainForm.BlendOver(bg, skyAccent, 95);
                ModernMainForm.DrawSmoothRoundedBox(g, numBoxX, numBoxY, 22, 22, 5f, numBg, numBrd, 1.0f);

                string selNumStr = (_profile.Id + 1).ToString();
                TextRenderer.DrawText(g, selNumStr, _selNumFont, new Rectangle(numBoxX, numBoxY, 22, 22), skyAccent, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
            }

            // Right-side "Otomatik (En İyi Profil)" / "En İyi Profil" or live benchmark progress inside selector box (NO ms badge)
            int rightReserve = 34;
            if (_isBenchmarkRunning && !string.IsNullOrEmpty(_benchStageText))
            {
                Size bSz = TextRenderer.MeasureText(_benchStageText, _selBadgeFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
                int bW = bSz.Width + 32;
                int bH = 24;
                int bX = this.Width - 32 - bW;
                int bY = centerY - (bH / 2);

                Color runClr = tp.SecondaryAccent;
                Color runBg = ModernMainForm.BlendOver(bg, runClr, 28);
                Color runBrd = ModernMainForm.BlendOver(bg, runClr, 95);
                ModernMainForm.DrawSmoothRoundedBox(g, bX, bY, bW, bH, 6f, runBg, runBrd, 1.0f);

                RectangleF spinRect = new RectangleF(bX + 8.5f, centerY - 5.5f, 11f, 11f);
                using (Pen trk = new Pen(ModernMainForm.BlendOver(runBg, Color.FromArgb(148, 163, 184), 65), 1.6f))
                using (Pen arc = new Pen(runClr, 1.7f))
                {
                    arc.StartCap = LineCap.Round;
                    arc.EndCap = LineCap.Round;
                    g.DrawEllipse(trk, spinRect);
                    g.DrawArc(arc, spinRect, _benchSpinnerAngle, 250f);
                }

                Rectangle textR = new Rectangle(bX + 23, bY, bW - 26, bH);
                TextRenderer.DrawText(g, _benchStageText, _selBadgeFont, textR, tp.TextPrimary, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
                rightReserve = (this.Width - bX) + 8;
            }
            else if (_isAutoModePending)
            {
                string bText = "Otomatik";
                Size bSz = TextRenderer.MeasureText(bText, _selBadgeFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
                int iconSpace = 15;
                int bW = bSz.Width + iconSpace + 18;
                int bH = 24;
                int bX = this.Width - 32 - bW;
                int bY = centerY - (bH / 2);

                Color badgeClr = _isLocked ? Color.FromArgb(120, 132, 150) : Color.FromArgb(245, 158, 11);
                Color badgeBg = ModernMainForm.BlendOver(bg, badgeClr, 28);
                Color badgeBrd = ModernMainForm.BlendOver(bg, badgeClr, 95);
                ModernMainForm.DrawSmoothRoundedBox(g, bX, bY, bW, bH, 6f, badgeBg, badgeBrd, 1.0f);

                DrawCrispStar(g, bX + 12.5f, centerY, 5.2f, 2.3f, badgeClr);
                Rectangle textR = new Rectangle(bX + 21, bY, bW - 25, bH);
                TextRenderer.DrawText(g, bText, _selBadgeFont, textR, badgeClr, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
                rightReserve = (this.Width - bX) + 8;
            }
            else if (_isAutoSelected || _profile.IsBestForLine || !string.IsNullOrEmpty(_profile.Tag))
            {
                string bText = _isAutoSelected
                    ? "Otomatik"
                    : (!string.IsNullOrEmpty(_profile.Tag) ? _profile.Tag : "En İyi Profil");
                Size bSz = TextRenderer.MeasureText(bText, _selBadgeFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
                int iconSpace = 15;
                int bW = bSz.Width + iconSpace + 18;
                int bH = 24;
                int bX = this.Width - 32 - bW;
                int bY = centerY - (bH / 2);

                Color badgeClr = Color.FromArgb(52, 211, 153);
                Color badgeBg = ModernMainForm.BlendOver(bg, badgeClr, 26);
                Color badgeBrd = ModernMainForm.BlendOver(bg, badgeClr, 90);
                ModernMainForm.DrawSmoothRoundedBox(g, bX, bY, bW, bH, 6f, badgeBg, badgeBrd, 1.0f);

                DrawCrispStar(g, bX + 12.5f, centerY, 5.2f, 2.3f, badgeClr);
                Rectangle textR = new Rectangle(bX + 21, bY, bW - 25, bH);
                TextRenderer.DrawText(g, bText, _selBadgeFont, textR, badgeClr, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
                rightReserve = (this.Width - bX) + 8;
            }

            // Name (cleanly aligned and vertically centered)
            string displayTitle = showAutoHeaderMode ? "Otomatik" : _profile.Name;
            int titleMaxW = Math.Max(80, this.Width - 46 - rightReserve);
            Rectangle titleRect = new Rectangle(46, 0, titleMaxW, this.Height);
            Color titleColor = (_isLocked && !_isBenchmarkRunning) ? tp.TextMuted : tp.TextPrimary;
            TextRenderer.DrawText(g, displayTitle, _selTitleFont, titleRect, titleColor, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);

            // Geometric Chevron Arrow (Down or Up, centered on right)
            int chX = this.Width - 18;
            int chY = centerY;
            Color chevronColor = _isLocked ? Color.FromArgb(100, 116, 139) : (_isOpen ? tp.SecondaryAccent : (_isHovered ? tp.TextPrimary : tp.TextMuted));

            using (Pen cp = new Pen(chevronColor, 1.4f))
            {
                cp.StartCap = LineCap.Round;
                cp.EndCap = LineCap.Round;
                cp.LineJoin = LineJoin.Round;
                cp.LineJoin = LineJoin.Round;
                if (_isOpen)
                {
                    PointF[] pts = new PointF[] {
                        new PointF(chX - 4f, chY + 2f),
                        new PointF(chX, chY - 2f),
                        new PointF(chX + 4f, chY + 2f)
                    };
                    g.DrawLines(cp, pts);
                }
                else
                {
                    PointF[] pts = new PointF[] {
                        new PointF(chX - 4f, chY - 2f),
                        new PointF(chX, chY + 2f),
                        new PointF(chX + 4f, chY - 2f)
                    };
                    g.DrawLines(cp, pts);
                }
            }
        }

        private static Color InterpolateColor(Color c1, Color c2, float t)
        {
            t = Math.Max(0f, Math.Min(1f, t));
            int r = (int)(c1.R + (c2.R - c1.R) * t);
            int g = (int)(c1.G + (c2.G - c1.G) * t);
            int b = (int)(c1.B + (c2.B - c1.B) * t);
            return Color.FromArgb(r, g, b);
        }
    }

