    // 2. Custom Dropdown Menu List Control (Inside ToolStripDropDown)
    public class IspDropdownMenuList : Control
    {
        private List<IspProfile> _profiles;
        private int _selectedIndex;
        private Action<int> _onSelect;
        private Action _onRunBenchmark;
        private bool _isAutoSelected = false;
        private int _hoveredIndex = -1;
        private bool _isBenchmarkHeaderHovered = false;
        private const int ItemH = 36;
        private const int HeaderAreaH = 48; // Top integrated Smart Benchmark row + balanced divider gap
        internal static readonly object ProfileMeasurementSync = new object();
        private static bool _isProbingIspPings = false;
        private Func<bool> _isBenchmarkRunning;

        public IspDropdownMenuList(List<IspProfile> profiles, int selectedIndex, Action<int> onSelect, Action onRunBenchmark = null, bool isAutoSelected = false, Func<bool> isBenchmarkRunning = null)
        {
            _profiles = profiles;
            _selectedIndex = selectedIndex;
            _onSelect = onSelect;
            _onRunBenchmark = onRunBenchmark;
            _isAutoSelected = isAutoSelected;
            _isBenchmarkRunning = isBenchmarkRunning;

            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
            this.UpdateStyles();

            int topH = (_onRunBenchmark != null) ? HeaderAreaH : 4;
            this.Size = new Size(400, topH + _profiles.Count * ItemH + 6);
            this.BackColor = ThemePalette.Get(ModernMainForm.ActiveTheme).FormBg;
            this.Cursor = Cursors.Hand;

            StartBackgroundIspPings();
        }

        private void StartBackgroundIspPings()
        {
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                lock (ProfileMeasurementSync)
                {
                    if (_isProbingIspPings || IsBenchmarkRunning()) return;
                    _isProbingIspPings = true;
                }
                try
                {
                    const string fallbackTarget = "66.22.244.2";
                    Dictionary<string, long> measuredTargetMs = new Dictionary<string, long>(StringComparer.Ordinal);
                    Dictionary<string, int> measuredTargetLoss = new Dictionary<string, int>(StringComparer.Ordinal);

                    for (int i = 0; i < _profiles.Count; i++)
                    {
                        if (IsBenchmarkRunning()) break;

                        IspProfile p = _profiles[i];
                        if (string.IsNullOrEmpty(p.PeeringTarget)) continue;

                        bool shouldMeasure;
                        lock (ProfileMeasurementSync)
                        {
                            if (IsBenchmarkRunning()) break;
                            shouldMeasure = p.PingMeasuredUtc == DateTime.MinValue
                                || (DateTime.UtcNow - p.PingMeasuredUtc).TotalSeconds >= 45;
                        }
                        if (!shouldMeasure) continue;

                        long ms;
                        int lossPct;
                        if (!measuredTargetMs.TryGetValue(p.PeeringTarget, out ms))
                        {
                            ms = NetworkProbe.MeasureTargetQuality(p.PeeringTarget, 3, 500, out lossPct);
                            if (ms >= 0 && lossPct > 33) ms = -1;
                            measuredTargetMs[p.PeeringTarget] = ms;
                            measuredTargetLoss[p.PeeringTarget] = lossPct;
                        }
                        lossPct = measuredTargetLoss[p.PeeringTarget];

                        if (ms < 0 && !string.Equals(p.PeeringTarget, fallbackTarget, StringComparison.Ordinal))
                        {
                            if (!measuredTargetMs.TryGetValue(fallbackTarget, out ms))
                            {
                                int fallbackLossPct;
                                ms = NetworkProbe.MeasureTargetQuality(fallbackTarget, 3, 500, out fallbackLossPct);
                                if (ms >= 0 && fallbackLossPct > 33) ms = -1;
                                measuredTargetMs[fallbackTarget] = ms;
                                measuredTargetLoss[fallbackTarget] = fallbackLossPct;
                            }
                            lossPct = measuredTargetLoss[fallbackTarget];
                        }

                        if (IsBenchmarkRunning()) break;

                        lock (ProfileMeasurementSync)
                        {
                            if (IsBenchmarkRunning()) break;
                            p.PingMs = ms;
                            p.PacketLossPct = lossPct;
                            p.PingMeasuredUtc = DateTime.UtcNow;
                        }

                        try
                        {
                            if (this.IsHandleCreated && !this.IsDisposed)
                            {
                                this.BeginInvoke((MethodInvoker)delegate
                                {
                                    if (!this.IsDisposed) this.Invalidate();
                                });
                            }
                        }
                        catch {}
                    }

                    try
                    {
                        if (this.IsHandleCreated && !this.IsDisposed)
                        {
                            this.BeginInvoke((MethodInvoker)delegate
                            {
                                if (!this.IsDisposed) this.Invalidate();
                                try
                                {
                                    // Arka plan Ä°SS listesi Ã¶lÃ§Ã¼mÃ¼, saÄŸ Ã¼stteki ana Discord ses pingi Ã§ipini ezmemelidir
                                }
                                catch {}
                            });
                        }
                    }
                    catch {}
                }
                catch {}
                finally
                {
                    lock (ProfileMeasurementSync)
                    {
                        _isProbingIspPings = false;
                    }
                }
            });
        }

        private bool IsBenchmarkRunning()
        {
            return _isBenchmarkRunning != null && _isBenchmarkRunning();
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            int topH = (_onRunBenchmark != null) ? HeaderAreaH : 4;

            bool overHeader = (_onRunBenchmark != null) && (e.Y >= 6 && e.Y <= 40);
            int ry = e.Y - topH;
            int idx = (overHeader || ry < 0) ? -1 : ry / ItemH;
            if (idx >= 0 && (ry - idx * ItemH) >= ItemH - 3) idx = -1;
            if (idx >= _profiles.Count) idx = -1;

            if (overHeader != _isBenchmarkHeaderHovered || idx != _hoveredIndex)
            {
                _isBenchmarkHeaderHovered = overHeader;
                _hoveredIndex = idx;
                this.Invalidate();
            }
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            _isBenchmarkHeaderHovered = false;
            _hoveredIndex = -1;
            this.Invalidate();
        }

        protected override void OnMouseClick(MouseEventArgs e)
        {
            base.OnMouseClick(e);
            if (e.Button != MouseButtons.Left) return;
            if (IsBenchmarkRunning()) return;

            if (_onRunBenchmark != null && e.Y >= 6 && e.Y <= 40)
            {
                _onRunBenchmark();
                return;
            }

            int topH = (_onRunBenchmark != null) ? HeaderAreaH : 4;
            int ry = e.Y - topH;
            int idx = ry < 0 ? -1 : ry / ItemH;
            if (idx >= 0 && (ry - idx * ItemH) >= ItemH - 3) idx = -1;
            if (idx >= 0 && idx < _profiles.Count)
            {
                if (_onSelect != null)
                {
                    _onSelect(idx);
                }
            }
        }

        private static readonly Font _itemTitleBoldFont = new Font("Segoe UI Semibold", 10.5F, FontStyle.Regular);
        private static readonly Font _itemTitleRegularFont = new Font("Segoe UI", 10.5F, FontStyle.Regular);
        private static readonly Font _itemTagFont = new Font("Segoe UI Semibold", 9.25F, FontStyle.Regular);
        private static readonly Font _itemMetricFont = new Font("Segoe UI", 9.5F, FontStyle.Regular);
        private static readonly Font _itemNumberFont = new Font("Segoe UI Semibold", 9.25F, FontStyle.Regular);

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            ThemePalette tp = ThemePalette.Get(ModernMainForm.ActiveTheme);
            g.Clear(tp.FormBg);

            // Sabit 3 sütunlu simetrik ızgara hizalaması:
            // Sol rozet sütunu: X = 14 (W = 22, H = 20)
            // Başlık sütunu   : X = 46
            // Sağ rozet sütunu: X = Width - 14 - 66 = 320 (W = 66, H = 22, Sağ kenar = 386)
            const int leftColX = 14;
            const int leftBoxW = 22;
            const int leftBoxH = 20;
            const int titleColX = 46;
            const int rightMargin = 14;
            const int rightPillW = 66;
            const int rightPillH = 22;
            int rightPillX = this.Width - rightMargin - rightPillW;

            int listStartY = 4;
            if (_onRunBenchmark != null)
            {
                listStartY = HeaderAreaH;
                bool highlightBench = _isBenchmarkHeaderHovered || _isAutoSelected;
                Color starAccent = Color.FromArgb(245, 158, 11);
                Color benchBg = _isBenchmarkHeaderHovered ? tp.CardHover : tp.CardBg;
                Color benchBrd = highlightBench ? ModernMainForm.BlendOver(tp.BorderColor, starAccent, _isBenchmarkHeaderHovered ? 160 : 110) : tp.BorderColor;
                ModernMainForm.DrawSmoothRoundedBox(g, 6, 6, this.Width - 12, 34, 7f, benchBg, benchBrd, 1.0f);

                int bCy = 6 + 17;

                // Sol Yıldız Rozeti (altındaki 1..9 kutularıyla birebir X=14, 22x20 hizasında)
                Color starBg = ModernMainForm.BlendOver(benchBg, starAccent, highlightBench ? 45 : 32);
                Color starBrd = ModernMainForm.BlendOver(benchBg, starAccent, highlightBench ? 145 : 100);
                ModernMainForm.DrawSmoothRoundedBox(g, leftColX, bCy - (leftBoxH / 2), leftBoxW, leftBoxH, 5f, starBg, starBrd, 1.0f);
                IspDropdownSelector.DrawCrispStar(g, leftColX + (leftBoxW / 2.0f), bCy, 5.2f, 2.3f, _isBenchmarkHeaderHovered ? Color.FromArgb(253, 224, 71) : starAccent);

                // Başlık (altındaki İSS isimleriyle birebir X=46 hizasında)
                Color benchTitleClr = _isBenchmarkHeaderHovered ? Color.FromArgb(253, 230, 138) : tp.TextPrimary;
                Rectangle benchTitleRect = new Rectangle(titleColX, 6, rightPillX - titleColX - 8, 34);
                TextRenderer.DrawText(g, "En iyi profili otomatik bul", _itemTitleBoldFont, benchTitleRect, benchTitleClr, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);

                // Sağ "Test" rozeti (ölçüm süresi ağ yanıtlarına göre değişebilir)
                int pillY = bCy - (rightPillH / 2);
                Color pillBg = ModernMainForm.BlendOver(benchBg, starAccent, highlightBench ? 40 : 26);
                Color pillBrd = ModernMainForm.BlendOver(benchBg, starAccent, highlightBench ? 145 : 96);
                ModernMainForm.DrawSmoothRoundedBox(g, rightPillX, pillY, rightPillW, rightPillH, 6f, pillBg, pillBrd, 1.0f);
                TextRenderer.DrawText(g, "Test", _itemTagFont, new Rectangle(rightPillX, pillY, rightPillW, rightPillH), _isBenchmarkHeaderHovered ? Color.FromArgb(253, 224, 71) : starAccent, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);

                // Üst aksiyon kartı ile liste arasında zarif 1px ayırıcı
                using (SolidBrush divB = new SolidBrush(tp.BorderColor))
                {
                    g.FillRectangle(divB, leftColX, 43, this.Width - (leftColX * 2), 1);
                }
            }

            // İSS Profil Satırları (1..9)
            for (int i = 0; i < _profiles.Count; i++)
            {
                IspProfile p = _profiles[i];
                int itemY = listStartY + i * ItemH;
                int itemCardH = ItemH - 3;

                bool isSel = (i == _selectedIndex);
                bool isHov = (i == _hoveredIndex);
                bool isBest = (p.IsBestForLine || !string.IsNullOrEmpty(p.Tag));
                Color rowSurfaceBg = tp.FormBg;

                // Seçili veya üzerine gelinen satır arka plan kartı
                if (isSel)
                {
                    rowSurfaceBg = ModernMainForm.BlendOver(tp.CardBg, tp.SecondaryAccent, 14);
                    Color selectedBorder = ModernMainForm.BlendOver(tp.BorderColor, tp.SecondaryAccent, 72);
                    ModernMainForm.DrawSmoothRoundedBox(g, 6, itemY, this.Width - 12, itemCardH, 6f, rowSurfaceBg, selectedBorder, 1.0f);
                }
                else if (isHov)
                {
                    rowSurfaceBg = tp.CardHover;
                    ModernMainForm.DrawSmoothRoundedBox(g, 6, itemY, this.Width - 12, itemCardH, 6f, rowSurfaceBg, tp.BorderHoverColor, 1.0f);
                }

                int cy = itemY + (itemCardH / 2);

                // 1. Sol Numara Rozeti (1..9) — X=14, 22x20
                int numBoxY = cy - (leftBoxH / 2);
                Rectangle numRect = new Rectangle(leftColX, numBoxY, leftBoxW, leftBoxH);
                string numStr = (i + 1).ToString();

                if (isSel)
                {
                    Color sky = tp.SecondaryAccent;
                    Color nBg = ModernMainForm.BlendOver(rowSurfaceBg, sky, 36);
                    Color nBrd = ModernMainForm.BlendOver(rowSurfaceBg, sky, 110);
                    ModernMainForm.DrawSmoothRoundedBox(g, leftColX, numBoxY, leftBoxW, leftBoxH, 5f, nBg, nBrd, 1.0f);
                    TextRenderer.DrawText(g, numStr, _itemNumberFont, numRect, sky, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
                }
                else if (isHov)
                {
                    ModernMainForm.DrawSmoothRoundedBox(g, leftColX, numBoxY, leftBoxW, leftBoxH, 5f, ModernMainForm.BlendOver(rowSurfaceBg, tp.SecondaryAccent, 16), tp.BorderColor, 1.0f);
                    TextRenderer.DrawText(g, numStr, _itemNumberFont, numRect, Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
                }
                else
                {
                    ModernMainForm.DrawSmoothRoundedBox(g, leftColX, numBoxY, leftBoxW, leftBoxH, 5f, tp.CardBg, tp.BorderColor, 1.0f);
                    TextRenderer.DrawText(g, numStr, _itemNumberFont, numRect, tp.TextMuted, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
                }

                // 2. Sağ Sütun: Simetrik Gecikme (ms) Rozeti (X=320, W=66, H=22 — tüm satırlarda aynı hizada)
                int rightCursorX = this.Width - rightMargin;

                if (p.PingMs >= 0)
                {
                    string msText = p.PingMs + " ms";
                    int msY = cy - (rightPillH / 2);

                    Color dotClr = p.PingMs < 50
                        ? Color.FromArgb(52, 211, 153)
                        : (p.PingMs < 80 ? Color.FromArgb(56, 189, 248) : Color.FromArgb(245, 158, 11));

                    Color mBg;
                    Color mBrd;
                    Color mTxt;
                    if (isSel || isBest)
                    {
                        mBg = ModernMainForm.BlendOver(rowSurfaceBg, dotClr, 26);
                        mBrd = ModernMainForm.BlendOver(rowSurfaceBg, dotClr, 88);
                        mTxt = dotClr;
                    }
                    else if (isHov)
                    {
                        mBg = ModernMainForm.BlendOver(rowSurfaceBg, dotClr, 20);
                        mBrd = ModernMainForm.BlendOver(rowSurfaceBg, dotClr, 65);
                        mTxt = Color.FromArgb(226, 232, 240);
                    }
                    else
                    {
                        // Seçili olmayan satırlarda göz yormayan sakin koyu-arduvaz kutu + renkli kalite LED noktası
                        mBg = tp.CardBg;
                        mBrd = tp.BorderColor;
                        mTxt = tp.TextPrimary;
                    }

                    ModernMainForm.DrawSmoothRoundedBox(g, rightPillX, msY, rightPillW, rightPillH, 6f, mBg, mBrd, 1.0f);

                    // Sol kalite LED noktası (5x5) + ortalı ms metni
                    using (SolidBrush dotB = new SolidBrush(dotClr))
                    {
                        g.FillEllipse(dotB, rightPillX + 9f, cy - 2.5f, 5f, 5f);
                    }
                    Rectangle msTextRect = new Rectangle(rightPillX + 16, msY, rightPillW - 18, rightPillH);
                    TextRenderer.DrawText(g, msText, _itemMetricFont, msTextRect, mTxt, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
                    rightCursorX = rightPillX - 6;
                }

                // 3. "★ En İyi" Kompakt Rozeti (yalnızca en iyi profilde, ms rozetinin hemen solunda)
                if (isBest)
                {
                    string tagStr = "En İyi";
                    int badgeW = 60;
                    int badgeH = rightPillH;
                    int badgeX = rightCursorX - badgeW;
                    int badgeY = cy - (badgeH / 2);

                    Color bClr = Color.FromArgb(52, 211, 153);
                    Color bBg = ModernMainForm.BlendOver(rowSurfaceBg, bClr, 26);
                    Color bBrd = ModernMainForm.BlendOver(rowSurfaceBg, bClr, 88);
                    ModernMainForm.DrawSmoothRoundedBox(g, badgeX, badgeY, badgeW, badgeH, 6f, bBg, bBrd, 1.0f);

                    IspDropdownSelector.DrawCrispStar(g, badgeX + 11.5f, cy, 4.6f, 2.0f, bClr);
                    Rectangle tagTextRect = new Rectangle(badgeX + 18, badgeY, badgeW - 20, badgeH);
                    TextRenderer.DrawText(g, tagStr, _itemTagFont, tagTextRect, bClr, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
                    rightCursorX = badgeX - 6;
                }

                // 4. Orta Sütun: İSS Başlığı (X=46)
                Color titleClr = tp.TextPrimary;
                Font titleFont = isSel ? _itemTitleBoldFont : _itemTitleRegularFont;
                int maxTitleW = Math.Max(90, rightCursorX - titleColX);
                Rectangle titleRect = new Rectangle(titleColX, itemY, maxTitleW, itemCardH);
                TextRenderer.DrawText(g, p.Name, titleFont, titleRect, titleClr, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
            }

            // Crisp 1px outer menu border (drawn with Default pixel offset so all 4 edges sit on exact outer pixels)
            g.SmoothingMode = SmoothingMode.None;
            g.PixelOffsetMode = PixelOffsetMode.Default;
            using (Pen borderPen = new Pen(tp.BorderColor, 1f))
            {
                g.DrawRectangle(borderPen, 0, 0, this.Width - 1, this.Height - 1);
            }
        }
    }

    // 2.5 Modern Interactive DNS Dropdown Button (Clean desktop utility chip with vector globe & chevron)
    public class DnsDropdownButton : Control
    {
        private List<DnsOption> _options;
        private int _selectedIndex = 0;
        private int _effectiveDnsIndex = 1;
        private bool _isOpen = false;
        private bool _isHovered = false;
        private float _hoverProgress = 0f;

        public bool IsOpen
        {
            get { return _isOpen; }
            set { _isOpen = value; this.Invalidate(); }
        }

        public int EffectiveDnsIndex
        {
            get { return _effectiveDnsIndex; }
            set { _effectiveDnsIndex = value; this.Invalidate(); }
        }

        public DnsDropdownButton(List<DnsOption> options, int selectedIndex)
        {
            _options = options;
            _selectedIndex = selectedIndex;

            if (_options != null)
            {
                int bypassIdx = _options.FindIndex(d => d != null && d.DpiArgs != null && d.DpiArgs.Contains("9953"));
                _effectiveDnsIndex = (bypassIdx > 0) ? bypassIdx : ((_options.Count > 1) ? 1 : 0);
            }

            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
            this.UpdateStyles();

            this.Size = new Size(195, 26);
            this.Cursor = Cursors.Hand;
            this.BackColor = Color.FromArgb(14, 17, 24);
        }

        public void SetSelected(int index)
        {
            _selectedIndex = index;
            this.Invalidate();
        }

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == 0x0021) // WM_MOUSEACTIVATE
            {
                m.Result = (IntPtr)1; // MA_ACTIVATE
                return;
            }
            base.WndProc(ref m);
        }

        public void UpdateAnimation()
        {
            if (this.Visible && this.Enabled && !this.IsDisposed && this.IsHandleCreated)
            {
                Form parent = this.FindForm();
                if (parent != null && parent.Visible && parent.WindowState != FormWindowState.Minimized)
                {
                    Point curPos = Cursor.Position;
                    Point clientPt = this.PointToClient(curPos);
                    if (this.ClientRectangle.Contains(clientPt))
                    {
                        _isHovered = true;
                    }
                    else
                    {
                        _isHovered = false;
                    }
                }
                else
                {
                    _isHovered = false;
                }
            }
            else
            {
                _isHovered = false;
            }

            float target = (_isHovered || _isOpen) ? 1.0f : 0.0f;
            if (Math.Abs(_hoverProgress - target) > 0.02f)
            {
                _hoverProgress += (target - _hoverProgress) * 0.25f;
                this.Invalidate();
            }
            else if (_hoverProgress != target)
            {
                _hoverProgress = target;
                this.Invalidate();
            }
        }

        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _isHovered = true; this.Invalidate(); }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _isHovered = false; this.Invalidate(); }

        private static Color InterpolateColor(Color c1, Color c2, float t)
        {
            t = Math.Max(0f, Math.Min(1f, t));
            int r = (int)(c1.R + (c2.R - c1.R) * t);
            int g = (int)(c1.G + (c2.G - c1.G) * t);
            int b = (int)(c1.B + (c2.B - c1.B) * t);
            return Color.FromArgb(r, g, b);
        }

        private static readonly Font _labelFont = new Font("Segoe UI Semibold", 9.5F, FontStyle.Regular);
        private static readonly Font _valueFont = new Font("Segoe UI Semibold", 9.5F, FontStyle.Regular);
        private static readonly Font _selBadgeFont = new Font("Segoe UI Semibold", 8.75F, FontStyle.Regular);

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            Color parentBg = this.Parent != null ? this.Parent.BackColor : Color.FromArgb(14, 17, 24);
            g.Clear(parentBg);

            ThemePalette tp = ThemePalette.Get(ModernMainForm.ActiveTheme);
            Color idleBg = tp.CardBg;
            Color hoverBg = tp.CardHover;
            Color curBg = InterpolateColor(idleBg, hoverBg, _hoverProgress);

            Color idleBorder = tp.BorderColor;
            Color activeBorder = tp.SecondaryAccent;
            Color curBorder = InterpolateColor(idleBorder, activeBorder, _hoverProgress);

            ModernMainForm.DrawSmoothRoundedBox(g, 1, 1, this.Width - 2, this.Height - 2, 8f, curBg, curBorder, 1.0f);

            int cy = this.Height / 2;

            // Minimalist Vector Globe Icon (Natural desktop aesthetic, no AI neon dot)
            Color iconColor = InterpolateColor(tp.TextMuted, tp.SecondaryAccent, _hoverProgress);
            using (Pen ip = new Pen(iconColor, 1.25f))
            {
                ip.StartCap = LineCap.Round;
                ip.EndCap = LineCap.Round;
                g.DrawEllipse(ip, 8, cy - 6, 12, 12);
                g.DrawLine(ip, 8, cy, 20, cy);
                g.DrawEllipse(ip, 11, cy - 6, 6, 12);
            }

            // "DNS:" Prefix
            int textX = 26;
            Color labelColor = InterpolateColor(tp.TextMuted, tp.TextPrimary, _hoverProgress);
            TextRenderer.DrawText(g, "DNS:", _labelFont, new Rectangle(textX, 0, 60, this.Height), labelColor, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
            int dnsW = TextRenderer.MeasureText("DNS:", _labelFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding).Width;

            // Right Badge (Otomatik)
            int rightReserve = 28;
            if (_selectedIndex == 0)
            {
                string bText = "Otomatik";
                Size bSz = TextRenderer.MeasureText(bText, _selBadgeFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
                int iconSpace = 15;
                int bW = bSz.Width + iconSpace + 18;
                int bH = 22;
                int bX = this.Width - 32 - bW;
                int bY = cy - (bH / 2);

                Color badgeClr = Color.FromArgb(52, 211, 153);
                Color badgeBg = ModernMainForm.BlendOver(curBg, badgeClr, 26);
                Color badgeBrd = ModernMainForm.BlendOver(curBg, badgeClr, 90);
                ModernMainForm.DrawSmoothRoundedBox(g, bX, bY, bW, bH, 5f, badgeBg, badgeBrd, 1.0f);

                IspDropdownSelector.DrawCrispStar(g, bX + 11.5f, cy, 4.6f, 2.0f, badgeClr);
                Rectangle textR = new Rectangle(bX + 19, bY, bW - 21, bH);
                TextRenderer.DrawText(g, bText, _selBadgeFont, textR, badgeClr, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
                rightReserve = (this.Width - bX) + 8;
            }

            // Provider Value: Active DNS provider (cleanly aligned without Otomatik prefix)
            string valText;
            if (_selectedIndex == 0 && _options != null && _options.Count > 0)
            {
                int eff = (_effectiveDnsIndex > 0 && _effectiveDnsIndex < _options.Count)
                    ? _effectiveDnsIndex
                    : -1;

                // Eğer belirlenen efektif DNS yanıt vermiyorsa (PingMs < 0), listedeki canlı sunucuya bak
                if (eff <= 0 || (eff < _options.Count && _options[eff].PingMs < 0))
                {
                    long lowestMs = long.MaxValue;
                    int lowestIdx = -1;
                    for (int i = 1; i < _options.Count; i++)
                    {
                        if (_options[i] != null && _options[i].IsAutomaticCandidate && _options[i].PingMs >= 0 && _options[i].PingMs < lowestMs)
                        {
                            lowestMs = _options[i].PingMs;
                            lowestIdx = i;
                        }
                    }
                    if (lowestIdx > 0)
                    {
                        eff = lowestIdx;
                    }
                    else
                    {
                        // Hiçbir canlı ölçüm yoksa: Türkiye İSS engelsiz port sunucusu Quad9 (Port 9953) varsayılandır
                        int bypassIdx = _options.FindIndex(d => d != null && d.IsAutomaticCandidate && d.DpiArgs != null && d.DpiArgs.Contains("9953"));
                        eff = (bypassIdx > 0) ? bypassIdx : ((_options.Count > 1) ? 1 : 0);
                    }
                }

                string effName = (eff >= 0 && eff < _options.Count && _options[eff] != null)
                    ? (!string.IsNullOrEmpty(_options[eff].DisplayName) ? _options[eff].DisplayName : _options[eff].Name)
                    : "Quad9 DNS";
                valText = effName;
            }
            else
            {
                valText = (_selectedIndex >= 0 && _selectedIndex < _options.Count && _options[_selectedIndex] != null) ? _options[_selectedIndex].Name : "Seçiniz";
            }
            int valX = textX + dnsW + 6;
            int maxValW = Math.Max(10, (this.Width - rightReserve) - valX);
            Rectangle valRect = new Rectangle(valX, 0, maxValW, this.Height);
            Color valColor = tp.TextPrimary;
            TextRenderer.DrawText(g, valText, _valueFont, valRect, valColor, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);

            // Refined Vector Chevron Arrow
            int chX = this.Width - 18;
            int chY = cy;
            Color chevronColor = iconColor;
            using (Pen cp = new Pen(chevronColor, 1.4f))
            {
                cp.StartCap = LineCap.Round;
                cp.EndCap = LineCap.Round;
                cp.LineJoin = LineJoin.Round;
                if (_isOpen)
                {
                    g.DrawLine(cp, chX - 4, cy + 2, chX, cy - 2);
                    g.DrawLine(cp, chX, cy - 2, chX + 4, cy + 2);
                }
                else
                {
                    g.DrawLine(cp, chX - 4, cy - 2, chX, cy + 2);
                    g.DrawLine(cp, chX, cy + 2, chX + 4, cy - 2);
                }
            }
        }
    }

    // 2.6 Modern Diagnostics Utility Button (Replaces bare HTML link with sleek desktop button)
    public class DiagnosticsButton : Control
    {
        private bool _isHovered = false;
        private bool _isPressed = false;
        private float _hoverProgress = 0f;

        public DiagnosticsButton()
        {
            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
            this.UpdateStyles();

            this.Size = new Size(125, 26);
            this.Cursor = Cursors.Hand;
            this.BackColor = Color.FromArgb(14, 17, 24);
        }

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == 0x0021) // WM_MOUSEACTIVATE
            {
                m.Result = (IntPtr)1; // MA_ACTIVATE
                return;
            }
            base.WndProc(ref m);
        }

        public void UpdateAnimation()
        {
            if (this.Visible && this.Enabled && !this.IsDisposed && this.IsHandleCreated)
            {
                Form parent = this.FindForm();
                if (parent != null && parent.Visible && parent.WindowState != FormWindowState.Minimized)
                {
                    Point curPos = Cursor.Position;
                    Point clientPt = this.PointToClient(curPos);
                    if (this.ClientRectangle.Contains(clientPt))
                    {
                        _isHovered = true;
                    }
                    else
                    {
                        _isHovered = false;
                    }
                }
                else
                {
                    _isHovered = false;
                }
            }
            else
            {
                _isHovered = false;
            }

            float target = _isHovered ? 1.0f : 0.0f;
            if (Math.Abs(_hoverProgress - target) > 0.02f)
            {
                _hoverProgress += (target - _hoverProgress) * 0.25f;
                this.Invalidate();
            }
            else if (_hoverProgress != target)
            {
                _hoverProgress = target;
                this.Invalidate();
            }
        }

        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _isHovered = true; this.Invalidate(); }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _isHovered = false; _isPressed = false; this.Invalidate(); }
        protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (e.Button == MouseButtons.Left) { _isPressed = true; this.Invalidate(); } }
        protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); _isPressed = false; this.Invalidate(); }
        protected override void OnMouseCaptureChanged(EventArgs e) { if (!this.Capture) { _isPressed = false; this.Invalidate(); } base.OnMouseCaptureChanged(e); }

        private static Color InterpolateColor(Color c1, Color c2, float t)
        {
            t = Math.Max(0f, Math.Min(1f, t));
            int r = (int)(c1.R + (c2.R - c1.R) * t);
            int g = (int)(c1.G + (c2.G - c1.G) * t);
            int b = (int)(c1.B + (c2.B - c1.B) * t);
            return Color.FromArgb(r, g, b);
        }

        private static readonly Font _btnFont = new Font("Segoe UI", 8.25F, FontStyle.Regular);

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            Color parentBg = this.Parent != null ? this.Parent.BackColor : Color.FromArgb(14, 17, 24);
            g.Clear(parentBg);

            Color idleBg = Color.FromArgb(20, 24, 34);
            Color hoverBg = _isPressed ? Color.FromArgb(18, 22, 32) : Color.FromArgb(26, 34, 48);
            Color curBg = InterpolateColor(idleBg, hoverBg, _hoverProgress);

            Color idleBorder = Color.FromArgb(38, 48, 64);
            Color hoverBorder = Color.FromArgb(56, 189, 248);
            Color curBorder = InterpolateColor(idleBorder, hoverBorder, _hoverProgress);

            ModernMainForm.DrawSmoothRoundedBox(g, 0, 0, this.Width, this.Height, 6f, curBg, curBorder, 1.0f);

            int cy = this.Height / 2;

            // Centered Content Calculation (Icon + Gap + Text)
            int iconW = 16;
            int gap = 8;
            int textW = TextRenderer.MeasureText("Hata kaydı oluştur", _btnFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix).Width;
            int totalContentW = iconW + gap + textW;
            int startX = (this.Width - totalContentW) / 2;

            // Network Activity Pulse / Heartbeat Icon
            Color iconColor = InterpolateColor(Color.FromArgb(148, 163, 184), Color.FromArgb(56, 189, 248), _hoverProgress);
            using (Pen ip = new Pen(iconColor, 1.35f))
            {
                ip.StartCap = LineCap.Round;
                ip.EndCap = LineCap.Round;
                Point[] pts = new Point[] {
                    new Point(startX, cy),
                    new Point(startX + 4, cy),
                    new Point(startX + 7, cy + 4),
                    new Point(startX + 10, cy - 5),
                    new Point(startX + 13, cy + 1),
                    new Point(startX + 16, cy)
                };
                g.DrawLines(ip, pts);
            }

            // "Hata kaydı oluştur" Text
            Color textColor = InterpolateColor(Color.FromArgb(203, 213, 225), Color.White, _hoverProgress);
            Rectangle textRect = new Rectangle(startX + iconW + gap, cy - 8, textW + 6, 16);
            TextRenderer.DrawText(g, "Hata kaydı oluştur", _btnFont, textRect, textColor, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
        }
    }

    // Modern Dark Custom DNS Dropdown Menu List Control (Replaces ContextMenuStrip)
    public class DnsDropdownMenuList : Control
    {
        internal const int RowHeight = 36;
        private const int SortAnimationDurationMs = 240;
        private const int MeasurementAnimationDurationMs = 220;
        private List<DnsOption> _options;
        private List<DnsOption> _displayOrder;
        private int _selectedIndex;
        private Action<int> _onSelect;
        private int _hoveredOptionId = -1;
        private readonly Dictionary<int, float> _hoverProgressById = new Dictionary<int, float>();
        private readonly Dictionary<int, float> _animationFrom = new Dictionary<int, float>();
        private readonly Dictionary<int, float> _animationTo = new Dictionary<int, float>();
        private readonly Dictionary<int, string> _measurementVisualStates = new Dictionary<int, string>();
        private readonly Dictionary<int, DateTime> _measurementAnimationStartedUtc = new Dictionary<int, DateTime>();
        private System.Windows.Forms.Timer _animationTimer;
        private DateTime _sortAnimationStartedUtc = DateTime.MinValue;
        private bool _isSortAnimating = false;
        private bool _protectionActive;
        private ToolTip _measurementToolTip;
        private string _lastMeasurementToolTipText = "";
        private int _scrollOffset = 0;

        public DnsDropdownMenuList(List<DnsOption> options, int selectedIndex, bool protectionActive, Action<int> onSelect)
        {
            _options = options;
            _selectedIndex = selectedIndex;
            _onSelect = onSelect;
            _protectionActive = protectionActive;
            _displayOrder = BuildSortedOrder();

            _measurementToolTip = new ToolTip();
            _measurementToolTip.InitialDelay = 450;
            _measurementToolTip.ReshowDelay = 100;
            _measurementToolTip.AutoPopDelay = 10000;
            _measurementToolTip.ShowAlways = true;

            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.Selectable, true);
            this.UpdateStyles();
            this.TabStop = true;

            this.Size = new Size(400, _options.Count * RowHeight + 8);
            this.BackColor = ThemePalette.Get(ModernMainForm.ActiveTheme).FormBg;
            this.Cursor = Cursors.Hand;
        }

        private int GetContentHeight()
        {
            return (_displayOrder != null ? _displayOrder.Count : 0) * RowHeight + 8;
        }

        private int GetMaximumScrollOffset()
        {
            return Math.Max(0, GetContentHeight() - this.Height);
        }

        public void SetViewportHeight(int height)
        {
            if (this.IsDisposed) return;
            int contentHeight = GetContentHeight();
            int minimumHeight = Math.Min(RowHeight, contentHeight);
            this.Height = Math.Max(minimumHeight, Math.Min(contentHeight, height));
            _scrollOffset = Math.Min(_scrollOffset, GetMaximumScrollOffset());
            this.Invalidate();
        }

        private bool IsDnsRowResponsive(DnsOption option)
        {
            return IsDnsMeasurementCurrent(option) &&
                option.DnsResponseCount >= DnsOption.MinimumValidDnsSamples && option.PingMs >= 0;
        }

        private bool IsDnsMeasurementCurrent(DnsOption option)
        {
            if (option == null || option.PingMeasuredUtc == DateTime.MinValue) return false;

            TimeSpan age = DateTime.UtcNow - option.PingMeasuredUtc;
            if (age.TotalSeconds < 0 || age.TotalSeconds > DnsOption.MaximumDnsMeasurementAgeSeconds) return false;

            // Koruma durumu tam eşleşiyorsa doğrudan geçerli
            if (option.DnsMeasurementProtectionActive == _protectionActive) return true;

            // Engelsiz alternatif port kullanan çözücüler (örn. Quad9 9953, OpenDNS 443)
            // WinDivert UDP:53 yönlendirmesinden bağımsızdır; ölçümleri koruma durumundan etkilenmez.
            if (!string.IsNullOrEmpty(option.DpiArgs))
            {
                if (option.DpiArgs.IndexOf("9953", StringComparison.Ordinal) >= 0 ||
                    option.DpiArgs.IndexOf("443", StringComparison.Ordinal) >= 0)
                {
                    return true;
                }
            }

            // Ölçüm 90 saniyeden yeniyse koruma geçişleri sırasında da güvenilir kabul et
            return age.TotalSeconds <= 90;
        }

        private string BuildMeasurementToolTip(DnsOption option)
        {
            if (option == null) return "";
            if (option.PingMeasuredUtc == DateTime.MinValue)
                return "Henüz ölçülmedi.";

            if (!IsDnsMeasurementCurrent(option) && option.DnsMeasurementProtectionActive != _protectionActive)
                return "Yeni ölçüm bekleniyor...";

            TimeSpan age = DateTime.UtcNow - option.PingMeasuredUtc;
            if (age.TotalSeconds < 0 || age.TotalSeconds > DnsOption.MaximumDnsMeasurementAgeSeconds)
                return "Yeniden ölçülüyor...";

            StringBuilder text = new StringBuilder();
            if (option.PingMs >= 0)
            {
                text.Append("Yanıt süresi: ");
                text.Append(option.PingMs == 0 ? "<1" : option.PingMs.ToString());
                text.AppendLine(" ms");
            }
            text.Append("Durum: ");
            if (option.DnsResponseCount > 0)
            {
                text.Append("Sorunsuz çalışıyor");
            }
            else if (!string.IsNullOrEmpty(option.DnsLastProbeError))
            {
                text.Append(option.DnsLastProbeError);
            }
            else
            {
                text.Append("Yanıt alınamadı");
            }
            text.AppendLine();
            text.Append("Son ölçüm: ");
            if (age.TotalSeconds < 60)
            {
                text.Append(Math.Max(0, (int)age.TotalSeconds));
                text.Append(" sn önce");
            }
            else if (age.TotalMinutes < 60)
            {
                text.Append((int)age.TotalMinutes);
                text.Append(" dk önce");
            }
            else
            {
                text.Append((int)age.TotalHours);
                text.Append(" sa önce");
            }
            return text.ToString();
        }

        private List<DnsOption> BuildSortedOrder()
        {
            List<DnsOption> order = new List<DnsOption>();
            if (_options == null) return order;

            DnsOption automatic = null;
            List<DnsOption> providers = new List<DnsOption>();
            for (int i = 0; i < _options.Count; i++)
            {
                DnsOption option = _options[i];
                if (option == null) continue;
                if (option.Id == 0) automatic = option;
                else providers.Add(option);
            }
            if (automatic != null) order.Add(automatic);

            providers.Sort(delegate(DnsOption left, DnsOption right)
            {
                bool leftResponsive = IsDnsRowResponsive(left);
                bool rightResponsive = IsDnsRowResponsive(right);
                if (leftResponsive != rightResponsive) return leftResponsive ? -1 : 1;
                if (leftResponsive && left.PingMs != right.PingMs) return left.PingMs.CompareTo(right.PingMs);
                return _options.IndexOf(left).CompareTo(_options.IndexOf(right));
            });
            order.AddRange(providers);
            return order;
        }

        private float GetCurrentRowOffset(int optionId, DateTime nowUtc)
        {
            float from;
            float to;
            if (_isSortAnimating && _animationFrom.TryGetValue(optionId, out from) && _animationTo.TryGetValue(optionId, out to))
            {
                double progress = (nowUtc - _sortAnimationStartedUtc).TotalMilliseconds / SortAnimationDurationMs;
                if (progress <= 0) return from;
                if (progress >= 1) return to;
                double eased = progress * progress * (3.0 - 2.0 * progress);
                return from + (float)((to - from) * eased);
            }

            if (_displayOrder != null)
            {
                for (int i = 0; i < _displayOrder.Count; i++)
                {
                    if (_displayOrder[i] != null && _displayOrder[i].Id == optionId) return i * RowHeight;
                }
            }
            return 0;
        }

        private void EnsureAnimationTimer()
        {
            if (this.IsDisposed) return;
            if (_animationTimer == null)
            {
                _animationTimer = new System.Windows.Forms.Timer();
                _animationTimer.Interval = 16;
                _animationTimer.Tick += new EventHandler(AnimationTimer_Tick);
            }
            if (!_animationTimer.Enabled) _animationTimer.Start();
        }

        private float GetHoverProgress(int optionId)
        {
            float progress;
            return _hoverProgressById.TryGetValue(optionId, out progress) ? progress : 0f;
        }

        private float GetMeasurementAnimationProgress(DnsOption option, DateTime nowUtc)
        {
            if (option == null) return 1f;
            bool isCurrent = IsDnsMeasurementCurrent(option);
            string visualState = isCurrent
                ? ((option.PingMs >= 0 ? option.PingMs.ToString() : "--") + ":" + option.DnsResponseCount.ToString())
                : "pending";
            string previousState;
            if (!_measurementVisualStates.TryGetValue(option.Id, out previousState))
            {
                _measurementVisualStates[option.Id] = visualState;
                return 1f;
            }
            if (!string.Equals(previousState, visualState, StringComparison.Ordinal))
            {
                _measurementVisualStates[option.Id] = visualState;
                _measurementAnimationStartedUtc[option.Id] = nowUtc;
                EnsureAnimationTimer();
                return 0f;
            }

            DateTime startedUtc;
            if (!_measurementAnimationStartedUtc.TryGetValue(option.Id, out startedUtc)) return 1f;
            double progress = (nowUtc - startedUtc).TotalMilliseconds / MeasurementAnimationDurationMs;
            if (progress >= 1.0)
            {
                _measurementAnimationStartedUtc.Remove(option.Id);
                return 1f;
            }
            if (progress <= 0.0) return 0f;
            return (float)(progress * progress * (3.0 - 2.0 * progress));
        }

        private void SetHoveredOption(int optionId)
        {
            if (_options != null && _selectedIndex >= 0 && _selectedIndex < _options.Count &&
                _options[_selectedIndex] != null && optionId == _options[_selectedIndex].Id)
            {
                optionId = -1;
            }
            if (_hoveredOptionId == optionId) return;
            _hoveredOptionId = optionId;
            if (_hoverProgressById.Count > 0 || optionId >= 0) EnsureAnimationTimer();
            this.Invalidate();
        }

        private void UpdateDisplayOrder(bool animate)
        {
            List<DnsOption> nextOrder = BuildSortedOrder();
            bool sameOrder = _displayOrder != null && _displayOrder.Count == nextOrder.Count;
            if (sameOrder)
            {
                for (int i = 0; i < nextOrder.Count; i++)
                {
                    if (_displayOrder[i] == null || nextOrder[i] == null || _displayOrder[i].Id != nextOrder[i].Id)
                    {
                        sameOrder = false;
                        break;
                    }
                }
            }
            if (sameOrder)
            {
                this.Invalidate();
                return;
            }

            DateTime nowUtc = DateTime.UtcNow;
            if (animate && this.IsHandleCreated && !this.IsDisposed && _displayOrder != null)
            {
                Dictionary<int, float> currentPositions = new Dictionary<int, float>();
                for (int i = 0; i < nextOrder.Count; i++)
                {
                    DnsOption option = nextOrder[i];
                    currentPositions[option.Id] = GetCurrentRowOffset(option.Id, nowUtc);
                }
                _animationFrom.Clear();
                _animationTo.Clear();
                for (int i = 0; i < nextOrder.Count; i++)
                {
                    DnsOption option = nextOrder[i];
                    _animationFrom[option.Id] = currentPositions[option.Id];
                    _animationTo[option.Id] = i * RowHeight;
                }
                _displayOrder = nextOrder;
                _sortAnimationStartedUtc = nowUtc;
                _isSortAnimating = true;
                EnsureAnimationTimer();
            }
            else
            {
                _animationFrom.Clear();
                _animationTo.Clear();
                _displayOrder = nextOrder;
                _isSortAnimating = false;
            }
            this.Invalidate();
        }

        private void AnimationTimer_Tick(object sender, EventArgs e)
        {
            DateTime nowUtc = DateTime.UtcNow;
            bool needsAnotherFrame = false;
            bool shouldInvalidate = false;
            if (_isSortAnimating) shouldInvalidate = true;
            if (_isSortAnimating && (nowUtc - _sortAnimationStartedUtc).TotalMilliseconds >= SortAnimationDurationMs)
            {
                _isSortAnimating = false;
                _animationFrom.Clear();
                _animationTo.Clear();
            }
            else if (_isSortAnimating)
            {
                needsAnotherFrame = true;
            }

            if (_hoverProgressById.Count > 0 || _hoveredOptionId >= 0)
            {
                List<int> hoverIds = new List<int>(_hoverProgressById.Keys);
                if (_hoveredOptionId >= 0 && !_hoverProgressById.ContainsKey(_hoveredOptionId))
                {
                    _hoverProgressById[_hoveredOptionId] = 0f;
                    hoverIds.Add(_hoveredOptionId);
                }
                for (int i = 0; i < hoverIds.Count; i++)
                {
                    int optionId = hoverIds[i];
                    float current = GetHoverProgress(optionId);
                    float target = optionId == _hoveredOptionId ? 1f : 0f;
                    float next = current + (target - current) * 0.32f;
                    if (Math.Abs(target - next) < 0.025f) next = target;
                    if (Math.Abs(current - next) > 0.001f) shouldInvalidate = true;
                    if (next <= 0f && target == 0f)
                    {
                        _hoverProgressById.Remove(optionId);
                    }
                    else
                    {
                        _hoverProgressById[optionId] = next;
                        if (Math.Abs(target - next) >= 0.025f) needsAnotherFrame = true;
                    }
                }
            }

            List<int> measurementIds = new List<int>(_measurementAnimationStartedUtc.Keys);
            for (int i = 0; i < measurementIds.Count; i++)
            {
                shouldInvalidate = true;
                if ((nowUtc - _measurementAnimationStartedUtc[measurementIds[i]]).TotalMilliseconds >= MeasurementAnimationDurationMs)
                {
                    _measurementAnimationStartedUtc.Remove(measurementIds[i]);
                }
                else
                {
                    needsAnotherFrame = true;
                }
            }

            if (shouldInvalidate) this.Invalidate();
            else if (_animationTimer != null) _animationTimer.Stop();
            if (!needsAnotherFrame && _animationTimer != null) _animationTimer.Stop();
        }

        private int HitTestOptionIndex(int y)
        {
            if (_displayOrder == null || _options == null) return -1;
            DateTime nowUtc = DateTime.UtcNow;
            int bestIndex = -1;
            float bestDistance = float.MaxValue;
            for (int i = 0; i < _displayOrder.Count; i++)
            {
                DnsOption option = _displayOrder[i];
                if (option == null) continue;
                float top = 4.0f + GetCurrentRowOffset(option.Id, nowUtc) - _scrollOffset;
                if (y < top || y >= top + RowHeight - 2.0f) continue;
                float distance = Math.Abs((top + (RowHeight - 2) / 2.0f) - y);
                if (distance < bestDistance)
                {
                    bestDistance = distance;
                    bestIndex = _options.IndexOf(option);
                }
            }
            return bestIndex;
        }

        public void RefreshMeasuredDns()
        {
            if (this.IsDisposed) return;
            UpdateDisplayOrder(true);
        }

        public void SetProtectionState(bool protectionActive)
        {
            if (this.IsDisposed || _protectionActive == protectionActive) return;
            _protectionActive = protectionActive;
            _lastMeasurementToolTipText = "";
            if (_measurementToolTip != null) _measurementToolTip.Hide(this);
            UpdateDisplayOrder(true);
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing && _animationTimer != null)
            {
                _animationTimer.Stop();
                _animationTimer.Dispose();
                _animationTimer = null;
            }
            if (disposing && _measurementToolTip != null)
            {
                _measurementToolTip.Dispose();
                _measurementToolTip = null;
            }
            base.Dispose(disposing);
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            int idx = HitTestOptionIndex(e.Y);
            int hoveredId = (idx >= 0 && idx < _options.Count) ? _options[idx].Id : -1;
            string toolTipText = (idx >= 0 && idx < _options.Count) ? BuildMeasurementToolTip(_options[idx]) : "";
            if (!string.Equals(toolTipText, _lastMeasurementToolTipText, StringComparison.Ordinal))
            {
                _lastMeasurementToolTipText = toolTipText;
                if (_measurementToolTip != null) _measurementToolTip.SetToolTip(this, toolTipText);
            }
            SetHoveredOption(hoveredId);
        }

        protected override void OnMouseEnter(EventArgs e)
        {
            base.OnMouseEnter(e);
            if (this.CanFocus) this.Focus();
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            base.OnMouseWheel(e);
            int maximum = GetMaximumScrollOffset();
            if (maximum <= 0 || e.Delta == 0) return;
            int steps = Math.Max(1, Math.Abs(e.Delta) / 120);
            int amount = RowHeight * 2 * steps;
            int nextOffset = _scrollOffset + (e.Delta < 0 ? amount : -amount);
            nextOffset = Math.Max(0, Math.Min(maximum, nextOffset));
            if (nextOffset == _scrollOffset) return;
            _scrollOffset = nextOffset;
            SetHoveredOption(-1);
            this.Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            SetHoveredOption(-1);
            _lastMeasurementToolTipText = "";
            if (_measurementToolTip != null) _measurementToolTip.SetToolTip(this, "");
            this.Invalidate();
        }

        protected override void OnMouseClick(MouseEventArgs e)
        {
            base.OnMouseClick(e);
            if (e.Button != MouseButtons.Left) return;
            int idx = HitTestOptionIndex(e.Y);
            if (idx >= 0 && idx < _options.Count)
            {
                if (_onSelect != null) _onSelect(idx);
            }
        }

        private static readonly Font _itemTitleBoldFont = new Font("Segoe UI", 10.0F, FontStyle.Bold);
        private static readonly Font _itemTitleRegularFont = new Font("Segoe UI", 10.0F, FontStyle.Regular);
        private static readonly Font _itemTagFont = new Font("Segoe UI", 9.25F, FontStyle.Bold);

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            using (SolidBrush bgB = new SolidBrush(this.BackColor))
            {
                g.FillRectangle(bgB, 0, 0, this.Width, this.Height);
            }

            ThemePalette theme = ThemePalette.Get(ModernMainForm.ActiveTheme);
            int itemH = RowHeight;
            DateTime paintUtc = DateTime.UtcNow;
            for (int i = 0; i < _displayOrder.Count; i++)
            {
                DnsOption opt = _displayOrder[i];
                int sourceIndex = _options.IndexOf(opt);
                int itemY = 4 + (int)Math.Round(GetCurrentRowOffset(opt.Id, paintUtc)) - _scrollOffset;
                int itemCardH = itemH - 2;

                bool isSel = (sourceIndex == _selectedIndex);
                float hoverProgress = GetHoverProgress(opt.Id);
                int hoverAlpha = (int)Math.Round(255f * hoverProgress);
                Color rowSurfaceBg = this.BackColor;

                // Row background highlight
                if (isSel)
                {
                    rowSurfaceBg = theme.CardBg;
                    ModernMainForm.DrawSmoothRoundedBox(g, 5, itemY, this.Width - 10, itemCardH, 6f, rowSurfaceBg, theme.BorderHoverColor, 1.0f);
                }
                else if (hoverProgress > 0.01f)
                {
                    rowSurfaceBg = ModernMainForm.BlendOver(this.BackColor, theme.CardHover, hoverAlpha);
                    Color hoverBorder = ModernMainForm.BlendOver(this.BackColor, theme.BorderColor, hoverAlpha);
                    ModernMainForm.DrawSmoothRoundedBox(g, 5, itemY, this.Width - 10, itemCardH, 6f, rowSurfaceBg, hoverBorder, 1.0f);
                }

                int cy = itemY + (itemCardH / 2);

                // Left Radio Indicator on EVERY row for complete visual balance & symmetry
                int rD = 12;
                int rx = 14;
                int ry = cy - (rD / 2);
                if (isSel)
                {
                    using (Pen rBorder = new Pen(theme.SecondaryAccent, 1.5f))
                    using (SolidBrush dotB = new SolidBrush(theme.SecondaryAccent))
                    {
                        g.DrawEllipse(rBorder, rx, ry, rD, rD);
                        g.FillEllipse(dotB, rx + 3, ry + 3, 6, 6);
                    }
                }
                else
                {
                    Color rClr = ModernMainForm.BlendOver(theme.BorderColor, theme.BorderHoverColor, hoverAlpha);
                    using (Pen rBorder = new Pen(rClr, 1.2f))
                    {
                        g.DrawEllipse(rBorder, rx, ry, rD, rD);
                    }
                }

                // Sağdaki durum rozetinden bağımsız deney/yedek etiketi
                int titleAlpha = (int)Math.Round(255f * hoverProgress);
                Color titleClr = isSel ? theme.TextPrimary : ModernMainForm.BlendOver(theme.TextMuted, theme.TextPrimary, titleAlpha);
                Font titleFont = isSel ? _itemTitleBoldFont : _itemTitleRegularFont;
                bool hasRowTag = opt.Id != 0 && !string.IsNullOrEmpty(opt.Tag);
                bool isExperimental = hasRowTag && string.Equals(opt.Tag, "DENEY", StringComparison.Ordinal);
                int titleWidth = hasRowTag ? 116 : 185;
                Rectangle titleRect = new Rectangle(34, itemY, titleWidth, itemCardH);
                TextRenderer.DrawText(g, opt.DisplayName, titleFont, titleRect, titleClr, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);

                if (hasRowTag)
                {
                    Size tagSize = TextRenderer.MeasureText(g, opt.Tag, _itemTagFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
                    int tagW = tagSize.Width + 12;
                    int tagX = titleRect.Right + 6;
                    Rectangle tagRect = new Rectangle(tagX, cy - 8, tagW, 16);
                    Color tagAccent = isExperimental ? Color.FromArgb(245, 158, 11) : opt.TagColor;
                    Color tagBg = ModernMainForm.BlendOver(rowSurfaceBg, tagAccent, 20);
                    Color tagBorder = ModernMainForm.BlendOver(rowSurfaceBg, tagAccent, 68);
                    using (SolidBrush tagBrush = new SolidBrush(tagBg))
                    using (Pen tagPen = new Pen(tagBorder, 1f))
                    using (GraphicsPath tagPath = ModernMainForm.CreateRoundedRectangleF(new RectangleF(tagRect.X, tagRect.Y, tagRect.Width, tagRect.Height), 6f))
                    {
                        g.FillPath(tagBrush, tagPath);
                        g.DrawPath(tagPen, tagPath);
                    }
                    TextRenderer.DrawText(g, opt.Tag, _itemTagFont, tagRect, tagAccent,
                        TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
                }

                // Sağ rozet yalnızca ölçüm durumu veya DNS yanıt süresini gösterir.
                int badgeW = 78;
                int badgeH = 22;
                int badgeX = this.Width - badgeW - 12;
                int badgeY = cy - (badgeH / 2);

                string badgeText;
                Color bgClr;
                Color borderClr;
                Color textClr;
                Color dotClr = Color.Transparent;

                if (!IsDnsMeasurementCurrent(opt))
                {
                    badgeText = "-- ms";
                    Color pendingClr = Color.FromArgb(148, 163, 184);
                    bgClr = ModernMainForm.BlendOver(rowSurfaceBg, pendingClr, 18);
                    borderClr = ModernMainForm.BlendOver(rowSurfaceBg, pendingClr, 58);
                    textClr = pendingClr;
                }
                else if (opt.DnsResponseCount > 0 && opt.PingMs >= 0)
                {
                    badgeText = (opt.PingMs == 0) ? "<1 ms" : (opt.PingMs + " ms");
                    if (opt.PingMs <= 30)
                    {
                        // <= 30 ms: Yeşil
                        Color gClr = Color.FromArgb(52, 211, 153);
                        bgClr = ModernMainForm.BlendOver(rowSurfaceBg, gClr, 24);
                        borderClr = ModernMainForm.BlendOver(rowSurfaceBg, gClr, 80);
                        textClr = gClr;
                        dotClr = gClr;
                    }
                    else if (opt.PingMs <= 65)
                    {
                        // 31-65 ms: Sarı
                        Color yClr = Color.FromArgb(234, 179, 8);
                        bgClr = ModernMainForm.BlendOver(rowSurfaceBg, yClr, 26);
                        borderClr = ModernMainForm.BlendOver(rowSurfaceBg, yClr, 80);
                        textClr = Color.FromArgb(250, 204, 21);
                        dotClr = yClr;
                    }
                    else
                    {
                        // >= 66 ms: Kırmızı
                        Color rClr = Color.FromArgb(239, 68, 68);
                        bgClr = ModernMainForm.BlendOver(rowSurfaceBg, rClr, 26);
                        borderClr = ModernMainForm.BlendOver(rowSurfaceBg, rClr, 80);
                        textClr = Color.FromArgb(248, 113, 113);
                        dotClr = rClr;
                    }
                }
                else
                {
                    badgeText = "Yanıt yok";
                    Color statusClr = Color.FromArgb(239, 68, 68);
                    bgClr = ModernMainForm.BlendOver(rowSurfaceBg, statusClr, 26);
                    borderClr = ModernMainForm.BlendOver(rowSurfaceBg, statusClr, 80);
                    textClr = Color.FromArgb(248, 113, 113);
                    dotClr = statusClr;
                }

                float measurementProgress = GetMeasurementAnimationProgress(opt, paintUtc);
                if (measurementProgress < 1f)
                {
                    int measurementAlpha = (int)Math.Round(255f * measurementProgress);
                    bgClr = ModernMainForm.BlendOver(rowSurfaceBg, bgClr, measurementAlpha);
                    borderClr = ModernMainForm.BlendOver(rowSurfaceBg, borderClr, measurementAlpha);
                    textClr = ModernMainForm.BlendOver(rowSurfaceBg, textClr, measurementAlpha);
                    if (dotClr != Color.Transparent)
                    {
                        dotClr = ModernMainForm.BlendOver(rowSurfaceBg, dotClr, measurementAlpha);
                    }
                }

                // Rozet Arka Planı ve Yumuşak Kenarlık
                ModernMainForm.DrawSmoothRoundedBox(g, badgeX, badgeY, badgeW, badgeH, 6f, bgClr, borderClr, 1.0f);

                // Canlı ping rozetinde sol tarafa şık minik durum noktası (Live Pulse Dot)
                if (dotClr != Color.Transparent)
                {
                    int dotSize = 6;
                    int dotX = badgeX + 9;
                    int dotY = cy - (dotSize / 2);
                    using (SolidBrush db = new SolidBrush(dotClr))
                    {
                        g.FillEllipse(db, dotX, dotY, dotSize, dotSize);
                    }
                    Rectangle textRectWithDot = new Rectangle(badgeX + 16, badgeY, badgeW - 18, badgeH);
                    TextRenderer.DrawText(g, badgeText, _itemTagFont, textRectWithDot, textClr, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
                }
                else
                {
                    Rectangle badgeTextRect = new Rectangle(badgeX, badgeY, badgeW, badgeH);
                    TextRenderer.DrawText(g, badgeText, _itemTagFont, badgeTextRect, textClr, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
                }
            }

            // Outer menu border
            g.SmoothingMode = SmoothingMode.None;
            g.PixelOffsetMode = PixelOffsetMode.Default;
            using (Pen borderPen = new Pen(theme.BorderColor, 1f))
            {
                g.DrawRectangle(borderPen, 0, 0, this.Width - 1, this.Height - 1);
            }
        }
    }

    // 3. Modern Rounded Button (Flawless anti-aliasing, vibrant interactive hover glow & illuminated borders)
    public class RoundedButton : Button
    {
        public int BorderRadius { get; set; }
        public Color BorderColor { get; set; }
        public Color HoverColor { get; set; }
        public Color HoverBorderColor { get; set; }
        public Color GlowColor { get; set; }
        public bool UseGradient { get; set; }
        public string IconType { get; set; }
        public string WatermarkText { get; set; }
        public int WatermarkMode { get; set; }
        // Ölçüm geri bildirimi: doluyken BusyText + dönen refresh ikonu
        public bool SpinWhenBusy { get; set; }
        public string BusyText { get; set; }
        // Boşta nazik nabız parlaması (opt-in)
        public bool SoftPulse { get; set; }
        // Kart gibi desenli zeminler üstünde duran düğmeler için köşe temizliği zemini
        // (verilmezse ebeveyn arka planı kullanılır).
        public Color BackdropColor { get; set; }

        private bool _busy = false;
        private float _spinAngle = 0f;
        private System.Windows.Forms.Timer _spinDriver;
        private System.Windows.Forms.Timer _pulseDriver;
        private float _pulsePhase = 0f;
        private int _pulseAlpha = 0;

        public bool IsBusy
        {
            get { return _busy; }
            set
            {
                if (_busy == value) return;
                _busy = value;
                if (_busy)
                {
                    _spinAngle = 0f;
                    EnsureSpinDriver();
                }
                else if (_spinDriver != null)
                {
                    _spinDriver.Stop();
                }
                this.Invalidate();
            }
        }

        private bool _isHovered = false;
        private bool _isPressed = false;
        private Font _ownFont;                            // sınıfın sahiplendiği taban font (Dispose'da bırakılır)
        private System.Windows.Forms.Timer _hoverDriver;  // harici animasyon sürücüsü olmayan formlarda hover motoru
        private float _hoverProgress = 0f;
        // Paint sıcak yolunda her karede font oluşturmamak için süreç ömrü boyunca paylaşılan önbellek.
        private static readonly Font _watermarkFont = new Font("Segoe UI", 6.5f, FontStyle.Bold);
        // Emoji glifleri (♻ / ✖) GraphicsPath ile mürekkep-merkezli çizilir; font ailesi burada paylaşılır.
        private static readonly Font _emojiGlyphFont = new Font("Segoe UI Emoji", 11.5F, FontStyle.Regular);

        public RoundedButton()
        {
            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
            this.UpdateStyles();

            this.FlatStyle = FlatStyle.Flat;
            this.FlatAppearance.BorderSize = 0;
            this.ForeColor = Color.FromArgb(226, 232, 240);
            _ownFont = new Font("Segoe UI", 8.25F, FontStyle.Bold);
            this.Font = _ownFont;
            BorderRadius = 8;
            BorderColor = Color.Transparent;
            HoverColor = Color.FromArgb(68, 150, 255);
            HoverBorderColor = Color.Empty;
            GlowColor = Color.Empty;
            UseGradient = false;
            IconType = "";
            WatermarkText = "";
            WatermarkMode = 0;
            SpinWhenBusy = false;
            BusyText = "";
            SoftPulse = false;
        }

        // Hover animasyonunu kendi içinde sürer: log görüntüleyici, güncelleme diyaloğu gibi
        // UpdateAnimation'ı düzenli çağırmayan formlarda hover bu yüzden ölü kalıyordu.
        private void EnsureHoverDriver()
        {
            if (this.IsDisposed || !this.IsHandleCreated) return;
            if (_hoverDriver == null)
            {
                _hoverDriver = new System.Windows.Forms.Timer();
                _hoverDriver.Interval = 30;
                _hoverDriver.Tick += delegate
                {
                    if (this.IsDisposed) return;
                    UpdateAnimation();
                    float tgt = _isHovered ? 1.0f : 0.0f;
                    if (Math.Abs(_hoverProgress - tgt) <= 0.02f && _hoverDriver != null)
                    {
                        _hoverDriver.Stop(); // hedefe ulaşıldı: boş yere CPU harcama
                    }
                };
            }
            _hoverDriver.Start();
        }

        // Ölçüm sürerken refresh ikonunu döndüren sürücü
        private void EnsureSpinDriver()
        {
            if (this.IsDisposed || !this.IsHandleCreated) return;
            if (_spinDriver == null)
            {
                _spinDriver = new System.Windows.Forms.Timer();
                _spinDriver.Interval = 30;
                _spinDriver.Tick += delegate
                {
                    if (this.IsDisposed || !_busy)
                    {
                        if (_spinDriver != null) _spinDriver.Stop();
                        return;
                    }
                    _spinAngle += 30f;
                    if (_spinAngle >= 360f) _spinAngle -= 360f;
                    this.Invalidate();
                };
            }
            _spinDriver.Start();
        }

        // Boşta nazik parlama nabzı: yalnızca form aktifken repaint eder
        private void EnsurePulseDriver()
        {
            if (!SoftPulse || this.IsDisposed || !this.IsHandleCreated) return;
            if (_pulseDriver == null)
            {
                _pulseDriver = new System.Windows.Forms.Timer();
                _pulseDriver.Interval = 40;
                _pulseDriver.Tick += delegate
                {
                    if (this.IsDisposed) return;
                    Form pf = this.FindForm();
                    if (pf == null || !pf.Visible || pf.WindowState == FormWindowState.Minimized || Form.ActiveForm != pf || !this.Enabled)
                    {
                        return;
                    }
                    _pulsePhase += 0.085f;
                    if (_pulsePhase > 6.2831855f) _pulsePhase -= 6.2831855f;
                    _pulseAlpha = (int)((0.5f + 0.5f * (float)Math.Sin(_pulsePhase)) * 22f);
                    this.Invalidate();
                };
            }
            _pulseDriver.Start();
        }

        protected override void OnHandleCreated(EventArgs e)
        {
            base.OnHandleCreated(e);
            if (_busy) EnsureSpinDriver();
            if (SoftPulse) EnsurePulseDriver();
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                if (_hoverDriver != null) { try { _hoverDriver.Stop(); _hoverDriver.Dispose(); } catch {} _hoverDriver = null; }
                if (_spinDriver != null) { try { _spinDriver.Stop(); _spinDriver.Dispose(); } catch {} _spinDriver = null; }
                if (_pulseDriver != null) { try { _pulseDriver.Stop(); _pulseDriver.Dispose(); } catch {} _pulseDriver = null; }
                if (_ownFont != null) { try { _ownFont.Dispose(); } catch {} _ownFont = null; }
            }
            base.Dispose(disposing);
        }

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == 0x0021) // WM_MOUSEACTIVATE
            {
                m.Result = (IntPtr)1; // MA_ACTIVATE
                return;
            }
            base.WndProc(ref m);
        }

        public void UpdateAnimation()
        {
            if (this.Visible && this.Enabled && !this.IsDisposed && this.IsHandleCreated)
            {
                Form parent = this.FindForm();
                if (parent != null && parent.Visible && parent.WindowState != FormWindowState.Minimized)
                {
                    Point curPos = Cursor.Position;
                    Point clientPt = this.PointToClient(curPos);
                    if (this.ClientRectangle.Contains(clientPt))
                    {
                        _isHovered = true;
                    }
                    else
                    {
                        _isHovered = false;
                    }
                }
                else
                {
                    _isHovered = false;
                }
            }
            else
            {
                _isHovered = false;
            }

            float target = _isHovered ? 1.0f : 0.0f;
            if (Math.Abs(_hoverProgress - target) > 0.02f)
            {
                _hoverProgress += (target - _hoverProgress) * 0.30f;
                this.Invalidate();
            }
            else if (_hoverProgress != target)
            {
                _hoverProgress = target;
                this.Invalidate();
            }
        }

        protected override void OnMouseEnter(EventArgs e)
        {
            base.OnMouseEnter(e);
            _isHovered = true;
            EnsureHoverDriver();
            this.Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            _isHovered = false;
            _isPressed = false;
            EnsureHoverDriver();
            this.Invalidate();
        }

        protected override void OnMouseDown(MouseEventArgs mevent)
        {
            base.OnMouseDown(mevent);
            if (mevent.Button == MouseButtons.Left)
            {
                _isPressed = true;
                this.Invalidate();
            }
        }

        protected override void OnMouseUp(MouseEventArgs mevent)
        {
            base.OnMouseUp(mevent);
            _isPressed = false;
            this.Invalidate();
        }

        protected override void OnPaint(PaintEventArgs pevent)
        {
            Graphics g = pevent.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            // Köşeleri zemine birebir temizle: kart üstündeki düğmeler BackdropColor ile zeminini bildirir.
            Color parentBg = (BackdropColor != Color.Empty)
                ? BackdropColor
                : (this.Parent != null ? this.Parent.BackColor : Color.FromArgb(14, 17, 24));
            g.Clear(parentBg);

            RectangleF rect = new RectangleF(1.0f, 1.0f, this.Width - 2.0f, this.Height - 2.0f);
            if (_isPressed)
            {
                rect.Y += 1.0f;
                rect.Height -= 1.0f;
            }

            Color currentBase = InterpolateColor(this.BackColor, this.HoverColor, _hoverProgress);
            Color textClr = this.ForeColor;

            if (!this.Enabled)
            {
                currentBase = Color.FromArgb(20, 24, 34);
                textClr = Color.FromArgb(100, 116, 139);
            }
            else if (_isPressed)
            {
                currentBase = Color.FromArgb(Math.Max(0, currentBase.R - 25), Math.Max(0, currentBase.G - 25), Math.Max(0, currentBase.B - 25));
            }

            // 3. Illuminated Border (Vibrant crisp highlight on hover)
            Color curBorder;
            if (!this.Enabled)
            {
                curBorder = Color.FromArgb(32, 40, 56);
            }
            else
            {
                Color idleB = (BorderColor != Color.Transparent && BorderColor != Color.Empty)
                    ? BorderColor
                    : (UseGradient ? Color.FromArgb(60, BackColor.R, BackColor.G, BackColor.B) : Color.FromArgb(42, 50, 68));
                Color hovB = (HoverBorderColor != Color.Empty)
                    ? HoverBorderColor
                    : (UseGradient ? Color.FromArgb(210, Math.Min(255, HoverColor.R + 60), Math.Min(255, HoverColor.G + 60), Math.Min(255, HoverColor.B + 60)) : Color.FromArgb(90, 125, 185));
                curBorder = InterpolateColor(idleB, hovB, _hoverProgress);
            }

            using (GraphicsPath path = ModernMainForm.CreateRoundedRectangleF(rect, (float)BorderRadius))
            {
                // 1. Soft Ambient Outer Glow on hover
                if (this.Enabled && _hoverProgress > 0.03f)
                {
                    Color glowBase = (GlowColor != Color.Empty && GlowColor.A != 0) ? GlowColor : (UseGradient ? this.HoverColor : Color.FromArgb(59, 130, 246));
                    int maxAlpha = UseGradient ? 65 : 40;
                    int glowAlpha = (int)(maxAlpha * _hoverProgress);
                    using (Pen glowPen = new Pen(Color.FromArgb(glowAlpha, glowBase.R, glowBase.G, glowBase.B), 2.0f))
                    {
                        glowPen.LineJoin = LineJoin.Round;
                        g.DrawPath(glowPen, path);
                    }
                }

                // 1b. Boşta nabız parlaması (opt-in; hover'da sönümlenir)
                if (this.Enabled && SoftPulse && _pulseAlpha > 0)
                {
                    int pulseA = (int)(_pulseAlpha * (1.0f - 0.6f * _hoverProgress));
                    if (pulseA > 0)
                    {
                        Color pulseBase = (GlowColor != Color.Empty && GlowColor.A != 0) ? GlowColor : (UseGradient ? this.HoverColor : Color.FromArgb(59, 130, 246));
                        using (Pen pulsePen = new Pen(Color.FromArgb(pulseA, pulseBase.R, pulseBase.G, pulseBase.B), 2.0f))
                        {
                            pulsePen.LineJoin = LineJoin.Round;
                            g.DrawPath(pulsePen, path);
                        }
                    }
                }

                // 2. Button Body Surface + Concentric Border
                if (UseGradient && this.Enabled)
                {
                    Color topClr = InterpolateColor(
                        Color.FromArgb(Math.Min(255, this.BackColor.R + 8), Math.Min(255, this.BackColor.G + 8), Math.Min(255, this.BackColor.B + 8)),
                        Color.FromArgb(Math.Min(255, this.HoverColor.R + 15), Math.Min(255, this.HoverColor.G + 15), Math.Min(255, this.HoverColor.B + 15)),
                        _hoverProgress);
                    Color btmClr = InterpolateColor(
                        Color.FromArgb(Math.Max(0, this.BackColor.R - 18), Math.Max(0, this.BackColor.G - 18), Math.Max(0, this.BackColor.B - 18)),
                        this.BackColor,
                        _hoverProgress);

                    if (_isPressed)
                    {
                        topClr = Color.FromArgb(Math.Max(0, topClr.R - 25), Math.Max(0, topClr.G - 25), Math.Max(0, topClr.B - 25));
                        btmClr = Color.FromArgb(Math.Max(0, btmClr.R - 25), Math.Max(0, btmClr.G - 25), Math.Max(0, btmClr.B - 25));
                    }

                    Color opaqueBorder = ModernMainForm.BlendOver(topClr, curBorder);
                    using (SolidBrush borderB = new SolidBrush(opaqueBorder))
                    {
                        g.FillPath(borderB, path);
                    }

                    RectangleF innerRect = new RectangleF(rect.X + 1.0f, rect.Y + 1.0f, rect.Width - 2.0f, rect.Height - 2.0f);
                    float innerR = Math.Max(1.0f, (float)BorderRadius - 1.0f);
                    using (GraphicsPath innerPath = ModernMainForm.CreateRoundedRectangleF(innerRect, innerR))
                    using (LinearGradientBrush lgb = new LinearGradientBrush(innerRect, topClr, btmClr, LinearGradientMode.Vertical))
                    {
                        g.FillPath(lgb, innerPath);
                    }

                    // 4. Top specular micro-glint line
                    int glintAlpha = (int)(45 + 130 * _hoverProgress);
                    Color glintColor = ModernMainForm.BlendOver(topClr, Color.FromArgb(glintAlpha, 255, 255, 255));
                    using (SolidBrush glintB = new SolidBrush(glintColor))
                    {
                        float gx = rect.X + BorderRadius;
                        float gw = rect.Width - BorderRadius * 2;
                        if (gw > 2.0f)
                        {
                            g.FillRectangle(glintB, gx, rect.Y + 1.0f, gw, 1.0f);
                        }
                    }
                }
                else
                {
                    Color opaqueFill = ModernMainForm.BlendOver(parentBg, currentBase);
                    Color opaqueBorder = ModernMainForm.BlendOver(opaqueFill, curBorder);
                    ModernMainForm.DrawSmoothRoundedBox(g, rect, (float)BorderRadius, opaqueFill, opaqueBorder, 1.0f);
                }
            }

            // 5. Icon & Text Rendering
            string shownText = (_busy && !string.IsNullOrEmpty(BusyText)) ? BusyText : this.Text;
            Size textSize = TextRenderer.MeasureText(shownText, this.Font, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
            bool hasIcon = (IconType == "play" || IconType == "stop" || IconType == "plus" || IconType == "copy" || IconType == "file" || IconType == "refresh" || IconType == "download" || IconType == "wrench" || IconType == "gamepad" || IconType == "bolt" || IconType == "pulse" || IconType == "recycle" || IconType == "close");
            int iconW = (IconType == "plus") ? 10 : ((IconType == "copy" || IconType == "file" || IconType == "refresh" || IconType == "download" || IconType == "wrench" || IconType == "gamepad" || IconType == "bolt" || IconType == "pulse") ? 14 : 12);
            int gap = (IconType == "plus") ? 6 : ((IconType == "copy" || IconType == "file" || IconType == "refresh" || IconType == "download" || IconType == "wrench" || IconType == "gamepad" || IconType == "bolt" || IconType == "pulse") ? 7 : 8);
            int totalW = hasIcon ? (iconW + gap + textSize.Width) : textSize.Width;
            int startX = (this.Width - totalW) / 2;
            // Metinsiz ikon butonlarında ikon tek başına tam ortalanır (örn. Bağlantı Kalitesi alt barı)
            if (hasIcon && shownText.Length == 0)
            {
                startX = (this.Width - 12) / 2;
            }

            if (IconType == "play")
            {
                int iconX = startX + 5;
                int iconY = this.Height / 2;
                PointF[] playPts = new PointF[] {
                    new PointF(iconX - 4.5f, iconY - 5.5f),
                    new PointF(iconX + 5.5f, iconY),
                    new PointF(iconX - 4.5f, iconY + 5.5f)
                };
                using (SolidBrush iconB = new SolidBrush(textClr))
                {
                    g.FillPolygon(iconB, playPts);
                }
            }
            else if (IconType == "stop")
            {
                int iconX = startX + 5;
                int iconY = this.Height / 2 - 5;
                RectangleF stopRect = new RectangleF(iconX - 5f, iconY, 10f, 10f);
                using (GraphicsPath stopPath = ModernMainForm.CreateRoundedRectangleF(stopRect, 2f))
                using (SolidBrush iconB = new SolidBrush(textClr))
                {
                    g.FillPath(iconB, stopPath);
                }
            }
            else if (IconType == "plus")
            {
                int iconX = startX + 5;
                int iconY = this.Height / 2;
                float arm = 4.0f;
                using (Pen plusPen = new Pen(textClr, 1.3f))
                {
                    plusPen.StartCap = LineCap.Round;
                    plusPen.EndCap = LineCap.Round;
                    g.DrawLine(plusPen, iconX - arm, iconY, iconX + arm, iconY);
                    g.DrawLine(plusPen, iconX, iconY - arm, iconX, iconY + arm);
                }
            }
            else if (IconType == "copy")
            {
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                using (Pen cp = new Pen(textClr, 1.25f))
                {
                    g.DrawRectangle(cp, iconX - 5, iconY - 5, 8, 9);
                    g.DrawRectangle(cp, iconX - 2, iconY - 2, 8, 9);
                }
            }
            else if (IconType == "file")
            {
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                using (Pen fp = new Pen(textClr, 1.25f))
                {
                    fp.StartCap = LineCap.Round;
                    fp.EndCap = LineCap.Round;
                    g.DrawRectangle(fp, iconX - 5, iconY - 6, 10, 12);
                    g.DrawLine(fp, iconX - 2, iconY - 2, iconX + 2, iconY - 2);
                    g.DrawLine(fp, iconX - 2, iconY + 1, iconX + 2, iconY + 1);
                }
            }
            else if (IconType == "refresh")
            {
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                bool spin = _busy && SpinWhenBusy;
                GraphicsState iconState = null;
                if (spin)
                {
                    iconState = g.Save();
                    g.TranslateTransform(iconX, iconY);
                    g.RotateTransform(_spinAngle);
                    g.TranslateTransform(-iconX, -iconY);
                }
                using (Pen rp = new Pen(textClr, 1.3f))
                {
                    rp.StartCap = LineCap.Round;
                    rp.EndCap = LineCap.Round;
                    g.DrawArc(rp, iconX - 5, iconY - 5, 10, 10, 45, 270);
                    g.DrawLine(rp, iconX + 3, iconY - 6, iconX + 5, iconY - 3);
                    g.DrawLine(rp, iconX + 1, iconY - 3, iconX + 5, iconY - 3);
                }
                if (iconState != null) g.Restore(iconState);
            }
            else if (IconType == "download")
            {
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                using (Pen dp = new Pen(textClr, 1.4f))
                {
                    dp.StartCap = LineCap.Round;
                    dp.EndCap = LineCap.Round;
                    dp.LineJoin = LineJoin.Round;
                    g.DrawLine(dp, iconX, iconY - 5, iconX, iconY + 2);
                    g.DrawLine(dp, iconX - 3, iconY - 1, iconX, iconY + 2);
                    g.DrawLine(dp, iconX + 3, iconY - 1, iconX, iconY + 2);
                    g.DrawLine(dp, iconX - 5, iconY + 5, iconX + 5, iconY + 5);
                }
            }
            else if (IconType == "wrench")
            {
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                using (Pen wp = new Pen(textClr, 1.35f))
                {
                    wp.StartCap = LineCap.Round;
                    wp.EndCap = LineCap.Round;
                    wp.LineJoin = LineJoin.Round;
                    g.DrawLine(wp, iconX - 5.5f, iconY + 5.5f, iconX + 0.5f, iconY - 0.5f);
                    g.DrawArc(wp, iconX - 2.5f, iconY - 6.5f, 7.5f, 7.5f, -60, 240);
                    g.DrawEllipse(wp, iconX - 7f, iconY + 4f, 2.5f, 2.5f);
                }
            }
            else if (IconType == "gamepad")
            {
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                using (Pen gp = new Pen(textClr, 1.25f))
                {
                    gp.LineJoin = LineJoin.Round;
                    RectangleF gpRect = new RectangleF(iconX - 6.5f, iconY - 4.5f, 13f, 9f);
                    using (GraphicsPath gpPath = ModernMainForm.CreateRoundedRectangleF(gpRect, 3.5f))
                    {
                        g.DrawPath(gp, gpPath);
                    }
                    // D-pad cross on left
                    g.DrawLine(gp, iconX - 4.5f, iconY, iconX - 2f, iconY);
                    g.DrawLine(gp, iconX - 3.25f, iconY - 1.25f, iconX - 3.25f, iconY + 1.25f);
                    // Action buttons dots on right
                    g.DrawLine(gp, iconX + 2f, iconY - 1f, iconX + 4.5f, iconY - 1f);
                    g.DrawLine(gp, iconX + 2f, iconY + 1f, iconX + 4.5f, iconY + 1f);
                }
            }
            else if (IconType == "bolt")
            {
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                PointF[] boltPts = new PointF[] {
                    new PointF(iconX + 0.8f, iconY - 6f),
                    new PointF(iconX - 4f, iconY),
                    new PointF(iconX - 0.8f, iconY),
                    new PointF(iconX - 2.2f, iconY + 6f),
                    new PointF(iconX + 4f, iconY - 0.8f),
                    new PointF(iconX + 0.8f, iconY - 0.8f)
                };
                using (SolidBrush bb = new SolidBrush(textClr))
                {
                    g.FillPolygon(bb, boltPts);
                }
            }
            else if (IconType == "pulse")
            {
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                using (Pen ip = new Pen(textClr, 1.25f))
                {
                    ip.StartCap = LineCap.Round;
                    ip.EndCap = LineCap.Round;
                    ip.LineJoin = LineJoin.Round;
                    PointF[] pts = new PointF[] {
                        new PointF(iconX - 6.5f, iconY),
                        new PointF(iconX - 3.5f, iconY),
                        new PointF(iconX - 1.5f, iconY + 4f),
                        new PointF(iconX + 1.5f, iconY - 5f),
                        new PointF(iconX + 3.5f, iconY + 2f),
                        new PointF(iconX + 6.5f, iconY)
                    };
                    g.DrawLines(ip, pts);
                }
            }
            else if (IconType == "recycle" || IconType == "close")
            {
                // Segoe UI Emoji glifini (♻ / ✖) mürekkep sınırlarına göre tam ortalayarak çiz.
                int iconX = startX + 6;
                int iconY = this.Height / 2;
                string glyph = (IconType == "recycle") ? "\u267B" : "\u2716";
                using (GraphicsPath glyphPath = new GraphicsPath())
                {
                    float emPx = _emojiGlyphFont.Size * 96f / 72f;
                    glyphPath.AddString(glyph, _emojiGlyphFont.FontFamily, (int)FontStyle.Regular, emPx,
                        new PointF(0f, 0f), StringFormat.GenericTypographic);
                    RectangleF gb = glyphPath.GetBounds();
                    if (gb.Width > 0f && gb.Height > 0f)
                    {
                        using (Matrix shift = new Matrix())
                        {
                            shift.Translate(iconX - (gb.X + gb.Width / 2f), iconY - (gb.Y + gb.Height / 2f));
                            glyphPath.Transform(shift);
                        }
                        using (SolidBrush glyphBrush = new SolidBrush(textClr))
                        {
                            g.FillPath(glyphBrush, glyphPath);
                        }
                    }
                }
            }

            // Draw semi-transparent Watermark text in right corner if specified
            int wmX = 0;
            if (!string.IsNullOrEmpty(WatermarkText))
            {
                Font wmFont = _watermarkFont;
                Size wmSize = TextRenderer.MeasureText(WatermarkText, wmFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix);
                wmX = this.Width - wmSize.Width - 9;
                int wmY = (WatermarkMode == 1) ? 3 : ((this.Height - wmSize.Height) / 2);
                int alpha = this.Enabled ? (int)(38 + 44 * _hoverProgress) : 20;
                using (SolidBrush wmBrush = new SolidBrush(Color.FromArgb(alpha, 255, 255, 255)))
                {
                    g.DrawString(WatermarkText, wmFont, wmBrush, wmX, wmY);
                }
            }

            // Tekil sembol / emoji butonlarında (örn: ➕) fontun yan boşluklarını (advance bearing)
            // yok sayıp mürekkep sınırlarına (ink bounds) göre milimetrik tam ortala.
            if (!hasIcon && string.IsNullOrEmpty(WatermarkText) && (shownText == "\u2795" || shownText == "+" || (shownText != null && shownText.Length == 1 && char.IsSymbol(shownText[0]))))
            {
                using (GraphicsPath gp = new GraphicsPath())
                {
                    float emPx = this.Font.Size * 96f / 72f;
                    gp.AddString(shownText, this.Font.FontFamily, (int)this.Font.Style, emPx, new PointF(0, 0), StringFormat.GenericTypographic);
                    RectangleF b = gp.GetBounds();
                    if (b.Width > 0 && b.Height > 0)
                    {
                        float cx = this.Width / 2f;
                        float cy = this.Height / 2f;
                        using (Matrix m = new Matrix())
                        {
                            m.Translate(cx - (b.X + b.Width / 2f), cy - (b.Y + b.Height / 2f));
                            gp.Transform(m);
                        }
                        using (SolidBrush sb = new SolidBrush(textClr))
                        {
                            g.FillPath(sb, gp);
                        }
                        return;
                    }
                }
            }

            int textX;
            if (hasIcon)
            {
                textX = startX + iconW + gap;
            }
            else if (!string.IsNullOrEmpty(WatermarkText))
            {
                int centeredX = (this.Width - textSize.Width) / 2;
                if (centeredX + textSize.Width > wmX - 4)
                {
                    textX = Math.Max(7, wmX - 4 - textSize.Width);
                }
                else
                {
                    textX = centeredX;
                }
            }
            else
            {
                textX = (this.Width - textSize.Width) / 2;
            }

            int textY = (this.Height - textSize.Height) / 2;
            TextRenderer.DrawText(g, shownText, this.Font, new Point(textX, textY), textClr, TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
        }

        private static Color InterpolateColor(Color c1, Color c2, float t)
        {
            t = Math.Max(0f, Math.Min(1f, t));
            int r = (int)(c1.R + (c2.R - c1.R) * t);
            int g = (int)(c1.G + (c2.G - c1.G) * t);
            int b = (int)(c1.B + (c2.B - c1.B) * t);
            return Color.FromArgb(r, g, b);
        }
    }

    // 4. Custom Modern Checkbox (Accessible, responsive, smooth toggle)
    public class CustomCheckBox : Control
    {
        private bool _checked = false;
        private bool _drawRoundedBackground = false;
        private Func<Color> _roundedBackgroundColorProvider;
        public bool DrawRoundedBackground
        {
            get { return _drawRoundedBackground; }
            set
            {
                if (_drawRoundedBackground != value)
                {
                    _drawRoundedBackground = value;
                    this.Invalidate();
                }
            }
        }

        public Func<Color> RoundedBackgroundColorProvider
        {
            get { return _roundedBackgroundColorProvider; }
            set
            {
                _roundedBackgroundColorProvider = value;
                this.Invalidate();
            }
        }

        public bool Checked
        {
            get { return _checked; }
            set
            {
                if (_checked != value)
                {
                    _checked = value;
                    if (CheckedChanged != null) CheckedChanged(this, EventArgs.Empty);
                    this.Invalidate();
                }
            }
        }

        public event EventHandler CheckedChanged;
        private bool _isHovered = false;
        private Font _ownFont; // sınıfın sahiplendiği taban font (Dispose'da bırakılır)

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == 0x0021) // WM_MOUSEACTIVATE
            {
                m.Result = (IntPtr)1; // MA_ACTIVATE
                return;
            }
            base.WndProc(ref m);
        }

        public CustomCheckBox()
        {
            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.Selectable, true);
            this.UpdateStyles();
            this.Cursor = Cursors.Hand;
            _ownFont = new Font("Segoe UI Semibold", 9F, FontStyle.Regular);
            this.Font = _ownFont;
            this.ForeColor = Color.FromArgb(214, 222, 235);
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing && _ownFont != null)
            {
                try { _ownFont.Dispose(); } catch {}
                _ownFont = null;
            }
            base.Dispose(disposing);
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            if (!_isHovered)
            {
                _isHovered = true;
                this.Invalidate();
            }
        }

        protected override void OnMouseEnter(EventArgs e)
        {
            base.OnMouseEnter(e);
            _isHovered = true;
            this.Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            _isHovered = false;
            this.Invalidate();
        }

        protected override void OnClick(EventArgs e)
        {
            base.OnClick(e);
            this.Checked = !this.Checked;
        }

        protected override void OnKeyDown(KeyEventArgs e)
        {
            base.OnKeyDown(e);
            if (e.KeyCode == Keys.Space || e.KeyCode == Keys.Enter)
            {
                this.Checked = !this.Checked;
                e.Handled = true;
            }
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            // Clear background
            Color parentBg = this.Parent != null ? this.Parent.BackColor : Color.FromArgb(14, 17, 24);
            g.Clear(parentBg);

            bool drawRoundedBackground = _drawRoundedBackground && _roundedBackgroundColorProvider != null;
            int contentOffsetX = drawRoundedBackground ? 8 : 0;
            if (drawRoundedBackground)
            {
                Color surfaceColor = _roundedBackgroundColorProvider();
                RectangleF surfaceRect = new RectangleF(0.5f, 0.5f, this.Width - 1.0f, this.Height - 1.0f);
                using (GraphicsPath surfacePath = ModernMainForm.CreateRoundedRectangleF(surfaceRect, 9.0f))
                using (SolidBrush surfaceBrush = new SolidBrush(surfaceColor))
                {
                    g.FillPath(surfaceBrush, surfacePath);
                }
            }

            int boxSize = 16;
            int boxY = (this.Height - boxSize) / 2;
            RectangleF boxRect = new RectangleF(contentOffsetX + 0.5f, boxY + 0.5f, boxSize - 1f, boxSize - 1f);

            Color boxBg = _checked ? Color.FromArgb(37, 99, 235) : Color.FromArgb(22, 27, 38);
            Color boxBorder = _isHovered ? Color.FromArgb(59, 130, 246) : Color.FromArgb(42, 50, 68);
            ThemePalette palette = ThemePalette.Get(ModernMainForm.ActiveTheme);
            if (drawRoundedBackground)
            {
                boxBg = _checked ? palette.PrimaryAccent : palette.FormBg;
                boxBorder = _checked ? palette.PrimaryAccent : (_isHovered ? palette.BorderHoverColor : palette.BorderColor);
            }

            using (GraphicsPath path = ModernMainForm.CreateRoundedRectangleF(boxRect, 4f))
            using (SolidBrush b = new SolidBrush(boxBg))
            using (Pen p = new Pen(boxBorder, 1f))
            {
                g.FillPath(b, path);
                g.DrawPath(p, path);
            }

            if (_checked)
            {
                using (Pen checkPen = new Pen(Color.White, 2f))
                {
                    checkPen.StartCap = LineCap.Round;
                    checkPen.EndCap = LineCap.Round;
                    Point[] pts = new Point[] {
                        new Point(contentOffsetX + 3, boxY + 8),
                        new Point(contentOffsetX + 6, boxY + 11),
                        new Point(contentOffsetX + 12, boxY + 4)
                    };
                    g.DrawLines(checkPen, pts);
                }
            }

            Rectangle textRect = new Rectangle(contentOffsetX + 24, 0, this.Width - contentOffsetX - 24, this.Height);
            Color textColor = drawRoundedBackground ? palette.TextPrimary : (_isHovered ? Color.White : this.ForeColor);
            TextFormatFlags textFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
            if (drawRoundedBackground) textFlags |= TextFormatFlags.NoPadding;
            TextRenderer.DrawText(g, this.Text, this.Font, textRect, textColor, textFlags);
        }
    }

    // 5b. Application Health & Diagnostic Performance Metrics
    public static class AppHealthMetrics
    {
        private static readonly DateTime _startTimeUtc = DateTime.UtcNow;
        private static int _watchdogTriggerCount = 0;
        private static int _crashesRecoveredCount = 0;
        private static int _tlsProbeCount = 0;
        private static int _tlsSuccessCount = 0;
        private static int _tlsFailCount = 0;
        private static long _totalTlsLatencyMs = 0;
        private static long _lastTlsLatencyMs = -1;
        private static int _dnsRepairsCount = 0;
        private static int _dnsRepairSuccessCount = 0;
        private static int _dnsRepairFailureCount = 0;
        private static int _sleepWakeCount = 0;
        private static int _watchdogUnknownCount = 0;
        private static int _watchdogConfirmedGatewayFailureCount = 0;
        private static int _watchdogInterventionCount = 0;
        private static int _watchdogInterventionSuccessCount = 0;
        private static int _watchdogInterventionFailureCount = 0;
        private static int _watchdogRollbackSuccessCount = 0;
        private static long _totalWatchdogInterventionMs = 0;
        private static long _lastWatchdogInterventionMs = -1;
        private static int _rtcHealTriggerCount = 0;
        private static int _rtcHealSuccessCount = 0;
        private static int _rtcHealFailCount = 0;
        private static long _lastRtcHealElapsedMs = -1;
        private static string _lastRtcHealReason = "";
        private static int _mediaQuicShieldActive = 0;
        private static int _mediaQuicProtectedExeCount = 0;
        private static long _lastCdnTlsLatencyMs = -1;
        private static long _lastMediaProxyTlsLatencyMs = -1;

        public static int WatchdogTriggerCount { get { return _watchdogTriggerCount; } }
        public static int CrashesRecoveredCount { get { return _crashesRecoveredCount; } }
        public static int TlsProbeCount { get { return _tlsProbeCount; } }
        public static int TlsSuccessCount { get { return _tlsSuccessCount; } }
        public static int TlsFailCount { get { return _tlsFailCount; } }
        public static long LastTlsLatencyMs { get { return Interlocked.Read(ref _lastTlsLatencyMs); } }
        public static int DnsRepairsCount { get { return _dnsRepairsCount; } }
        public static int DnsRepairSuccessCount { get { return _dnsRepairSuccessCount; } }
        public static int DnsRepairFailureCount { get { return _dnsRepairFailureCount; } }
        public static int SleepWakeCount { get { return _sleepWakeCount; } }
        public static int WatchdogUnknownCount { get { return _watchdogUnknownCount; } }
        public static int WatchdogConfirmedGatewayFailureCount { get { return _watchdogConfirmedGatewayFailureCount; } }
        public static int WatchdogInterventionCount { get { return _watchdogInterventionCount; } }
        public static int WatchdogInterventionSuccessCount { get { return _watchdogInterventionSuccessCount; } }
        public static int WatchdogInterventionFailureCount { get { return _watchdogInterventionFailureCount; } }
        public static int WatchdogRollbackSuccessCount { get { return _watchdogRollbackSuccessCount; } }
        public static long LastWatchdogInterventionMs { get { return Interlocked.Read(ref _lastWatchdogInterventionMs); } }
        public static int RtcHealTriggerCount { get { return _rtcHealTriggerCount; } }
        public static int RtcHealSuccessCount { get { return _rtcHealSuccessCount; } }
        public static int RtcHealFailCount { get { return _rtcHealFailCount; } }
        public static long LastRtcHealElapsedMs { get { return Interlocked.Read(ref _lastRtcHealElapsedMs); } }
        public static string LastRtcHealReason { get { return _lastRtcHealReason ?? ""; } }
        public static bool MediaQuicShieldActive { get { return _mediaQuicShieldActive != 0; } }
        public static int MediaQuicProtectedExeCount { get { return _mediaQuicProtectedExeCount; } }
        public static long LastCdnTlsLatencyMs { get { return Interlocked.Read(ref _lastCdnTlsLatencyMs); } }
        public static long LastMediaProxyTlsLatencyMs { get { return Interlocked.Read(ref _lastMediaProxyTlsLatencyMs); } }

        public static long AverageWatchdogInterventionMs
        {
            get
            {
                int count = _watchdogInterventionCount;
                return count <= 0 ? -1 : Interlocked.Read(ref _totalWatchdogInterventionMs) / count;
            }
        }

        public static int AverageTlsLatencyMs
        {
            get
            {
                int succ = _tlsSuccessCount;
                if (succ <= 0) return -1;
                return (int)(Interlocked.Read(ref _totalTlsLatencyMs) / succ);
            }
        }

        public static string GetUptimeString()
        {
            TimeSpan uptime = DateTime.UtcNow - _startTimeUtc;
            if (uptime.TotalDays >= 1)
            {
                return string.Format("{0} gün {1} saat {2} dk", (int)uptime.TotalDays, uptime.Hours, uptime.Minutes);
            }
            if (uptime.TotalHours >= 1)
            {
                return string.Format("{0} saat {1} dk", (int)uptime.TotalHours, uptime.Minutes);
            }
            if (uptime.TotalMinutes >= 1)
            {
                return string.Format("{0} dk {1} sn", (int)uptime.TotalMinutes, uptime.Seconds);
            }
            return string.Format("{0} sn", (int)uptime.TotalSeconds);
        }

        public static void RecordWatchdogTrigger()
        {
            Interlocked.Increment(ref _watchdogTriggerCount);
        }

        public static void RecordCrashRecovered()
        {
            Interlocked.Increment(ref _crashesRecoveredCount);
        }

        public static void RecordTlsProbe(long latencyMs)
        {
            Interlocked.Increment(ref _tlsProbeCount);
            if (latencyMs >= 0)
            {
                Interlocked.Increment(ref _tlsSuccessCount);
                Interlocked.Add(ref _totalTlsLatencyMs, latencyMs);
                Interlocked.Exchange(ref _lastTlsLatencyMs, latencyMs);
            }
            else
            {
                Interlocked.Increment(ref _tlsFailCount);
            }
        }

        public static void RecordDnsRepair()
        {
            Interlocked.Increment(ref _dnsRepairsCount);
        }

        public static void RecordDnsRepairResult(bool succeeded)
        {
            if (succeeded) Interlocked.Increment(ref _dnsRepairSuccessCount);
            else Interlocked.Increment(ref _dnsRepairFailureCount);
        }

        public static void RecordWatchdogUnknown()
        {
            Interlocked.Increment(ref _watchdogUnknownCount);
        }

        public static void RecordWatchdogConfirmedGatewayFailure()
        {
            Interlocked.Increment(ref _watchdogConfirmedGatewayFailureCount);
        }

        public static void RecordWatchdogIntervention(bool succeeded, bool rollbackSucceeded, long elapsedMs)
        {
            Interlocked.Increment(ref _watchdogInterventionCount);
            if (succeeded) Interlocked.Increment(ref _watchdogInterventionSuccessCount);
            else Interlocked.Increment(ref _watchdogInterventionFailureCount);
            if (rollbackSucceeded) Interlocked.Increment(ref _watchdogRollbackSuccessCount);
            if (elapsedMs >= 0)
            {
                Interlocked.Add(ref _totalWatchdogInterventionMs, elapsedMs);
                Interlocked.Exchange(ref _lastWatchdogInterventionMs, elapsedMs);
            }
        }

        public static void RecordSleepWake()
        {
            Interlocked.Increment(ref _sleepWakeCount);
        }

        public static void RecordRtcHeal(bool succeeded, long elapsedMs, string reason)
        {
            Interlocked.Increment(ref _rtcHealTriggerCount);
            if (succeeded) Interlocked.Increment(ref _rtcHealSuccessCount);
            else Interlocked.Increment(ref _rtcHealFailCount);
            if (elapsedMs >= 0) Interlocked.Exchange(ref _lastRtcHealElapsedMs, elapsedMs);
            if (!string.IsNullOrEmpty(reason)) _lastRtcHealReason = reason;
        }

        public static void RecordMediaQuicShieldState(bool active, int protectedExeCount)
        {
            Interlocked.Exchange(ref _mediaQuicShieldActive, active ? 1 : 0);
            Interlocked.Exchange(ref _mediaQuicProtectedExeCount, protectedExeCount);
        }

        public static void RecordMediaCdnProbe(long cdnMs, long mediaProxyMs)
        {
            Interlocked.Exchange(ref _lastCdnTlsLatencyMs, cdnMs);
            Interlocked.Exchange(ref _lastMediaProxyTlsLatencyMs, mediaProxyMs);
        }
    }

    public enum LogLevel
    {
        Debug,
        Info,
        Warn,
        Error,
        Fatal
    }

    // 5. System & Network Diagnostic Logging Engine
    public static class AppLogger
    {
        private static readonly object _lock = new object();
        private static readonly List<string> _recentLogs = new List<string>();
        private static readonly Queue<string> _pendingDiskQueue = new Queue<string>();
        private static System.Threading.Timer _batchTimer = null;
        private static string _logFilePath = null;
        // Kalıcı log yazıcısı: her satırda dosya aç/kapat + boyut ölçümü maliyetini ortadan kaldırır.
        private static StreamWriter _logWriter = null;
        private static long _logBytesWritten = 0;
        private static long _nextRotateAttemptAt = 0; // rotasyon üst üste başarısızsa geri çekilme eşiği
        private const long MaxLogSize = 2 * 1024 * 1024;

        // Bu oturuma özgü kısa kimlik — tanılama raporu başlığında kullanılır
        public static readonly string SessionId = Guid.NewGuid().ToString("N").Substring(0, 8).ToUpperInvariant();

        static AppLogger()
        {
            try
            {
                _batchTimer = new System.Threading.Timer(delegate { FlushInternal(false); }, null, 400, 400);
            }
            catch {}
        }

        public static string LogFilePath
        {
            get
            {
                if (_logFilePath == null)
                {
                    try
                    {
                        // AppPaths.LogsDir oluşturma hatasını sessizce yutabildiği için
                        // yazılamaz bir yola saplanmamak adına varlık kontrolü yapılır.
                        if (Directory.Exists(AppPaths.LogsDir))
                        {
                            _logFilePath = Path.Combine(AppPaths.LogsDir, "goodbyedpi_promax.log");
                        }
                        else
                        {
                            _logFilePath = Path.Combine(Path.GetTempPath(), "goodbyedpi_promax.log");
                        }
                    }
                    catch
                    {
                        _logFilePath = Path.Combine(Path.GetTempPath(), "goodbyedpi_promax.log");
                    }
                }
                return _logFilePath;
            }
        }

        public static void Init()
        {
            try
            {
                string oldLog1 = Path.Combine(AppPaths.AppDir, "goodbyedpi_promax.log");
                string oldLog2 = Path.Combine(AppPaths.AppDir, "goodbyedpi_turkey.log");
                string targetLog = Path.Combine(AppPaths.LogsDir, "goodbyedpi_promax.log");
                if (File.Exists(oldLog1) && !File.Exists(targetLog))
                {
                    try { File.Move(oldLog1, targetLog); } catch {}
                }
                else if (File.Exists(oldLog1))
                {
                    try { File.Delete(oldLog1); } catch {}
                }
                if (File.Exists(oldLog2))
                {
                    try { File.Delete(oldLog2); } catch {}
                }
            }
            catch {}

            try
            {
                Log("SYSTEM", string.Format("GoodbyeDPI Pro MAX Başlatıldı | OS: {0} ({1}) | Yönetici: {2}",
                    Environment.OSVersion.VersionString,
                    Environment.Is64BitOperatingSystem ? "64-bit" : "32-bit",
                    IsAdministrator() ? "EVET" : "HAYIR"), LogLevel.Info);
            }
            catch {}
        }

        public static bool IsAdministrator()
        {
            try
            {
                using (WindowsIdentity identity = WindowsIdentity.GetCurrent())
                {
                    WindowsPrincipal principal = new WindowsPrincipal(identity);
                    return principal.IsInRole(WindowsBuiltInRole.Administrator);
                }
            }
            catch
            {
                return false;
            }
        }

        public static void Log(string tag, string message)
        {
            LogLevel level = LogLevel.Info;
            if (string.Equals(tag, "ERROR", StringComparison.OrdinalIgnoreCase))
            {
                level = LogLevel.Error;
            }
            else if (string.Equals(tag, "WARNING", StringComparison.OrdinalIgnoreCase) || string.Equals(tag, "WARN", StringComparison.OrdinalIgnoreCase))
            {
                level = LogLevel.Warn;
            }
            Log(tag, message, level);
        }

        public static void Log(string tag, string message, LogLevel level)
        {
            if (string.IsNullOrEmpty(message)) return;
            string levelStr = level.ToString().ToUpperInvariant();
            string line = string.Format("[{0:yyyy-MM-dd HH:mm:ss}] [{1}] [{2}] {3}", DateTime.Now, levelStr, tag, message);

            bool immediate = (level == LogLevel.Error || level == LogLevel.Fatal);
            lock (_lock)
            {
                _recentLogs.Add(line);
                if (_recentLogs.Count > 300) _recentLogs.RemoveAt(0);
                _pendingDiskQueue.Enqueue(line);
                if (_pendingDiskQueue.Count >= 20) immediate = true;
            }

            if (immediate)
            {
                ThreadPool.QueueUserWorkItem(delegate { FlushInternal(true); });
            }
        }

        public static void Flush()
        {
            FlushInternal(true);
        }

        private static void FlushInternal(bool immediate)
        {
            lock (_lock)
            {
                if (_pendingDiskQueue.Count == 0) return;
                List<string> batch = new List<string>(_pendingDiskQueue.Count);
                while (_pendingDiskQueue.Count > 0)
                {
                    batch.Add(_pendingDiskQueue.Dequeue());
                }

                int primaryWrittenCount = 0;
                try
                {
                    EnsureLogWriter();
                    for (int i = 0; i < batch.Count; i++)
                    {
                        string line = batch[i];
                        int byteCount = Encoding.UTF8.GetByteCount(line) + Environment.NewLine.Length;
                        if (_logBytesWritten + byteCount > MaxLogSize && _logBytesWritten >= _nextRotateAttemptAt)
                        {
                            if (RotateLogFile())
                            {
                                _nextRotateAttemptAt = 0;
                            }
                            else
                            {
                                _nextRotateAttemptAt = _logBytesWritten + 512 * 1024;
                            }
                            EnsureLogWriter();
                        }
                        if (_logWriter != null)
                        {
                            _logWriter.WriteLine(line);
                            _logBytesWritten += byteCount;
                            primaryWrittenCount++;
                        }
                    }
                    if (_logWriter != null)
                    {
                        _logWriter.Flush();
                    }
                }
                catch
                {
                    try { if (_logWriter != null) _logWriter.Dispose(); } catch {}
                    _logWriter = null;
                    if (primaryWrittenCount > 0)
                    {
                        batch.RemoveRange(0, Math.Min(primaryWrittenCount, batch.Count));
                    }
                    try
                    {
                        if (batch.Count > 0)
                        {
                            StringBuilder sb = new StringBuilder();
                            for (int i = 0; i < batch.Count; i++)
                            {
                                sb.AppendLine(batch[i]);
                            }
                            File.AppendAllText(LogFilePath, sb.ToString(), Encoding.UTF8);
                        }
                    }
                    catch
                    {
                        // İki yazma yolu da başarısızsa diske gitmeyen kayıtları sonraki denemeye bırak.
                        for (int i = 0; i < batch.Count; i++)
                        {
                            _pendingDiskQueue.Enqueue(batch[i]);
                        }
                    }
                }
            }
        }

        public static void Shutdown()
        {
            try
            {
                if (_batchTimer != null)
                {
                    _batchTimer.Dispose();
                    _batchTimer = null;
                }
            }
            catch {}
            Flush();
            lock (_lock)
            {
                try { if (_logWriter != null) { _logWriter.Dispose(); _logWriter = null; } } catch {}
            }
        }

        public static string SanitizePii(string text)
        {
            if (string.IsNullOrEmpty(text)) return text;
            try
            {
                string userName = Environment.UserName;
                if (!string.IsNullOrEmpty(userName) && userName.Length > 1)
                {
                    text = text.Replace(@"\" + userName, @"\<user>");
                    text = text.Replace("/" + userName, "/<user>");
                }
                string userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
                if (!string.IsNullOrEmpty(userProfile))
                {
                    text = text.Replace(userProfile, @"C:\Users\<user>");
                }
            }
            catch {}
            return text;
        }

        // Kalıcı yazıcıyı (gerekirse) açar; dosya paylaşımı Notepad/ikinci kopya ile okumaya izin verir.
        private static void EnsureLogWriter()
        {
            if (_logWriter != null) return;
            string path = LogFilePath;
            FileStream fs = new FileStream(path, FileMode.Append, FileAccess.Write, FileShare.ReadWrite | FileShare.Delete);
            _logWriter = new StreamWriter(fs, new UTF8Encoding(false));
            _logWriter.AutoFlush = true;
            try { _logBytesWritten = fs.Length; } catch { _logBytesWritten = 0; }
        }

        // 2 MB devri: devir başarısız olsa bile (dosya başka programda açık olabilir)
        // log yazımı kesilmez; çağıran taraf geri çekilme eşiğiyle yeniden dener.
        private static bool RotateLogFile()
        {
            bool ok = false;
            try
            {
                if (_logWriter != null) { try { _logWriter.Dispose(); } catch {} _logWriter = null; }
                string oldLog = LogFilePath + ".old";
                try { if (File.Exists(oldLog)) File.Delete(oldLog); } catch {}
                if (File.Exists(LogFilePath)) File.Move(LogFilePath, oldLog);
                ok = true;
            }
            catch { ok = false; }
            if (ok) _logBytesWritten = 0;
            return ok;
        }

        public static void LogEngine(string line)
        {
            Log("ENGINE", line, LogLevel.Debug);
        }

        public static List<string> GetRecentLogs()
        {
            lock (_lock)
            {
                return new List<string>(_recentLogs);
            }
        }

        public static string GetFriendlyWindowsVersion()
        {
            try
            {
                int build = 0;
                try
                {
                    using (RegistryKey rk = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion"))
                    {
                        if (rk != null)
                        {
                            object bVal = rk.GetValue("CurrentBuild");
                            if (bVal == null) bVal = rk.GetValue("CurrentBuildNumber");
                            if (bVal != null) int.TryParse(bVal.ToString(), out build);
                        }
                    }
                }
                catch {}

                if (build == 0)
                {
                    build = Environment.OSVersion.Version.Build;
                }

                if (build >= 28000) return string.Format("Windows 11 26H1 (Build {0})", build);
                if (build >= 26300) return string.Format("Windows 11 26H2 (Build {0})", build);
                if (build >= 26200) return string.Format("Windows 11 25H2 (Build {0})", build);
                if (build >= 26100) return string.Format("Windows 11 24H2 (Build {0})", build);
                if (build >= 22631) return string.Format("Windows 11 23H2 (Build {0})", build);
                if (build >= 22000) return string.Format("Windows 11 21H2/22H2 (Build {0})", build);
                if (build >= 10240) return string.Format("Windows 10 (Build {0})", build);
            }
            catch {}
            return Environment.OSVersion.VersionString;
        }

        public static string GenerateFullReport(IspProfile currentProfile, bool isRunning, string pingMs)
        {
            // Canlı testler raporun başında bir kez koşar; hem SONUÇ triyaj satırında
            // hem de 4. bölümde aynı sonuçlar kullanılır (çift test maliyeti yoktur).
            string resolveErr;
            IPAddress[] localIps = NetworkProbe.ResolveHostIps("discord.com", out resolveErr);
            bool dnsPoisoned = false;
            string dnsIpsJoined = null;
            if (localIps != null && localIps.Length > 0)
            {
                StringBuilder ipStr = new StringBuilder();
                foreach (IPAddress ip in localIps)
                {
                    if (NetworkProbe.IsPoisonedDiscordIp(ip)) dnsPoisoned = true;
                    ipStr.Append(ip.ToString() + " ");
                }
                dnsIpsJoined = ipStr.ToString().Trim();
            }

            int udpBytes;
            string udpErr;
            long udpMs = NetworkProbe.TestUdpDns("9.9.9.9", 9953, 2500, out udpBytes, out udpErr);

            string tcpErr;
            long gwMs = NetworkProbe.TestTcpConnect("gateway.discord.gg", 443, 2500, out tcpErr);

            long dohMs = -1;
            string dohErr = null;
            try
            {
                Stopwatch swDoh = Stopwatch.StartNew();
                HttpWebRequest dohReq = (HttpWebRequest)WebRequest.Create("https://cloudflare-dns.com/dns-query?name=discord.com&type=A");
                dohReq.Accept = "application/dns-json";
                dohReq.UserAgent = "GoodbyeDPI-ProMAX/1.0";
                dohReq.Timeout = 3000;
                dohReq.Proxy = null;
                dohReq.KeepAlive = false;
                using (HttpWebResponse dohResp = (HttpWebResponse)dohReq.GetResponse())
                {
                    swDoh.Stop();
                    dohMs = swDoh.ElapsedMilliseconds;
                }
            }
            catch (Exception dohEx)
            {
                dohErr = dohEx.Message;
            }

            StringBuilder sb = new StringBuilder();
            sb.AppendLine("================================================================");
            sb.AppendLine("  GoodbyeDPI Pro MAX — Tanılama Raporu");
            sb.AppendLine(string.Format("  Sürüm: v{0}  •  Oturum: {1}  •  {2:yyyy-MM-dd HH:mm:ss}", UpdateManager.DisplayVersion, SessionId, DateTime.Now));
            sb.AppendLine("================================================================");
            sb.AppendLine();

            // SONUÇ: tek bakışta triyaj (mevcut testlerin sonuçlarından türetilir)
            if (dnsPoisoned)
            {
                sb.AppendLine("  ❌ SONUÇ: Discord DNS'i engellenmiş, özel veya yerel IP'ye yönlenmiş görünüyor");
                if (isRunning)
                {
                    sb.AppendLine("     -> Koruma aktif olmasına rağmen yerel DNS hâlâ zehirli görünüyor. DNS sağlayıcısını değiştirin (Yandex güvenli DNS önerilir).");
                }
                else
                {
                    sb.AppendLine("     -> BTK/İSS yönlendirmesi aktif. GoodbyeDPI korumasını başlatın.");
                }
            }
            else if (gwMs < 0)
            {
                sb.AppendLine("  ⚠️ SONUÇ: DPI ENGELİ MUHTEMEL — Discord ağ geçidine (gateway.discord.gg:443) erişilemedi");
                sb.AppendLine(isRunning
                    ? "     -> Koruma açık olmasına rağmen ağ geçidi yanıt vermedi. Modemi yeniden başlatıp tekrar deneyin; sorun sürerse bu raporu paylaşın."
                    : "     -> Koruma kapalı. GoodbyeDPI korumasını başlatın ve tekrar test edin.");
            }
            else
            {
                sb.AppendLine("  ✅ SONUÇ: Sorun tespit edilmedi — bağlantı ve DNS temiz görünüyor.");
                sb.AppendLine(string.Format("     -> Koruma Durumu: {0}", isRunning ? "AKTİF" : "KAPALI"));
            }
            sb.AppendLine();

            sb.AppendLine("[ SİSTEM SAĞLIK VE PERFORMANS ÖZETİ (HEALTH METRICS) ]");
            sb.AppendLine(string.Format("  • Oturum Çalışma Süresi (Uptime)     : {0}", AppHealthMetrics.GetUptimeString()));
            sb.AppendLine(string.Format("  • Bekçi Müdahale Sayısı (Watchdog)  : {0} kez devreye girdi", AppHealthMetrics.WatchdogTriggerCount));
            sb.AppendLine(string.Format("  • Otomatik İyileştirilen Çökme       : {0} çökme başarıyla kurtarıldı", AppHealthMetrics.CrashesRecoveredCount));
            sb.AppendLine(string.Format("  • Doğrulanmış gateway yolu arızası   : {0} gözlem; belirsiz sınıflandırma {1}",
                AppHealthMetrics.WatchdogConfirmedGatewayFailureCount, AppHealthMetrics.WatchdogUnknownCount));
            sb.AppendLine(string.Format("  • Profil denemesi                    : {0} toplam ({1} başarılı, {2} başarısız; geri alma {3})",
                AppHealthMetrics.WatchdogInterventionCount, AppHealthMetrics.WatchdogInterventionSuccessCount,
                AppHealthMetrics.WatchdogInterventionFailureCount, AppHealthMetrics.WatchdogRollbackSuccessCount));
            sb.AppendLine(string.Format("  • Profil denemesi süresi             : {0}",
                AppHealthMetrics.AverageWatchdogInterventionMs >= 0
                    ? string.Format("ortalama {0} ms; son {1} ms", AppHealthMetrics.AverageWatchdogInterventionMs, AppHealthMetrics.LastWatchdogInterventionMs)
                    : "henüz ölçülmedi"));
            sb.AppendLine(string.Format("  • Periyodik gateway bağlantı/TLS probu : {0} test yapıldı ({1} başarılı, {2} başarısız)",
                AppHealthMetrics.TlsProbeCount, AppHealthMetrics.TlsSuccessCount, AppHealthMetrics.TlsFailCount));
            sb.AppendLine(string.Format("  • Ortalama gateway uçtan uca bağlantı/TLS süresi: {0}",
                AppHealthMetrics.AverageTlsLatencyMs >= 0
                    ? string.Format("{0} ms (Son ölçülen: {1} ms)", AppHealthMetrics.AverageTlsLatencyMs, AppHealthMetrics.LastTlsLatencyMs >= 0 ? AppHealthMetrics.LastTlsLatencyMs.ToString() : "N/A")
                    : "Henüz ölçüm yapılmadı"));
            sb.AppendLine(string.Format("  • Discord RTC Ses Oto-İyileştirici    : {0} müdahale ({1} başarılı, {2} başarısız){3}",
                AppHealthMetrics.RtcHealTriggerCount, AppHealthMetrics.RtcHealSuccessCount, AppHealthMetrics.RtcHealFailCount,
                AppHealthMetrics.LastRtcHealElapsedMs >= 0
                    ? string.Format(" | Son: {0} ({1} ms)", AppHealthMetrics.LastRtcHealReason, AppHealthMetrics.LastRtcHealElapsedMs)
                    : ""));
            sb.AppendLine(string.Format("  • Discord Medya & QUIC Kalkanı        : {0}{1}",
                AppHealthMetrics.MediaQuicShieldActive
                    ? string.Format("AKTİF ({0} istemci ikilisi için UDP 443 QUIC hızlı TCP/TLS geçişinde)", AppHealthMetrics.MediaQuicProtectedExeCount)
                    : "KAPALI",
                (AppHealthMetrics.LastCdnTlsLatencyMs >= 0 || AppHealthMetrics.LastMediaProxyTlsLatencyMs >= 0)
                    ? string.Format(" | CDN TLS: {0} ms, Medya TLS: {1} ms",
                        AppHealthMetrics.LastCdnTlsLatencyMs >= 0 ? AppHealthMetrics.LastCdnTlsLatencyMs.ToString() : "N/A",
                        AppHealthMetrics.LastMediaProxyTlsLatencyMs >= 0 ? AppHealthMetrics.LastMediaProxyTlsLatencyMs.ToString() : "N/A")
                    : ""));
            if (AppHealthMetrics.DnsRepairsCount > 0)
            {
                sb.AppendLine(string.Format("  • Otomatik DNS Onarım Denemesi       : {0} (doğrulanan yanıt {1}, başarısız/belirsiz {2})",
                    AppHealthMetrics.DnsRepairsCount, AppHealthMetrics.DnsRepairSuccessCount, AppHealthMetrics.DnsRepairFailureCount));
            }
            if (AppHealthMetrics.SleepWakeCount > 0)
            {
                sb.AppendLine(string.Format("  • Uyku / Uyanma Döngüsü              : {0} kez uykudan uyanış sonrası sürücü tazelendi", AppHealthMetrics.SleepWakeCount));
            }
            sb.AppendLine();

            sb.AppendLine("[ SİSTEM ÖZETİ ]");
            sb.AppendLine(string.Format("  Tarih / Saat       : {0:yyyy-MM-dd HH:mm:ss}", DateTime.Now));
            sb.AppendLine(string.Format("  Windows Sürümü     : {0} [{1}] ({2})", GetFriendlyWindowsVersion(), Environment.OSVersion.VersionString, Environment.Is64BitOperatingSystem ? "64-bit" : "32-bit"));
            sb.AppendLine(string.Format("  Yönetici Yetkisi   : {0}", IsAdministrator() ? "EVET (Yönetici Modu)" : "HAYIR (YÖNETİCİ DEĞİL - HATA!)"));
            sb.AppendLine(string.Format("  Uygulama Dizini    : {0}", AppDomain.CurrentDomain.BaseDirectory));
            sb.AppendLine(string.Format("  Seçili Profil      : {0}", currentProfile != null ? currentProfile.Name : "Bilinmiyor"));
            sb.AppendLine(string.Format("  Koruma Durumu      : {0}", isRunning ? "AKTİF / ÇALIŞIYOR" : "KAPALI / DURDURULDU"));
            sb.AppendLine(string.Format("  Son Ölçülen Ping   : {0} ms", pingMs));
            sb.AppendLine();

            sb.AppendLine("[ 1. GÜVENLİK YAZILIMLARI (ANTİVİRÜS KONTROLÜ) ]");
            sb.AppendLine("  • Standart Windows Güvenliği devrede.");

            try
            {
                Process[] chromes = Process.GetProcessesByName("chrome");
                if (chromes != null && chromes.Length > 0)
                {
                    int headless = 0;
                    for (int i = 0; i < chromes.Length; i++)
                    {
                        if (chromes[i].MainWindowHandle == IntPtr.Zero) headless++;
                    }
                    if (headless > 0 && headless == chromes.Length)
                    {
                        sb.AppendLine(string.Format("  [!] BİLGİ: {0} adet penceresiz askıda kalmış Chrome süreci tespit edildi.", headless));
                        sb.AppendLine("      -> 'Ağ ve Discord'u onar' seçeneğini kullanarak bu süreçleri sonlandırabilirsiniz.");
                    }
                    // Süreç tutamaçlarını serbest bırak (rapor her açıldığında sızmasın).
                    for (int i = 0; i < chromes.Length; i++)
                    {
                        try { chromes[i].Dispose(); } catch {}
                    }
                }
            }
            catch {}
            sb.AppendLine();

            sb.AppendLine("[ 2. WINDOWS ÇEKİRDEK GÜVENLİĞİ VE SÜRÜCÜ DURUMU ]");
            string hvciState = "Kayıt yok / doğrulanamadı";
            try
            {
                using (RegistryKey rk = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity"))
                {
                    if (rk != null)
                    {
                        object val = rk.GetValue("Enabled");
                        if (val != null) hvciState = Convert.ToInt32(val) == 1 ? "Enabled=1 (etkin yapılandırılmış)" : "Enabled=0 (kapalı yapılandırılmış)";
                    }
                }
            }
            catch {}
            sb.AppendLine("  • Çekirdek Yalıtımı (HVCI) : " + hvciState);

            string driverBlocklistState = "Kayıt yok (Windows varsayılanı uygulanabilir)";
            try
            {
                using (RegistryKey rk = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Control\CI\Config"))
                {
                    if (rk != null)
                    {
                        object val = rk.GetValue("VulnerableDriverBlocklistEnable");
                        if (val != null) driverBlocklistState = Convert.ToInt32(val) == 1 ? "Etkin (Enabled=1)" : "Devre dışı yapılandırılmış (Enabled=0)";
                    }
                }
            }
            catch {}
            sb.AppendLine("  • Sürücü Engelleme Listesi: " + driverBlocklistState);

            string archDir;
            string driverFileName;
            string nativeArchitecture;
            string architectureError;
            if (AppPaths.TryGetEngineArchitecture(out archDir, out driverFileName, out nativeArchitecture, out architectureError))
            {
                string enginePath = AppPaths.Resolve(Path.Combine(archDir, "goodbyedpi.exe"));
                string dllPath = AppPaths.Resolve(Path.Combine(archDir, "WinDivert.dll"));
                string driverPath = AppPaths.Resolve(Path.Combine(archDir, driverFileName));
                string driverVersion = "bilinmiyor";
                if (File.Exists(driverPath))
                {
                    try { driverVersion = FileVersionInfo.GetVersionInfo(driverPath).FileVersion; } catch {}
                    if (string.IsNullOrEmpty(driverVersion)) driverVersion = "bilinmiyor";
                    sb.AppendLine(string.Format("  • WinDivert sürücüsü       : [DOSYA MEVCUT] {0} | Dosya sürümü: {1}", driverPath, driverVersion));
                }
                else
                {
                    sb.AppendLine("  • WinDivert sürücüsü       : [DOSYA YOK] " + driverPath);
                }
                sb.AppendLine("  • Yerel işlemci mimarisi   : " + nativeArchitecture);

                // Dosya bütünlüğü — SHA256; mevcut olması yüklenebildiğini veya Windows güvenlik ilkelerinden geçtiğini kanıtlamaz.
                sb.AppendLine("  • Dosya Bütünlüğü (SHA256) :");
                AppendFileHash(sb, "goodbyedpi.exe", enginePath);
                AppendFileHash(sb, "WinDivert.dll", dllPath);
                AppendFileHash(sb, driverFileName, driverPath);
            }
            else
            {
                sb.AppendLine("  • Yerel işlemci mimarisi   : " + nativeArchitecture);
                sb.AppendLine("  • WinDivert sürücüsü       : [BAŞLATILAMAZ] " + architectureError);
            }
            sb.AppendLine();

            sb.AppendLine("[ 3. AĞ BAĞDAŞTIRICILARI VE DNS YAPILANDIRMASI ]");
            try
            {
                NetworkInterface[] adapters = NetworkInterface.GetAllNetworkInterfaces();
                foreach (NetworkInterface nic in adapters)
                {
                    if (nic.OperationalStatus == OperationalStatus.Up &&
                        (nic.NetworkInterfaceType == NetworkInterfaceType.Ethernet || nic.NetworkInterfaceType == NetworkInterfaceType.Wireless80211))
                    {
                        sb.AppendLine(string.Format("  • Bağdaştırıcı: {0} ({1})", nic.Name, nic.NetworkInterfaceType));
                        IPInterfaceProperties ipProps = nic.GetIPProperties();
                        if (ipProps != null)
                        {
                            foreach (UnicastIPAddressInformation uni in ipProps.UnicastAddresses)
                            {
                                if (uni.Address.AddressFamily == AddressFamily.InterNetwork)
                                {
                                    sb.AppendLine(string.Format("    IPv4 Adresi    : {0}", uni.Address));
                                }
                            }
                            StringBuilder dnsList = new StringBuilder();
                            foreach (IPAddress dns in ipProps.DnsAddresses)
                            {
                                dnsList.Append(dns.ToString() + ", ");
                            }
                            sb.AppendLine(string.Format("    DNS Sunucuları : {0}", dnsList.ToString().TrimEnd(' ', ',')));

                            // Aktif bağlantı: ağ geçidi ve arayüz MTU değeri
                            StringBuilder gwList = new StringBuilder();
                            foreach (GatewayIPAddressInformation gw in ipProps.GatewayAddresses)
                            {
                                if (gw.Address != null && gw.Address.AddressFamily == AddressFamily.InterNetwork)
                                {
                                    gwList.Append(gw.Address.ToString() + ", ");
                                }
                            }
                            if (gwList.Length > 0)
                            {
                                sb.AppendLine(string.Format("    Ağ Geçidi     : {0}", gwList.ToString().TrimEnd(' ', ',')));
                            }
                            try
                            {
                                IPv4InterfaceProperties v4Props = ipProps.GetIPv4Properties();
                                if (v4Props != null)
                                {
                                    sb.AppendLine(string.Format("    MTU            : {0}", v4Props.Mtu));
                                }
                            }
                            catch {}
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                sb.AppendLine("  Bağdaştırıcı bilgisi alınamadı: " + ex.Message);
            }
            sb.AppendLine();

            sb.AppendLine("[ 4. CANLI BAĞLANTI VE DNS ÇÖZÜMLEME TESTLERİ ]");

            // A. Yerel DNS Çözümleme (sonuçlar rapor başında bir kez koşuldu)
            sb.Append("  • Yerel DNS (discord.com)         : ");
            if (localIps != null && localIps.Length > 0)
            {
                if (dnsPoisoned)
                {
                    sb.AppendLine("[!] Discord DNS'i engellenmiş, özel veya yerel IP'ye yönlenmiş görünüyor");
                    sb.AppendLine("    -> BTK/İSS engelleme yönlendirmesi tespit edildi. GoodbyeDPI koruması gereklidir.");
                }
                else
                {
                    sb.AppendLine(string.Format("[OK] TEMİZ ({0})", dnsIpsJoined));
                }
            }
            else if (!string.IsNullOrEmpty(resolveErr))
            {
                sb.AppendLine("[X] HATA: " + resolveErr);
            }
            else
            {
                sb.AppendLine("[X] Çözümlenemedi (Boş yanıt)");
            }

            // B. Quad9 Engelsiz DNS 9953 Portu Testi (NetworkProbe — kurulum sihirbazıyla ortak)
            // Üç ayrı sonuç dalı: başarılı (ms), zehirli/şeffaf vekil yanıtı (-3), engel/zaman aşımı (-1).
            sb.Append("  • Quad9 DNS Port 9953 (9.9.9.9)   : ");
            if (udpMs >= 0)
            {
                sb.AppendLine(string.Format("[OK] BAŞARILI ({0} ms, {1} bayt yanıt)", udpMs, udpBytes));
            }
            else if (udpMs == -3)
            {
                sb.AppendLine("[!] ZEHİRLİ/VEKİL YANIT: " + udpErr);
                sb.AppendLine("    -> UDP 9953 erişilebilir görünüyor ancak yanıt sahte/yönlendirilmiş; şifreli DNS (DoH) yedeği önerilir.");
            }
            else
            {
                sb.AppendLine("[X] BAŞARISIZ / ZAMAN AŞIMI: " + udpErr);
                sb.AppendLine("    -> İSS veya güvenlik duvarı port 9953 UDP paketlerini engelliyor olabilir.");
            }

            // C. Discord Gateway TCP 443 Testi (NetworkProbe — kurulum sihirbazıyla ortak)
            sb.Append("  • Discord Ağ Geçidi (gateway)     : ");
            if (gwMs >= 0)
            {
                sb.AppendLine(string.Format("[OK] BAĞLANDI ({0} ms)", gwMs));
            }
            else if (!string.IsNullOrEmpty(tcpErr))
            {
                sb.AppendLine("[X] HATA: " + tcpErr);
            }
            else
            {
                sb.AppendLine("[X] ZAMAN AŞIMI / BAĞLANILAMADI");
                sb.AppendLine("    -> DPI engeli aktif veya TCP 443 paketleri engelleniyor.");
            }

            // D. Cloudflare DoH (HTTPS Port 443 Şifreli) Testi
            sb.Append("  • Cloudflare DoH (HTTPS 443)      : ");
            if (dohMs >= 0)
            {
                sb.AppendLine(string.Format("[OK] BAŞARILI ({0} ms - HTTPS Port 443 Şifreli)", dohMs));
            }
            else
            {
                sb.AppendLine("[X] BAŞARISIZ: " + dohErr);
            }
            sb.AppendLine();

            sb.AppendLine("[ 5. GOODBYEDPI MOTOR DURUMU VE SON UYGULAMA LOGLARI ]");

            // WinDivert sürücü servisi durumu (yalnız registry okuması — harici sc.exe çalıştırılmaz)
            sb.Append("  • WinDivert Servisi            : ");
            try
            {
                string wdService = FindWinDivertServiceName();
                if (wdService == null)
                {
                    sb.AppendLine("[i] Bu uygulamanın sürücüsü henüz yüklenmemiş veya eşleşen hizmet bulunamadı.");
                }
                else
                {
                    int wdStart = -1;
                    string wdImagePath = null;
                    using (RegistryKey wdKey = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services\" + wdService, false))
                    {
                        if (wdKey != null)
                        {
                            object wdObj = wdKey.GetValue("Start");
                            if (wdObj != null) wdStart = Convert.ToInt32(wdObj);
                            wdImagePath = Convert.ToString(wdKey.GetValue("ImagePath"));
                        }
                    }
                    if (!string.IsNullOrEmpty(wdImagePath)) sb.AppendLine("      ImagePath: " + wdImagePath);

                    if (wdStart == 4)
                    {
                        sb.AppendLine("[!] DEVRE DIŞI (Start=4) — DPI motoru çalışamaz. Uygulama onarımı hizmeti Start=3'e döndürür; ardından korumayı yeniden başlatın.");
                    }
                    else if (wdStart == 3)
                    {
                        sb.AppendLine(string.Format("[OK] {0} — talep üzerine yükleme (Start=3), yüklendiğinde aktif", wdService));
                    }
                    else if (wdStart == 2)
                    {
                        sb.AppendLine(string.Format("[OK] {0} — otomatik başlatma (Start=2)", wdService));
                    }
                    else if (wdStart == 0 || wdStart == 1)
                    {
                        sb.AppendLine(string.Format("[OK] {0} — sistem başlangıcı (Start={1})", wdService, wdStart));
                    }
                    else
                    {
                        sb.AppendLine(string.Format("[?] {0} — bilinmeyen Start değeri: {1}", wdService, wdStart));
                    }
                }
            }
            catch (Exception wdEx)
            {
                sb.AppendLine("[X] OKUNAMADI: " + wdEx.Message);
            }

            // Son motor parametreleri (bu oturumda başlatıldıysa)
            sb.AppendLine(string.Format("  • Son Motor Ayarları           : {0}", string.IsNullOrEmpty(ModernMainForm._lastEngineInfo) ? "(bu oturumda motor henüz başlatılmadı)" : ModernMainForm._lastEngineInfo));
            if (!string.IsNullOrEmpty(ModernMainForm._lastEngineArgs))
            {
                sb.AppendLine(string.Format("    Argümanlar                   : goodbyedpi.exe {0}", ModernMainForm._lastEngineArgs));
            }

            try
            {
                Process[] dpiProcs = Process.GetProcessesByName("goodbyedpi");
                if (dpiProcs != null && dpiProcs.Length > 0)
                {
                    foreach (Process p in dpiProcs)
                    {
                        sb.AppendLine(string.Format("  • goodbyedpi.exe çalışıyor (PID: {0}, Bellek: {1:N0} KB)", p.Id, p.WorkingSet64 / 1024));
                    }
                }
                else
                {
                    sb.AppendLine("  • goodbyedpi.exe şu an ÇALIŞMIYOR.");
                }
                // Süreç tutamaçlarını serbest bırak.
                if (dpiProcs != null)
                {
                    for (int i = 0; i < dpiProcs.Length; i++)
                    {
                        try { dpiProcs[i].Dispose(); } catch {}
                    }
                }
            }
            catch {}

            sb.AppendLine();
            sb.AppendLine("  Son Olay Kayıtları (son 60 satır):");
            lock (_lock)
            {
                int startIdx = Math.Max(0, _recentLogs.Count - 60);
                for (int i = startIdx; i < _recentLogs.Count; i++)
                {
                    sb.AppendLine("    " + _recentLogs[i]);
                }
            }

            // Motor (ENGINE) kayıtları ayrı blok — destek analizi için altın değerinde
            sb.AppendLine();
            sb.AppendLine("  Son Motor (ENGINE) Kayıtları:");
            lock (_lock)
            {
                List<string> engineLines = new List<string>();
                for (int i = _recentLogs.Count - 1; i >= 0 && engineLines.Count < 20; i--)
                {
                    if (_recentLogs[i].IndexOf("] [ENGINE]", StringComparison.Ordinal) >= 0)
                    {
                        engineLines.Add(_recentLogs[i]);
                    }
                }

                if (engineLines.Count == 0)
                {
                    sb.AppendLine("    (motor kaydı yok — koruma bu oturumda henüz başlatılmadı)");
                }
                else
                {
                    for (int i = engineLines.Count - 1; i >= 0; i--)
                    {
                        sb.AppendLine("    " + engineLines[i]);
                    }
                }
            }

            sb.AppendLine();
            sb.AppendLine("[ RAPOR SONU ]");

            return sb.ToString();
        }

        // SHA256 yardımcısı — tanılama raporundaki dosya bütünlüğü bölümü için
        private static void AppendFileHash(StringBuilder sb, string label, string path)
        {
            try
            {
                if (!File.Exists(path))
                {
                    sb.AppendLine(string.Format("      {0,-18}: [dosya yok]", label));
                    return;
                }
                using (SHA256 sha = SHA256.Create())
                using (FileStream fs = File.OpenRead(path))
                {
                    byte[] hash = sha.ComputeHash(fs);
                    StringBuilder hex = new StringBuilder(hash.Length * 2);
                    for (int i = 0; i < hash.Length; i++) hex.Append(hash[i].ToString("x2"));
                    sb.AppendLine(string.Format("      {0,-18}: {1}", label, hex.ToString()));
                }
            }
            catch (Exception ex)
            {
                sb.AppendLine(string.Format("      {0,-18}: [okunamadı: {1}]", label, ex.Message));
            }
        }

        // Bu uygulamanın paketlediği sürücü dosyasına işaret eden WinDivert hizmetini bulur.
        internal static string FindWinDivertServiceName()
        {
            try
            {
                using (RegistryKey services = Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Services", false))
                {
                    if (services == null) return null;
                    string[] names = services.GetSubKeyNames();
                    for (int i = 0; i < names.Length; i++)
                    {
                        if (!names[i].StartsWith("WinDivert", StringComparison.OrdinalIgnoreCase)) continue;
                        using (RegistryKey service = services.OpenSubKey(names[i], false))
                        {
                            string imagePath = service == null ? null : Convert.ToString(service.GetValue("ImagePath"));
                            if (AppPaths.IsBundledWinDivertDriverPath(imagePath)) return names[i];
                        }
                    }
                }
            }
            catch {}
            return null;
        }
    }

