        private void LoadReport()
        {
            if (_reportLoading) return;
            _reportLoading = true;
            if (_btnRefresh != null && !_btnRefresh.IsDisposed) _btnRefresh.Enabled = false;

            _txtReport.Text = "Rapor hazırlanıyor, lütfen bekleyin...\r\n";
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                string report;
                try
                {
                    report = AppLogger.GenerateFullReport(_profile, _isRunning, _pingMs);
                }
                catch (Exception ex)
                {
                    // Rapor üretimi çökerse ThreadPool istisnası süreci düşürmesin;
                    // hata metni gösterilir ve buton aşağıdaki yolda yeniden açılır.
                    report = "Rapor oluşturulamadı: " + ex.Message;
                }
                if (!this.IsDisposed && this.IsHandleCreated)
                {
                    try
                    {
                        this.BeginInvoke((MethodInvoker)delegate
                        {
                            _reportLoading = false;
                            if (_btnRefresh != null && !_btnRefresh.IsDisposed) _btnRefresh.Enabled = true;
                            if (!this.IsDisposed && _txtReport != null && !_txtReport.IsDisposed)
                            {
                                _txtReport.Text = report;
                                _txtReport.Select(0, 0);
                            }
                        });
                    }
                    catch
                    {
                        // BeginInvoke başarısız olduysa buton kilitli kalmasın (çapraz-thread ihlali olmadan güvenli çağrı).
                        _reportLoading = false;
                        try
                        {
                            if (_btnRefresh != null && !_btnRefresh.IsDisposed && _btnRefresh.IsHandleCreated)
                            {
                                _btnRefresh.BeginInvoke((MethodInvoker)delegate
                                {
                                    if (!_btnRefresh.IsDisposed) _btnRefresh.Enabled = true;
                                });
                            }
                        }
                        catch {}
                    }
                }
                else
                {
                    _reportLoading = false;
                }
            });
        }

        private void BtnCopy_Click(object sender, EventArgs e)
        {
            try
            {
                if (!string.IsNullOrEmpty(_txtReport.Text))
                {
                    string safeText = AppLogger.SanitizePii(_txtReport.Text);
                    Clipboard.SetText(safeText);
                    ToastNotification.Show("Tan\u0131lama", "Rapor kopyaland\u0131 (ki\u015fisel bilgiler gizlendi).", ToastType.Success, 2500);
                    _btnCopy.Text = "Kopyalandı!";
                    _btnCopy.IconType = "";
                    System.Windows.Forms.Timer t = new System.Windows.Forms.Timer();
                    t.Interval = 2000;
                    t.Tick += delegate
                    {
                        t.Stop();
                        t.Dispose();
                        if (!_btnCopy.IsDisposed)
                        {
                            _btnCopy.Text = "Raporu Kopyala";
                            _btnCopy.IconType = "copy";
                        }
                    };
                    t.Start();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Kopyalama başarısız: " + ex.Message, "Hata", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        private void BtnSaveTxt_Click(object sender, EventArgs e)
        {
            try
            {
                if (string.IsNullOrEmpty(_txtReport.Text)) return;

                using (SaveFileDialog dlg = new SaveFileDialog())
                {
                    dlg.Title = "Tanılama Raporunu Kaydet";
                    dlg.Filter = "Metin Dosyası (*.txt)|*.txt";
                    dlg.FileName = string.Format("GoodbyeDPI_Tanilama_{0:yyyy-MM-dd_HH-mm}.txt", DateTime.Now);
                    if (dlg.ShowDialog(this) == DialogResult.OK)
                    {
                        string safeText = AppLogger.SanitizePii(_txtReport.Text);
                        File.WriteAllText(dlg.FileName, safeText, Encoding.UTF8);
                        AppLogger.Log("DIAG", "Tanılama raporu dosyaya kaydedildi: " + dlg.FileName);
                        ToastNotification.Show("Tan\u0131lama", "Rapor kaydedildi: " + Path.GetFileName(dlg.FileName), ToastType.Success, 3000);
                    }
                }
            }
            catch (Exception ex)
            {
                ToastNotification.Show("Tan\u0131lama", "Kay\u0131t hatas\u0131: " + ex.Message, ToastType.Error, 4000);
            }
        }

        private void BtnOpenFile_Click(object sender, EventArgs e)
        {
            try
            {
                string path = AppLogger.LogFilePath;
                if (!File.Exists(path))
                {
                    File.WriteAllText(path, _txtReport.Text, Encoding.UTF8);
                }
                // Boşluk içeren yollar için tırnaklanır; süreç tutamacı hemen bırakılır.
                using (Process np = Process.Start("notepad.exe", "\"" + path + "\"")) { }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Dosya açılamadı: " + ex.Message, "Hata", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }
    }

    public class DnsOption
    {
        public const int DnsProbeRounds = 1;
        public const int MaximumDnsProbeSamples = 2;
        public const int MinimumValidDnsSamples = 1;
        public const int MaximumDnsMeasurementAgeSeconds = 600;
        public const long MinimumAutoSwitchImprovementMs = 3;

        public int Id { get; set; }
        public string Name { get; set; }
        public string DisplayName { get; set; }
        public string DpiArgs { get; set; }
        public string Description { get; set; }
        public string Subtitle { get; set; }
        public string Tag { get; set; }
        public Color TagColor { get; set; }
        public bool IsDoh { get; set; }
        public string DohUrl { get; set; }
        public string RightText { get; set; }
        public string PingTargetIp { get; set; }
        public long PingMs { get; set; } // Geçerli DNS sorgu/yanıt RTT medyanı; -1 = yanıt yok/ölçülmedi
        public long DnsLatencySpreadMs { get; set; }
        public long DnsTcpTotalMs { get; set; } // TCP bağlantısı + DNS sorgusu + yanıt medyanı; -1 = TCP toplamı yok
        public int DnsResponseCount { get; set; } // Discord hedef adlarından alınan geçerli DNS yanıtı sayısı (0-6)
        public DateTime PingMeasuredUtc { get; set; }
        public bool DnsMeasurementProtectionActive { get; set; }
        public string DnsMeasurementTransport { get; set; }
        public string DnsLastProbeError { get; set; }
        public string DnsServerIdentifier { get; set; }
        public long AnycastEdgeRttMs { get; set; }
        public bool IsLocalAnycastEdge { get; set; }
        public string ResolvedEdgeIp { get; set; }
        public bool IsAutomaticCandidate { get; set; }
        public bool AllowProtectedUdpProbe { get; set; }

        public DnsOption(int id, string name, string displayName, string dpiArgs, string desc, string subtitle = "", string tag = "", Color tagColor = default(Color), bool isDoh = false, string dohUrl = "", string rightText = "", string pingTargetIp = "", bool isAutomaticCandidate = true, bool allowProtectedUdpProbe = false)
        {
            Id = id;
            Name = name;
            DisplayName = displayName;
            DpiArgs = dpiArgs;
            Description = desc;
            Subtitle = subtitle ?? "";
            Tag = tag;
            TagColor = (tagColor == default(Color)) ? Color.FromArgb(56, 189, 248) : tagColor;
            IsDoh = isDoh;
            DohUrl = dohUrl;
            RightText = rightText ?? "";
            PingTargetIp = string.IsNullOrEmpty(pingTargetIp) ? rightText : pingTargetIp;
            PingMs = -1;
            DnsLatencySpreadMs = 0;
            DnsTcpTotalMs = -1;
            DnsResponseCount = 0;
            PingMeasuredUtc = DateTime.MinValue;
            DnsMeasurementProtectionActive = false;
            DnsMeasurementTransport = "";
            DnsLastProbeError = "";
            DnsServerIdentifier = "";
            AnycastEdgeRttMs = -1;
            IsLocalAnycastEdge = false;
            ResolvedEdgeIp = "";
            IsAutomaticCandidate = isAutomaticCandidate;
            AllowProtectedUdpProbe = allowProtectedUdpProbe;
        }
    }

    public static class WhitelistHelper
    {
        public static string SanitizeDomain(string input)
        {
            if (string.IsNullOrEmpty(input)) return null;
            string domain = input.Trim().ToLowerInvariant();

            if (domain.StartsWith("https://")) domain = domain.Substring(8);
            else if (domain.StartsWith("http://")) domain = domain.Substring(7);
            else if (domain.StartsWith("ftp://")) domain = domain.Substring(6);

            int slashIdx = domain.IndexOf('/');
            if (slashIdx >= 0) domain = domain.Substring(0, slashIdx);
            int qIdx = domain.IndexOf('?');
            if (qIdx >= 0) domain = domain.Substring(0, qIdx);
            int hIdx = domain.IndexOf('#');
            if (hIdx >= 0) domain = domain.Substring(0, hIdx);

            int colonIdx = domain.IndexOf(':');
            if (colonIdx >= 0) domain = domain.Substring(0, colonIdx);

            if (domain.StartsWith("www.")) domain = domain.Substring(4);

            domain = domain.Trim().Trim('.');

            if (string.IsNullOrEmpty(domain) || !domain.Contains(".")) return null;

            for (int i = 0; i < domain.Length; i++)
            {
                char c = domain[i];
                if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '-'))
                    return null;
            }

            return domain;
        }

        public static bool SaveWhitelist(string path, IEnumerable<string> domains)
        {
            List<string> cleanList = new List<string>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string d in domains)
            {
                string s = SanitizeDomain(d);
                if (!string.IsNullOrEmpty(s) && seen.Add(s))
                {
                    cleanList.Add(s);
                }
            }
            cleanList.Sort(StringComparer.OrdinalIgnoreCase);

            string tmpPath = path + ".tmp";
            try
            {
                File.WriteAllLines(tmpPath, cleanList.ToArray(), new UTF8Encoding(false));
                if (File.Exists(path))
                {
                    try
                    {
                        // Atomik değişim: okuyan süreç (goodbyedpi.exe) asla yarım dosya görmez.
                        File.Replace(tmpPath, path, null);
                    }
                    catch
                    {
                        // Replace başarısızsa eski güvenli kopya yoluna düş.
                        File.Copy(tmpPath, path, true);
                        try { File.Delete(tmpPath); } catch {}
                    }
                }
                else
                {
                    File.Move(tmpPath, path);
                }
                return true;
            }
            catch
            {
                try
                {
                    File.WriteAllLines(path, cleanList.ToArray(), new UTF8Encoding(false));
                    try { if (File.Exists(tmpPath)) File.Delete(tmpPath); } catch {}
                    return true;
                }
                catch
                {
                    // Her iki yol da başarısız: çağıran taraf kullanıcıya gerçek durumu bildirebilsin.
                    return false;
                }
            }
        }

        public static void CleanRobloxCacheAndProcesses()
        {
            try
            {
                string[] robloxProcs = new string[] { "RobloxPlayerBeta", "RobloxPlayerLauncher", "RobloxCrashHandler", "RobloxStudioBeta" };
                foreach (string procName in robloxProcs)
                {
                    try
                    {
                        Process[] procs = Process.GetProcessesByName(procName);
                        if (procs != null)
                        {
                            for (int i = 0; i < procs.Length; i++)
                            {
                                try { procs[i].Kill(); procs[i].WaitForExit(300); procs[i].Dispose(); } catch {}
                            }
                        }
                    }
                    catch {}
                }

                string localApp = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                string tempRoblox = Path.Combine(localApp, @"Temp\Roblox");
                if (Directory.Exists(tempRoblox))
                {
                    try { Directory.Delete(tempRoblox, true); } catch {}
                }

                string robloxDownloads = Path.Combine(localApp, @"Roblox\Downloads");
                if (Directory.Exists(robloxDownloads))
                {
                    try { Directory.Delete(robloxDownloads, true); } catch {}
                }

                string robloxLogs = Path.Combine(localApp, @"Roblox\logs");
                if (Directory.Exists(robloxLogs))
                {
                    try
                    {
                        string[] files = Directory.GetFiles(robloxLogs);
                        foreach (string f in files) { try { File.Delete(f); } catch {} }
                    }
                    catch {}
                }
            }
            catch {}
        }
    }

    // Modern Dark Custom Domain List with built-in custom sleek dark scrollbar & inline delete
    public class ModernDarkDomainList : Control
    {
        private readonly List<string> _items = new List<string>();
        private readonly HashSet<string> _selectedItems = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        private int _hoveredIndex = -1;
        private int _hoveredDeleteIndex = -1;
        private bool _mouseInside = false;

        private int _itemHeight = 28;
        // Yumuşak kaydırma: _scrollTarget hedef, _scrollIndex/_scrollAnim çizilen konum.
        private int _scrollIndex = 0;
        private int _scrollTarget = 0;
        private float _scrollAnim = 0f;
        private bool _isDraggingThumb = false;
        private int _dragStartY = 0;
        private int _dragStartScroll = 0;
        private bool _isThumbHovered = false;

        private const int ScrollBarWidth = 8;
        private const int ScrollBarMargin = 6;

        public event EventHandler SelectionChanged;
        public event EventHandler<string> ItemDeleteClicked;

        private static readonly Font _itemFont = new Font("Segoe UI", 9F, FontStyle.Regular);
        private static readonly Font _deleteFont = new Font("Segoe UI", 8F, FontStyle.Bold);
        private static readonly Font _emptyFont = new Font("Segoe UI", 9F, FontStyle.Italic);

        // Animasyon durumları (formun 25 ms'lik saatinden Tick() ile ilerletilir)
        private float _hoverAlpha = 0f;        // satır hover dolgusunun belirme oranı
        private float _delAlpha = 0f;          // ✕ rozetinin yumuşak belirmesi
        private float _selAlpha = 1f;          // seçim vurgusu geçiş yumuşatması
        private float _selAlphaTarget = 1f;
        private float _revealT = 1.5f;         // açılışta satırların sıralı belirmesi (>=1.5: bitti)
        private readonly Dictionary<string, long> _pulses = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, long> _pendingDeleteFlash = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
        private static readonly System.Diagnostics.Stopwatch _clock = System.Diagnostics.Stopwatch.StartNew();

        public ModernDarkDomainList()
        {
            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.Selectable, true);
            this.UpdateStyles();

            this.BackColor = Color.FromArgb(17, 22, 33);
            this.ForeColor = Color.FromArgb(226, 232, 240);
            this.Cursor = Cursors.Default;
        }

        public ICollection<string> SelectedItems
        {
            get { return _selectedItems; }
        }

        public int ItemCount
        {
            get { return _items.Count; }
        }

        public void SetItems(IEnumerable<string> items)
        {
            _items.Clear();
            if (items != null)
            {
                _items.AddRange(items);
            }
            // Filtre değiştiğinde artık görünmeyen seçimler temizlenir; aksi halde
            // "Seçileni Sil" gizli/var olmayan alan adları üzerinde çalışabilir.
            if (_selectedItems.Count > 0)
            {
                List<string> staleSelection = new List<string>();
                foreach (string s in _selectedItems)
                {
                    if (!_items.Contains(s)) staleSelection.Add(s);
                }
                for (int i = 0; i < staleSelection.Count; i++) _selectedItems.Remove(staleSelection[i]);
            }
            _hoveredIndex = -1;
            _hoveredDeleteIndex = -1;
            _selAlphaTarget = _selectedItems.Count > 0 ? 1f : 0f;
            if (_selAlphaTarget <= 0f) _selAlpha = 0f;
            EnsureScrollBounds();
            this.Invalidate();
        }

        public void ClearSelection()
        {
            _selectedItems.Clear();
            _selAlphaTarget = 0f;
            this.Invalidate();
        }

        public void SelectItem(string domain)
        {
            _selectedItems.Clear();
            if (!string.IsNullOrEmpty(domain) && _items.Contains(domain))
            {
                _selectedItems.Add(domain);
                _selAlpha = Math.Min(_selAlpha, 0.4f); // seçim vurgusu yumuşakça belirsin
                _selAlphaTarget = 1f;
                int idx = _items.IndexOf(domain);
                EnsureVisible(idx);
            }
            else
            {
                _selAlphaTarget = 0f;
            }
            this.Invalidate();
        }

        public void EnsureVisible(int index)
        {
            if (index < 0 || index >= _items.Count) return;
            int visibleCount = GetVisibleItemCount();
            if (index < _scrollTarget)
            {
                _scrollTarget = index;
            }
            else if (index >= _scrollTarget + visibleCount)
            {
                _scrollTarget = Math.Max(0, index - visibleCount + 1);
            }
            EnsureScrollBounds();
            this.Invalidate();
        }

        private int GetVisibleItemCount()
        {
            return Math.Max(1, this.Height / _itemHeight);
        }

        private int GetMaxScroll()
        {
            int visible = GetVisibleItemCount();
            return Math.Max(0, _items.Count - visible);
        }

        private void EnsureScrollBounds()
        {
            int max = GetMaxScroll();
            if (_scrollTarget > max) _scrollTarget = max;
            if (_scrollTarget < 0) _scrollTarget = 0;
            if (_scrollAnim > max) _scrollAnim = max;
            if (_scrollAnim < 0f) _scrollAnim = 0f;
            if (_scrollIndex > max) _scrollIndex = max;
            if (_scrollIndex < 0) _scrollIndex = 0;
        }

        private Rectangle GetScrollBarTrackRect()
        {
            return new Rectangle(this.Width - ScrollBarWidth - ScrollBarMargin, ScrollBarMargin, ScrollBarWidth, this.Height - ScrollBarMargin * 2);
        }

        private Rectangle GetScrollBarThumbRect()
        {
            Rectangle track = GetScrollBarTrackRect();
            int maxScroll = GetMaxScroll();
            if (maxScroll <= 0 || _items.Count == 0) return Rectangle.Empty;

            float visibleRatio = (float)GetVisibleItemCount() / (float)_items.Count;
            int thumbHeight = Math.Max(24, (int)(track.Height * visibleRatio));
            int availableTrack = track.Height - thumbHeight;
            int thumbY = track.Y + (int)((float)_scrollIndex / (float)maxScroll * availableTrack);

            return new Rectangle(track.X, thumbY, track.Width, thumbHeight);
        }

        protected override void OnMouseCaptureChanged(EventArgs e)
        {
            // Thumb sürüklerken fare kontrol dışında bırakılırsa takılı kalmasın.
            if (!this.Capture && _isDraggingThumb)
            {
                _isDraggingThumb = false;
                this.Invalidate();
            }
            base.OnMouseCaptureChanged(e);
        }

        protected override void OnMouseWheel(MouseEventArgs e)
        {
            base.OnMouseWheel(e);
            _mouseInside = true;
            // Tekerlek hedefi kaydırır; çizim Tick() içinde yumuşakça yaklaşır.
            _scrollTarget += e.Delta > 0 ? -3 : 3;
            EnsureScrollBounds();
            UpdateHover(e.Location);
            this.Invalidate();
        }

        private Rectangle GetDeleteButtonRect(int rowY)
        {
            int maxScroll = GetMaxScroll();
            int x = this.Width - (maxScroll > 0 ? 38 : 28);
            int size = 18;
            int y = rowY + (_itemHeight - size) / 2;
            return new Rectangle(x, y, size, size);
        }

        private void UpdateHover(Point pt)
        {
            Rectangle thumbRect = GetScrollBarThumbRect();
            _isThumbHovered = !thumbRect.IsEmpty && thumbRect.Contains(pt);

            Rectangle trackRect = GetScrollBarTrackRect();
            if (trackRect.Contains(pt) && GetMaxScroll() > 0)
            {
                _hoveredIndex = -1;
                _hoveredDeleteIndex = -1;
                return;
            }

            int idx = _scrollIndex + (pt.Y / _itemHeight);
            if (idx >= 0 && idx < _items.Count)
            {
                _hoveredIndex = idx;
                int rowY = (idx - _scrollIndex) * _itemHeight;
                Rectangle delRect = GetDeleteButtonRect(rowY);
                _hoveredDeleteIndex = delRect.Contains(pt) ? idx : -1;
            }
            else
            {
                _hoveredIndex = -1;
                _hoveredDeleteIndex = -1;
            }
        }

        protected override void OnMouseMove(MouseEventArgs e)
        {
            base.OnMouseMove(e);
            if (_isDraggingThumb)
            {
                Rectangle track = GetScrollBarTrackRect();
                int maxScroll = GetMaxScroll();
                if (maxScroll > 0)
                {
                    float visibleRatio = (float)GetVisibleItemCount() / (float)_items.Count;
                    int thumbHeight = Math.Max(24, (int)(track.Height * visibleRatio));
                    int availableTrack = track.Height - thumbHeight;
                    if (availableTrack > 0)
                    {
                        int deltaY = e.Y - _dragStartY;
                        float scrollFrac = (float)deltaY / (float)availableTrack;
                        int newScroll = _dragStartScroll + (int)(scrollFrac * maxScroll);
                        _scrollIndex = Math.Max(0, Math.Min(maxScroll, newScroll));
                        _scrollAnim = _scrollIndex;   // sürüklemede 1:1 takip (animasyonsuz)
                        _scrollTarget = _scrollIndex;
                        this.Invalidate();
                    }
                }
                return;
            }

            UpdateHover(e.Location);
            this.Invalidate();
        }

        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            this.Focus();

            if (e.Button == MouseButtons.Left)
            {
                Rectangle thumbRect = GetScrollBarThumbRect();
                if (!thumbRect.IsEmpty && thumbRect.Contains(e.Location))
                {
                    _isDraggingThumb = true;
                    _dragStartY = e.Y;
                    _dragStartScroll = _scrollIndex;
                    this.Capture = true;
                    return;
                }

                Rectangle trackRect = GetScrollBarTrackRect();
                if (trackRect.Contains(e.Location) && GetMaxScroll() > 0)
                {
                    if (e.Y < thumbRect.Y) _scrollTarget = Math.Max(0, _scrollTarget - GetVisibleItemCount());
                    else _scrollTarget = Math.Min(GetMaxScroll(), _scrollTarget + GetVisibleItemCount());
                    this.Invalidate();
                    return;
                }

                int idx = _scrollIndex + (e.Y / _itemHeight);
                if (idx >= 0 && idx < _items.Count)
                {
                    int rowY = (idx - _scrollIndex) * _itemHeight;
                    Rectangle delRect = GetDeleteButtonRect(rowY);
                    if (delRect.Contains(e.Location))
                    {
                        // Kırmızı flaş oynar, ardından silme olayı tetiklenir (Tick içinde).
                        StartDeleteFlash(_items[idx]);
                        return;
                    }

                    string domain = _items[idx];
                    if ((ModifierKeys & Keys.Control) == Keys.Control)
                    {
                        if (_selectedItems.Contains(domain)) _selectedItems.Remove(domain);
                        else _selectedItems.Add(domain);
                    }
                    else
                    {
                        _selectedItems.Clear();
                        _selectedItems.Add(domain);
                    }

                    if (SelectionChanged != null) SelectionChanged(this, EventArgs.Empty);
                    this.Invalidate();
                }
            }
        }

        protected override void OnMouseUp(MouseEventArgs e)
        {
            base.OnMouseUp(e);
            if (_isDraggingThumb)
            {
                _isDraggingThumb = false;
                this.Capture = false;
                this.Invalidate();
            }
        }

        protected override void OnMouseEnter(EventArgs e)
        {
            base.OnMouseEnter(e);
            _mouseInside = true;
            this.Invalidate();
        }

        protected override void OnMouseLeave(EventArgs e)
        {
            base.OnMouseLeave(e);
            if (!_isDraggingThumb)
            {
                _mouseInside = false;
                _hoveredIndex = -1;
                _hoveredDeleteIndex = -1;
                _isThumbHovered = false;
                this.Invalidate();
            }
        }

        protected override void OnKeyDown(KeyEventArgs e)
        {
            base.OnKeyDown(e);
            if (e.KeyCode == Keys.Up)
            {
                MoveSelection(-1);
                e.Handled = true;
            }
            else if (e.KeyCode == Keys.Down)
            {
                MoveSelection(1);
                e.Handled = true;
            }
        }

        private void MoveSelection(int dir)
        {
            if (_items.Count == 0) return;
            int curIdx = -1;
            for (int i = 0; i < _items.Count; i++)
            {
                if (_selectedItems.Contains(_items[i]))
                {
                    curIdx = i;
                    break;
                }
            }

            int newIdx = curIdx + dir;
            if (newIdx < 0) newIdx = 0;
            if (newIdx >= _items.Count) newIdx = _items.Count - 1;

            _selectedItems.Clear();
            _selectedItems.Add(_items[newIdx]);
            EnsureVisible(newIdx);
            if (SelectionChanged != null) SelectionChanged(this, EventArgs.Empty);
            this.Invalidate();
        }

        private static long NowMs()
        {
            return _clock.ElapsedMilliseconds;
        }

        // Renk harmanı: t=0 -> from, t=1 -> to (yumuşak geçişler için).
        private static Color BlendColor(Color from, Color to, float t)
        {
            if (t <= 0f) return from;
            if (t >= 1f) return to;
            return Color.FromArgb(
                from.A + (int)((to.A - from.A) * t),
                from.R + (int)((to.R - from.R) * t),
                from.G + (int)((to.G - from.G) * t),
                from.B + (int)((to.B - from.B) * t));
        }

        // Satırın açılış belirmesindeki alfa değeri (0..1); satır başına küçük gecikme.
        private float GetRowReveal(int itemIdx, int itemCount)
        {
            if (_revealT >= 1.5f) return 1f;
            float delayPerRow = 0.30f / Math.Max(1, Math.Min(itemCount, 16));
            float local = (_revealT - itemIdx * delayPerRow) / 0.45f;
            if (local < 0f) return 0f;
            if (local > 1f) return 1f;
            return local;
        }

        // Açılışta satırların sıralı belirme animasyonunu başlatır.
        public void PlayReveal()
        {
            _revealT = 0f;
            this.Invalidate();
        }

        // Yeni eklenen alan adlarını kısa süreli parlamayla vurgular.
        public void PulseDomains(IEnumerable<string> domains)
        {
            if (domains == null) return;
            long now = NowMs();
            foreach (string d in domains)
            {
                if (!string.IsNullOrEmpty(d)) _pulses[d] = now;
            }
            this.Invalidate();
        }

        // Alan adını görünür alana kaydırır (yumuşak kaydırma hedefi güncellenir).
        public void ScrollToDomain(string domain)
        {
            if (string.IsNullOrEmpty(domain)) return;
            int idx = _items.IndexOf(domain);
            if (idx >= 0) EnsureVisible(idx);
        }

        // Silme: önce kısa kırmızı flaş, ardından ItemDeleteClicked olayı.
        private void StartDeleteFlash(string domain)
        {
            if (string.IsNullOrEmpty(domain)) return;
            if (_pendingDeleteFlash.ContainsKey(domain)) return; // çift tıklama koruması
            _pendingDeleteFlash[domain] = NowMs();
            this.Invalidate();
        }

        // Formun 25 ms'lik animasyon saati çağırır: hover belirmesi, yumuşak kaydırma,
        // satır reveal'i, yeni öğe parlamaları ve geciktirilmiş silme flaşları burada ilerler.
        public void Tick()
        {
            bool dirty = false;

            // 1) Hover dolgusu ve ✕ belirmesi
            bool hovering = _mouseInside && _hoveredIndex >= 0;
            float hTarget = hovering ? 1f : 0f;
            if (_hoverAlpha != hTarget)
            {
                _hoverAlpha += (hTarget - _hoverAlpha) * 0.30f;
                if (Math.Abs(_hoverAlpha - hTarget) < 0.03f) _hoverAlpha = hTarget;
                dirty = true;
            }
            if (_delAlpha != hTarget)
            {
                _delAlpha += (hTarget - _delAlpha) * 0.30f;
                if (Math.Abs(_delAlpha - hTarget) < 0.03f) _delAlpha = hTarget;
                dirty = true;
            }

            // 2) Seçim vurgusu geçişi
            if (_selAlpha != _selAlphaTarget)
            {
                _selAlpha += (_selAlphaTarget - _selAlpha) * 0.25f;
                if (Math.Abs(_selAlpha - _selAlphaTarget) < 0.03f) _selAlpha = _selAlphaTarget;
                dirty = true;
            }

            // 3) Yumuşak kaydırma
            if (!_isDraggingThumb)
            {
                if (Math.Abs(_scrollAnim - _scrollTarget) > 0.05f)
                {
                    _scrollAnim += (_scrollTarget - _scrollAnim) * 0.30f;
                    _scrollIndex = (int)Math.Round(_scrollAnim);
                    dirty = true;
                }
                else if (_scrollIndex != _scrollTarget)
                {
                    _scrollAnim = _scrollTarget;
                    _scrollIndex = _scrollTarget;
                    dirty = true;
                }
            }

            // 4) Açılış belirmesi
            if (_revealT < 1.5f)
            {
                _revealT += 0.055f;
                if (_revealT > 1.5f) _revealT = 1.5f;
                dirty = true;
            }

            // 5) Süresi dolan parlamaları temizle
            if (_pulses.Count > 0)
            {
                long now = NowMs();
                List<string> done = null;
                foreach (KeyValuePair<string, long> kv in _pulses)
                {
                    if (now - kv.Value >= 900)
                    {
                        if (done == null) done = new List<string>();
                        done.Add(kv.Key);
                    }
                }
                if (done != null)
                {
                    for (int i = 0; i < done.Count; i++) _pulses.Remove(done[i]);
                }
                dirty = true;
            }

            // 6) Silme flaşları: süresi dolanlar için olayı şimdi tetikle
            if (_pendingDeleteFlash.Count > 0)
            {
                long now = NowMs();
                List<string> fire = null;
                foreach (KeyValuePair<string, long> kv in _pendingDeleteFlash)
                {
                    if (now - kv.Value >= 170)
                    {
                        if (fire == null) fire = new List<string>();
                        fire.Add(kv.Key);
                    }
                }
                if (fire != null)
                {
                    for (int i = 0; i < fire.Count; i++) _pendingDeleteFlash.Remove(fire[i]);
                    for (int i = 0; i < fire.Count; i++)
                    {
                        if (ItemDeleteClicked != null) ItemDeleteClicked(this, fire[i]);
                    }
                }
                dirty = true;
            }

            if (dirty) this.Invalidate();
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            // Container Background
            using (SolidBrush bgB = new SolidBrush(this.BackColor))
            {
                g.FillRectangle(bgB, 0, 0, this.Width, this.Height);
            }

            int visibleCount = GetVisibleItemCount() + 1;
            int maxScroll = GetMaxScroll();
            int rightPadding = (maxScroll > 0) ? (ScrollBarWidth + ScrollBarMargin * 2) : 6;
            long now = NowMs();

            if (_items.Count == 0)
            {
                // Boş durum metni de yumuşakça belirir.
                float emptyA = Math.Max(0f, Math.Min(1f, _revealT / 0.5f));
                Rectangle emptyRect = new Rectangle(10, 0, this.Width - 20, this.Height);
                TextRenderer.DrawText(g, "Eşleşen alan adı bulunamadı.", _emptyFont, emptyRect,
                    BlendColor(this.BackColor, Color.FromArgb(100, 116, 139), emptyA),
                    TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
            }
            else
            {
                for (int i = 0; i < visibleCount; i++)
                {
                    int itemIdx = _scrollIndex + i;
                    if (itemIdx >= _items.Count) break;

                    string domain = _items[itemIdx];
                    int rowY = i * _itemHeight;
                    Rectangle rowRect = new Rectangle(3, rowY + 1, this.Width - rightPadding - 3, _itemHeight - 2);

                    bool isSelected = _selectedItems.Contains(domain);
                    bool isHovered = (itemIdx == _hoveredIndex) && _mouseInside;
                    float reveal = GetRowReveal(itemIdx, _items.Count);
                    if (reveal <= 0f) continue;

                    // 1) Yeni öğe parlaması: uçtan sönümlenen yumuşak vurgu
                    if (_pulses.ContainsKey(domain))
                    {
                        float pulseP = (float)(now - _pulses[domain]) / 900f;
                        if (pulseP < 0f) pulseP = 0f;
                        if (pulseP > 1f) pulseP = 1f;
                        int pulseA = (int)((1f - pulseP) * (1f - pulseP) * 60f);
                        if (pulseA > 0)
                        {
                            using (GraphicsPath pulsePath = ModernMainForm.CreateRoundedRectangleF(rowRect, 6f))
                            using (SolidBrush pulseB = new SolidBrush(Color.FromArgb((int)(pulseA * reveal), 56, 189, 248)))
                            {
                                g.FillPath(pulseB, pulsePath);
                            }
                        }
                    }

                    // 2) Silme flaşı: kısa kırmızı yanıp sönme
                    if (_pendingDeleteFlash.ContainsKey(domain))
                    {
                        float flashP = (float)(now - _pendingDeleteFlash[domain]) / 170f;
                        if (flashP < 0f) flashP = 0f;
                        if (flashP > 1f) flashP = 1f;
                        int flashA = (int)((1f - flashP) * 90f);
                        if (flashA > 0)
                        {
                            using (GraphicsPath flashPath = ModernMainForm.CreateRoundedRectangleF(rowRect, 6f))
                            using (SolidBrush flashB = new SolidBrush(Color.FromArgb(flashA, 248, 113, 113)))
                            {
                                g.FillPath(flashB, flashPath);
                            }
                        }
                    }

                    // 3) Seçim / hover dolgusu (yumuşak geçişli; zebra çizgisi yok — daha sade)
                    if (isSelected)
                    {
                        int selA = (int)(_selAlpha * reveal * 255f);
                        if (selA > 6)
                        {
                            using (GraphicsPath selPath = ModernMainForm.CreateRoundedRectangleF(rowRect, 6f))
                            using (LinearGradientBrush selB = new LinearGradientBrush(rowRect,
                                Color.FromArgb(selA, 29, 78, 216), Color.FromArgb(selA, 37, 99, 235), LinearGradientMode.Horizontal))
                            {
                                g.FillPath(selB, selPath);
                            }
                        }
                    }
                    else if (isHovered && _hoverAlpha > 0.03f)
                    {
                        int hovA = (int)(_hoverAlpha * reveal * 46f);
                        using (GraphicsPath hovPath = ModernMainForm.CreateRoundedRectangleF(rowRect, 6f))
                        using (SolidBrush hovB = new SolidBrush(Color.FromArgb(hovA, 56, 74, 104)))
                        {
                            g.FillPath(hovB, hovPath);
                        }
                    }

                    // 4) Alan adı metni (sade, temiz hizalama)
                    Color baseTextClr = isSelected ? Color.White : (isHovered ? Color.FromArgb(248, 250, 252) : Color.FromArgb(226, 232, 240));
                    Color textClr = BlendColor(this.BackColor, baseTextClr, reveal);
                    Rectangle textRect = new Rectangle(14, rowY, rowRect.Width - 40, _itemHeight);
                    TextRenderer.DrawText(g, domain, _itemFont, textRect, textClr,
                        TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);

                    // 5) ✕ rozeti: hover'da yumuşakça belirir, seçili satırda hep görünür
                    if (isSelected || isHovered)
                    {
                        Rectangle delRect = GetDeleteButtonRect(rowY);
                        bool isDelHover = (itemIdx == _hoveredDeleteIndex) && _mouseInside;
                        float delShow = isSelected ? 1f : _delAlpha;
                        if (delShow > 0.03f)
                        {
                            Color delBgColor = isDelHover
                                ? Color.FromArgb(225, 29, 72)
                                : Color.FromArgb(30, 41, 59);
                            int delA = (int)(delShow * reveal * 255f);

                            using (GraphicsPath delPath = ModernMainForm.CreateRoundedRectangleF(delRect, 4f))
                            using (SolidBrush delBg = new SolidBrush(Color.FromArgb(Math.Min(255, delA), delBgColor)))
                            {
                                g.FillPath(delBg, delPath);
                            }

                            // Keskin vektörel X
                            float cx = delRect.X + (delRect.Width / 2f);
                            float cy = delRect.Y + (delRect.Height / 2f);
                            float delArm = 3.5f;
                            Color xBase = isDelHover ? Color.White : Color.FromArgb(148, 163, 184);
                            Color xClr = BlendColor(this.BackColor, xBase, Math.Min(1f, delShow * reveal + 0.25f));
                            using (Pen xPen = new Pen(xClr, 1.25f))
                            {
                                xPen.StartCap = LineCap.Flat;
                                xPen.EndCap = LineCap.Flat;
                                g.DrawLine(xPen, cx - delArm, cy - delArm, cx + delArm, cy + delArm);
                                g.DrawLine(xPen, cx + delArm, cy - delArm, cx - delArm, cy + delArm);
                            }
                        }
                    }
                }
            }

            // İnce scrollbar: iz çizilmez; başparmak yumuşak ve sade
            if (maxScroll > 0)
            {
                Rectangle thumb = GetScrollBarThumbRect();
                if (!thumb.IsEmpty)
                {
                    Color thumbClr = (_isDraggingThumb || _isThumbHovered) ? Color.FromArgb(100, 116, 139) : Color.FromArgb(58, 72, 96);
                    using (GraphicsPath thumbPath = ModernMainForm.CreateRoundedRectangleF(thumb, 4f))
                    using (SolidBrush thumbB = new SolidBrush(thumbClr))
                    {
                        g.FillPath(thumbB, thumbPath);
                    }
                }
            }

            // Border of the entire list control
            using (Pen borderPen = new Pen(Color.FromArgb(36, 45, 62), 1f))
            {
                g.DrawRectangle(borderPen, 0, 0, this.Width - 1, this.Height - 1);
            }
        }
    }

    // Modern Vector Window Close Button (Razor-sharp flat-cap vector X, borderless modern crimson hover)
    public class ModernWindowCloseButton : Control
    {
        private bool _isHovered = false;
        private bool _isPressed = false;
        private float _hoverProgress = 0f;

        public ModernWindowCloseButton()
        {
            this.DoubleBuffered = true;
            this.SetStyle(ControlStyles.SupportsTransparentBackColor | ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint, true);
            this.UpdateStyles();
            this.Size = new Size(30, 30);
            this.Cursor = Cursors.Hand;
            this.BackColor = Color.Transparent;
        }

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == 0x0021) // WM_MOUSEACTIVATE
            {
                m.Result = (IntPtr)1; // MA_ACTIVATE
                return;
            }
            base.WndProc(ref m);
        }

        public void UpdateAnimation()
        {
            if (this.Visible && this.Enabled && !this.IsDisposed && this.IsHandleCreated)
            {
                Form parent = this.FindForm();
                if (parent != null && parent.Visible && parent.WindowState != FormWindowState.Minimized)
                {
                    Point curPos = Cursor.Position;
                    Point clientPt = this.PointToClient(curPos);
                    if (this.ClientRectangle.Contains(clientPt))
                    {
                        _isHovered = true;
                    }
                    else
                    {
                        _isHovered = false;
                    }
                }
                else
                {
                    _isHovered = false;
                }
            }
            else
            {
                _isHovered = false;
            }

            float target = _isHovered ? 1.0f : 0.0f;
            if (Math.Abs(_hoverProgress - target) > 0.03f)
            {
                _hoverProgress += (target - _hoverProgress) * 0.35f;
                this.Invalidate();
            }
            else if (_hoverProgress != target)
            {
                _hoverProgress = target;
                this.Invalidate();
            }
        }

        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _isHovered = true; this.Invalidate(); }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _isHovered = false; _isPressed = false; this.Invalidate(); }
        protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (e.Button == MouseButtons.Left) { _isPressed = true; this.Invalidate(); } }
        protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); _isPressed = false; this.Invalidate(); }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.PixelOffsetMode = PixelOffsetMode.HighQuality;

            RectangleF rect = new RectangleF(0.5f, 0.5f, this.Width - 1f, this.Height - 1f);

            // Borderless modern crimson fill on hover / pressed
            if (_hoverProgress > 0.01f || _isPressed)
            {
                int alpha = _isPressed ? 255 : (int)(255 * _hoverProgress);
                Color curBg = _isPressed ? Color.FromArgb(alpha, 190, 18, 60) : Color.FromArgb(alpha, 225, 29, 72);

                using (GraphicsPath path = ModernMainForm.CreateRoundedRectangleF(rect, 5f))
                using (SolidBrush b = new SolidBrush(curBg))
                {
                    g.FillPath(b, path);
                }
            }

            float cx = this.Width / 2f;
            float cy = this.Height / 2f;
            float arm = 4.5f;

            // Transition smoothly from slate-400 (148, 163, 184) to crisp white
            int r = (int)(148 + (255 - 148) * _hoverProgress);
            int gr = (int)(163 + (255 - 163) * _hoverProgress);
            int bl = (int)(184 + (255 - 184) * _hoverProgress);
            Color xColor = _isPressed ? Color.White : Color.FromArgb(Math.Min(255, r), Math.Min(255, gr), Math.Min(255, bl));

            using (Pen pen = new Pen(xColor, 1.25f))
            {
                pen.StartCap = LineCap.Flat;
                pen.EndCap = LineCap.Flat;
                g.DrawLine(pen, cx - arm, cy - arm, cx + arm, cy + arm);
                g.DrawLine(pen, cx + arm, cy - arm, cx - arm, cy + arm);
            }
        }
    }

