        private Point _dragStartPoint;
        private bool _isDraggingWindow;

        // Gerçek placeholder: sentinel metin Tag'da tutulur; arama/ekleme mantığı Tag ile
        // karşılaştırıp sentinel'i yok sayar (bkz. RefreshList / BtnAdd_Click).
        private static void SetPlaceholder(TextBox textBox, string placeholder)
        {
            Color placeholderColor = Color.FromArgb(100, 116, 139);
            Color normalColor = textBox.ForeColor;

            textBox.Tag = placeholder;
            textBox.ForeColor = placeholderColor;
            textBox.Text = placeholder;

            textBox.GotFocus += delegate(object s, EventArgs e)
            {
                if (textBox.Text == placeholder)
                {
                    textBox.ForeColor = normalColor;
                    textBox.Text = "";
                }
            };
            textBox.LostFocus += delegate(object s, EventArgs e)
            {
                if (textBox.Text.Length == 0)
                {
                    textBox.ForeColor = placeholderColor;
                    textBox.Text = placeholder;
                }
            };
        }

        public WhitelistManagerForm(string whitelistPath, Action onSaveAndApply)
        {
            _whitelistPath = whitelistPath;
            _onSaveAndApply = onSaveAndApply;

            this.FormBorderStyle = FormBorderStyle.None;
            this.StartPosition = FormStartPosition.CenterParent;
            this.ShowInTaskbar = false;
            this.Size = new Size(480, 520);
            this.BackColor = Color.FromArgb(15, 19, 29);
            this.DoubleBuffered = true;
            this.KeyPreview = true;
            this.Opacity = 1.0;
            this.Text = "Oyun veya Site Listesi";

            try
            {
                this.Icon = Icon.ExtractAssociatedIcon(Application.ExecutablePath);
            }
            catch {}

            InitializeControls();
            LoadDomains();
        }

        protected override void OnLoad(EventArgs e)
        {
            base.OnLoad(e);
        }

        protected override void OnActivated(EventArgs e)
        {
            base.OnActivated(e);
            if (this.Visible && !_isClosing)
            {
                if (this.Visible && _animTimer != null && !_animTimer.Enabled) _animTimer.Start();
            }
            CheckFileModifiedOnDisk();
        }

        private void CheckFileModifiedOnDisk()
        {
            try
            {
                if (File.Exists(_whitelistPath))
                {
                    DateTime curWrite = File.GetLastWriteTimeUtc(_whitelistPath);
                    if (curWrite > _lastLoadedFileTime)
                    {
                        // Kaydedilmemiş GUI değişiklikleri varken disk kopyası yüklenmez;
                        // aksi hâlde kullanıcının bekleyen düzenlemeleri sessizce ezilirdi.
                        if (_hasUnsavedChanges)
                        {
                            _lastLoadedFileTime = curWrite; // aynı sürümü tekrar tekrar görmeyi bırak
                            return;
                        }
                        if (LoadDomains())
                        {
                            ShowStatus("✓ Not Defteri değişiklikleri otomatik yüklendi.", false);
                        }
                        else
                        {
                            ShowStatus("Dosya değişti ama okunamadı; değişiklikleri görmek için tekrar deneyin.", true);
                        }
                    }
                }
            }
            catch {}
        }

        private void StartEntranceAnimation()
        {
            this.Opacity = 1.0;
        }

        private void AnimateClose()
        {
            if (_isClosing) return;
            _isClosing = true;

            bool saved = true;
            if (_hasUnsavedChanges)
            {
                try { saved = WhitelistHelper.SaveWhitelist(_whitelistPath, _allDomains); }
                catch { saved = false; }
                if (saved)
                {
                    _hasUnsavedChanges = false;
                    _lastLoadedFileTime = File.GetLastWriteTimeUtc(_whitelistPath);
                    if (_onSaveAndApply != null) _onSaveAndApply();
                }
            }
            if (saved)
            {
                this.Close();
            }
            else
            {
                _isClosing = false;
                ShowStatus("Kaydetme başarısız: dosya yazılamadı, pencere açık kaldı.", true);
            }
        }

        // Animasyonlu kapanış dışındaki kapanmalarda (Alt+F4 vb.) bekleyen değişiklikler kaybolmasın.
        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            if (!_isClosing && _hasUnsavedChanges)
            {
                bool saved = false;
                try
                {
                    saved = WhitelistHelper.SaveWhitelist(_whitelistPath, _allDomains);
                    if (saved)
                    {
                        _hasUnsavedChanges = false;
                        _lastLoadedFileTime = File.GetLastWriteTimeUtc(_whitelistPath);
                        if (_onSaveAndApply != null) _onSaveAndApply();
                    }
                }
                catch { saved = false; }

                if (!saved)
                {
                    // Dosya yazılamadı (ör. başka programda kilitli): değişiklikler sessizce
                    // kaybolmasın; kullanıcı bilinçli karar versin.
                    DialogResult res = MessageBox.Show(this,
                        "Bekleyen değişiklikler dosyaya yazılamadı. Yine de kapatılsın mı?\n(Kapatırsanız değişiklikler kaybolur.)",
                        "Kaydetme Başarısız", MessageBoxButtons.YesNo, MessageBoxIcon.Warning);
                    if (res != DialogResult.Yes)
                    {
                        e.Cancel = true;
                        return;
                    }
                }
            }
            base.OnFormClosing(e);
        }

