        private void AnimTimer_Tick(object sender, EventArgs e)
        {
            if (Form.ActiveForm != this)
            {
                if (_animTimer != null && _animTimer.Enabled) _animTimer.Stop();
                return;
            }
            if (_btnClose != null) _btnClose.UpdateAnimation();
            if (_btnPresetRoblox != null) _btnPresetRoblox.UpdateAnimation();
            if (_btnPresetWattpad != null) _btnPresetWattpad.UpdateAnimation();
            if (_btnPresetPastebin != null) _btnPresetPastebin.UpdateAnimation();
            if (_btnAdd != null) _btnAdd.UpdateAnimation();
            if (_btnDelete != null) _btnDelete.UpdateAnimation();
            if (_btnOpenNotepad != null) _btnOpenNotepad.UpdateAnimation();
            if (_btnSave != null) _btnSave.UpdateAnimation();
            if (_lstDomains != null) _lstDomains.Tick(); // hover / kaydırma / parlama / flaş animasyonları
            TickCountPulse();
            TickStatusFade();
            TickDeleteState();
        }

        // Renk harmanı: t=0 -> from, t=1 -> to (yumuşak geçişler için).
        private static Color BlendColor(Color from, Color to, float t)
        {
            if (t <= 0f) return from;
            if (t >= 1f) return to;
            return Color.FromArgb(
                from.A + (int)((to.A - from.A) * t),
                from.R + (int)((to.R - from.R) * t),
                from.G + (int)((to.G - from.G) * t),
                from.B + (int)((to.B - from.B) * t));
        }

        // Sayaç etiketi: sayı değiştiğinde kısa süreli vurgu nabzı.
        private void TickCountPulse()
        {
            if (_lblCount == null || _countPulse <= 0f) return;
            _countPulse -= 0.055f;
            if (_countPulse <= 0f)
            {
                _countPulse = 0f;
                _lblCount.ForeColor = Color.FromArgb(148, 163, 184);
            }
            else
            {
                _lblCount.ForeColor = BlendColor(Color.FromArgb(148, 163, 184), Color.FromArgb(125, 211, 252), _countPulse);
            }
        }

        // Durum yazısı: mesaj gelince belirir; süre dolunca sönüp senkron metnine döner.
        private void TickStatusFade()
        {
            if (_lblStatus == null) return;
            if (Math.Abs(_statusAlpha - _statusAlphaTarget) > 0.02f)
            {
                _statusAlpha += (_statusAlphaTarget - _statusAlpha) * 0.25f;
                ApplyStatusColor();
            }
            else if (_statusAlpha != _statusAlphaTarget)
            {
                _statusAlpha = _statusAlphaTarget;
                ApplyStatusColor();
                if (_statusAlphaTarget <= 0f && _statusSwapPending)
                {
                    _statusSwapPending = false;
                    _lblStatus.Text = "✓ Liste güncel";
                    _statusBaseColor = Color.FromArgb(52, 211, 153);
                    _statusAlphaTarget = 1f;
                }
            }
        }

        private void ApplyStatusColor()
        {
            if (_lblStatus == null) return;
            _lblStatus.ForeColor = BlendColor(FormBg, _statusBaseColor, _statusAlpha);
        }

        // "Seçileni Sil": seçim yokken sönük; seçim gelince kısa bir parlama ile kırmızıya döner.
        private void TickDeleteState()
        {
            if (_lstDomains == null || _btnDelete == null) return;
            int sel = _lstDomains.SelectedItems.Count;
            if (sel != _lastSelCount)
            {
                _lastSelCount = sel;
                UpdateDeleteButtonStyle(sel > 0);
                if (sel > 0) _deleteWake = 1f;
            }
            if (_deleteWake > 0f && _lastSelCount > 0)
            {
                _deleteWake -= 0.07f;
                if (_deleteWake < 0f) _deleteWake = 0f;
                float tri = 1f - Math.Abs(2f * _deleteWake - 1f); // 0->1->0 nabız
                _btnDelete.BorderColor = BlendColor(Color.FromArgb(64, 34, 40), Color.FromArgb(239, 68, 68), tri);
                _btnDelete.Invalidate();
            }
        }

        private void UpdateDeleteButtonStyle(bool active)
        {
            if (_btnDelete == null) return;
            if (active)
            {
                _btnDelete.ForeColor = Color.FromArgb(248, 113, 113);
                _btnDelete.BackColor = Color.FromArgb(26, 22, 26);
                _btnDelete.BorderColor = Color.FromArgb(64, 34, 40);
                _btnDelete.HoverBorderColor = Color.FromArgb(239, 68, 68);
                _btnDelete.HoverColor = Color.FromArgb(45, 22, 28);
                _btnDelete.GlowColor = Color.FromArgb(220, 38, 38);
            }
            else
            {
                _btnDelete.ForeColor = Color.FromArgb(107, 120, 142);
                _btnDelete.BackColor = Color.FromArgb(20, 24, 33);
                _btnDelete.BorderColor = Color.FromArgb(38, 46, 62);
                _btnDelete.HoverBorderColor = Color.FromArgb(38, 46, 62);
                _btnDelete.HoverColor = Color.FromArgb(23, 28, 39);
                _btnDelete.GlowColor = Color.Empty;
            }
            _btnDelete.Invalidate();
        }

        private void Header_MouseDown(object sender, MouseEventArgs e)
        {
            if (e.Button == MouseButtons.Left)
            {
                _isDraggingWindow = true;
                _dragStartPoint = e.Location;
            }
        }

        private void Header_MouseMove(object sender, MouseEventArgs e)
        {
            // Fare pencere dışında bırakılırsa sürükleme takılı kalmasın.
            if (_isDraggingWindow && (Control.MouseButtons & MouseButtons.Left) == 0)
            {
                _isDraggingWindow = false;
                return;
            }
            if (_isDraggingWindow)
            {
                this.Location = new Point(
                    this.Location.X + (e.X - _dragStartPoint.X),
                    this.Location.Y + (e.Y - _dragStartPoint.Y));
            }
        }

        private void Header_MouseUp(object sender, MouseEventArgs e)
        {
            _isDraggingWindow = false;
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            using (Pen borderPen = new Pen(Color.FromArgb(42, 52, 74), 1f))
            {
                e.Graphics.DrawRectangle(borderPen, 0, 0, this.Width - 1, this.Height - 1);
            }
        }

        private bool LoadDomains()
        {
            bool success = false;
            if (File.Exists(_whitelistPath))
            {
                try
                {
                    string[] lines = File.ReadAllLines(_whitelistPath);
                    List<string> loaded = new List<string>();
                    for (int i = 0; i < lines.Length; i++)
                    {
                        string s = WhitelistHelper.SanitizeDomain(lines[i]);
                        if (!string.IsNullOrEmpty(s))
                        {
                            loaded.Add(s);
                        }
                    }
                    // Yalnızca okuma başarılıysa bellekteki listeyi değiştir; aksi halde sonraki
                    // "Kaydet" boş listeyi diske yazıp tüm whitelist'i silebilir.
                    _allDomains.Clear();
                    for (int i = 0; i < loaded.Count; i++) _allDomains.Add(loaded[i]);
                    _lastLoadedFileTime = File.GetLastWriteTimeUtc(_whitelistPath);
                    success = true;
                }
                catch {}
            }
            else
            {
                _allDomains.Clear();
                success = true; // dosya yok: boş liste geçerli durumdur
            }
            RefreshList();
            UpdatePresetButtons();
            return success;
        }

        private void RefreshList()
        {
            // Savunma: kontroller kurulmadan (ör. yapıcı sırasında) listeyi doldurmaya çalışma.
            if (_lstDomains == null || _lblCount == null) return;
            _filteredDomains.Clear();
            string q = _txtSearch.Text.Trim().ToLowerInvariant();
            // Placeholder sentinel'i gerçek arama sorgusu gibi filtrelemeye sokma.
            if (_txtSearch.Tag != null && _txtSearch.Text == (string)_txtSearch.Tag) q = "";

            foreach (string d in _allDomains)
            {
                if (string.IsNullOrEmpty(q) || d.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    _filteredDomains.Add(d);
                }
            }
            _filteredDomains.Sort(StringComparer.OrdinalIgnoreCase);

            _lstDomains.SetItems(_filteredDomains);

            if (string.IsNullOrEmpty(q))
            {
                _lblCount.Text = string.Format("{0} adres kayıtlı", _allDomains.Count);
            }
            else
            {
                _lblCount.Text = string.Format("{0} sonuç ({1} toplam)", _filteredDomains.Count, _allDomains.Count);
            }

            // Liste verisi değiştiyse sayaç kısa bir vurgu nabzıyla dikkat çeker.
            if (_allDomains.Count != _lastCountValue)
            {
                _lastCountValue = _allDomains.Count;
                _countPulse = 1f;
                if (_lblCount != null) _lblCount.ForeColor = Color.FromArgb(125, 211, 252);
            }
        }

        private void UpdatePresetButtons()
        {
            UpdatePresetBtn(_btnPresetRoblox, "Roblox", RobloxDomains);
            UpdatePresetBtn(_btnPresetWattpad, "Wattpad", WattpadDomains);
            UpdatePresetBtn(_btnPresetPastebin, "Pastebin", PastebinDomains);
        }

        private void UpdatePresetBtn(RoundedButton btn, string name, string[] domains)
        {
            bool allPresent = true;
            for (int i = 0; i < domains.Length; i++)
            {
                if (!_allDomains.Contains(domains[i]))
                {
                    allPresent = false;
                    break;
                }
            }

            btn.BorderRadius = 13;
            if (allPresent)
            {
                btn.Text = "✓ " + name;
                btn.BackColor = Color.FromArgb(18, 36, 30);
                btn.ForeColor = Color.FromArgb(52, 211, 153);
                btn.BorderColor = Color.FromArgb(34, 110, 80);
                btn.HoverBorderColor = Color.FromArgb(52, 211, 153);
                btn.HoverColor = Color.FromArgb(24, 48, 38);
                btn.GlowColor = Color.Transparent;
            }
            else
            {
                btn.Text = "+ " + name;
                btn.BackColor = Color.FromArgb(22, 28, 40);
                btn.ForeColor = Color.FromArgb(203, 213, 225);
                btn.BorderColor = Color.FromArgb(42, 54, 76);
                btn.HoverBorderColor = Color.FromArgb(70, 88, 120);
                btn.HoverColor = Color.FromArgb(30, 38, 56);
                btn.GlowColor = Color.Transparent;
            }
        }

        private void TogglePreset(string name, string[] domains)
        {
            bool allPresent = true;
            for (int i = 0; i < domains.Length; i++)
            {
                if (!_allDomains.Contains(domains[i]))
                {
                    allPresent = false;
                    break;
                }
            }

            List<string> addedDomains = new List<string>();

            if (allPresent)
            {
                DialogResult dr = MessageBox.Show(this, name + " adreslerini listeden kaldırmak istiyor musunuz?", "Onay", MessageBoxButtons.YesNo, MessageBoxIcon.Question);
                if (dr == DialogResult.Yes)
                {
                    for (int i = 0; i < domains.Length; i++) _allDomains.Remove(domains[i]);
                    _hasUnsavedChanges = true;
                    ShowStatus(name + " adresleri kaldırıldı.", false);
                }
            }
            else
            {
                for (int i = 0; i < domains.Length; i++)
                {
                    if (_allDomains.Add(domains[i])) addedDomains.Add(domains[i]);
                }
                _hasUnsavedChanges = true;
                if (name == "Roblox")
                {
                    // Önbellek temizliği süreç öldürüp dosya silebilir; UI'yi kilitlememek için
                    // arka planda yürütülür (durum mesajı kullanıcıyı bekletmez).
                    ShowStatus("✓ Roblox eklendi ve önbellek temizleniyor...", false);
                    ThreadPool.QueueUserWorkItem(delegate(object st)
                    {
                        try { WhitelistHelper.CleanRobloxCacheAndProcesses(); } catch {}
                    });
                }
                else
                {
                    ShowStatus("✓ " + name + " adresleri eklendi.", false);
                }
            }

            RefreshList();
            UpdatePresetButtons();
            // Hızlı eklemede yeni satırlar parlar; ilk eklenen görünür alana kaydırılır.
            if (addedDomains.Count > 0)
            {
                _lstDomains.PulseDomains(addedDomains);
                _lstDomains.ScrollToDomain(addedDomains[0]);
            }
        }

        private void BtnPresetRoblox_Click(object sender, EventArgs e) { TogglePreset("Roblox", RobloxDomains); }
        private void BtnPresetWattpad_Click(object sender, EventArgs e) { TogglePreset("Wattpad", WattpadDomains); }
        private void BtnPresetPastebin_Click(object sender, EventArgs e) { TogglePreset("Pastebin", PastebinDomains); }

