        private static readonly Color TrackDark = Color.FromArgb(28, 36, 52);
        private static readonly Color AccentSky = Color.FromArgb(56, 189, 248);
        private static readonly Color AccentGreen = Color.FromArgb(52, 211, 153);
        private static readonly Color AccentAmber = Color.FromArgb(245, 158, 11);
        private static readonly Color AccentRed = Color.FromArgb(239, 68, 68);

        // Yazı tipleri: Segoe UI ailesi, aşamalı boyutlar (başlık 15,5 / büyük sayı 44 / gövde 10)
        private Font _fTitle;
        private Font _fSub;
        private Font _fBig;
        private Font _fUnit;
        private Font _fStatus;
