        private DateTime _startUtc;
        private DateTime _lastSampleUtc;
        private DateTime _warmUtc;
        private long _lastBytes;
        private long _warmBytes = -1;
        private bool _running;
        private bool _finished;
        private bool _usingBackup;
        private double _shownMbps;
        private double _displayMbps;   // yumuşatılmış gösterge değeri (animasyon)
        private float _pulsePhase;     // ölçüm sırasında nabız parlaması
        private double _progress;
        private double _downloadedMb;  // canlı: indirilen MB (istatistik kartı)
        private double _elapsedSec;    // canlı: geçen süre (istatistik kartı)
        private string _serverText = "—";
        private string _status = "Hazır. Ölçümü başlatın.";
        private string _resultText = "";

        // Görsel ölçüler tek yerde: örnek ekran görüntüsüne göre ince ayar kolay.
        private const int GaugeCy = 210;   // yay merkezi (dikey)
        private const int GaugeR = 94;     // yay yarıçapı
        private const int BigY = 126;      // büyük sayı üst kenarı
        private const int StatusY = 228;   // durum satırı
        private const int ProgressY = 258; // ince ilerleme çubuğu
        private const int StatsY = 280;    // istatistik kartları
        private const int ResultY = 348;   // sonuç kartı
        private const int ButtonY = 418;   // eylem düğmesi

        // Test sonucu metni: log ve doğrulama kanıtı ile aynı kaynak.
        public string LastSpeedResult { get { return _resultText; } }

        public SpeedTestForm()
        {
            this.FormBorderStyle = FormBorderStyle.None;
