            _fUnit = new Font("Segoe UI Semibold", 12F, FontStyle.Regular);
            _fStatus = new Font("Segoe UI", 10F, FontStyle.Regular);
            _fTick = new Font("Segoe UI", 7.75F, FontStyle.Regular);
            _fLabel = new Font("Segoe UI", 8.25F, FontStyle.Regular);
            _fValue = new Font("Segoe UI Semibold", 11.5F, FontStyle.Regular);
            _fResult = new Font("Segoe UI", 10F, FontStyle.Regular);
