            _btnStart.BackColor = Color.FromArgb(37, 99, 235);
            _btnStart.BorderColor = Color.FromArgb(50, 90, 190);
            _btnStart.HoverColor = Color.FromArgb(68, 150, 255);
            _btnStart.HoverBorderColor = Color.FromArgb(200, 230, 255);
            _btnStart.GlowColor = Color.FromArgb(59, 130, 246);
            _btnStart.BackdropColor = Color.FromArgb(14, 17, 24);
            _btnStart.SpinWhenBusy = true;
