        // Ölçüm durumunu sıfırlar: her sunucu denemesi (birincil/yedek) KENDİ sıfırından
        // başlar; önceki denemenin bekleme süresi ve bayat örnekleri sonuca karışmaz.
        private void ResetMeasurementState()
        {
            _shownMbps = 0;
            _displayMbps = 0;
            _pulsePhase = 0;
            _progress = 0;
            _downloadedMb = 0;
            _elapsedSec = 0;
            _lastBytes = 0;
            _warmBytes = -1;
            _startUtc = DateTime.UtcNow;
            _lastSampleUtc = _startUtc;
        }

        // Testi başlat: düğme ve doğrulama koşumu bu köprüyü kullanır.
        public void StartTest()
        {
            if (_running) return;
            _running = true;
            _finished = false;
            _resultText = "";
            _usingBackup = false;
            ResetMeasurementState();
            _serverText = "Cloudflare";
            _status = "Bağlantı kuruluyor…";
            _btnStart.Enabled = false;
            _btnStart.IconType = "refresh";   // ölçüm boyunca dönen tazeleme ikonu
            _btnStart.IsBusy = true;
            this.Invalidate();

            _timeoutTimer.Stop();
            _timeoutTimer.Start();
            _animTimer.Stop();
            _animTimer.Start();

            try
            {
                _wc = new WebClient();
                _wc.Proxy = null;
                _wc.Headers.Add("User-Agent", "GoodbyeDPI-ProMAX-SpeedTest");
                _wc.DownloadProgressChanged += new DownloadProgressChangedEventHandler(Wc_Progress);
                _wc.DownloadDataCompleted += new DownloadDataCompletedEventHandler(Wc_Completed);
                _wc.DownloadDataAsync(new Uri(PrimaryUrl));
            }
            catch (Exception ex)
            {
                FinishWithError("Test başlatılamadı: " + ex.Message);
            }
        }

        private void Wc_Progress(object sender, DownloadProgressChangedEventArgs e)
        {
            if (!_running || this.IsDisposed) return;

            DateTime now = DateTime.UtcNow;
            double elapsed = (now - _startUtc).TotalSeconds;

            // Canlı istatistik kartları (indirilen / süre) her ilerleme olayında tazelenir.
            _elapsedSec = elapsed;
            _downloadedMb = e.BytesReceived / (1024.0 * 1024.0);

            // Isınma payı: ilk 1,5 sn TCP yavaş başlangıçtır, ortalamaya katılmaz.
            if (_warmBytes < 0 && elapsed >= 1.5)
            {
                _warmBytes = e.BytesReceived;
                _warmUtc = now;
            }

            double dt = (now - _lastSampleUtc).TotalSeconds;
            if (dt < 0.3) return; // görsel güncellemeyi saniyede ~3 ile sınırla

            if (elapsed >= 1.5)
            {
                _shownMbps = (e.BytesReceived - _lastBytes) * 8.0 / 1000000.0 / dt;
            }
            _lastBytes = e.BytesReceived;
            _lastSampleUtc = now;

            _progress = e.TotalBytesToReceive > 0 ? (double)e.BytesReceived / e.TotalBytesToReceive : 0;
            int pct = (int)Math.Round(_progress * 100);
            if (_shownMbps > 0)
                _status = string.Format("Ölçüm sürüyor… %{0} • {1:0.0} Mbps", pct, _shownMbps);
            else
                _status = "Ölçüm sürüyor… %" + pct;
            this.Invalidate();
        }

        private void Wc_Completed(object sender, DownloadDataCompletedEventArgs e)
        {
            if (!_running || this.IsDisposed) return;
            _timeoutTimer.Stop();

            if (e.Cancelled)
            {
                _running = false;
                _shownMbps = 0;
                _progress = 0;
                _resultText = "Sonuç: Çok yavaş. 45 saniyede 10 MB tamamlanamadı (2 Mbps altı bir hız).";
                _status = "Ölçüm zaman aşımına uğradı.";
                AppLogger.Log("SPEED", "Hız testi zaman aşımına uğradı (çok yavaş bağlantı).");
                EndTest();
                return;
            }

            if (e.Error != null)
            {
                if (!_usingBackup)
                {
                    _usingBackup = true;
                    _serverText = "OVH (yedek)";
                    _status = "Birincil sunucu yanıt vermedi; yedek sunucu deneniyor…";
                    AppLogger.Log("SPEED", "Birincil test sunucusu başarısız (" + e.Error.Message + "), yedek sunucu deneniyor.");
                    try
                    {
                        // Yedek ölçüm SIFIRDAN başlar ve 45 sn güvenlik zamanlayıcısı yeniden
                        // kurulur (birincil denemenin beklemesi hız hesabına yansımaz).
                        ResetMeasurementState();
                        _wc.DownloadDataAsync(new Uri(BackupUrl));
                        _timeoutTimer.Start();
                        return;
                    }
                    catch (Exception ex2)
                    {
                        FinishWithError("Bağlantı kurulamadı: " + ex2.Message);
                        return;
                    }
                }
                FinishWithError("Bağlantı kurulamadı: " + e.Error.Message);
                return;
            }

            double mbps;
            double secondsUsed;
            double totalSeconds;
            double mb;
            try
            {
                DateTime endUtc = DateTime.UtcNow;
                long bytes = e.Result == null ? 0 : e.Result.Length;
                mb = bytes / (1024.0 * 1024.0);
                totalSeconds = (endUtc - _startUtc).TotalSeconds;

                if (_warmBytes > 0 && _warmUtc < endUtc)
                {
                    secondsUsed = (endUtc - _warmUtc).TotalSeconds;
                    mbps = (bytes - _warmBytes) * 8.0 / 1000000.0 / Math.Max(0.25, secondsUsed);
                }
                else
                {
                    secondsUsed = totalSeconds;
                    mbps = bytes * 8.0 / 1000000.0 / Math.Max(0.25, secondsUsed);
                }
                if (mbps < 0.1) mbps = 0.1; // sıfır görünmesin: ölçülemezse en az 0,1
            }
            catch (Exception ex)
            {
                FinishWithError("Sonuç hesaplanamadı: " + ex.Message);
                return;
            }

            _shownMbps = mbps;
            _progress = 1;
            _downloadedMb = mb;
            _elapsedSec = totalSeconds;
            _serverText = _usingBackup ? "OVH (yedek)" : "Cloudflare";
            _finished = true;

            string verdict;
            string hint;
            if (mbps < 5) { verdict = "Zayıf"; hint = "Video ve oyun için sınırda; sağlayıcınızla hattınızı kontrol edin."; }
            else if (mbps < 15) { verdict = "Orta"; hint = "Günlük kullanım için yeterli; büyük indirmeler yavaş olabilir."; }
            else if (mbps < 35) { verdict = "İyi"; hint = "Discord, oyun ve video için rahat bir hız."; }
            else if (mbps < 70) { verdict = "Çok iyi"; hint = "Yüksek hızlı bağlantı; çoklu cihazda rahat eder."; }
            else { verdict = "Mükemmel"; hint = "Fiber seviyesinde bir indirme hızı."; }

            _resultText = string.Format("Sonuç: {0}. {1}", verdict, hint);
            _status = "Test tamamlandı."; // MB/süre ayrıntısı istatistik kartlarında gösterilir.
            AppLogger.Log("SPEED", string.Format("Hız testi: {0:0.0} Mbps ({1:0.0} MB / {2:0.0} sn toplam; kararlı pencere {3:0.0} sn, {4})",
                mbps, mb, totalSeconds, secondsUsed, _usingBackup ? "yedek sunucu" : "birincil sunucu"));
            EndTest();
        }

        private void TimeoutTimer_Tick(object sender, EventArgs e)
        {
            _timeoutTimer.Stop();
            if (!_running) return;
            try { if (_wc != null && _wc.IsBusy) _wc.CancelAsync(); } catch { }
        }

        private void FinishWithError(string message)
        {
            _shownMbps = 0;
            _progress = 0;
            _resultText = message;
            _status = "Test başarısız.";
            AppLogger.Log("SPEED", message);
            EndTest();
        }

        private void EndTest()
        {
            _running = false;
            try { _timeoutTimer.Stop(); } catch { }
            _btnStart.Text = "Yeniden test et";
            _btnStart.IconType = "download";
            _btnStart.IsBusy = false;
            _btnStart.Enabled = true;
            try { if (_wc != null) { _wc.Dispose(); _wc = null; } } catch { }
            this.Invalidate();
        }

        // Kare animasyonu: gösterge değeri hedefe sönümlenir; ölçüm sırasında nabız parlar.
        private void AnimTimer_Tick(object sender, EventArgs e)
        {
            if (this.IsDisposed) return;
            bool needsPaint = false;

            double diff = _shownMbps - _displayMbps;
            if (Math.Abs(diff) > 0.05)
            {
                _displayMbps += diff * 0.22;
                if (Math.Abs(_shownMbps - _displayMbps) <= 0.05) _displayMbps = _shownMbps;
                needsPaint = true;
            }

            if (_running)
            {
                _pulsePhase += 0.09f;
                if (_pulsePhase > 6.2832f) _pulsePhase -= 6.2832f;
                needsPaint = true;
            }

            if (needsPaint) this.Invalidate();
            else _animTimer.Stop(); // hedefe ulaşıldı: boşta CPU harcamayı bırak
        }

        // Karekök ölçek: 0-200 Mbps aralığı, hız göstergesi hissi (10→%22, 50→%50, 100→%71, 200→%100)
        private static double GaugeFraction(double mbps)
        {
            double v = mbps;
            if (v < 0) v = 0;
            if (v > 200) v = 200;
            return Math.Sqrt(v / 200.0);
        }

        private Color GaugeColor()
        {
            if (_running || !_finished) return AccentSky;
            if (_shownMbps < 5) return AccentRed;
            if (_shownMbps < 15) return AccentAmber;
            return AccentGreen;
        }

        private Color BigNumberColor()
        {
            if (_running) return AccentSky;                        // ölçüm sırasında mavi
            if (!_finished) return Color.FromArgb(100, 116, 139);  // hazır: gri
            if (_shownMbps < 5) return AccentRed;
            if (_shownMbps < 15) return AccentAmber;
            return AccentGreen;
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            // Başlık: mini hız göstergesi simgesi + başlık + alt başlık
            float icx = M + 10f;
            float icy = 30f;
            float ir = 8f;
            using (Pen ip = new Pen(AccentSky, 2f))
            {
                ip.StartCap = LineCap.Round;
                ip.EndCap = LineCap.Round;
                g.DrawArc(ip, icx - ir, icy - ir, ir * 2, ir * 2, 180f, 180f);
            }
            using (Pen np = new Pen(AccentSky, 1.6f))
            {
                np.StartCap = LineCap.Round;
                np.EndCap = LineCap.Round;
                g.DrawLine(np, icx, icy, icx + 5f, icy - 5f);
            }
            using (SolidBrush nb = new SolidBrush(AccentSky))
            {
                g.FillEllipse(nb, icx - 1.6f, icy - 1.6f, 3.2f, 3.2f);
            }

            TextRenderer.DrawText(g, "Hız Testi", _fTitle, new Point(M + 28, 14), Color.FromArgb(248, 250, 252),
                TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
            TextRenderer.DrawText(g, "İnternet indirme hızınızı hızlıca test edin.", _fSub,
                new Point(M + 29, 45), TextDim, TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);

            DrawGauge(g);

            bool hasVal = _displayMbps > 0.049 || _finished;
            string big = hasVal ? _displayMbps.ToString("0.0") : "--";
            // 44 pt satır yüksekliği 79 px'tir; kutu kırpması yaşamamak için 92 px + NoClipping.
            TextRenderer.DrawText(g, big, _fBig, new Rectangle(0, BigY, W, 92), BigNumberColor(),
                TextFormatFlags.HorizontalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoClipping);
            TextRenderer.DrawText(g, "Mbps", _fUnit, new Rectangle(0, BigY + 62, W, 24), TextDim,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix);

            TextRenderer.DrawText(g, _status, _fStatus, new Rectangle(0, StatusY, W, 20), TextDim,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix);

            // İnce ilerleme çubuğu (indirme ilerlemesi)
            RectangleF barBg = new RectangleF(M, ProgressY, W - 2 * M, 6);
            using (GraphicsPath bp = ModernMainForm.CreateRoundedRectangleF(barBg, 3f))
            using (SolidBrush bb = new SolidBrush(TrackDark))
            {
                g.FillPath(bb, bp);
            }
            double pv = _progress;
            if (pv < 0) pv = 0;
            if (pv > 1) pv = 1;
            if (pv > 0.01)
            {
                RectangleF barFg = new RectangleF(barBg.X, barBg.Y, (float)(barBg.Width * pv), barBg.Height);
                using (GraphicsPath fp = ModernMainForm.CreateRoundedRectangleF(barFg, 3f))
                using (SolidBrush fb = new SolidBrush(_finished && _shownMbps >= 15 ? AccentGreen : AccentSky))
                {
                    g.FillPath(fb, fp);
                }
            }

            // İstatistik kartları: indirilen / süre / sunucu
            DrawStatCard(g, 0, "İNDİRİLEN", _downloadedMb > 0 ? _downloadedMb.ToString("0.0") + " MB" : "—");
            DrawStatCard(g, 1, "SÜRE", _elapsedSec > 0 ? _elapsedSec.ToString("0.0") + " sn" : "—");
            DrawStatCard(g, 2, "SUNUCU", _serverText);

            // Sonuç kartı
            RectangleF card = new RectangleF(M + 0.5f, ResultY + 0.5f, W - M * 2 - 1f, 58f);
            using (GraphicsPath cp = ModernMainForm.CreateRoundedRectangleF(card, 10f))
            using (SolidBrush cb = new SolidBrush(CardBg))
            using (Pen cpen = new Pen(CardBorder, 1f))
            {
                g.FillPath(cb, cp);
                g.DrawPath(cpen, cp);
            }
            if (!string.IsNullOrEmpty(_resultText))
            {
                TextRenderer.DrawText(g, _resultText, _fResult,
                    new Rectangle(M + 14, ResultY + 11, W - M * 2 - 28, 46), TextMain,
                    TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix);
            }
            else
            {
                TextRenderer.DrawText(g, "Test bittiğinde internet hızınız burada görünecek. Koruma internetinizi yavaşlatmaz.", _fResult,
                    new Rectangle(M + 14, ResultY + 13, W - M * 2 - 28, 42), TextFaint,
                    TextFormatFlags.WordBreak | TextFormatFlags.NoPrefix);
            }

            TextRenderer.DrawText(g, "Sonuç yaklaşık değerdir; sunucu ve saate göre değişebilir.", _fNote,
                new Rectangle(0, H - 24, W, 18), TextFaint,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix);
        }

        // Kadran: karekök ölçekli yay, çentikler, nabızlı parlama ve uç işareti.
        private void DrawGauge(Graphics g)
        {
            int cx = W / 2;
            float r = GaugeR;
            RectangleF arcRect = new RectangleF(cx - r, GaugeCy - r, r * 2, r * 2);

            // Zemin yayı
            using (Pen track = new Pen(TrackDark, 9f))
            {
                track.StartCap = LineCap.Round;
                track.EndCap = LineCap.Round;
                g.DrawArc(track, arcRect, 180f, 180f);
            }

            double frac = GaugeFraction(_displayMbps);
            float sweep = (float)(frac * 180.0);
            if (sweep > 0.5f)
            {
                Color c = GaugeColor();

                // Nabızlı yumuşak parlama (ölçüm sırasında hafifçe soluyup parlar)
                int glowA = _running ? (int)(36 + 22 * Math.Sin(_pulsePhase)) : 32;
                if (glowA < 0) glowA = 0;
                if (glowA > 92) glowA = 92;
                using (Pen glow = new Pen(Color.FromArgb(glowA, c.R, c.G, c.B), 17f))
                {
                    glow.StartCap = LineCap.Round;
                    glow.EndCap = LineCap.Round;
                    g.DrawArc(glow, arcRect, 180f, sweep);
                }

                // Değer yayı
                using (Pen val = new Pen(c, 9f))
                {
                    val.StartCap = LineCap.Round;
                    val.EndCap = LineCap.Round;
                    g.DrawArc(val, arcRect, 180f, sweep);
                }

                // Değer yayının bittiği noktada uç işareti
                double ang = (180.0 + frac * 180.0) * Math.PI / 180.0;
                float ex = (float)(cx + r * Math.Cos(ang));
                float ey = (float)(GaugeCy + r * Math.Sin(ang));
                using (SolidBrush dotW = new SolidBrush(Color.FromArgb(235, 255, 255, 255)))
                {
                    g.FillEllipse(dotW, ex - 3.4f, ey - 3.4f, 6.8f, 6.8f);
                }
                using (SolidBrush dotC = new SolidBrush(c))
                {
                    g.FillEllipse(dotC, ex - 2.1f, ey - 2.1f, 4.2f, 4.2f);
                }
            }

            // Çentikler ve etiketler: 0 / 10 / 50 / 100 / 200 (karekök ölçek, hız göstergesi düzeni)
            double[] ticks = new double[] { 0, 10, 50, 100, 200 };
            for (int i = 0; i < ticks.Length; i++)
            {
                double tf = Math.Sqrt(ticks[i] / 200.0);
                double rad = (180.0 + tf * 180.0) * Math.PI / 180.0;
                float x1 = (float)(cx + (r + 7) * Math.Cos(rad));
                float y1 = (float)(GaugeCy + (r + 7) * Math.Sin(rad));
                float x2 = (float)(cx + (r + 12) * Math.Cos(rad));
                float y2 = (float)(GaugeCy + (r + 12) * Math.Sin(rad));
                using (Pen tp = new Pen(Color.FromArgb(60, 74, 96), 1.2f))
                {
                    g.DrawLine(tp, x1, y1, x2, y2);
                }

                string lbl = ticks[i].ToString("0");
                Size ls = TextRenderer.MeasureText(lbl, _fTick, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
                int lx = (int)Math.Round(cx + (r + 22) * Math.Cos(rad) - ls.Width / 2.0);
                int ly = (int)Math.Round(GaugeCy + (r + 22) * Math.Sin(rad) - ls.Height / 2.0);
                TextRenderer.DrawText(g, lbl, _fTick, new Point(lx, ly), TextFaint,
                    TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
            }
        }

        // İstatistik kartı: üç eşit kart (indeks 0-2), etiket + değer.
        private void DrawStatCard(Graphics g, int index, string label, string value)
        {
            int gap = 10;
            int cardW = (W - M * 2 - gap * 2) / 3;
            int x = M + index * (cardW + gap);
            RectangleF rct = new RectangleF(x + 0.5f, StatsY + 0.5f, cardW - 1f, 55f);
            using (GraphicsPath p = ModernMainForm.CreateRoundedRectangleF(rct, 8f))
            using (SolidBrush b = new SolidBrush(CardBg))
            using (Pen pen = new Pen(CardBorder, 1f))
            {
                g.FillPath(b, p);
                g.DrawPath(pen, p);
            }
            TextRenderer.DrawText(g, label, _fLabel, new Point(x + 12, StatsY + 10), TextFaint,
                TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
            TextRenderer.DrawText(g, value, _fValue, new Rectangle(x + 12, StatsY + 26, cardW - 24, 22), TextMain,
                TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        }

        protected override bool ProcessCmdKey(ref Message msg, Keys keyData)
        {
            if (keyData == Keys.Escape)
            {
                this.Close();
                return true;
            }
            return base.ProcessCmdKey(ref msg, keyData);
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                _running = false;
                try { if (_timeoutTimer != null) { _timeoutTimer.Stop(); _timeoutTimer.Dispose(); } } catch { }
                _timeoutTimer = null;
                try { if (_animTimer != null) { _animTimer.Stop(); _animTimer.Dispose(); } } catch { }
                _animTimer = null;
                try { if (_wc != null) { _wc.CancelAsync(); } } catch { }
                try { if (_wc != null) { _wc.Dispose(); } } catch { }
                _wc = null;
                if (_fTitle != null) _fTitle.Dispose();
                if (_fSub != null) _fSub.Dispose();
                if (_fBig != null) _fBig.Dispose();
                if (_fUnit != null) _fUnit.Dispose();
                if (_fStatus != null) _fStatus.Dispose();
                if (_fTick != null) _fTick.Dispose();
                if (_fLabel != null) _fLabel.Dispose();
                if (_fValue != null) _fValue.Dispose();
                if (_fResult != null) _fResult.Dispose();
                if (_fNote != null) _fNote.Dispose();
                if (_fAction != null) _fAction.Dispose();
            }
            base.Dispose(disposing);
        }
    }

    #endregion

    #region First-Run Setup Wizard (Kurulum Sihirbazı)

    // ==================== Ağ Test Yardımcıları (Network Probe) ====================
    // Rapor (GenerateFullReport) ve Kurulum Sihirbazı tarafından paylaşılır.
    // Yalnızca salt-okunur ICMP/UDP/TCP testleri — P/Invoke yok, yeni DLL bağımlılığı yok.
    public static class NetworkProbe
    {
        private static int _dnsQuerySequence = Environment.TickCount;
        private static int _hostResolveInFlight = 0;

        private sealed class HostResolveState
        {
            public readonly object Sync = new object();
            public readonly ManualResetEvent Completed = new ManualResetEvent(false);
            public bool CallbackCompleted;
            public bool CallerReturned;
            public IPAddress[] Addresses;
            public string Error;
        }

        public static byte[] BuildDiscordQueryBytes()
        {
            return new byte[] {
                0x12, 0x34, 0x01, 0x00, 0x00, 0x01, 0x00, 0x00,
                0x00, 0x00, 0x00, 0x00, 0x07, 0x64, 0x69, 0x73,
                0x63, 0x6f, 0x72, 0x64, 0x03, 0x63, 0x6f, 0x6d,
                0x00, 0x00, 0x01, 0x00, 0x01
            };
        }

        public static IPAddress[] ResolveHostIps(string host, out string error)
        {
            error = null;
            if (string.IsNullOrWhiteSpace(host))
            {
                error = "DNS sorgu adı boş";
                return null;
            }
            if (Interlocked.CompareExchange(ref _hostResolveInFlight, 1, 0) != 0)
            {
                error = "Önceki DNS çözümlemesi hâlâ tamamlanmadı";
                return null;
            }

            HostResolveState state = new HostResolveState();
            bool requestStarted = false;
            try
            {
                Dns.BeginGetHostAddresses(host, delegate(IAsyncResult result)
                {
                    try
                    {
                        state.Addresses = Dns.EndGetHostAddresses(result);
                    }
                    catch (Exception ex)
                    {
                        state.Error = ex.Message;
                    }
                    finally
                    {
                        lock (state.Sync)
                        {
                            state.CallbackCompleted = true;
                            try { state.Completed.Set(); } catch {}
                            if (state.CallerReturned)
                            {
                                try { state.Completed.Dispose(); } catch {}
                            }
                        }
                        Interlocked.Exchange(ref _hostResolveInFlight, 0);
                    }
                }, null);
                requestStarted = true;

                bool completed = state.Completed.WaitOne(2000, true);
                lock (state.Sync)
                {
                    state.CallerReturned = true;
                    if (state.CallbackCompleted)
                    {
                        try { state.Completed.Dispose(); } catch {}
                    }
                }
                if (!completed)
                {
                    error = "DNS çözümlemesi 2000 ms içinde tamamlanmadı; bekleme sona erdi ve geç sonuç kullanılmayacak";
                    return null;
                }
                if (!string.IsNullOrEmpty(state.Error))
                {
                    error = state.Error;
                    return null;
                }
                return state.Addresses;
            }
            catch (Exception ex)
            {
                Interlocked.Exchange(ref _hostResolveInFlight, 0);
                lock (state.Sync)
                {
                    state.CallerReturned = true;
                    if (!requestStarted)
                    {
                        try { state.Completed.Dispose(); } catch {}
                    }
                    if (state.CallbackCompleted)
                    {
                        try { state.Completed.Dispose(); } catch {}
                    }
                }
                error = ex.Message;
                return null;
            }
        }

        public static bool IsPoisonedDiscordIp(IPAddress ip)
        {
            if (ip == null || ip.AddressFamily != AddressFamily.InterNetwork) return false;
            byte[] b = ip.GetAddressBytes();
            if (b == null || b.Length != 4) return false;
            return (b[0] == 195 && (b[1] == 175 || b[1] == 174)) ||
                (b[0] == 212 && (b[1] == 156 || b[1] == 252 || b[1] == 253)) ||
                b[0] == 0 || b[0] == 10 || b[0] == 127 ||
                (b[0] == 169 && b[1] == 254) ||
                (b[0] == 192 && b[1] == 168) ||
                (b[0] == 172 && b[1] >= 16 && b[1] <= 31) ||
                (b[0] == 100 && b[1] >= 64 && b[1] <= 127) ||
                b[0] >= 224;
        }

        // discord.com yerel DNS çözümlemesi engellenmiş, özel veya yerel IP'ye mi yönlenmiş?
        public static bool IsDiscordDnsPoisoned(out string ipsText)
        {
            ipsText = "";
            try
            {
                string err;
                IPAddress[] ips = ResolveHostIps("discord.com", out err);
                if (ips == null || ips.Length == 0)
                {
                    ipsText = string.IsNullOrEmpty(err) ? "Çözümlenemedi" : ("Hata: " + err);
                    return false;
                }

                bool poisoned = false;
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < ips.Length; i++)
                {
                    if (IsPoisonedDiscordIp(ips[i])) poisoned = true;
                    sb.Append(ips[i].ToString());
                    if (i < ips.Length - 1) sb.Append(", ");
                }
                ipsText = sb.ToString();
                return poisoned;
            }
            catch
            {
                return false;
            }
        }

        // UDP DNS sorgusu (discord.com A kaydı). Başarılıysa ms döner;
        // zehirli/engelli/şeffaf vekil yanıtıysa -3 döner; zaman aşımı/ağ hatasıysa -1 döner.
        public static long TestUdpDns(string server, int port, int timeoutMs, out int responseBytes, out string error)
        {
            return TestUdpDns(server, port, timeoutMs, "discord.com", out responseBytes, out error);
        }

        public static long TestUdpDns(string server, int port, int timeoutMs, string queryName, out int responseBytes, out string error)
        {
            return TestUdpDnsInternal(server, port, timeoutMs, queryName, out responseBytes, out error,
                null, false);
        }

        public static long TestUdpDnsWithNsid(string server, int port, int timeoutMs, string queryName,
            out int responseBytes, out string error, out string serverIdentifier)
        {
            StringBuilder capturedIdentifier = new StringBuilder(32);
            long elapsedMs = TestUdpDnsInternal(server, port, timeoutMs, queryName, out responseBytes,
                out error, capturedIdentifier, true);
            serverIdentifier = capturedIdentifier.Length > 0 ? capturedIdentifier.ToString() : null;
            return elapsedMs;
        }

        private static long TestUdpDnsInternal(string server, int port, int timeoutMs, string queryName,
            out int responseBytes, out string error, StringBuilder identifierCapture, bool requestNsid)
        {
            responseBytes = 0;
            error = null;
            try
            {
                if (string.IsNullOrWhiteSpace(server) || port < 1 || port > 65535 || timeoutMs <= 0)
                {
                    error = "Geçersiz DNS sunucusu veya bağlantı ayarı";
                    return -1;
                }
                IPAddress expectedAddress;
                if (!IPAddress.TryParse(server.Trim(), out expectedAddress))
                {
                    error = "DNS sunucusu açık bir IP adresi olmalı";
                    return -1;
                }
                string normalizedQueryName = string.IsNullOrEmpty(queryName) ? null : queryName.Trim().TrimEnd('.');
                int transactionId = Interlocked.Increment(ref _dnsQuerySequence) & 0xFFFF;
                byte[] q = BuildDnsQueryBytes(normalizedQueryName, transactionId, requestNsid);
                if (q == null)
                {
                    error = "Geçersiz DNS sorgu adı";
                    return -1;
                }

                using (UdpClient udp = new UdpClient(expectedAddress.AddressFamily))
                {
                    udp.Client.ReceiveTimeout = timeoutMs;
                    udp.Connect(new IPEndPoint(expectedAddress, port));
                    Stopwatch sw = Stopwatch.StartNew();
                    udp.Send(q, q.Length);
                    IPAddress anyAddress = (expectedAddress.AddressFamily == AddressFamily.InterNetworkV6)
                        ? IPAddress.IPv6Any
                        : IPAddress.Any;
                    while (true)
                    {
                        int remainingMs = timeoutMs - (int)Math.Min((long)int.MaxValue, sw.ElapsedMilliseconds);
                        if (remainingMs <= 0)
                        {
                            error = "DNS yanıt zaman aşımına uğradı";
                            return -1;
                        }

                        udp.Client.ReceiveTimeout = remainingMs;
                        IPEndPoint ep = new IPEndPoint(anyAddress, 0);
                        byte[] res;
                        long responseElapsedMs;
                        try
                        {
                            res = udp.Receive(ref ep);
                            responseElapsedMs = sw.ElapsedMilliseconds;
                        }
                        catch (SocketException socketError)
                        {
                            if (socketError.SocketErrorCode == SocketError.TimedOut)
                            {
                                error = "DNS yanıt zaman aşımına uğradı";
                                return -1;
                            }
                            throw;
                        }

                        if (!expectedAddress.Equals(ep.Address) || ep.Port != port)
                        {
                            error = "DNS yanıtı beklenen sunucudan gelmedi";
                            return -1;
                        }
                        bool isPoisonedOrProxy;
                        string resolvedIp;
                        if (!IsValidDnsResponse(res, transactionId, normalizedQueryName, out isPoisonedOrProxy, out error, out resolvedIp))
                        {
                            if (isPoisonedOrProxy) return -3;
                            if (string.Equals(error, "TXID eşleşmedi", StringComparison.Ordinal) ||
                                string.Equals(error, "Kısa yanıt", StringComparison.Ordinal) ||
                                string.Equals(error, "Bozuk DNS soru bölümü", StringComparison.Ordinal) ||
                                string.Equals(error, "DNS soru bölümü eşleşmedi", StringComparison.Ordinal))
                            {
                                responseBytes = 0;
                                continue;
                            }
                            return -1;
                        }

                        sw.Stop();
                        responseBytes = res.Length;
                        if (!string.IsNullOrEmpty(resolvedIp))
                        {
                            RecordResolvedEdgeIp(server, resolvedIp);
                        }
                        if (requestNsid && identifierCapture != null)
                        {
                            string parsedIdentifier;
                            if (TryExtractDnsNsid(res, transactionId, normalizedQueryName, out parsedIdentifier))
                            {
                                identifierCapture.Append(parsedIdentifier);
                            }
                        }
                        return responseElapsedMs;
                    }
                }
            }
            catch (Exception ex)
            {
                error = ex.Message;
                return -1;
            }
        }

        // DNS-over-TCP sorgusu. Süre, TCP bağlantısından tam DNS yanıtının alınmasına kadar ölçülür.
        public static long TestTcpDns(string server, int port, int timeoutMs, out int responseBytes, out string error)
        {
            return TestTcpDns(server, port, timeoutMs, "discord.com", out responseBytes, out error);
        }

        public static long TestTcpDns(string server, int port, int timeoutMs, string queryName, out int responseBytes, out string error)
        {
            long dnsRttMs;
            return TestTcpDns(server, port, timeoutMs, queryName, out responseBytes, out error, out dnsRttMs);
        }

        public static long TestTcpDns(string server, int port, int timeoutMs, string queryName,
            out int responseBytes, out string error, out long dnsRttMs)
        {
            return TestTcpDnsInternal(server, port, timeoutMs, queryName, out responseBytes, out error,
                out dnsRttMs, null, false);
        }

        public static long TestTcpDnsWithNsid(string server, int port, int timeoutMs, string queryName,
            out int responseBytes, out string error, out long dnsRttMs, out string serverIdentifier)
        {
            StringBuilder capturedIdentifier = new StringBuilder(32);
            long totalMs = TestTcpDnsInternal(server, port, timeoutMs, queryName, out responseBytes,
                out error, out dnsRttMs, capturedIdentifier, true);
            serverIdentifier = capturedIdentifier.Length > 0 ? capturedIdentifier.ToString() : null;
            return totalMs;
        }

        private static long TestTcpDnsInternal(string server, int port, int timeoutMs, string queryName,
            out int responseBytes, out string error, out long dnsRttMs, StringBuilder identifierCapture, bool requestNsid)
        {
            responseBytes = 0;
            error = null;
            dnsRttMs = -1;
            try
            {
                if (string.IsNullOrWhiteSpace(server) || port < 1 || port > 65535 || timeoutMs <= 0)
                {
                    error = "Geçersiz DNS sunucusu veya bağlantı ayarı";
                    return -1;
                }

                IPAddress expectedAddress;
                if (!IPAddress.TryParse(server.Trim(), out expectedAddress))
                {
                    error = "DNS sunucusu açık bir IP adresi olmalı";
                    return -1;
                }

                string normalizedQueryName = string.IsNullOrEmpty(queryName) ? null : queryName.Trim().TrimEnd('.');
                int transactionId = Interlocked.Increment(ref _dnsQuerySequence) & 0xFFFF;
                byte[] query = BuildDnsQueryBytes(normalizedQueryName, transactionId, requestNsid);
                if (query == null || query.Length > 65535)
                {
                    error = "Geçersiz DNS sorgu adı";
                    return -1;
                }

                using (TcpClient tcp = new TcpClient(expectedAddress.AddressFamily))
                {
                    Stopwatch totalStopwatch = Stopwatch.StartNew();
                    IAsyncResult connectResult = tcp.BeginConnect(expectedAddress, port, null, null);
                    WaitHandle connectHandle = connectResult.AsyncWaitHandle;
                    bool connected;
                    try
                    {
                        connected = connectHandle.WaitOne(timeoutMs, true);
                        if (!connected)
                        {
                            error = "DNS TCP bağlantı zaman aşımı";
                            try { tcp.Close(); } catch {}
                            return -1;
                        }
                        tcp.EndConnect(connectResult);
                    }
                    finally
                    {
                        try { connectHandle.Close(); } catch {}
                    }

                    IPEndPoint remoteEndpoint = tcp.Client.RemoteEndPoint as IPEndPoint;
                    if (!tcp.Connected || remoteEndpoint == null ||
                        !expectedAddress.Equals(remoteEndpoint.Address) || remoteEndpoint.Port != port)
                    {
                        error = "DNS TCP bağlantısı beklenen sunucuya kurulmadı";
                        return -1;
                    }

                    int remainingMs = timeoutMs - (int)Math.Min((long)int.MaxValue, totalStopwatch.ElapsedMilliseconds);
                    if (remainingMs <= 0)
                    {
                        error = "DNS TCP sorgu zaman aşımı";
                        return -1;
                    }

                    NetworkStream stream = tcp.GetStream();
                    stream.WriteTimeout = remainingMs;
                    byte[] framedQuery = new byte[query.Length + 2];
                    framedQuery[0] = (byte)((query.Length >> 8) & 0xFF);
                    framedQuery[1] = (byte)(query.Length & 0xFF);
                    Buffer.BlockCopy(query, 0, framedQuery, 2, query.Length);
                    Stopwatch dnsStopwatch = Stopwatch.StartNew();
                    stream.Write(framedQuery, 0, framedQuery.Length);

                    byte[] lengthPrefix = new byte[2];
                    if (!ReadDnsTcpBytes(stream, lengthPrefix, 0, lengthPrefix.Length, totalStopwatch, timeoutMs, out error))
                    {
                        return -1;
                    }

                    int responseLength = (lengthPrefix[0] << 8) | lengthPrefix[1];
                    if (responseLength < 12)
                    {
                        error = "DNS TCP yanıtı çok kısa";
                        return -1;
                    }

                    byte[] response = new byte[responseLength];
                    if (!ReadDnsTcpBytes(stream, response, 0, response.Length, totalStopwatch, timeoutMs, out error))
                    {
                        return -1;
                    }

                    dnsStopwatch.Stop();
                    totalStopwatch.Stop();
                    long elapsedMs = totalStopwatch.ElapsedMilliseconds;
                    long responseRttMs = dnsStopwatch.ElapsedMilliseconds;
                    bool isPoisonedOrProxy;
                    string resolvedIp;
                    if (!IsValidDnsResponse(response, transactionId, normalizedQueryName, out isPoisonedOrProxy, out error, out resolvedIp))
                    {
                        return isPoisonedOrProxy ? -3 : -1;
                    }

                    if (!string.IsNullOrEmpty(resolvedIp))
                    {
                        RecordResolvedEdgeIp(server, resolvedIp);
                    }
                    if (requestNsid && identifierCapture != null)
                    {
                        string parsedIdentifier;
                        if (TryExtractDnsNsid(response, transactionId, normalizedQueryName, out parsedIdentifier))
                        {
                            identifierCapture.Append(parsedIdentifier);
                        }
                    }

                    responseBytes = response.Length;
                    dnsRttMs = responseRttMs;
                    return elapsedMs;
                }
            }
            catch (Exception ex)
            {
                error = ex.Message;
                return -1;
            }
        }

        private static bool ReadDnsTcpBytes(NetworkStream stream, byte[] buffer, int offset, int count, Stopwatch stopwatch, int timeoutMs, out string error)
        {
            error = null;
            int totalRead = 0;
            while (totalRead < count)
            {
                int elapsedMs = (int)Math.Min((long)int.MaxValue, stopwatch.ElapsedMilliseconds);
                int remainingMs = timeoutMs - elapsedMs;
                if (remainingMs <= 0)
                {
                    error = "DNS TCP yanıt zaman aşımı";
                    return false;
                }

                stream.ReadTimeout = remainingMs;
                int bytesRead = stream.Read(buffer, offset + totalRead, count - totalRead);
                if (bytesRead <= 0)
                {
                    error = "DNS TCP yanıtı tamamlanmadı";
                    return false;
                }
                totalRead += bytesRead;
            }

            return true;
        }

        private static byte[] BuildDnsQueryBytes(string queryName, int transactionId)
        {
            return BuildDnsQueryBytes(queryName, transactionId, false);
        }

        private static byte[] BuildDnsQueryBytes(string queryName, int transactionId, bool requestNsid)
        {
            if (string.IsNullOrEmpty(queryName)) return null;
            string normalizedName = queryName.Trim().TrimEnd('.');
            if (normalizedName.Length == 0 || normalizedName.Length > 253) return null;

            List<byte> query = new List<byte>(normalizedName.Length + (requestNsid ? 29 : 18));
            query.Add((byte)((transactionId >> 8) & 0xFF));
            query.Add((byte)(transactionId & 0xFF));
            query.Add(0x01); query.Add(0x00); // Standard query, recursion desired.
            query.Add(0x00); query.Add(0x01); // One question.
            query.Add(0x00); query.Add(0x00); // No answer records.
            query.Add(0x00); query.Add(0x00); // No authority records.
            query.Add(0x00); query.Add(requestNsid ? (byte)0x01 : (byte)0x00); // Optional EDNS OPT record.

            string[] labels = normalizedName.Split('.');
            for (int i = 0; i < labels.Length; i++)
            {
                if (labels[i].Length == 0) return null;
                byte[] label = Encoding.ASCII.GetBytes(labels[i]);
                if (label.Length == 0 || label.Length > 63) return null;
                query.Add((byte)label.Length);
                query.AddRange(label);
            }

            query.Add(0x00); // Root label.
            query.Add(0x00); query.Add(0x01); // A record.
            query.Add(0x00); query.Add(0x01); // Internet class.
            if (requestNsid)
            {
                query.Add(0x00); // Root owner name for OPT.
                query.Add(0x00); query.Add(0x29); // OPT record type.
                query.Add(0x04); query.Add(0xD0); // Advertised UDP payload size: 1232 bytes.
                query.Add(0x00); query.Add(0x00); query.Add(0x00); query.Add(0x00); // Extended RCODE, version, flags.
                query.Add(0x00); query.Add(0x04); // RDATA length.
                query.Add(0x00); query.Add(0x03); // NSID option code.
                query.Add(0x00); query.Add(0x00); // Empty request payload.
            }
            return query.ToArray();
        }

        // DNS paketi içerisindeki sıkıştırılmış (0xC0) veya etiket dizisi adını atlar; yeni ofseti döner (hata: -1).
        private static int SkipDnsName(byte[] buf, int offset)
        {
            if (buf == null || offset < 0 || offset >= buf.Length) return -1;
            int safety = 0;
            while (offset < buf.Length && safety++ < 64)
            {
                byte len = buf[offset];
                if (len == 0)
                {
                    return offset + 1;
                }
                if ((len & 0xC0) == 0xC0)
                {
                    if (offset + 1 >= buf.Length) return -1;
                    return offset + 2;
                }
                offset += 1 + len;
            }
            return -1;
        }

        private static bool TryReadDnsName(byte[] buf, ref int offset, out string name)
        {
            name = null;
            if (buf == null || offset < 0 || offset >= buf.Length) return false;

            StringBuilder result = new StringBuilder();
            int cursor = offset;
            int resumeOffset = -1;
            int expandedLength = 0;
            int safety = 0;
            while (cursor >= 0 && cursor < buf.Length && safety++ < 128)
            {
                byte labelLength = buf[cursor];
                if (labelLength == 0)
                {
                    offset = (resumeOffset >= 0) ? resumeOffset : cursor + 1;
                    name = result.ToString();
                    return true;
                }

                if ((labelLength & 0xC0) == 0xC0)
                {
                    if (cursor + 1 >= buf.Length) return false;
                    int pointer = ((labelLength & 0x3F) << 8) | buf[cursor + 1];
                    if (pointer >= buf.Length || pointer >= cursor) return false;
                    if (resumeOffset < 0) resumeOffset = cursor + 2;
                    cursor = pointer;
                    continue;
                }

                if ((labelLength & 0xC0) != 0 || labelLength > 63 || cursor + 1 + labelLength > buf.Length)
                {
                    return false;
                }

                if (result.Length > 0) result.Append('.');
                result.Append(Encoding.ASCII.GetString(buf, cursor + 1, labelLength));
                expandedLength += labelLength + 1;
                if (expandedLength > 255) return false;
                cursor += 1 + labelLength;
            }

            return false;
        }

        private static bool TryExtractDnsNsid(byte[] response, int expectedTransactionId,
            string expectedQueryName, out string serverIdentifier)
        {
            serverIdentifier = null;
            if (response == null || response.Length < 12 ||
                response[0] != (byte)((expectedTransactionId >> 8) & 0xFF) ||
                response[1] != (byte)(expectedTransactionId & 0xFF)) return false;

            int questionCount = (response[4] << 8) | response[5];
            int answerCount = (response[6] << 8) | response[7];
            int authorityCount = (response[8] << 8) | response[9];
            int additionalCount = (response[10] << 8) | response[11];
            if (questionCount != 1) return false;

            int offset = 12;
            string responseQueryName;
            if (!TryReadDnsName(response, ref offset, out responseQueryName) || offset + 4 > response.Length ||
                !string.Equals(responseQueryName, expectedQueryName, StringComparison.OrdinalIgnoreCase) ||
                response[offset] != 0 || response[offset + 1] != 1 ||
                response[offset + 2] != 0 || response[offset + 3] != 1) return false;
            offset += 4;

            int normalRecordCount = answerCount + authorityCount;
            for (int i = 0; i < normalRecordCount; i++)
            {
                if (!TrySkipDnsResourceRecord(response, ref offset)) return false;
            }

            for (int i = 0; i < additionalCount; i++)
            {
                string ownerName;
                int recordType;
                int dataOffset;
                int recordEnd;
                if (!TryReadDnsResourceRecord(response, ref offset, out ownerName, out recordType,
                    out dataOffset, out recordEnd)) return false;
                if (recordType != 41 || ownerName.Length != 0) continue;

                int optionOffset = dataOffset;
                while (optionOffset < recordEnd)
                {
                    if (optionOffset + 4 > recordEnd) return false;
                    int optionCode = (response[optionOffset] << 8) | response[optionOffset + 1];
                    int optionLength = (response[optionOffset + 2] << 8) | response[optionOffset + 3];
                    optionOffset += 4;
                    if (optionLength > recordEnd - optionOffset) return false;
                    if (optionCode == 3 && optionLength > 0)
                    {
                        serverIdentifier = FormatDnsServerIdentifier(response, optionOffset, optionLength);
                        return !string.IsNullOrEmpty(serverIdentifier);
                    }
                    optionOffset += optionLength;
                }
            }

            return false;
        }

        private static bool TryReadDnsResourceRecord(byte[] response, ref int offset, out string ownerName,
            out int recordType, out int dataOffset, out int recordEnd)
        {
            ownerName = null;
            recordType = 0;
            dataOffset = 0;
            recordEnd = 0;
            if (!TryReadDnsName(response, ref offset, out ownerName) || offset + 10 > response.Length) return false;

            recordType = (response[offset] << 8) | response[offset + 1];
            int dataLength = (response[offset + 8] << 8) | response[offset + 9];
            dataOffset = offset + 10;
            recordEnd = dataOffset + dataLength;
            if (recordEnd < dataOffset || recordEnd > response.Length) return false;
            offset = recordEnd;
            return true;
        }

        private static bool TrySkipDnsResourceRecord(byte[] response, ref int offset)
        {
            string ownerName;
            if (!TryReadDnsName(response, ref offset, out ownerName) || ownerName == null ||
                offset + 10 > response.Length) return false;
            int dataLength = (response[offset + 8] << 8) | response[offset + 9];
            int recordEnd = offset + 10 + dataLength;
            if (recordEnd < offset || recordEnd > response.Length) return false;
            offset = recordEnd;
            return true;
        }

        private static string FormatDnsServerIdentifier(byte[] response, int offset, int length)
        {
            if (response == null || offset < 0 || length <= 0 || offset + length > response.Length) return null;
            int shownLength = Math.Min(length, 32);
            bool isPrintable = true;
            for (int i = 0; i < shownLength; i++)
            {
                if (response[offset + i] < 0x20 || response[offset + i] > 0x7E)
                {
                    isPrintable = false;
                    break;
                }
            }

            StringBuilder value = new StringBuilder();
            if (isPrintable)
            {
                value.Append(Encoding.ASCII.GetString(response, offset, shownLength));
            }
            else
            {
                value.Append("0x");
                for (int i = 0; i < shownLength; i++) value.Append(response[offset + i].ToString("X2"));
            }
            if (length > shownLength) value.Append("…");
            return value.ToString();
        }

        private static readonly object _anycastEdgeCacheLock = new object();
        private static readonly Dictionary<string, string> _lastResolvedIpByDnsServer = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        private static readonly Dictionary<string, long> _anycastEdgeRttCache = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
        private static readonly Dictionary<string, DateTime> _anycastEdgeRttCacheTimeUtc = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);

        internal static void RecordResolvedEdgeIp(string dnsServer, string resolvedIp)
        {
            if (string.IsNullOrEmpty(dnsServer) || string.IsNullOrEmpty(resolvedIp)) return;
            lock (_anycastEdgeCacheLock)
            {
                if (_lastResolvedIpByDnsServer.Count > 128) _lastResolvedIpByDnsServer.Clear();
                _lastResolvedIpByDnsServer[dnsServer.Trim()] = resolvedIp;
            }
        }

        public static bool TryGetLastResolvedEdgeIp(string dnsServer, out string resolvedIp)
        {
            resolvedIp = null;
            if (string.IsNullOrEmpty(dnsServer)) return false;
            lock (_anycastEdgeCacheLock)
            {
                return _lastResolvedIpByDnsServer.TryGetValue(dnsServer.Trim(), out resolvedIp) && !string.IsNullOrEmpty(resolvedIp);
            }
        }

        // Çözümlenen Anycast CDN IP'sine (ör. Discord/Cloudflare Edge) mikro TCP 443 RTT yoklaması yapar.
        // Aynı Anycast IP birden çok DNS sunucusundan dönerse 5 dakikalık önbellekten 0 ms maliyetle okunur.
        public static long ProbeAnycastEdgeRttMs(string edgeIp, int timeoutMs)
        {
            if (string.IsNullOrEmpty(edgeIp)) return -1;
            string key = edgeIp.Trim();
            DateTime now = DateTime.UtcNow;
            lock (_anycastEdgeCacheLock)
            {
                long cachedRtt;
                DateTime cachedUtc;
                if (_anycastEdgeRttCache.TryGetValue(key, out cachedRtt) &&
                    _anycastEdgeRttCacheTimeUtc.TryGetValue(key, out cachedUtc) &&
                    (now - cachedUtc).TotalSeconds <= 300.0)
                {
                    return cachedRtt;
                }
            }

            string tcpErr;
            long rtt = TestTcpConnect(key, 443, Math.Max(200, Math.Min(650, timeoutMs)), out tcpErr);
            if (rtt >= 0)
            {
                lock (_anycastEdgeCacheLock)
                {
                    if (_anycastEdgeRttCache.Count > 128)
                    {
                        _anycastEdgeRttCache.Clear();
                        _anycastEdgeRttCacheTimeUtc.Clear();
                    }
                    _anycastEdgeRttCache[key] = rtt;
                    _anycastEdgeRttCacheTimeUtc[key] = DateTime.UtcNow;
                }
            }
            return rtt;
        }

        // Çözümlenen Anycast CDN noktasının veya DNS NSID kimliğinin Türkiye/yerel POP (İstanbul/Ankara/İzmir)
        // olup olmadığını doğrular (düşük RTT <= 28 ms veya NSID POP kodu).
        public static bool IsTurkishOrLocalAnycastPop(string serverIdentifier, long edgeRttMs)
        {
            if (edgeRttMs >= 0 && edgeRttMs <= 28) return true;
            if (!string.IsNullOrEmpty(serverIdentifier))
            {
                string lower = serverIdentifier.ToLowerInvariant();
                if (lower.Contains("ist") || lower.Contains("ank") || lower.Contains("saw") ||
                    lower.Contains("adb") || lower.Contains("izmir") || lower.Contains("sof"))
                {
                    return true;
                }
            }
            return false;
        }

        // RFC 1035/5452: yanıtı sorgu kimliği, adı, kayıt türü/sınıfı ve cevap bölümüne göre eşleştir.
        private static bool IsValidDnsResponse(byte[] res, int expectedTransactionId, string expectedQueryName, out bool isPoisonedOrProxy, out string error)
        {
            string unusedFirstIp;
            return IsValidDnsResponse(res, expectedTransactionId, expectedQueryName, out isPoisonedOrProxy, out error, out unusedFirstIp);
        }

        private static bool IsValidDnsResponse(byte[] res, int expectedTransactionId, string expectedQueryName, out bool isPoisonedOrProxy, out string error, out string firstValidIp)
        {
            isPoisonedOrProxy = false;
            error = null;
            firstValidIp = null;
            if (res == null || res.Length < 12)
            {
                error = "Kısa yanıt";
                return false;
            }
            if (res[0] != (byte)((expectedTransactionId >> 8) & 0xFF) || res[1] != (byte)(expectedTransactionId & 0xFF))
            {
                error = "TXID eşleşmedi";
                return false;
            }
            if ((res[2] & 0x80) == 0 || (res[2] & 0x78) != 0)
            {
                error = "DNS yanıtı veya sorgu türü geçersiz";
                return false;
            }
            // TC (truncated) bayraklı yanıt eksiktir; içindeki A kaydına güvenilmez.
            if ((res[2] & 0x02) != 0)
            {
                error = "Kesilmiş yanıt (TC)";
                return false;
            }
            // RCODE != 0 (NXDOMAIN/SERVFAIL/REFUSED): Şeffaf DNS vekili engellemesi olabilir.
            int rcode = (res[3] & 0x0F);
            if (rcode != 0)
            {
                if (rcode == 3 || rcode == 5) isPoisonedOrProxy = true;
                error = isPoisonedOrProxy ? "Engelli / Zehirli (Şeffaf Vekil)" : "DNS hata kodu (RCODE)";
                return false;
            }
            int qdCount = (res[4] << 8) | res[5];
            int anCount = (res[6] << 8) | res[7];
            int nsCount = (res[8] << 8) | res[9];
            int arCount = (res[10] << 8) | res[11];
            if (qdCount != 1)
            {
                error = "Soru sayısı eşleşmedi";
                return false;
            }
            if (anCount <= 0)
            {
                error = "Kayıt içermiyor";
                return false;
            }

            int pos = 12;
            string responseQueryName;
            if (!TryReadDnsName(res, ref pos, out responseQueryName) || pos + 4 > res.Length)
            {
                error = "Bozuk DNS soru bölümü";
                return false;
            }
            int questionType = (res[pos] << 8) | res[pos + 1];
            int questionClass = (res[pos + 2] << 8) | res[pos + 3];
            if (!string.Equals(responseQueryName, expectedQueryName, StringComparison.OrdinalIgnoreCase) || questionType != 1 || questionClass != 1)
            {
                error = "DNS soru bölümü eşleşmedi";
                return false;
            }
            pos += 4;

            // Yalnızca sorgu adı veya onun CNAME zinciri için dönen IN sınıfı A kayıtlarını kullanılabilir say.
            List<string> cnameOwners = new List<string>();
            List<string> cnameTargets = new List<string>();
            List<string> answerAOwners = new List<string>();
            List<bool> answerAUsable = new List<bool>();
            List<string> answerAIps = new List<string>();
            for (int a = 0; a < anCount; a++)
            {
                string ownerName;
                if (!TryReadDnsName(res, ref pos, out ownerName) || pos + 10 > res.Length)
                {
                    error = "Bozuk DNS yanıt kayıt bölümü";
                    return false;
                }

                int rrType = (res[pos] << 8) | res[pos + 1];
                int rrClass = (res[pos + 2] << 8) | res[pos + 3];
                int rdLength = (res[pos + 8] << 8) | res[pos + 9];
                int dataOffset = pos + 10;
                int recordEnd = dataOffset + rdLength;
                if (recordEnd < dataOffset || recordEnd > res.Length)
                {
                    error = "Bozuk DNS yanıt kayıt bölümü";
                    return false;
                }

                if (rrClass == 1 && rrType == 5) // TYPE CNAME (canonical name)
                {
                    int cnameOffset = dataOffset;
                    string targetName;
                    if (!TryReadDnsName(res, ref cnameOffset, out targetName) || cnameOffset != recordEnd ||
                        string.IsNullOrEmpty(ownerName) || string.IsNullOrEmpty(targetName))
                    {
                        error = "Bozuk DNS CNAME kaydı";
                        return false;
                    }
                    cnameOwners.Add(ownerName);
                    cnameTargets.Add(targetName);
                }
                else if (rrClass == 1 && rrType == 1) // TYPE A (IPv4)
                {
                    if (rdLength != 4)
                    {
                        error = "Bozuk DNS A kaydı";
                        return false;
                    }

                    byte b0 = res[dataOffset];
                    byte b1 = res[dataOffset + 1];
                    byte b2 = res[dataOffset + 2];
                    byte b3 = res[dataOffset + 3];

                    // BTK / İSS engelleme sayfası veya yerel/özel/CGNAT/geçersiz IP kontrolü
                    bool invalidOrBlocked =
                        (b0 == 195 && b1 == 175 && b2 == 254 && b3 == 2) ||
                        (b0 == 195 && b1 == 175) ||
                        (b0 == 212 && b1 == 156) ||
                        (b0 == 212 && (b1 == 252 || b1 == 253)) ||
                        (b0 == 195 && b1 == 174) ||
                        b0 == 0 || b0 == 10 || b0 == 127 ||
                        (b0 == 169 && b1 == 254) ||
                        (b0 == 192 && b1 == 168) ||
                        (b0 == 172 && b1 >= 16 && b1 <= 31) ||
                        (b0 == 100 && b1 >= 64 && b1 <= 127) ||
                        b0 >= 224;

                    answerAOwners.Add(ownerName);
                    answerAUsable.Add(!invalidOrBlocked);
                    answerAIps.Add(string.Format("{0}.{1}.{2}.{3}", b0, b1, b2, b3));
                }

                pos = recordEnd;
            }

            // Başlıkta bildirilen yetki/ek kayıtlar da tam olmalı; yalnızca A kaydı yeterli değildir.
            for (int r = 0; r < nsCount + arCount; r++)
            {
                if (!TrySkipDnsResourceRecord(res, ref pos))
                {
                    error = "Bozuk DNS yetki/ek kayıt bölümü";
                    return false;
                }
            }

            List<string> reachableNames = new List<string>();
            reachableNames.Add(expectedQueryName);
            for (int depth = 0; depth < 16; depth++)
            {
                string currentName = reachableNames[reachableNames.Count - 1];
                int cnameIndex = -1;
                for (int c = 0; c < cnameOwners.Count; c++)
                {
                    if (string.Equals(cnameOwners[c], currentName, StringComparison.OrdinalIgnoreCase))
                    {
                        cnameIndex = c;
                        break;
                    }
                }
                if (cnameIndex < 0) break;

                string nextName = cnameTargets[cnameIndex];
                bool alreadyReached = false;
                for (int r = 0; r < reachableNames.Count; r++)
                {
                    if (string.Equals(reachableNames[r], nextName, StringComparison.OrdinalIgnoreCase))
                    {
                        alreadyReached = true;
                        break;
                    }
                }
                if (alreadyReached)
                {
                    error = "DNS CNAME döngüsü";
                    return false;
                }
                reachableNames.Add(nextName);
            }

            int validARecords = 0;
            for (int a = 0; a < answerAOwners.Count; a++)
            {
                bool ownerIsReachable = false;
                for (int r = 0; r < reachableNames.Count; r++)
                {
                    if (string.Equals(answerAOwners[a], reachableNames[r], StringComparison.OrdinalIgnoreCase))
                    {
                        ownerIsReachable = true;
                        break;
                    }
                }
                if (!ownerIsReachable) continue;
                if (!answerAUsable[a])
                {
                    isPoisonedOrProxy = true;
                    error = "Engelli / Zehirli (Şeffaf Vekil)";
                    return false;
                }
                if (firstValidIp == null && a < answerAIps.Count)
                {
                    firstValidIp = answerAIps[a];
                }
                validARecords++;
            }

            if (validARecords == 0)
            {
                error = "Sorgu adı için kullanılabilir A yanıtı yok";
                return false;
            }
            return true;
        }

        private static int _cachedDetectedIsp = -2;
        private static DateTime _cachedDetectedIspUtc = DateTime.MinValue;
        private static readonly object _ispDetectLock = new object();

        // Harici HTTP/IP sorgusu yapmadan (0/72 AV temizliği) yerel adaptör + hızlı ICMP TTL=2..6 omurga hop
        // analizi ile gerçek Türkiye İSS profilini (0..8) tespit eder; bulunamazsa -1 döner.
        public static int DetectIspLocalAndNextHop()
        {
            if (_cachedDetectedIsp != -2 && (DateTime.UtcNow - _cachedDetectedIspUtc).TotalSeconds < 120)
            {
                return _cachedDetectedIsp;
            }

            lock (_ispDetectLock)
            {
                if (_cachedDetectedIsp != -2 && (DateTime.UtcNow - _cachedDetectedIspUtc).TotalSeconds < 120)
                {
                    return _cachedDetectedIsp;
                }

                int found = -1;
                try
                {
                    foreach (NetworkInterface ni in NetworkInterface.GetAllNetworkInterfaces())
                    {
                        if (ni.OperationalStatus != OperationalStatus.Up) continue;
                        if (ni.NetworkInterfaceType == NetworkInterfaceType.Loopback ||
                            ni.NetworkInterfaceType == NetworkInterfaceType.Tunnel) continue;

                        IPInterfaceProperties props = ni.GetIPProperties();
                        string desc = ((ni.Description ?? "") + " " + (ni.Name ?? "") + " " + (props.DnsSuffix ?? "")).ToLowerInvariant();
                        int byText = MatchIspText(desc);
                        if (byText >= 0) { found = byText; break; }

                        foreach (IPAddress dns in props.DnsAddresses)
                        {
                            int m = MatchIspIp(dns);
                            if (m >= 0) { found = m; break; }
                        }
                        if (found >= 0) break;

                        foreach (GatewayIPAddressInformation gw in props.GatewayAddresses)
                        {
                            if (gw == null || gw.Address == null) continue;
                            int m = MatchIspIp(gw.Address);
                            if (m >= 0) { found = m; break; }
                        }
                        if (found >= 0) break;
                    }

                    if (found < 0)
                    {
                        // Ev yönlendiricisi (192.168.1.1) ve CGNAT (100.64.x.x / 10.x.x.x) arkasındaysa
                        // tek iş parçacığında hızlı (160ms) TTL=2..6 sorgusuyla ilk genel İSS yönlendiricisini yakala
                        // (Ters DNS / NetBIOS kilitlenmesi olmaması için yalnızca IP bloğu eşleştirmesi yapılır)
                        byte[] payload = new byte[] { 0x47, 0x44, 0x50, 0x49 };
                        using (Ping ping = new Ping())
                        {
                            for (int ttl = 2; ttl <= 6; ttl++)
                            {
                                try
                                {
                                    PingOptions opts = new PingOptions(ttl, true);
                                    PingReply reply = ping.Send("1.1.1.1", 160, payload, opts);
                                    if (reply == null || reply.Status == IPStatus.TimedOut)
                                    {
                                        reply = ping.Send("8.8.8.8", 160, payload, opts);
                                    }
                                    if (reply != null && reply.Address != null &&
                                        (reply.Status == IPStatus.TtlExpired || reply.Status == IPStatus.Success))
                                    {
                                        IPAddress hopIp = reply.Address;
                                        if (IsPublicNonCloudflareHop(hopIp))
                                        {
                                            int m = MatchIspIp(hopIp);
                                            if (m >= 0)
                                            {
                                                found = m;
                                                break;
                                            }
                                        }
                                    }
                                    if (reply != null && reply.Status == IPStatus.Success) break;
                                }
                                catch {}
                            }
                        }
                    }

                    if (found < 0)
                    {
                        // Ev yönlendiricisi ve CGNAT arkasındaysa genel IP'yi doğrudan DNS'siz Cloudflare trace ile yakala
                        try
                        {
                            string pubIpStr = FetchPublicIpDirect();
                            if (!string.IsNullOrEmpty(pubIpStr))
                            {
                                IPAddress pubIp;
                                if (IPAddress.TryParse(pubIpStr, out pubIp))
                                {
                                    int m = MatchIspIp(pubIp);
                                    if (m >= 0)
                                    {
                                        found = m;
                                    }
                                    else
                                    {
                                        try
                                        {
                                            IPHostEntry hostEntry = Dns.GetHostEntry(pubIp);
                                            if (hostEntry != null && !string.IsNullOrEmpty(hostEntry.HostName))
                                            {
                                                int byHost = MatchIspText(hostEntry.HostName.ToLowerInvariant());
                                                if (byHost >= 0) found = byHost;
                                            }
                                        }
                                        catch {}
                                    }
                                }
                            }
                        }
                        catch {}
                    }
                }
                catch {}

                _cachedDetectedIsp = found;
                _cachedDetectedIspUtc = DateTime.UtcNow;
                return found;
            }
        }

        private static string FetchPublicIpDirect()
        {
            string[] endpoints = new string[] { "http://1.1.1.1/cdn-cgi/trace", "http://1.0.0.1/cdn-cgi/trace" };
            for (int i = 0; i < endpoints.Length; i++)
            {
                try
                {
                    HttpWebRequest req = (HttpWebRequest)WebRequest.Create(endpoints[i]);
                    req.Timeout = 1200;
                    req.ReadWriteTimeout = 1200;
                    req.UserAgent = "GoodbyeDPI-ProMAX";
                    req.Proxy = null;
                    using (HttpWebResponse resp = (HttpWebResponse)req.GetResponse())
                    using (StreamReader sr = new StreamReader(resp.GetResponseStream(), Encoding.ASCII))
                    {
                        string line;
                        while ((line = sr.ReadLine()) != null)
                        {
                            if (line.StartsWith("ip=", StringComparison.OrdinalIgnoreCase))
                            {
                                return line.Substring(3).Trim();
                            }
                        }
                    }
                }
                catch {}
            }
            return null;
        }

        private static bool IsPublicNonCloudflareHop(IPAddress ip)
        {
            if (ip == null || ip.AddressFamily != AddressFamily.InterNetwork) return false;
            byte[] b = ip.GetAddressBytes();
            if (b == null || b.Length != 4) return false;
            int b0 = b[0], b1 = b[1];
            // Özel/yerel veya CGNAT (100.64.0.0/10) adreslerini atla
            if (b0 == 0 || b0 == 10 || b0 == 127 || (b0 == 192 && b1 == 168) || (b0 == 172 && b1 >= 16 && b1 <= 31)) return false;
            if (b0 == 100 && b1 >= 64 && b1 <= 127) return false;
            // Hedef 1.1.1.1 / 8.8.8.8 veya Cloudflare/Google anycast kenar ağlarını atla
            if (b0 == 1 && b1 == 1 && b[2] == 1 && b[3] == 1) return false;
            if (b0 == 8 && b1 == 8 && b[2] == 8 && b[3] == 8) return false;
            if (b0 == 172 && b1 >= 64 && b1 <= 71) return false;
            if (b0 == 104 && b1 >= 16 && b1 <= 31) return false;
            if (b0 == 142 && (b1 == 250 || b1 == 251)) return false;
            return true;
        }

        // İndeksler InitializeProfiles() ile birebir hizalıdır:
        // 0: Türk Telekom, 1: Superonline, 2: Vodafone, 3: Kablonet, 4: TurkNet,
        // 5: Millenicom, 6: Netspeed, 7: GıbırNet, 8: Diğer Sağlayıcılar (Comnet vb.)
        private static int MatchIspText(string text)
        {
            if (string.IsNullOrEmpty(text)) return -1;
            if (text.Contains("ttnet") || text.Contains("turktelekom") || text.Contains("türk telekom")) return 0;
            if (text.Contains("superonline") || text.Contains("turkcell") || text.Contains("sol.net.tr")) return 1;
            if (text.Contains("vodafone") || text.Contains("borusan")) return 2;
            if (text.Contains("kablonet") || text.Contains("turksat") || text.Contains("uydunet")) return 3;
            if (text.Contains("turk.net") || text.Contains("turknet")) return 4;
            if (text.Contains("millenicom") || text.Contains("doping")) return 5;
            if (text.Contains("netspeed")) return 6;
            if (text.Contains("gibir") || text.Contains("gıbır")) return 7;
            if (text.Contains("comnet") || text.Contains("pelikan") || text.Contains("fixnet") || text.Contains("atlantis") || text.Contains("goknet")) return 8;
            return -1;
        }

        private static int MatchIspIp(IPAddress ip)
        {
            if (ip == null || ip.AddressFamily != AddressFamily.InterNetwork) return -1;
            byte[] b = ip.GetAddressBytes();
            if (b == null || b.Length != 4) return -1;
            int b0 = b[0], b1 = b[1];
            // Özel/yerel veya CGNAT (100.64.0.0/10) adreslerini atla
            if (b0 == 10 || b0 == 127 || (b0 == 192 && b1 == 168) || (b0 == 172 && b1 >= 16 && b1 <= 31)) return -1;
            if (b0 == 100 && b1 >= 64 && b1 <= 127) return -1;

            // 0: Türk Telekom (AS9121 / AS47331 — 195.175.*, 81.212..215.*, 212.156.*, 212.174..175.*, 88.224..255.*, 78.160..191.*, 85.96..111.*, 95.0..15.*, 178.240..247.*, 31.223.*)
            if ((b0 == 195 && b1 == 175) || (b0 == 212 && (b1 == 156 || b1 == 174 || b1 == 175)) ||
                (b0 == 88 && b1 >= 224 && b1 <= 255) || (b0 == 78 && b1 >= 160 && b1 <= 191) ||
                (b0 == 85 && b1 >= 96 && b1 <= 111) || (b0 == 81 && b1 >= 212 && b1 <= 215) ||
                (b0 == 95 && b1 >= 0 && b1 <= 15) || (b0 == 178 && b1 >= 240 && b1 <= 247) ||
                (b0 == 31 && b1 == 223))
                return 0;

            // 1: Turkcell Superonline (AS34984 — 212.252..253.*, 176.232..241.*, 176.40..43.*, 85.29.*, 82.222.*, 95.65.*, 5.26..27.*, 37.154..155.*, 46.154..155.*)
            if ((b0 == 212 && (b1 == 252 || b1 == 253)) || (b0 == 85 && b1 == 29) ||
                (b0 == 176 && ((b1 >= 40 && b1 <= 43) || (b1 >= 232 && b1 <= 241))) ||
                (b0 == 82 && b1 == 222) || (b0 == 95 && b1 == 65) ||
                (b0 == 5 && (b1 == 26 || b1 == 27)) ||
                (b0 == 37 && (b1 == 154 || b1 == 155)) ||
                (b0 == 46 && (b1 == 154 || b1 == 155)))
                return 1;

            // 2: Vodafone Türkiye (AS15924 / AS15897 — 213.74.*, 31.145..148.*, 176.88..91.*, 46.2.*, 78.135.*, 94.120..123.*, 149.140.*, 178.233.*)
            if ((b0 == 213 && b1 == 74) || (b0 == 31 && b1 >= 145 && b1 <= 148) ||
                (b0 == 176 && b1 >= 88 && b1 <= 91) || (b0 == 46 && b1 == 2) ||
                (b0 == 78 && b1 == 135) || (b0 == 94 && b1 >= 120 && b1 <= 123) ||
                (b0 == 149 && b1 == 140) || (b0 == 178 && b1 == 233))
                return 2;

            // 3: Türksat Kablonet (AS20978 — 62.248.*, 195.174.*, 94.54..55.*, 46.196..197.*, 109.228.192..255)
            if ((b0 == 195 && b1 == 174) || (b0 == 94 && (b1 == 54 || b1 == 55)) ||
                (b0 == 62 && b1 == 248) || (b0 == 46 && (b1 == 196 || b1 == 197)))
                return 3;

            // 4: TurkNet (AS12735 — 193.192.*, 159.146.*, 31.155.*, 95.70.*, 185.114.*, 188.119.*, 5.44.*)
            if ((b0 == 31 && b1 == 155) || (b0 == 95 && b1 == 70) ||
                (b0 == 185 && b1 == 114) || (b0 == 188 && b1 == 119) ||
                (b0 == 193 && b1 == 192) || (b0 == 159 && b1 == 146) ||
                (b0 == 5 && b1 == 44))
                return 4;

            // 5: Millenicom (AS43260)
            if ((b0 == 77 && b1 == 92) || (b0 == 109 && b1 == 228))
                return 5;

            // 6: Netspeed (AS206375 / AS203503)
            if ((b0 == 188 && b1 == 132) || (b0 == 185 && (b1 == 216 || b1 == 219 || b1 == 188 || b1 == 132)) ||
                (b0 == 45 && (b1 == 147 || b1 == 135)) || (b0 == 139 && b1 == 28) || (b0 == 93 && b1 == 157))
                return 6;

            // 7: GıbırNet (AS208452)
            if ((b0 == 185 && b1 == 247) || (b0 == 45 && (b1 == 138 || b1 == 12)))
                return 7;

            // 8: Diğer Sağlayıcılar / Comnet (AS61135)
            if ((b0 == 185 && b1 == 226) || (b0 == 45 && b1 == 155))
                return 8;

            return -1;
        }

        // Standart Port 53 sorgusunda dönen sahte/zehirli yanıtın Türk Telekom (195.175.254.2 / 212.156.x.x)
        // altyapı imzası taşıyıp taşımadığını doğrudan ham UDP soketiyle (sistem DNS kilitlenmesi olmadan) inceler.
        public static bool DetectTtnetDnsPoisonSignature()
        {
            try
            {
                using (UdpClient udp = new UdpClient())
                {
                    udp.Client.ReceiveTimeout = 350;
                    byte[] q = BuildDiscordQueryBytes();
                    udp.Connect("1.1.1.1", 53);
                    udp.Send(q, q.Length);
                    IPEndPoint ep = new IPEndPoint(IPAddress.Any, 0);
                    byte[] res = udp.Receive(ref ep);
                    if (res != null && res.Length >= 16)
                    {
                        for (int i = 12; i <= res.Length - 4; i++)
                        {
                            // 195.175.254.2 veya 195.175.x.x veya 212.156.x.x
                            if ((res[i] == 195 && res[i + 1] == 175) ||
                                (res[i] == 212 && res[i + 1] == 156))
                            {
                                return true;
                            }
                        }
                    }
                }
            }
            catch {}
            return false;
        }

        // Pasif DPI & TLS ClientHello davranış analizi (Koruma kapalıyken bile çalışır, DNS beklemesi yapmaz):
        // - "OPEN" : TLS 1.2/1.3 el sıkışması doğrudan başarılı oldu (rstRttMs = el sıkışma süresi)
        // - "RST"  : TCP bağlantısı kuruldu ancak ClientHello SNI gönderildiğinde DPI cihazından
        //            anında sahte TCP Reset (RST) döndü (rstRttMs = DPI kutusunun ms cinsinden mesafesi, ör. 4-15 ms)
        // - "DROP" : TCP bağlantısı kuruldu ancak ClientHello paketi DPI tarafından sessizce düşürüldü (Timeout / Blackhole)
        // - "FAIL" : TCP bağlantısı hiç kurulamadı
        public static string ProbeTlsDpiBehavior(string sniHost, int timeoutMs, out long rstOrTlsRttMs)
        {
            rstOrTlsRttMs = -1;
            // Sistem DNS çözümleyicisini bekleyip takılmamak için doğrudan Discord'un resmi Cloudflare Gateway IP'sine bağlanıp SNI gönder
            const string directDiscordEdgeIp = "162.159.135.234";

            try
            {
                using (TcpClient tcp = new TcpClient())
                {
                    IAsyncResult ar = tcp.BeginConnect(directDiscordEdgeIp, 443, null, null);
                    bool connected = ar.AsyncWaitHandle.WaitOne(Math.Min(450, timeoutMs), true);
                    try
                    {
                        if (!connected)
                        {
                            try { tcp.Close(); } catch {}
                            return "FAIL";
                        }
                        tcp.EndConnect(ar);
                        if (!tcp.Connected) return "FAIL";
                    }
                    finally
                    {
                        try { ar.AsyncWaitHandle.Close(); } catch {}
                    }

                    int tlsWait = Math.Max(350, timeoutMs - 200);
                    tcp.ReceiveTimeout = tlsWait;
                    tcp.SendTimeout = tlsWait;

                    Stopwatch swTls = Stopwatch.StartNew();
                    try
                    {
                        using (System.Net.Security.SslStream ssl = new System.Net.Security.SslStream(
                            tcp.GetStream(),
                            false,
                            delegate(object s, System.Security.Cryptography.X509Certificates.X509Certificate cert,
                                     System.Security.Cryptography.X509Certificates.X509Chain chain,
                                     System.Net.Security.SslPolicyErrors sslErrors)
                            {
                                return sslErrors == System.Net.Security.SslPolicyErrors.None;
                            }))
                        {
                            ssl.AuthenticateAsClient(sniHost, null, SslProtocols.Tls12 | (SslProtocols)12288, false);
                            swTls.Stop();
                            rstOrTlsRttMs = Math.Max(1L, swTls.ElapsedMilliseconds);
                            return "OPEN";
                        }
                    }
                    catch (Exception ex)
                    {
                        swTls.Stop();
                        long elapsed = Math.Max(1L, swTls.ElapsedMilliseconds);
                        SocketException sockEx = ex as SocketException;
                        if (sockEx == null && ex.InnerException != null)
                        {
                            sockEx = ex.InnerException as SocketException;
                            if (sockEx == null && ex.InnerException.InnerException != null)
                            {
                                sockEx = ex.InnerException.InnerException as SocketException;
                            }
                        }

                        if (sockEx != null)
                        {
                            if (sockEx.SocketErrorCode == SocketError.TimedOut)
                            {
                                rstOrTlsRttMs = elapsed;
                                return "DROP";
                            }
                            if (sockEx.SocketErrorCode == SocketError.ConnectionReset ||
                                sockEx.SocketErrorCode == SocketError.ConnectionAborted ||
                                sockEx.SocketErrorCode == SocketError.Shutdown)
                            {
                                rstOrTlsRttMs = elapsed;
                                return "RST";
                            }
                        }

                        // Zaman aşımı süresinin %85'inden kısa sürede aniden kesildiyse DPI RST/MITM kesintisidir
                        if (elapsed < (tlsWait * 85) / 100)
                        {
                            rstOrTlsRttMs = elapsed;
                            return "RST";
                        }

                        rstOrTlsRttMs = elapsed;
                        return "DROP";
                    }
                }
            }
            catch
            {
                return "FAIL";
            }
        }

        // Çoklu örneklem (multi-sample) ICMP ping, medyan gecikme, jitter (dalgalanma) ve paket kaybı ölçümü.
        public static long MeasureTargetQualityDetailed(string host, int samples, int timeoutMs, out int packetLossPct, out long jitterMs)
        {
            packetLossPct = 100;
            jitterMs = 0;
            if (string.IsNullOrEmpty(host) || samples <= 0) return -1;
            List<long> rtts = new List<long>(samples);
            try
            {
                using (Ping ping = new Ping())
                {
                    for (int i = 0; i < samples; i++)
                    {
                        try
                        {
                            PingReply reply = ping.Send(host, timeoutMs);
                            if (reply != null && reply.Status == IPStatus.Success)
                            {
                                rtts.Add(reply.RoundtripTime);
                            }
                        }
                        catch {}
                    }
                }
            }
            catch {}

            int okCount = rtts.Count;
            packetLossPct = ((samples - okCount) * 100) / samples;
            if (okCount == 0) return -1;

            rtts.Sort();
            long minRtt = rtts[0];
            long maxRtt = rtts[okCount - 1];
            jitterMs = maxRtt - minRtt;
            long medianRtt = rtts[okCount / 2];
            return medianRtt;
        }

        // Çoklu örneklem (multi-sample) ICMP ping ve paket kaybı ölçümü.
        // Başarılıysa medyan RTT (ms) döner; tümü başarısızsa -1 döner.
        public static long MeasureTargetQuality(string host, int samples, int timeoutMs, out int packetLossPct)
        {
            long jitter;
            return MeasureTargetQualityDetailed(host, samples, timeoutMs, out packetLossPct, out jitter);
        }

        // TCP bağlantı testi. Başarılıysa ms döner; değilse -1 (error: zaman aşımında null, hatada mesaj).
        public static long TestTcpConnect(string host, int port, int timeoutMs, out string error)
        {
            error = null;
            try
            {
                using (TcpClient tcp = new TcpClient())
                {
                    Stopwatch sw = Stopwatch.StartNew();
                    IAsyncResult ar = tcp.BeginConnect(host, port, null, null);
                    bool ok = ar.AsyncWaitHandle.WaitOne(timeoutMs, true);
                    try
                    {
                        if (ok)
                        {
                            // Tamamlanan işlem her koşulda EndConnect ile kapatılır: bağlantı
                            // reddi ve DNS hataları yalnızca EndConnect'te istisna olarak
                            // görünür; eskiden bu dallar yutulup "zaman aşımı" sanılıyordu.
                            tcp.EndConnect(ar);
                            if (tcp.Connected)
                            {
                                sw.Stop();
                                return sw.ElapsedMilliseconds;
                            }
                        }
                        else
                        {
                            // Zaman aşımında bekleyen bağlantı kapatılır; aksi halde soket ve
                            // EndConnect asenkron durumu arka planda sızar.
                            try { tcp.Close(); } catch {}
                        }
                    }
                    catch (Exception ex)
                    {
                        error = ex.Message;
                        return -1;
                    }
                    finally
                    {
                        try { ar.AsyncWaitHandle.Close(); } catch {}
                    }
                    return -1;
                }
            }
            catch (Exception ex)
            {
                error = ex.Message;
                return -1;
            }
        }

        // Gerçek TCP + TLS (ClientHello SNI) el sıkışma testi.
        // Türkiye'deki DPI kutuları TCP 3-yollu el sıkışmaya (SYN/SYN-ACK) izin verip TLS ClientHello
        // içerisindeki SNI ("gateway.discord.gg") paketinde bağlantıyı sıfırladığı (RST/Drop) için
        // gerçek DPI doğrulaması TLS katmanında yapılır.
        public static long TestTlsHandshake(string host, int port, int timeoutMs, out string error)
        {
            error = null;
            try
            {
                using (TcpClient tcp = new TcpClient())
                {
                    Stopwatch sw = Stopwatch.StartNew();
                    IAsyncResult ar = tcp.BeginConnect(host, port, null, null);
                    bool ok = ar.AsyncWaitHandle.WaitOne(timeoutMs, true);
                    try
                    {
                        if (!ok)
                        {
                            try { tcp.Close(); } catch {}
                            error = "TCP zaman aşımı";
                            return -1;
                        }
                        tcp.EndConnect(ar);
                        if (!tcp.Connected)
                        {
                            error = "TCP bağlanamadı";
                            return -1;
                        }
                    }
                    finally
                    {
                        try { ar.AsyncWaitHandle.Close(); } catch {}
                    }

                    int remainingMs = Math.Max(600, timeoutMs - (int)sw.ElapsedMilliseconds);
                    tcp.ReceiveTimeout = remainingMs;
                    tcp.SendTimeout = remainingMs;

                    using (System.Net.Security.SslStream ssl = new System.Net.Security.SslStream(
                        tcp.GetStream(),
                        false,
                        delegate(object s, System.Security.Cryptography.X509Certificates.X509Certificate cert,
                                 System.Security.Cryptography.X509Certificates.X509Chain chain,
                                 System.Net.Security.SslPolicyErrors sslErrors)
                        {
                            // Yalnızca hedef sunucu adı ve sertifika zinciri doğrulanırsa erişilebilir say.
                            return sslErrors == System.Net.Security.SslPolicyErrors.None;
                        }))
                    {
                        // .NET Framework varsayılanı (SslProtocols.Default) TLS 1.0 gönderir; Discord ve
                        // Cloudflare TLS 1.0'ı kabul etmediği için modern protokoller (TLS 1.2/1.3) sabitlenir.
                        // 12288 = TLS 1.3 (eski referans derlemelerinde isimli sabiti yok; Program.Main
                        // http tarafında aynı sayısal kalıbı kullanır). Aksi halde DPI engeli yokken bile
                        // test yanlışlıkla "engelli" dönüyor, motor boşuna yedek mod değiştiriyordu.
                        ssl.AuthenticateAsClient(host, null, SslProtocols.Tls12 | (SslProtocols)12288, false);
                        sw.Stop();
                        return sw.ElapsedMilliseconds;
                    }
                }
            }
            catch (Exception ex)
            {
                error = ex.Message;
                return -1;
            }
        }

        // Tek ICMP ping. Başarılıysa ms döner; değilse -1.
        public static long TestPing(string host, int timeoutMs)
        {
            if (string.IsNullOrEmpty(host)) return -1;
            try
            {
                using (Ping ping = new Ping())
                {
                    PingReply reply = ping.Send(host, timeoutMs);
                    if (reply != null && reply.Status == IPStatus.Success) return reply.RoundtripTime;
                }
            }
            catch {}
            return -1;
        }
    }

    // ==================== Discord WebRTC & UDP Ses Kalkanı (Voice Guard) ====================
    // Discord ses odalarında "RTC Bağlanıyor", "Rota Yok" ve paket kaybı sorunlarını kökten önler.
    // İSS UDP filtrelerini aşmak için MTU Clamping (1420 Byte) ve Windows Multimedya Ses Önceliği uygular.
    public static class DiscordVoiceGuard
    {
        private static volatile bool _isGuardActive = false;
        private static string _activeInterfaceName = null;
        private static int _activeInterfaceOriginalMtu = 0;
        private static readonly object _syncRoot = new object();

        public static bool IsGuardActive { get { return _isGuardActive; } }

        public static string GetActivePhysicalInterfaceName()
        {
            try
            {
                NetworkInterface[] nics = NetworkInterface.GetAllNetworkInterfaces();
                foreach (NetworkInterface nic in nics)
                {
                    if (nic.OperationalStatus != OperationalStatus.Up) continue;
                    if (nic.NetworkInterfaceType != NetworkInterfaceType.Ethernet &&
                        nic.NetworkInterfaceType != NetworkInterfaceType.Wireless80211) continue;

                    string desc = (nic.Description ?? "").ToLowerInvariant();
                    if (desc.Contains("virtual") || desc.Contains("vpn") || desc.Contains("tap") ||
                        desc.Contains("hyper-v") || desc.Contains("vmware") || desc.Contains("vbox") ||
                        desc.Contains("loopback") || desc.Contains("pseudo")) continue;

                    IPInterfaceProperties ipProps = nic.GetIPProperties();
                    if (ipProps == null || ipProps.GatewayAddresses == null || ipProps.GatewayAddresses.Count == 0) continue;

                    bool hasIpv4Gateway = false;
                    foreach (GatewayIPAddressInformation gw in ipProps.GatewayAddresses)
                    {
                        if (gw.Address != null && gw.Address.AddressFamily == AddressFamily.InterNetwork && !gw.Address.Equals(IPAddress.Any))
                        {
                            hasIpv4Gateway = true;
                            break;
                        }
                    }
                    if (hasIpv4Gateway)
                    {
                        return (nic.Name ?? "").Replace("\"", "").Replace("\r", "").Replace("\n", "");
                    }
                }
            }
            catch {}
            return null;
        }

        public static void ApplyVoiceProtection()
        {
            lock (_syncRoot)
            {
                try
                {
                    // 1. MMCSS Audio & Pro Audio Ses İpliği Önceliği + Network Throttling Kaldırma
                    try
                    {
                        using (RegistryKey sysProfile = Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"))
                        {
                            if (sysProfile != null)
                            {
                                sysProfile.SetValue("NetworkThrottlingIndex", unchecked((int)0xffffffff), RegistryValueKind.DWord);
                                sysProfile.SetValue("SystemResponsiveness", 0, RegistryValueKind.DWord);
                            }
                        }

                        using (RegistryKey audioKey = Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Audio"))
                        {
                            if (audioKey != null)
                            {
                                audioKey.SetValue("GPU Priority", 8, RegistryValueKind.DWord);
                                audioKey.SetValue("Priority", 6, RegistryValueKind.DWord);
                                audioKey.SetValue("Scheduling Category", "High", RegistryValueKind.String);
                                audioKey.SetValue("SFIO Priority", "High", RegistryValueKind.String);
                            }
                        }

                        using (RegistryKey proAudioKey = Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio"))
                        {
                            if (proAudioKey != null)
                            {
                                proAudioKey.SetValue("GPU Priority", 8, RegistryValueKind.DWord);
                                proAudioKey.SetValue("Priority", 6, RegistryValueKind.DWord);
                                proAudioKey.SetValue("Scheduling Category", "High", RegistryValueKind.String);
                                proAudioKey.SetValue("SFIO Priority", "High", RegistryValueKind.String);
                            }
                        }
                    }
                    catch {}

                    // 2. MTU Clamping (1420 Byte): WebRTC UDP paketlerinin İSS rotasında bölünmesini ve drop olmasını önler
                    string iface = GetActivePhysicalInterfaceName();
                    if (!string.IsNullOrEmpty(_activeInterfaceName) &&
                        !string.Equals(_activeInterfaceName, iface, StringComparison.OrdinalIgnoreCase))
                    {
                        if (_activeInterfaceOriginalMtu > 0 &&
                            RunNetshDirect(string.Format("interface ipv4 set subinterface \"{0}\" mtu={1} store=active", _activeInterfaceName, _activeInterfaceOriginalMtu)))
                        {
                            _activeInterfaceName = null;
                            _activeInterfaceOriginalMtu = 0;
                        }
                        else
                        {
                            AppLogger.Log("VOICE_GUARD", "Önceki ağ kartının MTU değeri yeni kart etkinleştirilmeden geri yüklenemedi.", LogLevel.Warn);
                        }
                    }

                    bool mtuConfigured = !string.IsNullOrEmpty(_activeInterfaceName) &&
                        string.Equals(_activeInterfaceName, iface, StringComparison.OrdinalIgnoreCase);
                    if (!string.IsNullOrEmpty(iface))
                    {
                        if (string.IsNullOrEmpty(_activeInterfaceName))
                        {
                            int originalMtu = GetInterfaceMtu(iface);
                            if (originalMtu > 0 && RunNetshDirect(string.Format("interface ipv4 set subinterface \"{0}\" mtu=1420 store=active", iface)))
                            {
                                _activeInterfaceName = iface;
                                _activeInterfaceOriginalMtu = originalMtu;
                                mtuConfigured = true;
                            }
                            else
                            {
                                AppLogger.Log("VOICE_GUARD", "Ağ kartı MTU değeri güvenle değiştirilemedi; mevcut değer korundu.", LogLevel.Warn);
                            }
                        }
                    }

                    _isGuardActive = true;
                    string mtuStatus = mtuConfigured ? "MTU: 1420" : "MTU değiştirilmedi";
                    AppLogger.Log("VOICE_GUARD", "Discord WebRTC & UDP Ses Koruyucu devrede (" + mtuStatus + ", MMCSS Audio: High).", LogLevel.Info);
                }
                catch (Exception ex)
                {
                    AppLogger.Log("VOICE_GUARD", "Discord ses koruma uygulanırken hata: " + ex.Message, LogLevel.Warn);
                }
            }
        }

        public static void RestoreVoiceProtection()
        {
            lock (_syncRoot)
            {
                try
                {
                    if (!string.IsNullOrEmpty(_activeInterfaceName))
                    {
                        if (_activeInterfaceOriginalMtu <= 0 ||
                            !RunNetshDirect(string.Format("interface ipv4 set subinterface \"{0}\" mtu={1} store=active", _activeInterfaceName, _activeInterfaceOriginalMtu)))
                        {
                            AppLogger.Log("VOICE_GUARD", "Ağ kartının önceki MTU değeri geri yüklenemedi.", LogLevel.Warn);
                            return;
                        }
                        _activeInterfaceName = null;
                        _activeInterfaceOriginalMtu = 0;
                    }
                    _isGuardActive = false;
                    AppLogger.Log("VOICE_GUARD", "Discord Ses Koruyucu devre dışı; ağ kartının önceki MTU değeri geri yüklendi.", LogLevel.Info);
                }
                catch {}
            }
        }

        private static bool RunNetshDirect(string args)
        {
            try
            {
                using (Process p = new Process())
                {
                    p.StartInfo.FileName = "netsh.exe";
                    p.StartInfo.Arguments = args;
                    p.StartInfo.UseShellExecute = false;
                    p.StartInfo.CreateNoWindow = true;
                    p.StartInfo.WindowStyle = ProcessWindowStyle.Hidden;
                    if (!p.Start()) return false;
                    if (!p.WaitForExit(3000))
                    {
                        try
                        {
                            p.Kill();
                            p.WaitForExit(1000);
                        }
                        catch {}
                        return false;
                    }
                    return p.ExitCode == 0;
                }
            }
            catch { return false; }
        }

        private static int GetInterfaceMtu(string interfaceName)
        {
            if (string.IsNullOrEmpty(interfaceName)) return 0;
            try
            {
                NetworkInterface[] nics = NetworkInterface.GetAllNetworkInterfaces();
                foreach (NetworkInterface nic in nics)
                {
                    if (!string.Equals(nic.Name, interfaceName, StringComparison.OrdinalIgnoreCase)) continue;
                    IPv4InterfaceProperties ipv4 = nic.GetIPProperties().GetIPv4Properties();
                    return ipv4 == null ? 0 : ipv4.Mtu;
                }
            }
            catch {}
            return 0;
        }
    }

    // ==================== Discord CDN Medya & Ekran Paylaşımı Hızlandırıcı (QUIC Engeli Kırıcı) ====================
    // Discord'un resim, video, profil fotoğrafı ve yayın (Go Live) önizlemelerini indirirken kullandığı
    // UDP Port 443 (HTTP/3 QUIC) paketleri Türkiye'deki İSS DPI cihazları tarafından sessizce düşürülür (blackhole)
    // ve TCP/TLS'e düşene kadar 5-10 saniye donmaya yol açar.
    // Bu modül yalnızca Discord yürütülebilir dosyaları için giden UDP 443 (QUIC) denemelerini yerel çekirdekte
    // anında reddederek (<0.1 ms) trafiğin sıfır bekleme ile DPI korumalı TCP/TLS üzerinden akmasını sağlar;
    // WebRTC ses ve yayın akışı yüksek UDP portlarını (19000-65535) kullandığından sese hiçbir olumsuz etkisi yoktur.
    public static class DiscordMediaAccelerator
    {
        public const string FirewallRuleName = "GoodbyeDPI_ProMAX_Discord_QUIC_Block";
        private const string RegistryQuicShieldValue = "QuicShieldActive";
        private const string AppSettingsRegistryKey = @"Software\GoodbyeDPI_Pro_MAX";

        private static readonly object _syncRoot = new object();
        private static readonly HashSet<string> _protectedExePaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        private static volatile bool _isShieldActive = false;
        private static DateTime _lastProcessCheckUtc = DateTime.MinValue;
        private static volatile bool _warmUpRunning = false;

        public static bool IsShieldActive { get { return _isShieldActive; } }

        public static void CleanupStaleShieldOnStartup()
        {
            try
            {
                bool wasActive = false;
                using (RegistryKey key = Registry.CurrentUser.OpenSubKey(AppSettingsRegistryKey, false))
                {
                    if (key != null)
                    {
                        object v = key.GetValue(RegistryQuicShieldValue);
                        if (v is int && ((int)v) != 0) wasActive = true;
                        else if (v != null && v.ToString() == "1") wasActive = true;
                    }
                }
                if (wasActive)
                {
                    RestoreMediaAcceleration(true);
                }
            }
            catch {}
        }

        public static void ApplyMediaAcceleration(bool warmUpEndpoints)
        {
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                ApplyMediaAccelerationCore(warmUpEndpoints);
            });
        }

        public static void ApplyMediaAccelerationCore(bool warmUpEndpoints)
        {
            lock (_syncRoot)
            {
                try
                {
                    List<string> discordExes = DiscoverDiscordExecutables();
                    StringBuilder batch = new StringBuilder();
                    batch.AppendFormat("advfirewall firewall delete rule name=\"{0}\"\r\n", FirewallRuleName);

                    int addedCount = 0;
                    _protectedExePaths.Clear();
                    for (int i = 0; i < discordExes.Count; i++)
                    {
                        string exePath = (discordExes[i] ?? "").Replace("\"", "").Replace("\r", "").Replace("\n", "").Trim();
                        if (string.IsNullOrEmpty(exePath) || !File.Exists(exePath)) continue;
                        if (_protectedExePaths.Add(exePath))
                        {
                            batch.AppendFormat(
                                "advfirewall firewall add rule name=\"{0}\" dir=out action=block protocol=UDP remoteport=443 program=\"{1}\" enable=yes profile=any\r\n",
                                FirewallRuleName,
                                exePath);
                            addedCount++;
                        }
                    }

                    // Eğer henüz yerel Discord yolu bulunamadıysa bile eski kuralı temizle
                    batch.AppendLine("exit");
                    bool batchOk = RunNetshBatch(batch.ToString());
                    _isShieldActive = batchOk && addedCount > 0;
                    SaveShieldRegistryMarker(_isShieldActive);
                    AppHealthMetrics.RecordMediaQuicShieldState(_isShieldActive, addedCount);

                    if (_isShieldActive)
                    {
                        AppLogger.Log("MEDIA_ACCEL", string.Format(
                            "Discord CDN & Medya QUIC Kalkanı aktif ({0} istemci ikilisi için UDP 443 QUIC hızlı TCP/TLS geçişine alındı).",
                            addedCount), LogLevel.Info);
                    }
                }
                catch (Exception ex)
                {
                    AppLogger.Log("MEDIA_ACCEL", "Medya hızlandırıcı uygulanırken hata: " + ex.Message, LogLevel.Warn);
                }
            }

            if (warmUpEndpoints)
            {
                WarmUpAndProbeMediaCdnAsync();
            }
        }

        // Çalışma sırasında Discord yeni bir app-1.0.xxxx sürümüne güncellenirse veya sonradan açılırsa
        // yeni ikili dosyayı da otomatik olarak QUIC kalkanına dahil eder.
        public static void EnsureRunningDiscordProtected()
        {
            DateTime now = DateTime.UtcNow;
            if ((now - _lastProcessCheckUtc).TotalSeconds < 15.0) return;
            _lastProcessCheckUtc = now;

            bool needsRefresh = false;
            lock (_syncRoot)
            {
                string[] procNames = new string[] { "Discord", "DiscordCanary", "DiscordPTB" };
                for (int i = 0; i < procNames.Length; i++)
                {
                    Process[] procs = null;
                    try
                    {
                        procs = Process.GetProcessesByName(procNames[i]);
                        if (procs != null)
                        {
                            for (int j = 0; j < procs.Length; j++)
                            {
                                try
                                {
                                    if (procs[j] != null && procs[j].MainModule != null)
                                    {
                                        string path = procs[j].MainModule.FileName;
                                        if (!string.IsNullOrEmpty(path) && !_protectedExePaths.Contains(path))
                                        {
                                            needsRefresh = true;
                                            break;
                                        }
                                    }
                                }
                                catch {}
                            }
                        }
                    }
                    catch {}
                    finally
                    {
                        if (procs != null)
                        {
                            for (int j = 0; j < procs.Length; j++)
                            {
                                try { if (procs[j] != null) procs[j].Dispose(); } catch {}
                            }
                        }
                    }
                    if (needsRefresh) break;
                }
            }

            if (needsRefresh)
            {
                ApplyMediaAcceleration(true);
            }
        }

        public static void RestoreMediaAcceleration(bool forceClean)
        {
            lock (_syncRoot)
            {
                try
                {
                    if (!_isShieldActive && !forceClean && _protectedExePaths.Count == 0) return;

                    StringBuilder batch = new StringBuilder();
                    batch.AppendFormat("advfirewall firewall delete rule name=\"{0}\"\r\n", FirewallRuleName);
                    batch.AppendLine("exit");
                    RunNetshBatch(batch.ToString());

                    _protectedExePaths.Clear();
                    _isShieldActive = false;
                    SaveShieldRegistryMarker(false);
                    AppHealthMetrics.RecordMediaQuicShieldState(false, 0);
                    AppLogger.Log("MEDIA_ACCEL", "Discord CDN & Medya QUIC Kalkanı kaldırıldı; güvenlik duvarı kuralı temizlendi.", LogLevel.Info);
                }
                catch {}
            }
        }

        public static void WarmUpAndProbeMediaCdnAsync()
        {
            if (_warmUpRunning) return;
            _warmUpRunning = true;
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    string cdnErr;
                    long cdnMs = NetworkProbe.TestTlsHandshake("cdn.discordapp.com", 443, 2200, out cdnErr);
                    string mediaErr;
                    long mediaMs = NetworkProbe.TestTlsHandshake("media.discordapp.net", 443, 2200, out mediaErr);
                    AppHealthMetrics.RecordMediaCdnProbe(cdnMs, mediaMs);

                    if (cdnMs >= 0 && mediaMs >= 0)
                    {
                        AppLogger.Log("MEDIA_ACCEL", string.Format(
                            "Discord Medya CDN ön-ısıtma tamamlandı (cdn.discordapp.com: {0} ms, media.discordapp.net: {1} ms).",
                            cdnMs, mediaMs), LogLevel.Info);
                    }
                    else
                    {
                        AppLogger.Log("MEDIA_ACCEL", string.Format(
                            "Discord Medya CDN ön-ısıtma kısmi/başarısız (cdn: {0}, media: {1}).",
                            cdnMs >= 0 ? (cdnMs + " ms") : (cdnErr ?? "zaman aşımı"),
                            mediaMs >= 0 ? (mediaMs + " ms") : (mediaErr ?? "zaman aşımı")), LogLevel.Warn);
                    }
                }
                catch {}
                finally
                {
                    _warmUpRunning = false;
                }
            });
        }

        private static List<string> DiscoverDiscordExecutables()
        {
            List<string> results = new List<string>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            // 1. Çalışan Discord süreçlerinin tam dosya yolları
            string[] procNames = new string[] { "Discord", "DiscordCanary", "DiscordPTB" };
            for (int i = 0; i < procNames.Length; i++)
            {
                Process[] procs = null;
                try
                {
                    procs = Process.GetProcessesByName(procNames[i]);
                    if (procs != null)
                    {
                        for (int j = 0; j < procs.Length; j++)
                        {
                            try
                            {
                                if (procs[j] != null && procs[j].MainModule != null)
                                {
                                    string pPath = procs[j].MainModule.FileName;
                                    if (!string.IsNullOrEmpty(pPath) && File.Exists(pPath) && seen.Add(pPath))
                                    {
                                        results.Add(pPath);
                                    }
                                }
                            }
                            catch {}
                        }
                    }
                }
                catch {}
                finally
                {
                    if (procs != null)
                    {
                        for (int j = 0; j < procs.Length; j++)
                        {
                            try { if (procs[j] != null) procs[j].Dispose(); } catch {}
                        }
                    }
                }
            }

            // 2. LocalAppData altındaki en güncel 2 app-* klasörü (güncelleme geçişlerini de kapsar)
            try
            {
                string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                string[][] editions = new string[][]
                {
                    new string[] { "Discord", "Discord.exe" },
                    new string[] { "DiscordCanary", "DiscordCanary.exe" },
                    new string[] { "DiscordPTB", "DiscordPTB.exe" }
                };

                for (int e = 0; e < editions.Length; e++)
                {
                    string baseFolder = Path.Combine(localAppData, editions[e][0]);
                    string exeName = editions[e][1];
                    if (!Directory.Exists(baseFolder)) continue;

                    string[] appDirs = Directory.GetDirectories(baseFolder, "app-*");
                    if (appDirs == null || appDirs.Length == 0) continue;

                    Array.Sort(appDirs, delegate(string a, string b)
                    {
                        return Directory.GetLastWriteTimeUtc(a).CompareTo(Directory.GetLastWriteTimeUtc(b));
                    });

                    int startIdx = Math.Max(0, appDirs.Length - 2);
                    for (int k = appDirs.Length - 1; k >= startIdx; k--)
                    {
                        string candidateExe = Path.Combine(appDirs[k], exeName);
                        if (File.Exists(candidateExe) && seen.Add(candidateExe))
                        {
                            results.Add(candidateExe);
                        }
                    }
                }
            }
            catch {}

            return results;
        }

        private static void SaveShieldRegistryMarker(bool active)
        {
            try
            {
                using (RegistryKey key = Registry.CurrentUser.CreateSubKey(AppSettingsRegistryKey))
                {
                    if (key != null)
                    {
                        key.SetValue(RegistryQuicShieldValue, active ? 1 : 0, RegistryValueKind.DWord);
                    }
                }
            }
            catch {}
        }

        private static bool RunNetshBatch(string batchCommands)
        {
            try
            {
                string sysDir = Environment.GetFolderPath(Environment.SpecialFolder.System);
                string netshPath = Path.Combine(sysDir, "netsh.exe");
                if (!File.Exists(netshPath)) netshPath = "netsh.exe";

                ProcessStartInfo psi = new ProcessStartInfo(netshPath);
                psi.UseShellExecute = false;
                psi.CreateNoWindow = true;
                psi.WindowStyle = ProcessWindowStyle.Hidden;
                psi.RedirectStandardInput = true;
                psi.RedirectStandardOutput = false;
                psi.RedirectStandardError = false;

                using (Process p = Process.Start(psi))
                {
                    if (p == null) return false;
                    try
                    {
                        p.StandardInput.Write(batchCommands);
                        p.StandardInput.Flush();
                        p.StandardInput.Close();
                    }
                    catch {}
                    if (!p.WaitForExit(4000))
                    {
                        try { p.Kill(); p.WaitForExit(1000); } catch {}
                        return false;
                    }
                    return true;
                }
            }
            catch
            {
                return false;
            }
        }
    }

    // ==================== İlk Açılış Sihirbazı ====================
    // 5 ekran: 0:Hoş Geldin, 1:İSS Testi, 2:DNS Yarışı, 3:Oyun Optimizasyonu, 4:Özet
    // Odak disiplini: yalnızca kullanıcı akışıyla açılır; oyun algılanırsa ertelenir (ana form tarafı).
    public class WizardForm : Form
    {
        private const int StepCount = 5;
        private const int ListTopIsp = 36;
        private const int IspRowH = 32;
        private const int IspRowGap = 3;
        private const int ListTopDns = 32;
        private const int DnsRowH = 42;
        private const int DnsRowGap = 6;
        private const int WizardDnsCount = 5;

        private static bool TryGetDnsEndpoint(DnsOption opt, out string server, out int port)
        {
            server = "";
            port = 53;
            if (opt == null || string.IsNullOrEmpty(opt.PingTargetIp)) return false;
            server = opt.PingTargetIp.Trim();
            if (!string.IsNullOrEmpty(opt.DpiArgs))
            {
                int pm = opt.DpiArgs.IndexOf("--dns-port", StringComparison.OrdinalIgnoreCase);
                if (pm >= 0)
                {
                    string tail = opt.DpiArgs.Substring(pm + "--dns-port".Length).Trim();
                    string[] values = tail.Split(new char[] { ' ', '\t', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                    int p;
                    if (values.Length > 0 && int.TryParse(values[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out p) &&
                        p >= 1 && p <= 65535)
                    {
                        port = p;
                    }
                }
            }
            return true;
        }

        // ===== Sonuçlar (ShowDialog dönüşünde ana form okur; yan etki ana formda uygulanır) =====
        public bool Applied = false;
        public int ResultProfileIdx = -1;
        public int ResultDnsIdx = -1;
        public bool ApplyGamingOptimization = false;
        public bool StartProtection = false;

        private readonly List<IspProfile> _profiles;
        private readonly List<DnsOption> _dnsOptions;

        private int _currentStep = 0;
        private int _selProfile = -1;
        private int _selDns = -1;
        private bool _ispUserTouched = false;
        private bool _dnsUserTouched = false;

        // İSS testi durumu (-2: bekliyor, -1: başarısız, >=0: ms)
        private long[] _ispTimes;
        private int _ispPending = 0;
        private bool _ispStarted = false;
        private bool _ispDone = false;
        private int _ispRecommended = -1;
        private int _ispDetectedByHop = -1;
        private int _ispHoverRow = -1;
        private bool _dpiPoisoned = false;
        private string _dpiDnsText = "";
        private long _dpiGatewayMs = -2;

        // DNS yarışı durumu (-2: bekliyor, -1: başarısız, >=0: ms)
        private long[] _dnsTimes;
        private int _dnsPending = 0;
        private bool _dnsStarted = false;
        private bool _dnsDone = false;
        private int _dnsFastest = -1;
        private int _dnsHoverRow = -1;
        private bool _port53ProxyDetected = false;

        // Gömülü başlık çubuğu durumu (ana formdaki desenin dialog sürümü)
        private bool _isDraggingWindow;
        private Point _dragStartPoint;

        // Kontroller
        private DoubleBufferedPanel _headerPanel;
        private DoubleBufferedPanel _stepStrip;
        private DoubleBufferedPanel _panelWelcome;
        private DoubleBufferedPanel _panelIsp;
        private DoubleBufferedPanel _panelDns;
        private DoubleBufferedPanel _panelGaming;
        private DoubleBufferedPanel _panelSummary;
        private RoundedButton _btnQuick;
        private RoundedButton _btnManual;
        private RoundedButton _btnBack;
        private RoundedButton _btnNext;
        private RoundedButton _btnSaveOnly;
        private CustomCheckBox _chkGaming;
        private System.Windows.Forms.Timer _animTimer;

        // Adım geçiş animasyonu (içerik kayması + şerit dolgusu)
        private const int StepSlidePixels = 22;
        private const int StepSlideTicksTotal = 7;
        private DoubleBufferedPanel _contentHost;
        private Control _stepSlidePanel;
        private int _stepSlideTicks = 0;
        private int _stepSlideTotal = 1;
        private int _stepSlideDir = 1;
        private double _stripFill = 1.0;

        // Fontlar (Dispose'da serbest bırakılır)
        // Tipografi ölçeği: mikro 8.5 · gövde 9.5 · vurgu 10/10.5 · bölüm 11.5 · kahraman 17
        private readonly Font _fontStepNum = new Font("Segoe UI", 8.5F, FontStyle.Bold);
        private readonly Font _fontHero = new Font("Segoe UI", 17F, FontStyle.Bold);
        private readonly Font _fontSection = new Font("Segoe UI", 11.5F, FontStyle.Bold);
        private readonly Font _fontBody = new Font("Segoe UI", 9.5F, FontStyle.Regular);
        private readonly Font _fontBodyBold = new Font("Segoe UI", 9.5F, FontStyle.Bold);
        private readonly Font _fontBullet = new Font("Segoe UI", 9.5F, FontStyle.Regular);
        private readonly Font _fontRowName = new Font("Segoe UI Semibold", 10F, FontStyle.Regular);
        private readonly Font _fontRowSub = new Font("Segoe UI", 8.5F, FontStyle.Regular);
        private readonly Font _fontRowMs = new Font("Segoe UI", 10.5F, FontStyle.Bold);
        private readonly Font _fontChip = new Font("Segoe UI", 8F, FontStyle.Bold);
        private readonly Font _fontSmall = new Font("Segoe UI", 8.5F, FontStyle.Regular);
        private readonly Font _fontCheck = new Font("Segoe UI Semibold", 9.5F, FontStyle.Regular);

        public WizardForm(List<IspProfile> profiles, List<DnsOption> dnsOptions, int currentProfileIdx, int currentDnsIdx)
        {
            _profiles = profiles ?? new List<IspProfile>();
            _dnsOptions = dnsOptions ?? new List<DnsOption>();

            _selProfile = _profiles.Count > 0 ? Math.Max(0, Math.Min(currentProfileIdx, _profiles.Count - 1)) : -1;
            _selDns = _dnsOptions.Count > 0 ? Math.Max(0, Math.Min(currentDnsIdx, _dnsOptions.Count - 1)) : -1;

            _ispTimes = new long[_profiles.Count];
            _dnsTimes = new long[_dnsOptions.Count];
            for (int i = 0; i < _ispTimes.Length; i++) _ispTimes[i] = -2;
            for (int i = 0; i < _dnsTimes.Length; i++) _dnsTimes[i] = -2;

            this.Text = "GoodbyeDPI Pro MAX - Kurulum Sihirbazı";
            this.ClientSize = new Size(640, 592);
            this.StartPosition = FormStartPosition.CenterParent;
            this.FormBorderStyle = FormBorderStyle.None;
            this.MaximizeBox = false;
            this.MinimizeBox = false;
            this.ShowInTaskbar = false;
            // Esc ile sihirbaz kapatılabilir (standart pencere davranışı korunur).
            this.KeyPreview = true;
            this.KeyDown += delegate(object s, KeyEventArgs ke)
            {
                if (ke.KeyCode == Keys.Escape) { this.Close(); return; }

                // Enter → birincil eylem (Hızlı Kurulum / İleri / Korumayı Başlat).
                // Odak bir butondaysa butonun kendi davranışına karışılmaz.
                if (ke.KeyCode == Keys.Enter)
                {
                    Control ac = this.ActiveControl;
                    if (!(ac is ButtonBase))
                    {
                        RoundedButton primary = (_currentStep == 0) ? _btnQuick : _btnNext;
                        if (primary != null && !primary.IsDisposed && primary.Visible && primary.Enabled)
                        {
                            ke.Handled = true;
                            ke.SuppressKeyPress = true;
                            primary.PerformClick();
                        }
                    }
                }
            };
            this.BackColor = Color.FromArgb(14, 17, 24);
            this.ForeColor = Color.FromArgb(226, 232, 240);
            this.Font = new Font("Segoe UI", 9F, FontStyle.Regular);

            InitializeControls();
            ShowStep(0);

            // Buton hover animasyonları (ana formdaki desenin dialog sürümü)
            _animTimer = new System.Windows.Forms.Timer();
            _animTimer.Interval = 33;
            _animTimer.Tick += delegate
            {
                if (this.IsDisposed) return;
                try
                {
                    if (_btnQuick != null) _btnQuick.UpdateAnimation();
                    if (_btnManual != null) _btnManual.UpdateAnimation();
                    if (_btnBack != null) _btnBack.UpdateAnimation();
                    if (_btnNext != null) _btnNext.UpdateAnimation();
                    if (_btnSaveOnly != null) _btnSaveOnly.UpdateAnimation();

                    // Adım kayma animasyonu
                    if (_stepSlidePanel != null) TickStepSlide();

                    // İSS testi sürerken canlılık nabzı (yalnızca pencere odaktayken)
                    if (_panelIsp != null && _panelIsp.Visible && _ispStarted && !_ispDone && this.ContainsFocus)
                    {
                        _panelIsp.Invalidate();
                    }
                }
                catch {}
            };
            _animTimer.Start();
        }

        protected override void OnHandleCreated(EventArgs e)
        {
            base.OnHandleCreated(e);
            ModernMainForm.ApplyImmersiveDarkMode(this.Handle);
        }

        protected override CreateParams CreateParams
        {
            get
            {
                CreateParams cp = base.CreateParams;
                cp.ClassStyle |= 0x00020000; // CS_DROPSHADOW
                return cp;
            }
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            using (Pen bPen = new Pen(Color.FromArgb(38, 52, 76), 1f))
            {
                e.Graphics.DrawRectangle(bPen, 0, 0, this.Width - 1, this.Height - 1);
            }
        }

        protected override void OnShown(EventArgs e)
        {
            base.OnShown(e);
            // Açılış animasyonu: karşılama içeriği sağdan kayarak gelir.
            if (_currentStep == 0) StartStepSlide(1);
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                try { if (_animTimer != null) { _animTimer.Stop(); _animTimer.Dispose(); _animTimer = null; } } catch {}
                try { _fontStepNum.Dispose(); } catch {}
                try { _fontHero.Dispose(); } catch {}
                try { _fontSection.Dispose(); } catch {}
                try { _fontBody.Dispose(); } catch {}
                try { _fontBodyBold.Dispose(); } catch {}
                try { _fontBullet.Dispose(); } catch {}
                try { _fontRowName.Dispose(); } catch {}
                try { _fontRowSub.Dispose(); } catch {}
                try { _fontRowMs.Dispose(); } catch {}
                try { _fontChip.Dispose(); } catch {}
                try { _fontSmall.Dispose(); } catch {}
                try { _fontCheck.Dispose(); } catch {}
            }
            base.Dispose(disposing);
        }

