        // ==================== Adım Yönetimi ====================

        private void ShowStep(int step)
        {
            int prevStep = _currentStep;
            _currentStep = Math.Max(0, Math.Min(StepCount - 1, step));
            bool forward = (_currentStep >= prevStep);

            if (_panelWelcome != null) _panelWelcome.Visible = (_currentStep == 0);
            if (_panelIsp != null) _panelIsp.Visible = (_currentStep == 1);
            if (_panelDns != null) _panelDns.Visible = (_currentStep == 2);
            if (_panelGaming != null) _panelGaming.Visible = (_currentStep == 3);
            if (_panelSummary != null) _panelSummary.Visible = (_currentStep == 4);

            // Footer buton düzeni
            bool inFlow = _currentStep >= 1;
            if (_btnBack != null) _btnBack.Visible = inFlow;
            if (_btnNext != null)
            {
                _btnNext.Visible = inFlow;
                if (_currentStep == 4)
                {
                    _btnNext.Text = "Korumayı Başlat";
                    _btnNext.IconType = "play";
                }
                else
                {
                    _btnNext.Text = "İleri";
                    _btnNext.IconType = "";
                }
            }
            if (_btnSaveOnly != null) _btnSaveOnly.Visible = (_currentStep == 4);

            if (_headerPanel != null && !_headerPanel.IsDisposed) _headerPanel.Invalidate();
            if (_stepStrip != null && !_stepStrip.IsDisposed) _stepStrip.Invalidate();
            if (_panelSummary != null && !_panelSummary.IsDisposed && _currentStep == 4) _panelSummary.Invalidate();

            // Adım geçiş animasyonu (yalnızca gerçek değişimde; yön ileri/geri)
            if (_currentStep != prevStep) StartStepSlide(forward ? 1 : -1);

            // Testleri tembel başlat (adım ilk kez açıldığında)
            if (_currentStep == 1 && !_ispStarted) RunIspTests();
            if (_currentStep == 2 && !_dnsStarted) RunDnsRace();
        }

        // ==================== Adım Geçiş Animasyonu ====================

        private void StartStepSlide(int dir)
        {
            try
            {
                if (_contentHost == null || _contentHost.IsDisposed || !this.IsHandleCreated) return;

                // Önceki animasyon sürüyorsa önce onu normal düzenine döndür
                EndStepSlide();

                Control p = null;
                if (_currentStep == 0) p = _panelWelcome;
                else if (_currentStep == 1) p = _panelIsp;
                else if (_currentStep == 2) p = _panelDns;
                else if (_currentStep == 3) p = _panelGaming;
                else p = _panelSummary;
                if (p == null || p.IsDisposed || !p.Visible) return;

                _stepSlidePanel = p;
                _stepSlideDir = (dir >= 0) ? 1 : -1;
                _stepSlideTotal = StepSlideTicksTotal;
                _stepSlideTicks = _stepSlideTotal;
                ApplyStepSlideOffset(StepSlidePixels * _stepSlideDir);

                // Şerit dolgusu yalnızca ileri geçişlerde soldan sağa büyür
                if (_stepSlideDir > 0 && _currentStep > 0) _stripFill = 0.0;
                else _stripFill = 1.0;
                if (_stepStrip != null && !_stepStrip.IsDisposed) _stepStrip.Invalidate();
            }
            catch {}
        }

        private void ApplyStepSlideOffset(int dx)
        {
            if (_stepSlidePanel == null || _contentHost == null || _contentHost.IsDisposed) return;
            int cw = _contentHost.ClientSize.Width;
            int ch = _contentHost.ClientSize.Height;
            if (cw <= 0 || ch <= 0) return;
            _stepSlidePanel.Dock = DockStyle.None;
            _stepSlidePanel.Bounds = new Rectangle(dx, 0, cw, ch);
        }

        private void TickStepSlide()
        {
            if (_stepSlidePanel == null) return;

            if (_stepSlideTicks > 0) _stepSlideTicks--;

            if (_stepSlideTicks <= 0)
            {
                EndStepSlide();
                _stripFill = 1.0;
                if (_stepStrip != null && !_stepStrip.IsDisposed) _stepStrip.Invalidate();
                return;
            }

            // Ease-out: hızlı başlar, yumuşak oturur
            double frac = (double)_stepSlideTicks / _stepSlideTotal;
            int dx = (int)Math.Round(StepSlidePixels * _stepSlideDir * frac * frac);
            ApplyStepSlideOffset(dx);

            if (_stripFill < 1.0)
            {
                _stripFill = Math.Min(1.0, _stripFill + 1.0 / _stepSlideTotal);
                if (_stepStrip != null && !_stepStrip.IsDisposed) _stepStrip.Invalidate();
            }
        }

        private void EndStepSlide()
        {
            if (_stepSlidePanel != null)
            {
                try { _stepSlidePanel.Dock = DockStyle.Fill; } catch {}
                _stepSlidePanel = null;
            }
            _stepSlideTicks = 0;
        }

        private void Finish(bool startProtection)
        {
            try
            {
                Applied = true;
                ResultProfileIdx = _selProfile;
                ResultDnsIdx = _selDns;
                ApplyGamingOptimization = (_chkGaming != null && _chkGaming.Checked);
                StartProtection = startProtection;
                AppLogger.Log("WIZARD", string.Format("Sihirbaz tamamlandı: Profil={0}, DNS={1}, OyunOpt={2}, Koruma={3}",
                    ResultProfileIdx, ResultDnsIdx, ApplyGamingOptimization, StartProtection));
            }
            catch {}
            finally
            {
                this.DialogResult = DialogResult.OK;
                this.Close();
            }
        }

        // ==================== Çizim: Başlık & Adım Şeridi ====================

        private void HeaderPanel_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            using (SolidBrush bgBrush = new SolidBrush(Color.FromArgb(16, 20, 29)))
            {
                g.FillRectangle(bgBrush, _headerPanel.ClientRectangle);
            }
            using (Pen pen = new Pen(Color.FromArgb(30, 38, 54), 1f))
            {
                g.DrawLine(pen, 0, _headerPanel.Height - 1, _headerPanel.Width, _headerPanel.Height - 1);
            }

            // Kalkan ikonu (26px)
            DrawShield(g, 10, 16, 26, Color.FromArgb(56, 189, 248), Color.FromArgb(99, 102, 241), true);

            // Sağ üst: adım rozeti
            string stepText = string.Format("ADIM {0}/{1}", _currentStep + 1, StepCount);
            Rectangle bdgRect = new Rectangle(_headerPanel.Width - 108, 18, 88, 22);
            using (GraphicsPath bPath = ModernMainForm.CreateRoundedRectangleF(new RectangleF(bdgRect.X, bdgRect.Y, bdgRect.Width, bdgRect.Height), 4f))
            using (SolidBrush bBg = new SolidBrush(Color.FromArgb(20, 34, 56)))
            using (Pen bPen = new Pen(Color.FromArgb(45, 100, 160), 1f))
            {
                g.FillPath(bBg, bPath);
                g.DrawPath(bPen, bPath);
            }
            TextRenderer.DrawText(g, stepText, _fontStepNum, bdgRect, Color.FromArgb(125, 211, 252),
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
        }

        private void StepStrip_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;

            int cy = _stepStrip.Height / 2;
            int spacing = 46;
            int startX = (_stepStrip.Width - (StepCount - 1) * spacing) / 2;

            for (int i = 0; i < StepCount; i++)
            {
                int cx = startX + i * spacing;
                bool done = i < _currentStep;
                bool cur = (i == _currentStep);

                if (i > 0)
                {
                    int lx1 = cx - spacing + 9;
                    int lx2 = cx - 9;
                    bool filled = (i <= _currentStep);
                    if (filled && i == _currentStep && _stripFill < 1.0)
                    {
                        // İlerlerken son bağlantı soldan sağa dolar (geçiş animasyonuyla eşzamanlı)
                        using (Pen dim = new Pen(Color.FromArgb(38, 50, 70), 2f))
                        {
                            g.DrawLine(dim, lx1, cy, lx2, cy);
                        }
                        float part = (float)((lx2 - lx1) * _stripFill);
                        using (Pen fill = new Pen(Color.FromArgb(70, 90, 130), 2f))
                        {
                            g.DrawLine(fill, lx1, cy, lx1 + part, cy);
                        }
                    }
                    else
                    {
                        using (Pen lp = new Pen(filled ? Color.FromArgb(70, 90, 130) : Color.FromArgb(38, 50, 70), 2f))
                        {
                            g.DrawLine(lp, lx1, cy, lx2, cy);
                        }
                    }
                }

                int r = cur ? 6 : 5;
                if (cur)
                {
                    using (Pen halo = new Pen(Color.FromArgb(40, 56, 189, 248), 3f))
                    {
                        g.DrawEllipse(halo, cx - r - 3, cy - r - 3, (r + 3) * 2, (r + 3) * 2);
                    }
                }

                Color dotFill = cur ? Color.FromArgb(56, 189, 248) : (done ? Color.FromArgb(52, 211, 153) : Color.FromArgb(30, 38, 54));
                Color dotBorder = cur ? Color.FromArgb(125, 211, 252) : (done ? Color.FromArgb(52, 211, 153) : Color.FromArgb(55, 68, 92));
                using (SolidBrush b = new SolidBrush(dotFill))
                using (Pen p = new Pen(dotBorder, 1.4f))
                {
                    g.FillEllipse(b, cx - r, cy - r, r * 2, r * 2);
                    g.DrawEllipse(p, cx - r, cy - r, r * 2, r * 2);
                }

                if (done)
                {
                    using (Pen ck = new Pen(Color.FromArgb(9, 30, 22), 1.6f))
                    {
                        ck.StartCap = LineCap.Round;
                        ck.EndCap = LineCap.Round;
                        g.DrawLines(ck, new PointF[] {
                            new PointF(cx - 2.6f, cy - 0.2f),
                            new PointF(cx - 0.8f, cy + 1.8f),
                            new PointF(cx + 2.8f, cy - 2.2f)
                        });
                    }
                }
            }
        }

        // Ortak: kalkan logosu (küçük ikon ve 64px karşılama logosu)
        private static void DrawShield(Graphics g, int x, int y, int size, Color c1, Color c2, bool withCheck)
        {
            float u = size / 64f;
            using (GraphicsPath shield = new GraphicsPath())
            {
                shield.AddLine(x + 2f * u, y + 8f * u, x + 62f * u, y + 8f * u);
                shield.AddLine(x + 62f * u, y + 8f * u, x + 62f * u, y + 30f * u);
                shield.AddBezier(x + 62f * u, y + 30f * u, x + 62f * u, y + 48f * u, x + 42f * u, y + 58f * u, x + 32f * u, y + 63f * u);
                shield.AddBezier(x + 32f * u, y + 63f * u, x + 22f * u, y + 58f * u, x + 2f * u, y + 48f * u, x + 2f * u, y + 30f * u);
                shield.CloseFigure();

                using (LinearGradientBrush lgb = new LinearGradientBrush(
                    new Rectangle(x, y, size, size), c1, c2, 45f))
                {
                    g.FillPath(lgb, shield);
                }
            }

            if (withCheck)
            {
                using (Pen p = new Pen(Color.White, Math.Max(1.4f, 4.5f * u)))
                {
                    p.StartCap = LineCap.Round;
                    p.EndCap = LineCap.Round;
                    p.LineJoin = LineJoin.Round;
                    g.DrawLines(p, new PointF[] {
                        new PointF(x + 18f * u, y + 32f * u),
                        new PointF(x + 28f * u, y + 43f * u),
                        new PointF(x + 46f * u, y + 22f * u)
                    });
                }
            }
        }

        // Ortak: radio işareti
        private static void DrawRadio(Graphics g, int cx, int cy, bool selected, Color accent)
        {
            int r = 8;
            using (Pen ring = new Pen(selected ? accent : Color.FromArgb(71, 85, 105), 1.6f))
            {
                g.DrawEllipse(ring, cx - r, cy - r, r * 2, r * 2);
            }
            if (selected)
            {
                using (SolidBrush fill = new SolidBrush(accent))
                {
                    g.FillEllipse(fill, cx - 4, cy - 4, 8, 8);
                }
            }
        }

        // Ortak: sağa hizalı ms metni çizer, metnin sol kenarını döndürür
        private int DrawMsRight(Graphics g, Rectangle rowRect, long value)
        {
            string msText;
            Color msColor;
            Font useFont = _fontRowMs;
            if (value == -3)
            {
                msText = "Engelli";
                msColor = Color.FromArgb(239, 68, 68);
                useFont = _fontBodyBold;
            }
            else if (value == -2)
            {
                msText = "test...";
                msColor = Color.FromArgb(100, 116, 139);
            }
            else if (value < 0)
            {
                msText = "yanıt yok";
                msColor = Color.FromArgb(239, 68, 68);
            }
            else
            {
                msText = value + " ms";
                msColor = ModernMainForm.GetPingQualityColor((int)value);
            }

            Size msSize = TextRenderer.MeasureText(g, msText, useFont, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
            int msX = rowRect.Right - 14 - msSize.Width;
            TextRenderer.DrawText(g, msText, useFont, new Rectangle(msX, rowRect.Y, msSize.Width + 2, rowRect.Height), msColor,
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
            return msX;
        }

        // Ortak durum rozetini çizer ve çipin sol kenarını döndürür
        private int DrawBadgeChip(Graphics g, int rightLimitX, int rowY, int rowH, string text, bool experimental = false)
        {
            Size cs = TextRenderer.MeasureText(g, text, _fontChip, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding);
            int chipW = cs.Width + 16;
            Rectangle chipRect = new Rectangle(rightLimitX - chipW, rowY + (rowH - 18) / 2, chipW, 18);
            Color fillColor = experimental ? Color.FromArgb(47, 35, 16) : Color.FromArgb(20, 44, 34);
            Color borderColor = experimental ? Color.FromArgb(70, 245, 158, 11) : Color.FromArgb(50, 52, 211, 153);
            Color textColor = experimental ? Color.FromArgb(251, 191, 36) : Color.FromArgb(52, 211, 153);
            using (GraphicsPath cpath = ModernMainForm.CreateRoundedRectangleF(new RectangleF(chipRect.X, chipRect.Y, chipRect.Width, chipRect.Height), 9f))
            using (SolidBrush cb = new SolidBrush(fillColor))
            using (Pen cp = new Pen(borderColor, 1f))
            {
                g.FillPath(cb, cpath);
                g.DrawPath(cp, cpath);
            }
            TextRenderer.DrawText(g, text, _fontChip, chipRect, textColor,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
            return chipRect.X;
        }

