        // ==================== Adım 1: İSS Testi ====================

        private int HitTestIspRow(Point p)
        {
            if (_profiles.Count == 0) return -1;
            if (p.X < 16 || p.X > _panelIsp.Width - 16) return -1;
            int y = p.Y - ListTopIsp;
            if (y < 0) return -1;
            int slot = y / (IspRowH + IspRowGap);
            int inRow = y % (IspRowH + IspRowGap);
            // inRow == IspRowH tam olarak boşluğun ilk pikselidir; satır sayılmaz.
            if (inRow >= IspRowH) return -1;
            if (slot < 0 || slot >= _profiles.Count) return -1;
            return slot;
        }

        private void IspPanel_MouseMove(object sender, MouseEventArgs e)
        {
            int idx = HitTestIspRow(e.Location);
            if (idx != _ispHoverRow)
            {
                _ispHoverRow = idx;
                if (_panelIsp != null && !_panelIsp.IsDisposed) _panelIsp.Invalidate();
            }
        }

        private void IspPanel_MouseClick(object sender, MouseEventArgs e)
        {
            int idx = HitTestIspRow(e.Location);
            if (idx >= 0)
            {
                _selProfile = idx;
                _ispUserTouched = true;
                if (_panelIsp != null && !_panelIsp.IsDisposed) _panelIsp.Invalidate();
            }
        }

        private void IspPanel_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            int w = _panelIsp.Width;

            // Durum satırı
            string statusText;
            if (!_ispDone)
            {
                // Toplam adım: profil pingleri + 3 ek görev (İSS algılama, DNS zehirlenme, gateway TLS).
                // _ispPending değeriyle (Count+3) birebir hizalanır; sayaç eksiye düşmez.
                int total = _profiles.Count + 3;
                int completed = total - Math.Max(0, _ispPending);
                statusText = string.Format("İnternet sağlayıcıları test ediliyor... ({0}/{1})", completed, total);
            }
            else
            {
                if (_ispRecommended >= 0)
                {
                    statusText = "Test tamamlandı. En hızlı profil seçildi. Değiştirmek için satıra tıklayın.";
                }
                else
                {
                    statusText = "Test tamamlandı. Mevcut profiliniz korundu. Değiştirmek için satıra tıklayın.";
                }
            }
            TextRenderer.DrawText(g, statusText, _fontBody, new Rectangle(16, 8, w - 32, 22), Color.FromArgb(148, 163, 184),
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);

            // Test sürerken sağda nabız gibi atan canlılık noktası
            if (_ispStarted && !_ispDone)
            {
                double ph = (Environment.TickCount % 1000) / 1000.0;
                double pulse = (Math.Sin(ph * 2 * Math.PI) + 1) / 2;
                float pcx = w - 24f;
                float pcy = 19f;
                using (SolidBrush halo = new SolidBrush(Color.FromArgb((int)(35 + 60 * pulse), 56, 189, 248)))
                using (SolidBrush core = new SolidBrush(Color.FromArgb((int)(165 + 90 * pulse), 56, 189, 248)))
                {
                    g.FillEllipse(halo, pcx - 7f, pcy - 7f, 14f, 14f);
                    g.FillEllipse(core, pcx - 3.5f, pcy - 3.5f, 7f, 7f);
                }
            }

            // Profil satırları
            int y = ListTopIsp;
            for (int i = 0; i < _profiles.Count; i++)
            {
                Rectangle rr = new Rectangle(16, y, w - 32, IspRowH);
                bool selected = (i == _selProfile);
                bool hovered = (i == _ispHoverRow);
                Color accent = _profiles[i].AccentColor;

                using (GraphicsPath path = ModernMainForm.CreateRoundedRectangleF(new RectangleF(rr.X, rr.Y, rr.Width, rr.Height), 7f))
                using (SolidBrush bg = new SolidBrush(hovered ? Color.FromArgb(22, 30, 44) : Color.FromArgb(18, 24, 34)))
                using (Pen pen = new Pen(selected ? accent : Color.FromArgb(38, 50, 70), selected ? 1.6f : 1f))
                {
                    g.FillPath(bg, path);
                    g.DrawPath(pen, path);
                }

                DrawRadio(g, rr.X + 20, rr.Y + rr.Height / 2, selected, accent);

                int msX = DrawMsRight(g, rr, _ispTimes[i]);

                int rightLimit = msX - 12;
                if (_ispDone && i == _ispRecommended)
                {
                    rightLimit = DrawBadgeChip(g, rightLimit, rr.Y, rr.Height, "✓ ÖNERİLEN") - 8;
                }

                int nameW = Math.Max(20, rightLimit - (rr.X + 42));
                TextRenderer.DrawText(g, _profiles[i].Name, _fontRowName,
                    new Rectangle(rr.X + 42, rr.Y, nameW, rr.Height), Color.FromArgb(226, 232, 240),
                    TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);

                y += IspRowH + IspRowGap;
            }

            // DPI durum kutusu (alt)
            int infoTop = _panelIsp.Height - 56;
            Rectangle infoRect = new Rectangle(16, infoTop, w - 32, 48);
            Color ibBorder, ibBg, ibTitle;
            string infoTitle, infoDetail;

            if (!_ispDone)
            {
                ibBorder = Color.FromArgb(38, 50, 70);
                ibBg = Color.FromArgb(18, 24, 34);
                ibTitle = Color.FromArgb(148, 163, 184);
                infoTitle = "Bağlantı testleri sürüyor...";
                infoDetail = "Discord bağlantısı ve sağlayıcı profilleri kontrol ediliyor.";
            }
            else if (_dpiPoisoned)
            {
                ibBorder = Color.FromArgb(90, 239, 68, 68);
                ibBg = Color.FromArgb(40, 20, 22);
                ibTitle = Color.FromArgb(239, 68, 68);
                infoTitle = "DNS engeli tespit edildi";
                infoDetail = "Discord adresleri engelleniyor. Koruma açıldığında otomatik düzelecek.";
            }
            else if (_dpiGatewayMs < 0)
            {
                ibBorder = Color.FromArgb(90, 245, 158, 11);
                ibBg = Color.FromArgb(40, 32, 14);
                ibTitle = Color.FromArgb(245, 158, 11);
                infoTitle = "Discord sunucularına ulaşılamadı";
                infoDetail = "Bağlantı engelli görünüyor. Koruma başlatıldığında erişim açılacak.";
            }
            else
            {
                ibBorder = Color.FromArgb(70, 52, 211, 153);
                ibBg = Color.FromArgb(20, 38, 32);
                ibTitle = Color.FromArgb(52, 211, 153);
                infoTitle = "Bağlantı sorunsuz görünüyor";
                infoDetail = string.Format("Discord erişimi açık ({0} ms).", _dpiGatewayMs);
            }

            using (GraphicsPath ipath = ModernMainForm.CreateRoundedRectangleF(new RectangleF(infoRect.X, infoRect.Y, infoRect.Width, infoRect.Height), 7f))
            using (SolidBrush ib = new SolidBrush(ibBg))
            using (Pen ip = new Pen(ibBorder, 1f))
            {
                g.FillPath(ib, ipath);
                g.DrawPath(ip, ipath);
            }
            TextRenderer.DrawText(g, infoTitle, _fontBodyBold, new Rectangle(infoRect.X + 14, infoRect.Y + 5, infoRect.Width - 28, 18), ibTitle,
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
            TextRenderer.DrawText(g, infoDetail, _fontSmall, new Rectangle(infoRect.X + 14, infoRect.Y + 25, infoRect.Width - 28, 16), Color.FromArgb(148, 163, 184),
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        }

        // ==================== Adım 2: DNS Yarışı ====================

        private int HitTestDnsRow(Point p)
        {
            if (_dnsOptions.Count == 0) return -1;
            if (p.X < 16 || p.X > _panelDns.Width - 16) return -1;
            int y = p.Y - ListTopDns;
            if (y < 0) return -1;
            int slot = y / (DnsRowH + DnsRowGap);
            int inRow = y % (DnsRowH + DnsRowGap);
            // inRow == DnsRowH tam olarak boşluğun ilk pikselidir; satır sayılmaz.
            if (inRow >= DnsRowH) return -1;
            if (slot < 0 || slot >= Math.Min(WizardDnsCount, _dnsOptions.Count)) return -1;
            return slot;
        }

        private void DnsPanel_MouseMove(object sender, MouseEventArgs e)
        {
            int idx = HitTestDnsRow(e.Location);
            if (idx != _dnsHoverRow)
            {
                _dnsHoverRow = idx;
                if (_panelDns != null && !_panelDns.IsDisposed) _panelDns.Invalidate();
            }
        }

        private void DnsPanel_MouseClick(object sender, MouseEventArgs e)
        {
            int idx = HitTestDnsRow(e.Location);
            if (idx >= 0)
            {
                _selDns = idx;
                _dnsUserTouched = true;
                if (_panelDns != null && !_panelDns.IsDisposed) _panelDns.Invalidate();
            }
        }

        private void DnsPanel_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            int w = _panelDns.Width;

            // Durum satırı
            string statusText;
            int total = Math.Min(WizardDnsCount, _dnsOptions.Count) - 1;
            if (!_dnsDone)
            {
                int completed = total - Math.Max(0, _dnsPending);
                statusText = string.Format("DNS sunucuları test ediliyor... ({0}/{1})", Math.Max(0, completed), Math.Max(1, total));
            }
            else if (_port53ProxyDetected)
            {
                statusText = "Standart DNS engeli tespit edildi. Engelsiz port kullanan Quad9 (Port 9953) seçildi.";
            }
            else
            {
                if (_dnsFastest >= 0 && !_dnsUserTouched)
                {
                    statusText = "Test tamamlandı. En hızlı DNS otomatik seçildi. Değiştirmek için satıra tıklayın.";
                }
                else if (_dnsFastest >= 0)
                {
                    statusText = "Test tamamlandı. Seçiminiz korundu. Değiştirmek için satıra tıklayın.";
                }
                else
                {
                    statusText = "Test tamamlandı. Mevcut seçiminiz korundu.";
                }
            }
            TextRenderer.DrawText(g, statusText, _fontBody, new Rectangle(16, 8, w - 32, 22), Color.FromArgb(148, 163, 184),
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);

            // Test sürerken sağda nabız gibi atan canlılık noktası
            if (_dnsStarted && !_dnsDone)
            {
                double ph = (Environment.TickCount % 1000) / 1000.0;
                double pulse = (Math.Sin(ph * 2 * Math.PI) + 1) / 2;
                float pcx = w - 24f;
                float pcy = 19f;
                using (SolidBrush halo = new SolidBrush(Color.FromArgb((int)(35 + 60 * pulse), 56, 189, 248)))
                using (SolidBrush core = new SolidBrush(Color.FromArgb((int)(165 + 90 * pulse), 56, 189, 248)))
                {
                    g.FillEllipse(halo, pcx - 7f, pcy - 7f, 14f, 14f);
                    g.FillEllipse(core, pcx - 3.5f, pcy - 3.5f, 7f, 7f);
                }
            }

            // DNS satırları
            int y = ListTopDns;
            int drawCount = Math.Min(WizardDnsCount, _dnsOptions.Count);
            for (int i = 0; i < drawCount; i++)
            {
                Rectangle rr = new Rectangle(16, y, w - 32, DnsRowH);
                bool selected = (i == _selDns);
                bool hovered = (i == _dnsHoverRow);
                Color accent = _dnsOptions[i].TagColor;

                using (GraphicsPath path = ModernMainForm.CreateRoundedRectangleF(new RectangleF(rr.X, rr.Y, rr.Width, rr.Height), 7f))
                using (SolidBrush bg = new SolidBrush(hovered ? Color.FromArgb(22, 30, 44) : Color.FromArgb(18, 24, 34)))
                using (Pen pen = new Pen(selected ? accent : Color.FromArgb(38, 50, 70), selected ? 1.6f : 1f))
                {
                    g.FillPath(bg, path);
                    g.DrawPath(pen, path);
                }

                DrawRadio(g, rr.X + 20, rr.Y + rr.Height / 2, selected, accent);

                int msX = DrawMsRight(g, rr, _dnsTimes[i]);

                int rightLimit = msX - 12;
                bool experimental = string.Equals(_dnsOptions[i].Tag, "DENEY", StringComparison.Ordinal);
                if (experimental)
                {
                    rightLimit = DrawBadgeChip(g, rightLimit, rr.Y, rr.Height, _dnsOptions[i].Tag, true) - 8;
                }
                else if (_dnsDone && i == _dnsFastest && _dnsTimes[i] >= 0)
                {
                    string badgeLabel = (_port53ProxyDetected && i == _dnsFastest) ? "✓ ÖNERİLEN" : "✓ EN HIZLI";
                    rightLimit = DrawBadgeChip(g, rightLimit, rr.Y, rr.Height, badgeLabel) - 8;
                }

                int nameW = Math.Max(20, rightLimit - (rr.X + 42));
                TextRenderer.DrawText(g, _dnsOptions[i].DisplayName, _fontRowName,
                    new Rectangle(rr.X + 42, rr.Y + 5, nameW, 17), Color.FromArgb(226, 232, 240),
                    TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);

                string sub;
                if (i == 0)
                {
                    sub = "Akıllı Dinamik Seçim";
                }
                else
                {
                    string srv;
                    int prt;
                    if (TryGetDnsEndpoint(_dnsOptions[i], out srv, out prt))
                    {
                        sub = string.Format("{0}:{1}", srv, prt);
                    }
                    else
                    {
                        sub = "";
                    }
                }
                TextRenderer.DrawText(g, sub, _fontRowSub,
                    new Rectangle(rr.X + 42, rr.Y + 22, nameW, 16), Color.FromArgb(120, 134, 156),
                    TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);

                y += DnsRowH + DnsRowGap;
            }

            // Alt bilgi notu
            TextRenderer.DrawText(g, "İpucu: İnternet sağlayıcınız standart DNS portunu (53) engelliyorsa alternatif portlu Quad9 (Port 9953) veya OpenDNS (Port 443) bu engeli aşar. Engel yoksa en düşük ms değerine sahip olanı seçebilirsiniz.",
                _fontSmall, new Rectangle(16, 280, w - 32, 48), Color.FromArgb(100, 116, 139),
                TextFormatFlags.Left | TextFormatFlags.NoPrefix | TextFormatFlags.WordBreak);
        }

