        // ==================== Adım 4: Özet ====================

        private void SummaryPanel_Paint(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;

            int w = _panelSummary.Width;

            TextRenderer.DrawText(g, "Kurulum Özeti", _fontSection,
                new Rectangle(24, 16, w - 48, 26), Color.FromArgb(248, 250, 252),
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);

            string profileName = (_selProfile >= 0 && _selProfile < _profiles.Count) ? _profiles[_selProfile].Name : "-";
            Color profileColor = (_selProfile >= 0 && _selProfile < _profiles.Count) ? _profiles[_selProfile].AccentColor : Color.FromArgb(148, 163, 184);

            string dnsName = (_selDns >= 0 && _selDns < _dnsOptions.Count) ? _dnsOptions[_selDns].DisplayName : "-";
            Color dnsColor = (_selDns >= 0 && _selDns < _dnsOptions.Count) ? _dnsOptions[_selDns].TagColor : Color.FromArgb(148, 163, 184);

            bool gaming = (_chkGaming != null && _chkGaming.Checked);
            string gamingText = gaming ? "Açık (önerilen)" : "Kapalı";
            Color gamingColor = gaming ? Color.FromArgb(52, 211, 153) : Color.FromArgb(148, 163, 184);

            int y = 50;
            DrawSummaryRow(g, w, y, "İnternet Profili", profileName, profileColor); y += 50;
            DrawSummaryRow(g, w, y, "DNS Sunucusu", dnsName, dnsColor); y += 50;
            DrawSummaryRow(g, w, y, "Oyun Optimizasyonu", gamingText, gamingColor); y += 62;

            TextRenderer.DrawText(g, "'Korumayı Başlat' düğmesine basarak hemen kullanmaya başlayabilirsiniz.\r\n'Sadece Kaydet' ayarları kaydeder, korumayı istediğiniz zaman ana ekrandan açabilirsiniz.",
                _fontBody, new Rectangle(24, y, w - 48, 70), Color.FromArgb(148, 163, 184),
                TextFormatFlags.Left | TextFormatFlags.NoPrefix | TextFormatFlags.WordBreak);
        }

        private void DrawSummaryRow(Graphics g, int panelW, int y, string label, string value, Color valueColor)
        {
            Rectangle rr = new Rectangle(24, y, panelW - 48, 40);
            using (GraphicsPath path = ModernMainForm.CreateRoundedRectangleF(new RectangleF(rr.X, rr.Y, rr.Width, rr.Height), 7f))
            using (SolidBrush bg = new SolidBrush(Color.FromArgb(18, 24, 34)))
            using (Pen pen = new Pen(Color.FromArgb(38, 50, 70), 1f))
            {
                g.FillPath(bg, path);
                g.DrawPath(pen, path);
            }

            TextRenderer.DrawText(g, label, _fontBody,
                new Rectangle(rr.X + 16, rr.Y, rr.Width / 2, rr.Height), Color.FromArgb(148, 163, 184),
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);

            TextRenderer.DrawText(g, value, _fontBodyBold,
                new Rectangle(rr.X + rr.Width / 2, rr.Y, rr.Width / 2 - 16, rr.Height), valueColor,
                TextFormatFlags.Right | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        }

        // ==================== Asenkron Testler ====================

        private void RunIspTests()
        {
            if (_ispStarted) return;
            _ispStarted = true;
            _ispPending = _profiles.Count + 3;

            for (int i = 0; i < _profiles.Count; i++)
            {
                int profileIndex = i;
                string target = _profiles[i].PeeringTarget;
                ThreadPool.QueueUserWorkItem(delegate(object state)
                {
                    long best = -1;
                    for (int attempt = 0; attempt < 3; attempt++)
                    {
                        long ms = NetworkProbe.TestPing(target, 600);
                        if (ms >= 0)
                        {
                            best = (best < 0) ? ms : Math.Min(best, ms);
                        }
                    }
                    PostIspResult(profileIndex, best);
                });
            }

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                int detected = NetworkProbe.DetectIspLocalAndNextHop();
                PostIspDetectedHop(detected);
            });

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                string ips;
                bool poisoned = NetworkProbe.IsDiscordDnsPoisoned(out ips);
                PostDpiDnsResult(poisoned, ips);
            });

            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                string err;
                long ms = NetworkProbe.TestTlsHandshake("gateway.discord.gg", 443, 2500, out err);
                PostDpiGatewayResult(ms);
            });
        }

        private void RunDnsRace()
        {
            if (_dnsStarted) return;
            _dnsStarted = true;

            int count = Math.Min(WizardDnsCount, _dnsOptions.Count);
            if (count <= 1)
            {
                FinalizeDnsResults();
                return;
            }

            // Index 0 (Otomatik) fiziksel sunucu değildir; 1..count-1 arasındaki gerçek sunucular test edilir
            int probeCount = count - 1;
            _dnsPending = probeCount;

            for (int i = 1; i < count; i++)
            {
                int idx = i;
                string server;
                int port;
                if (!TryGetDnsEndpoint(_dnsOptions[idx], out server, out port))
                {
                    PostDnsResult(idx, -1);
                    continue;
                }

                ThreadPool.QueueUserWorkItem(delegate(object state)
                {
                    int bytes;
                    string err;
                    long ms = NetworkProbe.TestUdpDns(server, port, 1500, out bytes, out err);
                    PostDnsResult(idx, ms);
                });
            }
        }

        private void PostIspResult(int index, long ms)
        {
            if (this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (this.IsDisposed) return;
                    if (index >= 0 && index < _ispTimes.Length) _ispTimes[index] = ms;
                    _ispPending--;
                    if (_ispPending <= 0) FinalizeIspResults();
                    if (_panelIsp != null && !_panelIsp.IsDisposed) _panelIsp.Invalidate();
                });
            }
            catch {}
        }

        private void PostIspDetectedHop(int detectedIndex)
        {
            if (this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (this.IsDisposed) return;
                    _ispDetectedByHop = detectedIndex;
                    _ispPending--;
                    if (_ispPending <= 0) FinalizeIspResults();
                    if (_panelIsp != null && !_panelIsp.IsDisposed) _panelIsp.Invalidate();
                });
            }
            catch {}
        }

        private void PostDpiDnsResult(bool poisoned, string ips)
        {
            if (this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (this.IsDisposed) return;
                    _dpiPoisoned = poisoned;
                    _dpiDnsText = ips;
                    _ispPending--;
                    if (_ispPending <= 0) FinalizeIspResults();
                    if (_panelIsp != null && !_panelIsp.IsDisposed) _panelIsp.Invalidate();
                });
            }
            catch {}
        }

        private void PostDpiGatewayResult(long ms)
        {
            if (this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (this.IsDisposed) return;
                    _dpiGatewayMs = ms;
                    _ispPending--;
                    if (_ispPending <= 0) FinalizeIspResults();
                    if (_panelIsp != null && !_panelIsp.IsDisposed) _panelIsp.Invalidate();
                });
            }
            catch {}
        }

        private void FinalizeIspResults()
        {
            _ispDone = true;

            // Hiç başlatılamayan (-2, "test ediliyor" durumu) yuvalar hataya çevrilir;
            // aksi hâlde İSS listesi "test ediliyor" yazısında kilitli kalırdı.
            for (int i = 0; i < _ispTimes.Length; i++)
            {
                if (_ispTimes[i] == -2) _ispTimes[i] = -1;
            }

            if (_ispDetectedByHop >= 0 && _ispDetectedByHop < _profiles.Count)
            {
                _ispRecommended = _ispDetectedByHop;
                if (!_ispUserTouched)
                {
                    _selProfile = _ispDetectedByHop;
                }
            }
            else
            {
                // En iyi ve ikinci en iyi geçerli ölçümü bul.
                long best = long.MaxValue;
                long second = long.MaxValue;
                int bestIdx = -1;
                for (int i = 0; i < _ispTimes.Length; i++)
                {
                    long v = _ispTimes[i];
                    if (v < 0) continue;
                    if (v < best)
                    {
                        second = best;
                        best = v;
                        bestIdx = i;
                    }
                    else if (v < second)
                    {
                        second = v;
                    }
                }

                bool ambiguous = (bestIdx >= 0 && second != long.MaxValue && (second - best) < 3);
                _ispRecommended = ambiguous ? -1 : bestIdx;

                if (!_ispUserTouched && !ambiguous && bestIdx >= 0)
                {
                    _selProfile = bestIdx;
                }
            }
            if (_panelIsp != null && !_panelIsp.IsDisposed) _panelIsp.Invalidate();
            if (_panelSummary != null && !_panelSummary.IsDisposed) _panelSummary.Invalidate();
        }

        private void PostDnsResult(int index, long ms)
        {
            if (this.IsDisposed || !this.IsHandleCreated) return;
            try
            {
                this.BeginInvoke((MethodInvoker)delegate
                {
                    if (this.IsDisposed) return;
                    if (index >= 0 && index < _dnsTimes.Length) _dnsTimes[index] = ms;
                    _dnsPending--;
                    if (_dnsPending <= 0) FinalizeDnsResults();
                    if (_panelDns != null && !_panelDns.IsDisposed) _panelDns.Invalidate();
                });
            }
            catch {}
        }

        private void FinalizeDnsResults()
        {
            _dnsDone = true;
            _port53ProxyDetected = false;

            int count = Math.Min(WizardDnsCount, _dnsOptions.Count);
            for (int i = 0; i < _dnsTimes.Length; i++)
            {
                if (_dnsTimes[i] == -2) _dnsTimes[i] = -1;
                if (i >= 1 && _dnsTimes[i] == -3) _port53ProxyDetected = true;
            }

            // Port 53 engeli kontrolü:
            // Standart port (53) kullanan test sunucularının tamamı başarısız (-1) veya vekil/zehirli (-3) yanıt veriyor mu?
            int port53Count = 0;
            int port53FailCount = 0;
            for (int i = 1; i < count; i++)
            {
                string s;
                int p;
                if (TryGetDnsEndpoint(_dnsOptions[i], out s, out p) && p == 53)
                {
                    port53Count++;
                    if (_dnsTimes[i] < 0) port53FailCount++;
                }
            }
            if (port53Count > 0 && port53FailCount == port53Count)
            {
                _port53ProxyDetected = true;
            }

            // En iyi fiziksel sunucuyu bul (index 1..count-1)
            long best = long.MaxValue;
            int bestIdx = -1;
            for (int i = 1; i < count; i++)
            {
                long v = _dnsTimes[i];
                // Zehirli/şeffaf vekil (-3) veya zaman aşımı (-1) olanlar asla "EN HIZLI" seçilemez
                if (v >= 0 && v < best)
                {
                    best = v;
                    bestIdx = i;
                }
            }

            // Otomatik (index 0) için en iyi süreyi ata
            if (bestIdx >= 0)
            {
                _dnsTimes[0] = best;
            }
            else
            {
                _dnsTimes[0] = -1;
            }

            // İSS'de Port 53 şeffaf vekil / engelleme tespit edildiyse,
            // engelsiz porta sahip Quad9 (Port 9953, index 3) varsa onu öner
            if (_port53ProxyDetected || _dpiPoisoned || _dpiGatewayMs < 0)
            {
                int bypassIdx = -1;
                for (int i = 1; i < count; i++)
                {
                    string s;
                    int p;
                    if (TryGetDnsEndpoint(_dnsOptions[i], out s, out p) && p != 53 && _dnsTimes[i] >= 0)
                    {
                        bypassIdx = i;
                        break;
                    }
                }
                if (bypassIdx >= 0)
                {
                    bestIdx = bypassIdx;
                }
            }

            _dnsFastest = bestIdx;
            if (!_dnsUserTouched && bestIdx >= 0)
            {
                _selDns = bestIdx;
            }
            if (_panelDns != null && !_panelDns.IsDisposed) _panelDns.Invalidate();
            if (_panelSummary != null && !_panelSummary.IsDisposed) _panelSummary.Invalidate();
        }
    }

    #endregion

    #region Windows Security & Defender Integration

    /// <summary>
    /// Windows Defender otomatik dışlama ve yerel dijital sertifika güven yönetimi.
    /// Program yönetici olarak çalıştığından, harici .bat dosyalarına gerek kalmadan
    /// klasör yolunu Defender dışlamalarına ve yerel sertifikayı Güvenilen Yayıncılara ekler.
    /// </summary>
    public static class WindowsSecurityHelper
    {
        private const string RegistryKeyName = @"Software\GoodbyeDPI_Pro_MAX";
        private const string ExclusionValueName = "DefenderExclusionFolder";
        private static int _isApplying = 0; // 0=idle, 1=busy

        /// <summary>
        /// Uygulama açılışında klasörün dışlanıp dışlanmadığını kontrol eder;
        /// gerekiyorsa arka planda sessizce dışlamayı ekler ve UI'da modern bildirim gösterir.
        /// </summary>
        public static void EnsureFolderExclusionAsync(ModernMainForm form)
        {
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    string currentDir = AppDomain.CurrentDomain.BaseDirectory;
                    if (string.IsNullOrEmpty(currentDir)) return;
                    currentDir = currentDir.TrimEnd('\\', '/');

                    string registeredDir = null;
                    using (RegistryKey key = Registry.CurrentUser.OpenSubKey(RegistryKeyName, false))
                    {
                        if (key != null)
                        {
                            object val = key.GetValue(ExclusionValueName);
                            if (val != null) registeredDir = val.ToString().TrimEnd('\\', '/');
                        }
                    }

                    // Aynı klasör için daha önce dışlama ve sertifika kaydı yapılmışsa açılışta tekrar çalıştırma (0 ms gecikme)
                    if (string.Equals(currentDir, registeredDir, StringComparison.OrdinalIgnoreCase))
                    {
                        return;
                    }

                    // İlk açılış veya klasör yeni bir konuma taşınmış: dışlama ve sertifikayı kaydet
                    ApplyExclusionInternal(currentDir, form, true);
                }
                catch (Exception ex)
                {
                    AppLogger.Log("SECURITY", "Defender dışlama denetimi hatası: " + ex.Message);
                }
            });
        }

        /// <summary>
        /// Kullanıcı arayüzünden (Tepsi menüsü veya Sorun Giderici) manuel tetiklenen dışlama yenileme.
        /// </summary>
        public static void ApplyExclusionManual(ModernMainForm form)
        {
            ThreadPool.QueueUserWorkItem(delegate(object state)
            {
                try
                {
                    string currentDir = AppDomain.CurrentDomain.BaseDirectory;
                    if (string.IsNullOrEmpty(currentDir)) return;
                    currentDir = currentDir.TrimEnd('\\', '/');

                    ApplyExclusionInternal(currentDir, form, false);
                }
                catch (Exception ex)
                {
                    AppLogger.Log("SECURITY", "Manuel Defender dışlama hatası: " + ex.Message);
                }
            });
        }

        private static void ApplyExclusionInternal(string folderPath, ModernMainForm form, bool isSilentStartup)
        {
            if (Interlocked.CompareExchange(ref _isApplying, 1, 0) != 0) return;

            try
            {
                bool defenderSuccess = AddDefenderExclusion(folderPath);
                bool certSuccess = InstallLocalCertificate(folderPath);

                if (defenderSuccess || certSuccess)
                {
                    // Başarılı kaydı Registry'ye işle
                    try
                    {
                        using (RegistryKey key = Registry.CurrentUser.CreateSubKey(RegistryKeyName))
                        {
                            if (key != null)
                            {
                                key.SetValue(ExclusionValueName, folderPath);
                            }
                        }
                    }
                    catch {}

                    AppLogger.Log("SECURITY", "Windows Defender dışlaması ve yerel sertifika güveni uygulandı: " + folderPath);

                    if (form != null && !form.IsDisposed)
                    {
                        form.BeginInvoke((MethodInvoker)delegate
                        {
                            if (form.IsDisposed) return;
                            string title = "Windows Güvenliği";
                            string msg = isSilentStartup
                                ? "Program klasörü Windows Defender dışlamalarına otomatik eklendi."
                                : "Windows Defender dışlaması ve dijital sertifika güveni güncellendi.";
                            ToastNotification.Show(title, msg, ToastType.Success, 4000);
                        });
                    }
                }
                else
                {
                    if (!isSilentStartup && form != null && !form.IsDisposed)
                    {
                        form.BeginInvoke((MethodInvoker)delegate
                        {
                            if (form.IsDisposed) return;
                            ToastNotification.Show("Windows Güvenliği", "Dışlama eklenemedi veya Defender devre dışı.", ToastType.Info, 3500);
                        });
                    }
                }
            }
            finally
            {
                Interlocked.Exchange(ref _isApplying, 0);
            }
        }

        /// <summary>
        /// Windows Defender Add-MpPreference komutu ile klasörü dışlamalara ekler.
        /// </summary>
        public static bool AddDefenderExclusion(string folderPath)
        {
            try
            {
                if (string.IsNullOrEmpty(folderPath) || !Directory.Exists(folderPath)) return false;

                string escapedPath = folderPath.Replace("'", "''");
                ProcessStartInfo psi = new ProcessStartInfo();
                psi.FileName = "powershell.exe";
                psi.Arguments = "-NoProfile -NonInteractive -WindowStyle Hidden -Command \"Add-MpPreference -ExclusionPath '" + escapedPath + "' -ErrorAction SilentlyContinue\"";
                psi.CreateNoWindow = true;
                psi.UseShellExecute = false;
                psi.WindowStyle = ProcessWindowStyle.Hidden;

                using (Process proc = Process.Start(psi))
                {
                    if (proc != null)
                    {
                        bool finished = proc.WaitForExit(4000);
                        if (!finished)
                        {
                            try { proc.Kill(); } catch {}
                            return false;
                        }
                        return proc.ExitCode == 0;
                    }
                }
            }
            catch (Exception ex)
            {
                AppLogger.Log("SECURITY", "AddDefenderExclusion hatası: " + ex.Message);
            }
            return false;
        }

        /// <summary>
        /// Varsa GoodbyeDPI_Cert.cer sertifikasını certutil ile TrustedPublisher ve Root deposuna kaydeder.
        /// </summary>
        public static bool InstallLocalCertificate(string folderPath)
        {
            try
            {
                if (string.IsNullOrEmpty(folderPath)) return false;
                string certPath = Path.Combine(folderPath, "GoodbyeDPI_Cert.cer");
                if (!File.Exists(certPath))
                {
                    certPath = Path.Combine(folderPath, "core", "GoodbyeDPI_Cert.cer");
                }
                if (!File.Exists(certPath)) return false;

                string escapedCert = certPath.Replace("\"", "\\\"");

                RunCertUtil("-addstore -f \"TrustedPublisher\" \"" + escapedCert + "\"");
                RunCertUtil("-addstore -f \"Root\" \"" + escapedCert + "\"");
                return true;
            }
            catch (Exception ex)
            {
                AppLogger.Log("SECURITY", "InstallLocalCertificate hatası: " + ex.Message);
            }
            return false;
        }

        private static void RunCertUtil(string args)
        {
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo();
                psi.FileName = "certutil.exe";
                psi.Arguments = args;
                psi.CreateNoWindow = true;
                psi.UseShellExecute = false;
                psi.WindowStyle = ProcessWindowStyle.Hidden;
                using (Process proc = Process.Start(psi))
                {
                    if (proc != null)
                    {
                        if (!proc.WaitForExit(3000))
                        {
                            try { proc.Kill(); } catch {}
                        }
                    }
                }
            }
            catch {}
        }
    }

    #endregion
}
